insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M2-MA-T04','M2-MA','M2','T04','การให้เหตุผลทางเรขาคณิต',4,'บทที่ 4 การให้เหตุผลทางเรขาคณิต','["ความรู้พื้นฐานเกี่ยวกับการให้เหตุผลทางเรขาคณิต", "การสร้างและการให้เหตุผลเกี่ยวกับการสร้าง", "การให้เหตุผลเกี่ยวกับรูปสามเหลี่ยมและรูปสี่เหลี่ยม"]'::jsonb,'ค22102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ค22102','live',4);
