insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M2-SC-T05','M2-SC','M2','T05','ดินและน้ำ',5,'บทที่ 5 ดินและน้ำ','["ดิน ชั้นดินและชั้นหน้าตัดดิน", "การตรวจวัดเนื้อดินและความชื้นในดิน", "การตรวจวัดความเป็นกรด-เบสของดินและการใช้ประโยชน์ดินจากข้อมูลที่ตรวจวัด", "แหล่งน้ำผิวดิน", "แหล่งน้ำใต้ดิน"]'::jsonb,'ว22102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ว22102','live',5);
