insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M2-SO-T01','M2-SO','M2','T01','เครื่องมือทางภูมิศาสตร์',1,'บทที่ 1 เครื่องมือทางภูมิศาสตร์','["เครื่องมือทางภูมิศาสตร์ เช่น เครื่องมือต่างๆ คำนวณระยะทางและเวลา RS GPS GIS ดาวเทียม ภาพถ่ายทางอากาศ ภาพถ่ายจากดาวเทียม"]'::jsonb,'ส22103',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ส22103','live',1);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M2-SO-T02','M2-SO','M2','T02','ภูมิศาสตร์กายภาพ',2,'บทที่ 2 ภูมิศาสตร์กายภาพ','["ภูมิศาสตร์กายภาพโลก เช่น โลก หิน ชั้นบรรยากาศ ฤดูกาล ภูเขา ที่ราบ ที่ราบสูง เขตทะเลทราย การจำแนกภูมิอากาศ ป่าไม้", "ปรากฏการณ์ทางภูมิศาสตร์โลก เช่น การเปลี่ยนแปลงเปลือกโลก การเปลี่ยนแปลงบรรยากาศโลก การเปลี่ยนแปลงโดยมนุษย์ (ภูมิสังคมใหม่ เช่น polder)", "ภูมิศาสตร์ประเทศไทย"]'::jsonb,'ส22103',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ส22103','live',2);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M2-SO-T03','M2-SO','M2','T03','วิกฤตการณ์ด้านทรัพยากรธรรมชาติและสิ่งแวดล้อม',3,'บทที่ 3 วิกฤตการณ์ด้านทรัพยากรธรรมชาติและสิ่งแวดล้อม','["ปรากฏการณ์เรือนกระจก / เอลนีโญ ลานีญา / การเกิดช่องโหว่ของชั้นโอโซน / ฝนกรด พายุหมุน / ไฟป่า / พื้นที่อับฝน / ปรากฏการณ์อุณหภูมิผกผัน / กระแสน้ำในมหาสมุทร ปะการังฟอกขาว / น้ำเปลี่ยนสีหรือขี้ปลาวาฬ", "ปรากฏการณ์ เอลนีโญ ลานีญา", "ปรากฏการณ์การเกิดช่องโหว่ของชั้นโอโซน", "ปรากฏการณ์ฝนกรด พายุหมุน", "ปรากฏการณ์ไฟป่า", "ปรากฏการณ์พื้นที่อับฝน", "ปรากฏการณ์ปรากฏการณ์อุณหภูมิผกผัน", "ปรากฏการณ์กระแสน้ำในมหาสมุทร ปะการังฟอกขาว", "ปรากฏการณ์น้ำเปลี่ยนสีหรือขี้ปลาวาฬ", "ปัญหาและการแก้ไขทรัพยากรต่างๆ เช่น ดินเปรี้ยว ดินเค็ม"]'::jsonb,'ส22103',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ส22103','live',3);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M2-SO-T04','M2-SO','M2','T04','ภัยพิบัติทางธรรมชาติ',4,'บทที่ 4 ภัยพิบัติทางธรรมชาติ','["ภัยพิบัติทางธรรมชาติ เช่น แผ่นดินไหว / ภูเขาไฟปะทุ / สึนามิ / อุทกภัย / แผ่นดินถล่ม การกัดเซาะของชายฝั่ง / วาตภัย / ไฟป่า / ภาวะโลกร้อน / ภูมิอากาศแปรปรวน / ภัยแล้ง"]'::jsonb,'ส22103',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ส22103','live',4);
