insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-PH-T01','M4-PH','M4','T01','สมดุลกล',1,'บทที่ 1 สมดุลกล','["สมดุลกล", "ศูนย์กลางมวลและศูนย์ถ่วง", "สมดุลต่อการเลื่อนที่", "โมเมนต์ของแรง", "เสถียรภาพของวัตถุ"]'::jsonb,'ว30212',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ว30212','live',1);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-PH-T02','M4-PH','M4','T02','งานและพลังงาน',2,'บทที่ 2 งานและพลังงาน','["งานเนื่องจากแรงคงตัว", "งานเนื่องจากแรงไม่คงตัว", "กำลัง", "พลังงานจลน์", "พลังงานศักย์", "งานเนื่องจากแรงอนุรักษ์", "กฎการอนุรักษ์พลังงานกล", "ประสิทธิภาพของเครื่องกล", "หลักการของงานกับเครื่องกลอย่างง่าย", "หลักการของสมดุลกลกับเครื่องกลอย่างง่าย"]'::jsonb,'ว30212',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ว30212','live',2);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-PH-T03','M4-PH','M4','T03','โมเมนตัมและการชน',3,'บทที่ 3 โมเมนตัมและการชน','["โมเมนตัม", "แรงและการเปลี่ยนโมเมนตัม", "การดล", "การอนุรักษ์โมเมนตัม", "การชนของวัตถุในหนึ่งมิติ", "การดีดตัวแยกจากกันของวัตถุในหนึ่งมิติ", "การทดลองเสมือนจริง การชนและการดีดตัวแยกจากกันของวัตถุในหนึ่งมิติ"]'::jsonb,'ว30212',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ว30212','live',3);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-PH-T04','M4-PH','M4','T04','การเคลื่อนที่แนวโค้ง',4,'บทที่ 4 การเคลื่อนที่แนวโค้ง','["การเคลื่อนที่แบบโพรเจกไทล์", "การเคลื่อนที่แบบวงกลมสม่ำเสมอ", "การเคลื่อนที่ของดาวเทียม"]'::jsonb,'ว30212',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ว30212','live',4);
