insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-CH-T01','M4-CH','M4','T01','โมลและสูตรเคมี',1,'บทที่ 1 โมลและสูตรเคมี','["มวลอะตอม", "โมล", "มวลต่อโมล", "ความสัมพันธ์ระหว่างโมล มวล และปริมาตรของแก๊ส", "กฎสัดส่วนคงที่", "ร้อยละโดยมวลของธาตุ", "สูตรโมเลกุลและสูตรอย่างง่าย"]'::jsonb,'ว30222',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ว30222','live',1);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-CH-T02','M4-CH','M4','T02','สารละลาย',2,'บทที่ 2 สารละลาย','["ความเข้มข้นของสารละลาย", "การคำนวณเกี่ยวกับความเข้มข้นของสารละลาย", "การเตรียมสารละลายจากสารบริสุทธิ์", "การเตรียมสารละลายเจือจางจากสารละลายเข้มข้น", "จุดเดือดของสารละลาย", "จุดหลอมเหลวของสารละลาย"]'::jsonb,'ว30222',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ว30222','live',2);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-CH-T03','M4-CH','M4','T03','ปริมาณสัมพันธ์',3,'บทที่ 3 ปริมาณสัมพันธ์','["ปฏิกิริยาเคมีและสมการเคมี", "การดุลสมการเคมี", "มวลของสารกับสมการเคมี", "การคำนวณปริมาณสารที่เกี่ยวข้องกับมวล", "การคำนวณปริมาณสารที่เกี่ยวข้องกับความเข้มข้น", "ปฏิกิริยาเคมีของแก๊สและการคำนวณ", "การคำนวณปริมาณสารในปฏิกิริยาเคมี", "สารกำหนดปริมาณ", "ผลได้ร้อยละ"]'::jsonb,'ว30222',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ว30222','live',3);
insert into public.subjects (id,grade_code,code,name_th,icon,color,course_codes,status,note,sort) values ('M4-BI','M4','BI','ชีววิทยา','🧬','#30B0C7',array['ว30232']::text[],'live',null,3);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-BI-T01','M4-BI','M4','T01','โครโมโซมและสารพันธุกรรม',1,'บทที่ 1 โครโมโซมและสารพันธุกรรม','["โครโมโซม", "การค้นพบสารพันธุกรรม", "องค์ประกอบทางเคมีของ DNA โครงสร้างของ DNA", "การจำลองดีเอ็นเอ", "การควบคุมลักษณะทางพันธุกรรมของ DNA", "มิวเทชันระดับยีน", "มิวเทชันระดับโครโมโซม"]'::jsonb,'ว30232',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ว30232','live',1);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-BI-T02','M4-BI','M4','T02','การถ่ายทอดลักษณะทางพันธุกรรม',2,'บทที่ 2 การถ่ายทอดลักษณะทางพันธุกรรม','["การศึกษาพันธุกรรมของเมนเดล", "กฎการแยก", "กฎการรวมกลุ่มอย่างอิสระ", "การถ่ายทอดยีนบนโครโมโซม", "ความเด่นไม่สมบูรณ์ ความเด่นร่วม", "มัลติเพิลแอลลีล", "ลักษณะควบคุมด้วยยีนหลายคู่", "การถ่ายทอดยีนบนโครโมโซมเพศ", "ยีนบนโครโมโซมเดียวกัน"]'::jsonb,'ว30232',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ว30232','live',2);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-BI-T03','M4-BI','M4','T03','เทคโนโลยีทางดีเอ็นเอ',3,'บทที่ 3 เทคโนโลยีทางดีเอ็นเอ','["การโคลนยีนโดยใช้พลาสมิดของแบคทีเรีย", "การเพิ่มจำนวน DNA ด้วยเทคนิค PCR", "การหาขนาดของ DNA และการหาลำดับนิวคลีโอไทด์", "การประยุกต์ใช้เทคโนโลยีทางดีเอ็นเอ", "เทคโนโลยีทางดีเอ็นเอกับความปลอดภัยทางชีวภาพ และชีวจริยธรรม"]'::jsonb,'ว30232',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ว30232','live',3);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-BI-T04','M4-BI','M4','T04','วิวัฒนาการ',4,'บทที่ 4 วิวัฒนาการ','["หลักฐานและข้อมูลที่ใช้ในการศึกษาวิวัฒนาการของสิ่งมีชีวิต", "แนวคิดเกี่ยวกับวิวัฒนาการของสิ่งมีชีวิต", "พันธุศาสตร์ประชากร", "ปัจจัยที่ทำให้เกิดการเปลี่ยนแปลงความถี่ของแอลลีล", "กำเนิดสปีชีส์"]'::jsonb,'ว30232',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ว30232','live',4);
insert into public.subjects (id,grade_code,code,name_th,icon,color,course_codes,status,note,sort) values ('M4-MA','M4','MA','คณิตศาสตร์','🔢','#007AFF',array['ค31102']::text[],'live',null,4);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-MA-T01','M4-MA','M4','T01','เรขาคณิตวิเคราะห์',1,'บทที่ 1 เรขาคณิตวิเคราะห์','["ระบบพิกัดฉาก", "ระยะห่างระหว่างจุดสองจุด", "จุดแบ่งของส่วนของเส้นตรงออกเป็นอัตราส่วน m : n", "ความชันของเส้นตรง", "สมการเส้นตรง", "ความสัมพันธ์ระหว่างเส้นตรงสองเส้น (ขนานและตั้งฉาก)", "จุดตัดแกน x และจุดตัดแกน y", "ระยะห่างระหว่างจุดกับเส้นตรง", "ระยะห่างระหว่างเส้นขนานสองเส้น", "พื้นที่รูปหลายเหลี่ยม", "มุมระหว่างเส้นตรงสองเส้น", "สมการเส้นตรงที่แบ่งครึ่งมุมระหว่างเส้นตรง 2 เส้นตัดกัน", "จุดตัดของเส้นมัธยฐาน หรือจุด centroid"]'::jsonb,'ค31102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ค31102','live',1);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-MA-T02','M4-MA','M4','T02','ภาคตัดกรวย',2,'บทที่ 2 ภาคตัดกรวย','["การเลื่อนแกนทางขนาน", "วงกลม (นิยาม)", "วงกลม (สมการวงกลม)", "ระยะทางสั้นที่สุดและยาวที่สุดจากจุดไปยังวงกลม", "เส้นสัมผัสวงกลม", "พาราโบลา (นิยาม)", "พาราโบลา (สมการพาราโบลา)", "วงรี (นิยาม)", "วงรี (สมการวงรี)", "วงรี (เนื้อหาเพิ่มเติม)", "ไฮเพอร์โบลา (นิยาม)", "ไฮเพอร์โบลา (สมการไฮเพอร์โบลา)"]'::jsonb,'ค31102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ค31102','live',2);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-MA-T03','M4-MA','M4','T03','ทฤษฎีจำนวน',3,'บทที่ 3 ทฤษฎีจำนวน','["การหารลงตัว (บทนิยาม)", "การหารลงตัว (ทฤษฎีบทที่สำคัญ)", "การหารลงตัว (ตัวหารที่น่าสนใจ)", "จำนวนเฉพาะ (บทนิยาม)", "หลักการตรวจสอบจำนวนเฉพาะ", "ทฤษฎีบทหลักมูลทางเลขคณิต", "ขั้นตอนวิธีการหาร (ทฤษฎีบทและบทนิยาม)", "ห.ร.ม. (บทนิยามและสมบัติที่สำคัญ)", "การหา ห.ร.ม. โดยวิธียูคลิด", "จำนวนเฉพาะสัมพัทธ์ (บทนิยามและสมบัติที่สำคัญ)", "ค.ร.น. (บทนิยามและสมบัติที่สำคัญ)"]'::jsonb,'ค31102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ค31102','live',3);
insert into public.subjects (id,grade_code,code,name_th,icon,color,course_codes,status,note,sort) values ('M4-EN','M4','EN','ภาษาอังกฤษ','🔤','#AF52DE',array['อ31102']::text[],'live',null,5);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-EN-T01','M4-EN','M4','T01','Grammar: โครงสร้างคำและกลุ่มนาม',1,'บทที่ 1 Grammar: โครงสร้างคำและกลุ่มนาม','["Part of Speech: การจำแนกหน้าที่และตำแหน่งคำ 4 ชนิดหลัก (N. V. Adj. Adv.) ในประโยค", "Noun & Article: คำนามเอกพจน์/พหูพจน์ นามนับได้/ไม่ได้ และกฎการใช้ a an the", "Quantifier & Pronoun: การบอกปริมาณและการใช้สรรพนามรูปต่างๆ ให้สัมพันธ์กับนาม"]'::jsonb,'อ31102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · อ31102','live',1);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-EN-T02','M4-EN','M4','T02','Grammar: ระบบกริยาและกาลเวลา',2,'บทที่ 2 Grammar: ระบบกริยาและกาลเวลา','["Subject-Verb Agreement: กฎความสอดคล้องระหว่างประธานและกริยาขั้นพื้นฐาน", "Tenses System: 6 กาลหลัก (Present Simple/Cont/Perf Past Simple/Cont Future Simple)", "Modal Verbs: กริยาช่วยแสดงความสามารถ ความเป็นไปได้ และคำขอร้อง (can may must should)"]'::jsonb,'อ31102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · อ31102','live',2);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-EN-T03','M4-EN','M4','T03','Grammar: รูปประโยคและอนุประโยค',3,'บทที่ 3 Grammar: รูปประโยคและอนุประโยค','["Passive Voice: โครงสร้างถูกกระทำใน Tenses พื้นฐาน (S + be + V3)", "Conditional Sentences: ประโยคเงื่อนไข If-Clause Type 0 1 2 3", "Non-Finite Verbs: การใช้ Infinitive with/without to และ Gerund พื้นฐาน", "Reported Speech: การเปลี่ยนประโยคบอกเล่า คำสั่ง และคำถามจาก Direct สู่ Indirect Speech"]'::jsonb,'อ31102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · อ31102','live',3);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-EN-T04','M4-EN','M4','T04','Grammar: ส่วนขยายและคำเชื่อม',4,'บทที่ 4 Grammar: ส่วนขยายและคำเชื่อม','["Adjective Adverb & Comparison: การวางตำแหน่ง การขยายคำ และการเปรียบเทียบขั้นกว่า/ขั้นสุด", "Preposition Conjunction & Question Tag: คำบุพบท คำเชื่อมพื้นฐาน และคำถามท้ายประโยค"]'::jsonb,'อ31102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · อ31102','live',4);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-EN-T05','M4-EN','M4','T05','Error Identification',5,'บทที่ 5 Error Identification','["การตรวจจับจุดผิด Word Form และ Parts of Speech วางผิดตำแหน่ง", "การตรวจจับจุดผิด Subject-Verb Agreement เมื่อมี Prepositional Phrase คั่นกลาง", "การตรวจจับจุดผิด Tense คู่กับ Time Markers ในอดีต ปัจจุบัน และอนาคต", "การจับจุดผิดโครงสร้าง Active vs. Passive Voice ในประโยคเดี่ยว", "การตรวจจับจุดผิด Adjective vs. Adverb และโครงสร้าง Comparison"]'::jsonb,'อ31102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · อ31102','live',5);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-EN-T06','M4-EN','M4','T06','Reading Comprehension',6,'บทที่ 6 Reading Comprehension','["การระบุหัวข้อและใจความสำคัญระดับย่อหน้า (Topic & Main Idea)", "การตามหาคำอ้างอิงของสรรพนามในบริบท (Pronoun Reference)", "การอ่านและค้นหาข้อมูลเฉพาะจากสื่อสั้น (Notices Ads Announcements Signs)", "การแยกแยะข้อเท็จจริงและความคิดเห็น (Fact vs. Opinion)", "เทคนิคการเดาความหมายคำศัพท์จากบริบทแวดล้อม (Context Clues พื้นฐาน)"]'::jsonb,'อ31102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · อ31102','live',6);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-EN-T07','M4-EN','M4','T07','Conversation Skills',7,'บทที่ 7 Conversation Skills','["สำนวนการทักทาย การแนะนำตัว การกล่าวลา และการตอบรับอย่างสุภาพ", "การถาม-ตอบข้อมูล ทิศทาง และการนัดหมายในชีวิตประจำวัน", "บทสนทนาตามสถานการณ์จริง (ร้านอาหาร โรงแรม สนามบิน ช็อปปิ้ง)", "การแสดงความคิดเห็น การเห็นด้วย และไม่เห็นด้วยอย่างสุภาพ (Agreeing & Disagreeing)", "สำนวนที่พบบ่อยในการสื่อสารชีวิตประจำวัน (Common Daily Idioms & Slang)"]'::jsonb,'อ31102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · อ31102','live',7);
insert into public.subjects (id,grade_code,code,name_th,icon,color,course_codes,status,note,sort) values ('M4-TH','M4','TH','ภาษาไทย','📖','#FF9500',array['ท31102']::text[],'live',null,6);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-TH-T01','M4-TH','M4','T01','ราชาศัพท์และระดับภาษาเพื่อการสื่อสาร',1,'บทที่ 1 ราชาศัพท์และระดับภาษาเพื่อการสื่อสาร','["ราชาศัพท์สำหรับพระมหากษัตริย์และพระบรมวงศานุวงศ์", "คำศัพท์สำหรับพระภิกษุสงฆ์และคำสุภาพในสังคมไทย", "กฎการใช้ ''ทรง'' และข้อห้ามใช้ในคำราชาศัพท์", "ระดับภาษา 5 ระดับ (พิธีการ ทางการ กึ่งทางการ สนทนา กันเอง)"]'::jsonb,'ท31102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ท31102','live',1);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-TH-T02','M4-TH','M4','T02','วรรณคดีมรดกและบทกวีศักดิ์สิทธิ์ (ม.4)',2,'บทที่ 2 วรรณคดีมรดกและบทกวีศักดิ์สิทธิ์ (ม.4)','["บทนมัสการคุณานุคุณ (บทนมัสการมาตาปิตุคุณและอาจริยคุณ): อินทรวิเชียรฉันท์ 11", "มงคลสูตรคำฉันท์: มงคล 38 ประการและฉันทลักษณ์คำฉันท์", "การวิเคราะห์คุณค่าด้านวรรณศิลป์ ความเชื่อ และศีลธรรมทางพุทธศาสนา"]'::jsonb,'ท31102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ท31102','live',2);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-TH-T03','M4-TH','M4','T03','วรรณคดีมหากาพย์และการศึก (ม.4)',3,'บทที่ 3 วรรณคดีมหากาพย์และการศึก (ม.4)','["อิเหนา ตอน ศึกกะหมังกุหนิง: กลอนบทละครและศิลปะการรบ", "การวิเคราะห์ความขัดแย้ง พฤติกรรมตัวละคร และค่านิยมราชสำนัก", "รสวรรณคดีและการพรรณนากระบวนทัพและอารมณ์สะเทือนใจ"]'::jsonb,'ท31102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ท31102','live',3);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-TH-T04','M4-TH','M4','T04','วรรณกรรมร้อยแก้วและเรื่องแปล (ม.4)',4,'บทที่ 4 วรรณกรรมร้อยแก้วและเรื่องแปล (ม.4)','["นิทานเวตาล เรื่องที่ 10: กลวิธีโครงเรื่องซ้อนโครงเรื่อง (Frame Story)", "การวิเคราะห์ปมปัญหาเชิงปรัชญาและเชาวน์ปัญญาของเวตาล", "คุณค่าทางจริยธรรมและจิตวิทยาการปกครอง"]'::jsonb,'ท31102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ท31102','live',4);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-TH-T05','M4-TH','M4','T05','วรรณคดีนิราศและกวีนิพนธ์เอก (ม.4)',5,'บทที่ 5 วรรณคดีนิราศและกวีนิพนธ์เอก (ม.4)','["นิราศนรินทร์คำโคลง: ความเป็นเลิศแห่งโคลงสี่สุภาพ", "การเปรียบเทียบวรรณศิลป์ ภาพพจน์ และอารมณ์พลัดพราก", "บริบทประวัติศาสตร์สงครามเก้าทัพในสมัยรัตนโกสินทร์ตอนต้น"]'::jsonb,'ท31102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ท31102','live',5);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-TH-T06','M4-TH','M4','T06','วรรณกรรมสะท้อนสังคมและบทความร่วมสมัย (ม.4)',6,'บทที่ 6 วรรณกรรมสะท้อนสังคมและบทความร่วมสมัย (ม.4)','["บทความ ''หัวใจชายหนุ่ม'' (พระบาทสมเด็จพระมงกุฎเกล้าเจ้าอยู่หัว): รูปแบบนวนิยายจดหมาย", "การปะทะกันระหว่างค่านิยมตะวันตกกับวัฒนธรรมไทยดั้งเดิม", "บทกวี ''ทุกข์ของชาวนาในบทกวี'' (สมเด็จพระกนิษฐาธิราชเจ้าฯ): การวิเคราะห์ปัญหาเชิงโครงสร้างสังคม"]'::jsonb,'ท31102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ท31102','live',6);
insert into public.subjects (id,grade_code,code,name_th,icon,color,course_codes,status,note,sort) values ('M4-SO','M4','SO','สังคมศึกษา','🌏','#5AC8FA',array['ส31103']::text[],'live',null,7);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-SO-T01','M4-SO','M4','T01','รัฐและการเมืองไทย',1,'บทที่ 1 รัฐและการเมืองไทย','["คุณธรรม จริยธรรมของการเป็นพลเมืองดี", "รัฐ (องค์ประกอบรัฐ / รัฐเดี่ยว รัฐรวม / ประเทศที่มีกษัตริย์หรือประธานาธิบดีเป็นประมุข)", "การจัดระเบียบการปกครอง (รวม / แบ่ง / กระจาย / ข้อดี-ข้อเสีย)", "การบริหารราชการแผ่นดิน (กลาง / ภูมิภาค / ท้องถิ่น)", "ระบบรัฐบาล (รัฐสภา / ประธานาธิบดี / แบบกึ่ง)", "ประชาธิปไตย (หลักการ / รูปแบบ / ข้อดี-ข้อเสีย)", "เผด็จการ (หลักการ / อำนาจนิยม เบ็ดเสร็จนิยม / ข้อดี-ข้อเสีย)", "การใช้อำนาจอธิปไตย (นิติบัญญัติ / บริหาร / ตุลาการ)", "อำนาจหน้าที่ของรัฐสภา คณะรัฐมนตรี", "ฐานะและพระราชอำนาจของพระมหากษัตริย์", "รัฐธรรมนูญ", "สถานการณ์การเมืองไทยปัจจุบัน"]'::jsonb,'ส31103',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ส31103','live',1);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-SO-T02','M4-SO','M4','T02','สังคมวัฒนธรรม',2,'บทที่ 2 สังคมวัฒนธรรม','["วัฒนธรรม (ความหมาย / ลักษณะ / ความสำคัญ / ประเภท / วัฒนธรรมไทยกับวัฒนธรรมสากล ประเพณีท้องถิ่น)", "ศัพท์ เช่น โครงสร้างสังคม / สถาบันสังคม / การจัดระเบียบทางสังคม / การขัดเกลาทางสังคม"]'::jsonb,'ส31103',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ส31103','live',2);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-SO-T03','M4-SO','M4','T03','กฎหมาย',3,'บทที่ 3 กฎหมาย','["กฎหมายแพ่ง (ผู้เยาว์ / หมั้น สมรส / รับบุตรบุญธรรม / มรดก / นิติกรรมสัญญา / กู้ยืมเงิน)", "กฎหมายอาญา (ลักษณะ / ประเภท / โทษทางอาญา / บุคคลในกระบวนการยุติธรรม)", "ศาลไทย (ศาลรัฐธรรมนูญ / ศาลปกครอง / ศาลยุติธรรม)", "ทรัพย์สินทางปัญญา"]'::jsonb,'ส31103',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ส31103','live',3);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-SO-T04','M4-SO','M4','T04','สิทธิมนุษยชน',4,'บทที่ 4 สิทธิมนุษยชน','["ความหมาย ความสำคัญ และหลักการพื้นฐานของสิทธิมนุษยชน (ศักดิ์ศรีความเป็นมนุษย์ / สิทธิ เสรีภาพ / ความเสมอภาค)", "ปฏิญญาสากลว่าด้วยสิทธิมนุษยชน (UDHR) และอนุสัญญาระหว่างประเทศ (สิทธิเด็ก / สตรี / คนพิการ)", "สิทธิมนุษยชนตามรัฐธรรมนูญแห่งราชอาณาจักรไทย (สิทธิ เสรีภาพ หน้าที่ของปวงชนชาวไทยและหน้าที่ของรัฐ)", "กลไกการคุ้มครองสิทธิมนุษยชนในประเทศ (คณะกรรมการสิทธิมนุษยชนแห่งชาติ (กสม.) / ผู้ตรวจการแผ่นดิน / ศาล)", "องค์กรระหว่างประเทศและองค์กรเอกชน (NGO) ด้านสิทธิมนุษยชน (UNHCR / Amnesty International / สภากาชาด)", "สถานการณ์และปัญหาสิทธิมนุษยชนในปัจจุบัน (การค้ามนุษย์ / แรงงานข้ามชาติ / สิทธิความหลากหลายทางเพศ / เสรีภาพการแสดงออก)"]'::jsonb,'ส31103',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ส31103','live',4);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M4-SO-T05','M4-SO','M4','T05','ความสัมพันธ์ระหว่างประเทศ',5,'บทที่ 5 ความสัมพันธ์ระหว่างประเทศ','["ความหมาย ความสำคัญ และปัจจัยกำหนดนโยบายต่างประเทศของรัฐ", "องค์การระหว่างประเทศระดับโลก (สหประชาชาติ (UN) โครงสร้าง 6 องค์กรหลัก และองค์กรชำนัญพิเศษ)", "องค์กรความร่วมมือระดับภูมิภาค (อาเซียน (ASEAN) เสาหลัก 3 เสา / APEC / EU / NATO / BRICS)", "กฎหมายระหว่างประเทศและการทูต (สนธิสัญญา เอกสิทธิ์และความคุ้มกันทางการทูต)", "ความขัดแย้งและข้อพิพาทระหว่างประเทศในยุคปัจจุบัน (สงคราม ข้อพิพาทดินแดน การก่อการร้ายสากล)", "ความร่วมมือระหว่างประเทศและโลกาภิวัตน์ (การเปลี่ยนแปลงสภาพภูมิอากาศ สิทธิมนุษยชน ความมั่นคงทางพลังงานและอาหาร)"]'::jsonb,'ส31103',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ส31103','live',5);
insert into public.grades (code,name_th,app_name,sort,status,external_url,room_max) values ('M5','ม.5','Exam Gym ปิยมิตรมัธยม ม.5',5,'live',null,10);
insert into public.subjects (id,grade_code,code,name_th,icon,color,course_codes,status,note,sort) values ('M5-PH','M5','PH','ฟิสิกส์','🧲','#5856D6',array['ว30214']::text[],'live',null,1);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M5-PH-T01','M5-PH','M5','T01','ไฟฟ้าสถิต',1,'บทที่ 1 ไฟฟ้าสถิต','["ประจุไฟฟ้าและกฎการอนุรักษ์ประจุไฟฟ้า", "การเหนี่ยวนำไฟฟ้าสถิต", "กฎของคูลอมบ์", "ความหมายสนามไฟฟ้า", "สนามไฟฟ้าของจุดประจุ", "สนามไฟฟ้าของระบบประจุ", "เส้นสนามไฟฟ้า", "แรงกระทำต่ออนุภาคที่มีประจุในสนามไฟฟ้า", "ความต่างศักย์เนื่องจากสนามไฟฟ้าสม่ำเสมอ", "ศักย์ไฟฟ้าเนื่องจากจุดประจุ", "หลักการทำงานของตัวเก็บประจุ", "ความจุของตัวเก็บประจุ", "พลังงานสะสมในตัวเก็บประจุ", "การต่อตัวเก็บประจุ", "เครื่องถ่ายเอกสารและเครื่องพิมพ์เลเซอร์", "การเคลือบสีฝุ่นด้วยไฟฟ้าสถิต", "เครื่องฟอกอากาศ และเครื่องตกตะกอนไฟฟ้าสถิต", "การอธิบายปรากฎการณ์ฟ้าผ่าและฟ้าแลบ", "การใช้สายรัดข้อมือของช่างอิเล็กทรอนิกส์", "การเติมน้ำมัน"]'::jsonb,'ว30214',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ว30214','live',1);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M5-PH-T02','M5-PH','M5','T02','ไฟฟ้ากระแส',2,'บทที่ 2 ไฟฟ้ากระแส','["กระแสไฟฟ้าในตัวนำ", "กระแสไฟฟ้าในลวดตัวนำ", "กฎของโอห์มและความต้านทาน", "สภาพต้านทานไฟฟ้าและสภาพนำไฟฟ้า", "ตัวต้านทาน", "การต่อตัวต้านทาน", "พลังงานไฟฟ้าและความต่างศักย์", "พลังงานไฟฟ้าและกำลังไฟฟ้าของเครื่องใช้ไฟฟ้ากระแสตรง", "การต่อแบตเตอรี่", "การวิเคราะห์วงจรไฟฟ้ากระแสตรง", "พลังงานทดแทน", "เทคโนโลยีด้านพลังงาน"]'::jsonb,'ว30214',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ว30214','live',2);
insert into public.subjects (id,grade_code,code,name_th,icon,color,course_codes,status,note,sort) values ('M5-CH','M5','CH','เคมี','⚗️','#FF3B30',array['ว30224']::text[],'live',null,2);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M5-CH-T01','M5-CH','M5','T01','กรด-เบส',1,'บทที่ 1 กรด-เบส','["สมบัติทั่วไปของกรด เบส ทฤษฎีกรด เบสอาร์เรเนียส", "ทฤษฎีกรด เบสเบรินสเตด ลาวรี ทฤษฎีกรด เบสลิวอิส", "คู่กรด-เบส", "การแตกตัวของกรดแก่และเบสแก่", "การแตกตัวของกรดอ่อน", "การแตกตัวของเบสอ่อน ความสัมพันธ์ระหว่างร้อยละการแตกตัว ค่าคงที่การแตกตัว และความเข้มข้นของกรดและเบส", "การแตกตัวของน้ำ ความสัมพันธ์ระหว่าง Ka Kb และ Kw", "สมบัติกรด เบสของเกลือ", "pH ของสารละลายกรดและเบส", "การคำนวณเกี่ยวกับ pH และ pOH ของสารละลาย", "การวัด pH ในสารละลายกรดและเบส", "ปฏิกิริยาเคมีระหว่างกรดและเบส", "การไทเทรตกรด-เบส", "จุดยุติและการเลือกใช้อินดิเคเตอร์", "สารละลายบัฟเฟอร์", "การเตรียมสารละลายบัฟเฟอร์", "การประยุกต์ใช้ความรู้เกี่ยวกับกรด เบส"]'::jsonb,'ว30224',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ว30224','live',1);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M5-CH-T02','M5-CH','M5','T02','เคมีไฟฟ้า',2,'บทที่ 2 เคมีไฟฟ้า','["เลขออกซิเดชัน", "ปฏิกิริยารีดอกซ์", "ความสามารถในการเป็นตัวรีดิวซ์และตัวออกซิไดส์", "การดุลสมการรีดอกซ์โดยวิธีเลขออกซิเดชัน", "การดุลสมการรีดอกซ์โดยวิธีครึ่งปฏิกิริยา", "องค์ประกอบของเซลล์เคมีไฟฟ้า", "ชนิดของเซลล์เคมีไฟฟ้า", "แผนภาพเซลล์", "ศักย์ไฟฟ้าของเซลล์", "ศักย์ไฟฟ้ามาตรฐานของครึ่งเซลล์รีดักชัน", "แบตเตอรี่", "การกัดกร่อนของโลหะ", "การป้องกันการกัดกร่อนของโลหะ", "การชุบโลหะด้วยกระแสไฟฟ้า", "การแยกสลายด้วยไฟฟ้า", "เซลล์เชื้อเพลิง", "เทคโนโลยีที่เกี่ยวข้องกับเคมีไฟฟ้า"]'::jsonb,'ว30224',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ว30224','live',2);
insert into public.subjects (id,grade_code,code,name_th,icon,color,course_codes,status,note,sort) values ('M5-BI','M5','BI','ชีววิทยา','🧬','#30B0C7',array['ว30234']::text[],'live',null,3);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M5-BI-T01','M5-BI','M5','T01','ระบบย่อยอาหาร',1,'บทที่ 1 ระบบย่อยอาหาร','["การย่อยอาหารของสัตว์", "การย่อยอาหารของมนุษย์"]'::jsonb,'ว30234',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ว30234','live',1);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M5-BI-T02','M5-BI','M5','T02','ระบบหายใจ',2,'บทที่ 2 ระบบหายใจ','["การแลกเปลี่ยนแก๊สของสัตว์", "อวัยวะและโครงสร้างในระบบหายใจของมนุษย์", "การแลกเปลี่ยนแก๊สและการลำเลียงแก๊ส", "กลไกการหายใจของสัตว์", "การควบคุมการหายใจและความผิดปกติที่เกี่ยวข้องกับระบบหายใจ"]'::jsonb,'ว30234',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ว30234','live',2);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M5-BI-T03','M5-BI','M5','T03','ระบบหมุนเวียนเลือดและระบบน้ำเหลือง',3,'บทที่ 3 ระบบหมุนเวียนเลือดและระบบน้ำเหลือง','["การลำเลียงสารในร่างกายของสัตว์", "หัวใจ", "หลอดเลือด", "เลือด", "ระบบน้ำเหลือง"]'::jsonb,'ว30234',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ว30234','live',3);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M5-BI-T04','M5-BI','M5','T04','ระบบภูมิคุ้มกัน',4,'บทที่ 4 ระบบภูมิคุ้มกัน','["กลไกการต่อต้านหรือทำลายสิ่งแปลกปลอมแบบไม่จำเพาะ", "กลไกการต่อต้านหรือทำลายสิ่งแปลกปลอมแบบจำเพาะ", "การสร้างเสริมภูมิคุ้มกัน", "ความผิดปกติระบบภูมิคุ้มกัน"]'::jsonb,'ว30234',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ว30234','live',4);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M5-BI-T05','M5-BI','M5','T05','ระบบขับถ่าย',5,'บทที่ 5 ระบบขับถ่าย','["การขับถ่ายของสัตว์", "การขับถ่ายของมนุษย์", "การทำงานของหน่วยไต", "ไตกับการรักษาดุลยภาพของน้ำและสารต่าง ๆ ในร่างกาย", "ความผิดปกติของระบบขับถ่าย"]'::jsonb,'ว30234',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ว30234','live',5);
insert into public.subjects (id,grade_code,code,name_th,icon,color,course_codes,status,note,sort) values ('M5-MA','M5','MA','คณิตศาสตร์','🔢','#007AFF',array['ค32102']::text[],'live',null,4);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M5-MA-T01','M5-MA','M5','T01','ฟังก์ชันตรีโกณมิติ',1,'บทที่ 1 ฟังก์ชันตรีโกณมิติ','["วงกลมหนึ่งหน่วย", "มุมและการวัดมุม", "ฟังก์ชันไซน์ และฟังก์ชันโคไซน์ (บทนิยาม)", "ฟังก์ชันตรีโกณมิติอื่น ๆ (แทนเจนต์ โคแทนเจนต์ เซแคนต์ โคเซแคนต์)", "เอกลักษณ์ตรีโกณมิติ", "ค่าของฟังก์ชันตรีโกณมิติ", "การแปลงมุม", "ความสัมพันธ์ระหว่างฟังก์ชันตรีโกณมิติกับสามเหลี่ยมมุมฉาก", "Co-function", "กราฟของฟังก์ชันตรีโกณมิติ", "สูตรตรีโกณมิติ (ผลบวกและผลต่างของมุม)", "สูตรตรีโกณมิติ (มุมสองเท่า ครึ่งเท่า สามเท่า)", "สูตรแปลงผลคูณ ผลบวก และผลต่าง ของฟังก์ชันไซน์และโคไซน์", "การแก้สมการและอสมการของฟังก์ชันตรีโกณมิติ", "อินเวอร์สของฟังก์ชันตรีโกณมิติ (บทนิยาม)", "ความสัมพันธ์ของฟังก์ชันตรีโกณมิติกับอินเวอร์สของฟังก์ชันตรีโกณมิติ", "สมบัติของอินเวอร์สของฟังก์ชันตรีโกณมิติ", "การแก้สมการของอินเวอร์สของฟังก์ชันตรีโกณมิติ (สมการ arc)", "ฟังก์ชันตรีโกณมิติกับเรขาคณิต (กฎของไซน์และโคไซน์ การหาระยะทางและความสูง)"]'::jsonb,'ค32102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ค32102','live',1);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M5-MA-T02','M5-MA','M5','T02','จำนวนเชิงซ้อน',2,'บทที่ 2 จำนวนเชิงซ้อน','["ความรู้เบื้องต้น (บทนิยาม และกำลังของ i)", "การเท่ากันของจำนวนเชิงซ้อน", "การบวก ลบ คูณ หาร จำนวนเชิงซ้อน", "สังยุคของจำนวนเชิงซ้อน", "กราฟของจำนวนเชิงซ้อน", "สมบัติค่าสัมบูรณ์ของจำนวนเชิงซ้อน", "อินเวอร์สการคูณของจำนวนเชิงซ้อน", "จำนวนเชิงซ้อนในรูปเชิงขั้ว (บทนิยาม กราฟ และทฤษฎีบท)", "รากที่ n ของจำนวนเชิงซ้อน", "การแก้สมการพหุนาม (ทฤษฎีบทเศษเหลือ และทฤษฎีบทตัวประกอบจำนวนตรรกยะ)", "ทฤษฎีบทสังยุคของรากของสมการ"]'::jsonb,'ค32102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ค32102','live',2);
insert into public.subjects (id,grade_code,code,name_th,icon,color,course_codes,status,note,sort) values ('M5-EN','M5','EN','ภาษาอังกฤษ','🔤','#AF52DE',array['อ32102']::text[],'live',null,5);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M5-EN-T01','M5-EN','M5','T01','Grammar: โครงสร้างคำและกลุ่มนาม',1,'บทที่ 1 Grammar: โครงสร้างคำและกลุ่มนาม','["Word Formation: การวิเคราะห์รากศัพท์ Prefixes/Suffixes เชิงลึกและการเปลี่ยนหน้าที่คำขั้นสูง", "Noun & Determiners: คำนามรูปพิเศษ นามรวมหมู่ (Collective Nouns) และ Determiners ชั้นสูง", "Advanced Pronouns: สรรพนามเชื่อมโยงและสรรพนามไม่เจาะจงที่กำกวม (Ambiguous Pronouns)"]'::jsonb,'อ32102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · อ32102','live',1);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M5-EN-T02','M5-EN','M5','T02','Grammar: ระบบกริยาและกาลเวลา',2,'บทที่ 2 Grammar: ระบบกริยาและกาลเวลา','["Subject-Verb Agreement: ประธานซับซ้อน Inverted Subject และข้อยกเว้นออกสอบบ่อย", "Perfect & Continuous Aspects: มิติของ Tenses ผสม Stative Verbs ในรูปแฝง และ Sequence of Tenses", "Advanced Modals: Modal Perfect (must/should/could + have + V3) คาดคะเนอดีต"]'::jsonb,'อ32102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · อ32102','live',2);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M5-EN-T03','M5-EN','M5','T03','Grammar: รูปประโยคและอนุประโยค',3,'บทที่ 3 Grammar: รูปประโยคและอนุประโยค','["Passive Voice: รูปกรรมวาจกพิเศษ (Causative Form Impersonal Passive Perception Verbs)", "Advanced Conditionals: Mixed Conditionals Inversion If-Clause และคำเชื่อมเงื่อนไขอื่น", "Participle Clauses: โครงสร้างลดรูปและการวางตำแหน่ง (Present/Past Participle Clauses)", "Subjunctive Mood & Inversion: ประโยคสมมุติเชิงวิชาการ และการกลับประธาน-กริยาเน้นความ"]'::jsonb,'อ32102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · อ32102','live',3);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M5-EN-T04','M5-EN','M5','T04','Grammar: ส่วนขยายและคำเชื่อม',4,'บทที่ 4 Grammar: ส่วนขยายและคำเชื่อม','["Parallelism: โครงสร้างคู่ขนานในประโยคความซ้อนยาวและรายการเชื่อมโยง", "Discourse Markers & Transitions: ตัวเชื่อมเชิงเหตุผล ตรรกะขัดแย้ง และการร้อยเรียงระดับย่อหน้า"]'::jsonb,'อ32102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · อ32102','live',4);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M5-EN-T05','M5-EN','M5','T05','Error Identification',5,'บทที่ 5 Error Identification','["การตรวจจับจุดผิดกริยาแท้ vs กริยาไม่แท้ (Finite vs. Non-finite Traps) ในประโยคยาว", "การจับจุดผิดส่วนขยายลอยและวางผิดที่ (Dangling & Misplaced Modifiers)", "การตรวจจับจุดผิดโครงสร้างคู่ขนานที่ไม่สมดุล (Faulty Parallelism)", "การตรวจจับจุดผิด Subject-Verb Agreement ที่มีส่วนขยายซ้อนหลายชั้น", "เทคนิคการตัดช้อยส์และดักจุดหลอก Error Identification ระดับข้อสอบ A-Level"]'::jsonb,'อ32102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · อ32102','live',5);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M5-EN-T06','M5-EN','M5','T06','Reading Comprehension',6,'บทที่ 6 Reading Comprehension','["การวิเคราะห์น้ำเสียง เจตนา และทัศนคติของผู้เขียน (Author''s Tone Attitude & Purpose)", "การอนุมานความหมายและการสรุปความที่ซ่อนอยู่ (Inference & Drawing Conclusions)", "การอ่านจับใจความบทความวิชาการ วิทยาศาสตร์ เทคโนโลยี และสังคมศาสตร์ (400–600 คำ)", "การอ่านวิเคราะห์ข้อมูลจากชาร์ต กราฟ และอินโฟกราฟิก (Infographics & Data Interpretation)", "ยุทธวิธีบริหารเวลาและการสแกนข้อมูลแบบจับเวลาสอบจริง (Speed Reading Drills)"]'::jsonb,'อ32102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · อ32102','live',6);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M5-EN-T07','M5-EN','M5','T07','Conversation Skills',7,'บทที่ 7 Conversation Skills','["การเจรจาต่อรอง การโน้มน้าวใจ และการประนีประนอม (Negotiation & Persuasion)", "การร้องเรียน การขอโทษ และการแก้ปัญหาเฉพาะหน้า (Making Complaints & Problem Solving)", "การวิเคราะห์อารมณ์และนัยแฝงในคำพูดของผู้สนทนา (Speaker''s Implied Meaning)", "สำนวนภาษาอังกฤษเชิงวิชาการและธุรกิจ (Academic & Business Expressions)", "การจำลองทำข้อสอบ TGAT1 Speaking & Conversation Skills แบบจับเวลาเสมือนจริง"]'::jsonb,'อ32102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · อ32102','live',7);
insert into public.subjects (id,grade_code,code,name_th,icon,color,course_codes,status,note,sort) values ('M5-TH','M5','TH','ภาษาไทย','📖','#FF9500',array['ท32102']::text[],'live',null,6);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M5-TH-T01','M5-TH','M5','T01','ฉันทลักษณ์ร่ายและฉันท์',1,'บทที่ 1 ฉันทลักษณ์ร่ายและฉันท์','["ฉันทลักษณ์ร่าย: ร่ายสุภาพ ร่ายยาว ร่ายโบราณ", "ฉันทลักษณ์ฉันท์: อินทรวิเชียรฉันท์ 11, วิชชุมมาลาฉันท์ 8, ฉบัง 16", "กฎเกณฑ์คำครุ-ลหุ และการวางจังหวะลีลาในฉันทลักษณ์", "การฝึกแต่งบทประพันธ์ประเภทร่ายและฉันท์"]'::jsonb,'ท32102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ท32102','live',1);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M5-TH-T02','M5-TH','M5','T02','วรรณคดีมหากาพย์ประวัติศาสตร์ (ลิลิตตะเลงพ่าย)',2,'บทที่ 2 วรรณคดีมหากาพย์ประวัติศาสตร์ (ลิลิตตะเลงพ่าย)','["ประวัติความเป็นมาและโครงสร้างฉันทลักษณ์ลิลิต (ร่ายสุภาพและโคลงสุภาพ)", "การวิเคราะห์ยุทธหัตถี: วีรกรรม ความเสียสละ และความกตัญญูกตเวทิตา", "ภาพพจน์วรรณศิลป์ชั้นสูง: การใช้อุปมา อุปลักษณ์ สัทพจน์ และอติพจน์", "คุณค่าทางประวัติศาสตร์ ขนบธรรมเนียมการศึก และจริยธรรมของผู้นำ"]'::jsonb,'ท32102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ท32102','live',2);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M5-TH-T03','M5-TH','M5','T03','วรรณคดีคำสอนและพุทธปรัชญา (มหาเวสสันดรชาดก กัณฑ์มัทรี)',3,'บทที่ 3 วรรณคดีคำสอนและพุทธปรัชญา (มหาเวสสันดรชาดก กัณฑ์มัทรี)','["ฉันทลักษณ์ร่ายยาวและทำนองเทศน์มหาชาติ", "การวิเคราะห์ตัวละคร: พระเวสสันดรและพระนางมัทรี (มหาทานบารมีกับความรักของแม่)", "รสวรรณคดีสัลลาปังคพิสัย (ความโศกเศร้า) และโวหารภาพพจน์สะเทือนอารมณ์", "คุณค่าทางสังคม ค่านิยมกตัญญู และปรัชญาพุทธศาสนา"]'::jsonb,'ท32102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ท32102','live',3);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M5-TH-T04','M5-TH','M5','T04','บทละครพูดคำฉันท์ชั้นยอด (มัทนะพาธา)',4,'บทที่ 4 บทละครพูดคำฉันท์ชั้นยอด (มัทนะพาธา)','["พระราชนิพนธ์ในรัชกาลที่ 6 และฉันทลักษณ์คำฉันท์หลากหลายรูปแบบ", "แก่นเรื่อง: ''ความรักเป็นทุกข์'' และบทเรียนเรื่องตัณหา-ความหลง", "การวิเคราะห์ตัวละคร: นางมัทนา ท้าวสุเทษณ์ และท้าวชัยเสน", "ความประณีตของวรรณศิลป์คำฉันท์และการสร้างคำสมาส-สนธิในบทกวี"]'::jsonb,'ท32102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ท32102','live',4);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M5-TH-T05','M5-TH','M5','T05','วรรณกรรมภูมิปัญญาและการแพทย์ไทย (คัมภีร์ฉันทศาสตร์ แพทย์ศาสตร์สงเคราะห์)',5,'บทที่ 5 วรรณกรรมภูมิปัญญาและการแพทย์ไทย (คัมภีร์ฉันทศาสตร์ แพทย์ศาสตร์สงเคราะห์)','["ฉันทลักษณ์กาพย์ยานี 11 และภูมิปัญญาการแพทย์แผนไทยโบราณ", "จรรยาบรรณแพทย์และคุณธรรม 8 ประการของหมอ", "ทฤษฎีธาตุทั้ง 4 และการสะท้อนความเชื่อในสังคมไทยยุคโบราณ"]'::jsonb,'ท32102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ท32102','live',5);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M5-TH-T06','M5-TH','M5','T06','วรรณกรรมบทความวิพากษ์สังคม (โคลนติดล้อ ตอน ความนิยมเป็นเสมียน)',6,'บทที่ 6 วรรณกรรมบทความวิพากษ์สังคม (โคลนติดล้อ ตอน ความนิยมเป็นเสมียน)','["พระราชนิพนธ์ ''อัศวพาหุ'' (รัชกาลที่ 6) และการเขียนบทความแสดงทรรศนะ", "การวิเคราะห์ปัญหาค่านิยม ''ติดยศศักดิ์'' ของปัญญาชนสยาม", "กลวิธีการใช้ภาษาโน้มน้าวใจและการใช้เหตุผลสนับสนุนข้อโต้แย้ง"]'::jsonb,'ท32102',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ท32102','live',6);
insert into public.subjects (id,grade_code,code,name_th,icon,color,course_codes,status,note,sort) values ('M5-SO','M5','SO','สังคมศึกษา','🌏','#5AC8FA',array['ส32104']::text[],'live',null,7);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M5-SO-T01','M5-SO','M5','T01','ประวัติศาสตร์ไทย',1,'บทที่ 1 ประวัติศาสตร์ไทย','["ประวัติศาสตร์พื้นฐาน (ยุคสมัย / ศักราช / หลักฐาน / วิธีการทางประวัติศาสตร์)", "แคว้นโบราณในไทย แนวคิดถิ่นเดิมของชนชาติไทย รัฐโบราณในเอเชียตะวันออกเฉียงใต้", "สมัยสุโขทัย (พัฒนาการด้าน การเมืองการปกครอง / เศรษฐกิจ สังคม / ต่างประเทศ / ภูมิปัญญาไทย / บุคคลสำคัญและผลงาน)", "สมัยรัตนโกสินทร์ (พัฒนาการด้าน การเมืองการปกครอง / เศรษฐกิจ สังคม / ต่างประเทศ / ภูมิปัญญาไทย / บุคคลสำคัญและผลงาน)", "สมัยอยุธยา (พัฒนาการด้าน การเมืองการปกครอง / เศรษฐกิจ สังคม / ต่างประเทศ / ภูมิปัญญาไทย / บุคคลสำคัญและผลงาน)", "อิทธิพลของวัฒนธรรมตะวันออกและตะวันตกที่มีต่อสังคมไทย", "การปฏิรูปบ้านเมืองในสมัยรัชกาลที่ 5", "การเมืองไทยยุคประชาธิปไตย (คณะราษฎร 2475 / นายกรัฐมนตรี)"]'::jsonb,'ส32104',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ส32104','live',1);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M5-SO-T02','M5-SO','M5','T02','ประวัติศาสตร์สากล',2,'บทที่ 2 ประวัติศาสตร์สากล','["ยุคก่อนประวัติศาสตร์ (ยุคหิน ยุคโลหะ)", "อารยธรรมตะวันตก - ยุคโบราณ (อียิปต์)", "อารยธรรมตะวันตก - ยุคโบราณ (กรีก)", "อารยธรรมตะวันตก - ยุคโบราณ (โรมัน)", "อารยธรรมตะวันตก - ยุคโบราณ (เมโสโปเตเมีย)", "อารยธรรมตะวันตก - สมัยใหม่ (การฟื้นฟูศิลปวิทยาการ)", "อารยธรรมตะวันตก - สมัยใหม่ (รัฐชาติในยุโรป)", "อารยธรรมตะวันตก - สมัยใหม่ (ปฎิรูปศาสนา)", "อารยธรรมตะวันตก - สมัยใหม่ (ปฏิวัติวิทยาศาสตร์)", "อารยธรรมตะวันตก - สมัยใหม่ (ปฏิวัติอุตสาหกรรม)", "อารยธรรมตะวันตก - สมัยใหม่ (ปฏิวัติทางภูมิปัญญา)", "อารยธรรมตะวันตก - สมัยใหม่ (นักปรัชญาการเมือง)", "อารยธรรมตะวันตก - สมัยใหม่ (การปฏิวัติครั้งสำคัญของโลก)", "อารยธรรมตะวันตก - สมัยใหม่ (สงครามโลกครั้งที่ 1)", "อารยธรรมตะวันตก - สมัยใหม่ (สงครามโลกครั้งที่ 2)", "อารยธรรมตะวันตก - สมัยใหม่ (สงครามเย็น)", "อารยธรรมตะวันตก - สมัยใหม่ (สงครามและความขัดแย้ง)", "อารยธรรมตะวันตก - สมัยใหม่ (สหประชาชาติและองค์การระหว่างประเทศ)", "อารยธรรมตะวันตก - สมัยใหม่ (เหตุการณ์โลกปัจจุบัน)", "อารยธรรมตะวันตก - ยุคกลาง (Feudalism Manor สงครามครูเสด ไบแซนไทน์ อารยธรรมอิสลาม)", "อารยธรรมตะวันออก - จีน (ราชวงศ์ / ลัทธิ / มรดกอารยธรรม / นักการเมือง / จีนปัจจุบัน)", "อารยธรรมตะวันออก - อินเดีย (ลุ่มแม่น้ำสินธุ / วรรณะ / ราชวงศ์ / มรดกอารยธรรม / มหาตมะ คานธี)"]'::jsonb,'ส32104',2,'Helix ผังการเรียน 24 ต.ค. 2569 · ส32104','live',2);
insert into public.grades (code,name_th,app_name,sort,status,external_url,room_max) values ('M6','ม.6','Exam Gym ปิยมิตรมัธยม ม.6',6,'external','https://kruom9.github.io/kruom-cefr/examgym/m6-ios/',10);
insert into public.subjects (id,grade_code,code,name_th,icon,color,course_codes,status,note,sort) values ('M6-SO','M6','SO','สังคมศึกษา','🌏','#5AC8FA',array['A-Level 70']::text[],'imported','คลังข้อสอบเดิมของ Exam Gym ม.6 (นำเข้าตามเดิม ไม่แก้ไข) · บทเรียนเทอม 2 ยังต้องเติม',1);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M6-SO-S1','M6-SO','M6','S1','ศาสนา ศีลธรรม จริยธรรม',1,'สาระที่ 1 ศาสนา ศีลธรรม จริยธรรม','["1.1 หลักธรรม พุทธประวัติ และพุทธศาสนสุภาษิต", "1.2 คัมภีร์ ศาสนพิธี และศาสนิกชนที่ดี", "1.3 ศาสนาอื่นและการเปรียบเทียบศาสนา"]'::jsonb,'A-Level 70',null,'Exam Gym ม.6 (5620e4c34f07e5317732fb11438834e9aa57e8c3) · A-Level 70 สังคมศึกษา','live',1);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M6-SO-S2','M6-SO','M6','S2','หน้าที่พลเมือง วัฒนธรรม และการดำเนินชีวิตในสังคม',2,'สาระที่ 2 หน้าที่พลเมือง วัฒนธรรม และการดำเนินชีวิตในสังคม','["2.1 สังคม วัฒนธรรม และพลเมืองดี", "2.2 กฎหมายในชีวิตประจำวัน", "2.3 การเมืองการปกครอง รัฐธรรมนูญ และสิทธิมนุษยชน"]'::jsonb,'A-Level 70',null,'Exam Gym ม.6 (5620e4c34f07e5317732fb11438834e9aa57e8c3) · A-Level 70 สังคมศึกษา','live',2);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M6-SO-S3','M6-SO','M6','S3','เศรษฐศาสตร์',3,'สาระที่ 3 เศรษฐศาสตร์','["3.1 อุปสงค์ อุปทาน ตลาด และราคา", "3.2 เศรษฐศาสตร์มหภาค การเงิน การคลัง", "3.3 พื้นฐานเศรษฐศาสตร์ เศรษฐกิจพอเพียง และสหกรณ์", "3.4 เศรษฐกิจระหว่างประเทศ"]'::jsonb,'A-Level 70',null,'Exam Gym ม.6 (5620e4c34f07e5317732fb11438834e9aa57e8c3) · A-Level 70 สังคมศึกษา','live',3);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M6-SO-S4','M6-SO','M6','S4','ประวัติศาสตร์',4,'สาระที่ 4 ประวัติศาสตร์','["4.1 เวลา หลักฐาน และวิธีการทางประวัติศาสตร์", "4.2 ประวัติศาสตร์ไทย", "4.3 ประวัติศาสตร์โลก"]'::jsonb,'A-Level 70',null,'Exam Gym ม.6 (5620e4c34f07e5317732fb11438834e9aa57e8c3) · A-Level 70 สังคมศึกษา','live',4);
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ('M6-SO-S5','M6-SO','M6','S5','ภูมิศาสตร์',5,'สาระที่ 5 ภูมิศาสตร์','["5.1 แผนที่ เครื่องมือ และภูมิสารสนเทศ", "5.2 ภูมิศาสตร์กายภาพ และภัยพิบัติ", "5.3 ภูมิศาสตร์มนุษย์ ประชากร และเศรษฐกิจ", "5.4 สิ่งแวดล้อม และความร่วมมือระหว่างประเทศ"]'::jsonb,'A-Level 70',null,'Exam Gym ม.6 (5620e4c34f07e5317732fb11438834e9aa57e8c3) · A-Level 70 สังคมศึกษา','live',5);
insert into public.subjects (id,grade_code,code,name_th,icon,color,course_codes,status,note,sort) values ('M6-TH','M6','TH','ภาษาไทย','📖','#FF9500',array['A-Level 81']::text[],'imported','คลังข้อสอบเดิมของ Exam Gym ม.6 (นำเข้าตามเดิม ไม่แก้ไข)',2);
