insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-1','M6','M6-SO','M6-SO-S1','A-Level 70',null,2,'ดร. เอ็มเบดการ์ เกิดในครอบครัวจัณฑาลที่ยากจนและต้องอดทนจากการดูถูกเหยียดหยาม กระนั้นท่านก็ต่อสู้กับอุปสรรคที่มาพร้อมกับชาติกำเนิดและตั้งปณิธานแน่วแน่ว่าจะต้องทำให้สังคมอินเดียยอมรับศักดิ์ศรีความเป็นมนุษย์อย่างเท่าเทียมกัน ด้วยการขวนขวายหาความรู้จนจบการศึกษาระดับปริญญาเอก จนได้เป็นผู้มีบทบาทสำคัญในรัฐบาลอินเดีย และช่วยร่างกฎหมายหลายฉบับที่ช่วยยกระดับความเท่าเทียมของประชาชนชาวอินเดีย
จากเรื่องราวของ ดร. เอ็มเบดการ์ ที่ยกมาข้างต้นสอดคล้องกับบารมีจากทศชาดกในข้อใดมากที่สุด','["วิริยบารมี ขันติบารมี ปัญญาบารมี", "ทานบารมี วิริยบารมี ศีลบารมี", "ขันติบารมี เนกขัมมบารมี อุเบกขาบารมี", "เนกขัมมบารมี อธิษฐานบารมี สัจจบารมี", "สัจจบารมี อธิษฐานบารมี เมตตาบารมี"]'::jsonb,0,array[0]::smallint[],'["ทศชาติชาดกกับบารมี 10: เตมีย์–เนกขัมม มหาชนก–วิริยะ สุวรรณสาม–เมตตา เนมิราช–อธิษฐาน มโหสถ–ปัญญา ภูริทัต–ศีล จันทกุมาร–ขันติ นารทะ–อุเบกขา วิธุรบัณฑิต–สัจจะ เวสสันดร–ทาน · ดร.เอ็มเบดการ์ อดทนต่อการดูถูก (ขันติ) ต่อสู้อุปสรรคไม่ย่อท้อ (วิริยะ) ขวนขวายความรู้จนจบปริญญาเอกและร่างกฎหมาย (ปัญญา)"]'::jsonb,'["ถูก ความเพียรต่อสู้อุปสรรค (วิริยะ) ความอดทนต่อการเหยียดหยาม (ขันติ) และการใช้ความรู้ยกระดับสังคม (ปัญญา) ตรงกับเรื่องราวมากที่สุด", "เรื่องราวไม่ได้เน้นการให้ทาน และไม่ได้เน้นการรักษาศีล", "ขันติตรง แต่เนกขัมม (การออกจากกาม/ออกบวช) และอุเบกขา (การวางใจเป็นกลาง) ไม่ใช่จุดเด่นของเรื่อง", "มีความตั้งใจแน่วแน่ (อธิษฐาน) อยู่บ้าง แต่เนกขัมมและสัจจะไม่ใช่ประเด็นหลัก และขาดวิริยะ ปัญญา ที่ชัดเจนกว่า", "สัจจะและเมตตาไม่ใช่ประเด็นหลักของเรื่อง และขาดความเพียรกับปัญญาที่เห็นชัด"]'::jsonb,'{"topic": "1.1", "n": 1}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-1');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-2','M6','M6-SO','M6-SO-S1','A-Level 70',null,2,'นายภาคภูมิรู้สึกอึดอัดใจกับงานที่ทำอยู่ แม้จะมีค่าตอบแทนสูง แต่ก็ต้องทำผิดกฎหมายบางอย่างอยู่เสมอ เขาจึงตัดสินใจลาออกจากงานดังกล่าวเพื่อไปทำงานสุจริตที่มีรายได้น้อยกว่า เมื่อเพื่อนของเขาทักท้วงว่าการกระทำเช่นนั้นทำให้ขาดรายได้โดยไม่จำเป็น นายภาคภูมิจึงอธิบายว่า “การงานที่ทุจริตนั้นช่วยให้ได้เงินก้อนใหญ่ก็จริง แต่ก็สร้างบาปกรรมและความผิดทางกฎหมายที่ต้องเจอในระยะยาว ฉันเลยเลือกความสุจริตแม้จะจนลงแต่ก็สบายใจ”
การพิจารณาเรื่องการงานของนายภาคภูมิข้างต้น สอดคล้องกับวิธีคิดแบบโยนิโสมนสิการในข้อใดมากที่สุด','["วิธีคิดแบบสืบสาวเหตุปัจจัย", "วิธีคิดแบบคุณค่าแท้–คุณค่าเทียม", "วิธีคิดแบบแยกแยะส่วนประกอบ", "วิธีคิดแบบเป็นอยู่ในขณะปัจจุบัน", "วิธีคิดแบบเห็นคุณ-โทษ และทางออก"]'::jsonb,4,array[4]::smallint[],'["โยนิโสมนสิการ (คิดอย่างแยบคาย) มีหลายวิธี เช่น สืบสาวเหตุปัจจัย แยกแยะส่วนประกอบ คุณค่าแท้–คุณค่าเทียม คุณ–โทษ–ทางออก อยู่กับปัจจุบัน นายภาคภูมิชั่งข้อดี (เงินมาก) ข้อเสีย (บาป ผิดกฎหมาย) แล้วเลือกทางออก (งานสุจริต) = วิธีคิดแบบคุณ–โทษ และทางออก"]'::jsonb,'["สืบสาวเหตุปัจจัยคือการหาสาเหตุของปัญหาย้อนกลับไป แต่นายภาคภูมิกำลังชั่งข้อดีข้อเสียเพื่อเลือกทาง", "คุณค่าแท้–คุณค่าเทียมใช้พิจารณาการบริโภค/การใช้สิ่งของว่าตอบสนองความจำเป็นแท้หรือความอยาก ไม่ตรงกับการชั่งข้อดีข้อเสียของงาน", "แยกแยะส่วนประกอบคือการแยกสิ่งหนึ่งออกเป็นองค์ประกอบย่อย (เช่น ขันธ์ 5) ไม่ใช่กรณีนี้", "อยู่ในขณะปัจจุบันคือการคิดเรื่องที่ต้องทำตอนนี้ ไม่กังวลอดีต/อนาคต แต่นายภาคภูมิคิดถึงผลระยะยาว", "ถูก เห็นคุณ (ได้เงินก้อนใหญ่) เห็นโทษ (บาปกรรม ผิดกฎหมาย) และเลือกทางออก (งานสุจริต แม้จนแต่สบายใจ)"]'::jsonb,'{"topic": "1.1", "n": 2}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-2');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-3','M6','M6-SO','M6-SO-S1','A-Level 70',null,2,'“เมื่อสิ่งนี้มี สิ่งนี้จึงมี เพราะสิ่งนี้เกิดขึ้น สิ่งนี้จึงเกิดขึ้น เมื่อสิ่งนี้ไม่มี สิ่งนี้ก็ไม่มี เพราะสิ่งนี้ดับ สิ่งนี้จึงดับ” ตรงกับตัวเลือกใดในคำสอนพุทธศาสนา','["อริยสัจ 4", "โลกธรรม 8", "อิทัปปัจจยตา", "สาราณียธรรม 6", "อปริหานิยธรรม 7"]'::jsonb,2,array[2]::smallint[],'["อิทัปปัจจยตา = กฎความเป็นเหตุปัจจัยของสิ่งทั้งหลาย “เมื่อสิ่งนี้มี สิ่งนี้จึงมี เพราะสิ่งนี้เกิด สิ่งนี้จึงเกิด เมื่อสิ่งนี้ไม่มี สิ่งนี้ก็ไม่มี เพราะสิ่งนี้ดับ สิ่งนี้จึงดับ”"]'::jsonb,'["อริยสัจ 4 คือ ทุกข์ สมุทัย นิโรธ มรรค ใช้หลักเหตุผล แต่ข้อความในโจทย์เป็นบทนิยามของอิทัปปัจจยตาโดยตรง", "โลกธรรม 8 คือ ได้ลาภ–เสื่อมลาภ ได้ยศ–เสื่อมยศ สรรเสริญ–นินทา สุข–ทุกข์ ไม่เกี่ยวกับข้อความนี้", "ถูก ข้อความในโจทย์คือคำนิยามของอิทัปปัจจยตา (หลักความเป็นเหตุเป็นผลที่อาศัยกันเกิด)", "สาราณียธรรม 6 เป็นหลักการอยู่ร่วมกันในหมู่คณะ", "อปริหานิยธรรม 7 เป็นธรรมที่ไม่ทำให้หมู่คณะเสื่อม"]'::jsonb,'{"topic": "1.1", "n": 3}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-3');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-4','M6','M6-SO','M6-SO-S1','A-Level 70',null,2,'เพื่อนสนิทที่คบกันมาตั้งแต่เด็กของนายสมภพมายืมเงินจำนวนมากโดยสัญญาว่าจะคืนให้ภายในเวลาที่กำหนด ด้วยความไว้ใจนายสมภพจึงให้เพื่อนยืมเงินเก็บไปเกือบทั้งหมด ภายหลังพบว่าเพื่อนไปพูดลับหลังในทางที่ไม่ดีและไม่มีความสามารถที่จะคืนเงินได้ ทำให้นายสมภพทั้งเสียใจและโมโหจนไม่เป็นอันกินอันนอน แต่บางครั้งก็ยังสงสารเพื่อนจับใจ
พุทธศาสนสุภาษิตเหล่านี้สามารถนำไปใช้เตือนสตินายสมภพได้ยกเว้นข้อใด','["สติ โลกสฺมิ ชาคโร", "โกธํ ฆตฺวา สุขํ เสติ", "อิณาทานํ ทุกฺขํ โลเก", "นตฺถิ โลเก อนินฺทิโต", "น อุจฺจาวจํ ปณฺฑิตา ทสฺสยนฺติ"]'::jsonb,2,array[2]::smallint[],'["เลือกสุภาษิตที่ “ไม่” ใช้เตือนสตินายสมภพ (ผู้ให้ยืม เสียใจ โมโห ถูกนินทา) · สติ โลกสฺมิ ชาคโร = สติเป็นเครื่องตื่นในโลก · โกธํ ฆตฺวา สุขํ เสติ = ฆ่าความโกรธได้ย่อมอยู่เป็นสุข · อิณาทานํ ทุกฺขํ โลเก = การกู้หนี้เป็นทุกข์ในโลก · นตฺถิ โลเก อนินฺทิโต = คนที่ไม่ถูกนินทาไม่มีในโลก · น อุจฺจาวจํ ปณฺฑิตา ทสฺสยนฺติ = บัณฑิตย่อมไม่แสดงอาการขึ้น ๆ ลง ๆ"]'::jsonb,'["ใช้เตือนได้ ให้มีสติตื่นรู้ ไม่จมอยู่กับความเสียใจและความโกรธ", "ใช้เตือนได้ นายสมภพโมโหจนกินไม่ได้นอนไม่หลับ ถ้าละความโกรธได้ก็เป็นสุข", "ใช้เตือนไม่ได้ (คำตอบ) “การกู้หนี้เป็นทุกข์” เตือนผู้ที่ไปกู้ยืม (เพื่อน) ไม่ใช่เตือนนายสมภพผู้ให้ยืม", "ใช้เตือนได้ นายสมภพถูกเพื่อนพูดลับหลัง สุภาษิตนี้ช่วยให้ยอมรับว่าการถูกนินทาเป็นธรรมดาของโลก", "ใช้เตือนได้ ช่วยให้นายสมภพไม่หวั่นไหวไปกับอารมณ์ขึ้นลง (เสียใจ โมโห สงสาร)"]'::jsonb,'{"topic": "1.1", "n": 4}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-4');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-5','M6','M6-SO','M6-SO-S1','A-Level 70',null,2,'ข้อใดกล่าว ไม่ถูกต้อง ตามหลักคำสอนของศาสนาอิสลาม','["มนุษย์ควรแสวงหาความประนีประนอมเมื่อถูกข่มเหง", "มนุษย์ดีชั่วต่างกันเพราะการปฏิบัติตามคำสอนของพระเจ้า", "มนุษย์ควรรักษาความยุติธรรมเหนือความสัมพันธ์ในครอบครัว", "มนุษย์มีเสรีภาพในการเลือกนับถือศาสนา แต่ต้องรับผลจากการตัดสินใจของตน", "มนุษย์ควรให้ความยำเกรงต่อนักบวช ผู้มีหน้าที่ปฏิบัติศาสนกิจใกล้ชิดพระเจ้า"]'::jsonb,4,array[4]::smallint[],'["อิสลามไม่มีระบบนักบวชเป็นตัวกลางระหว่างมนุษย์กับพระเจ้า มุสลิมทุกคนติดต่อกับอัลลอฮ์โดยตรง (อิหม่ามเป็นผู้นำละหมาด ไม่ใช่นักบวช) · อิสลามสอนความยุติธรรม เสรีภาพในการนับถือศาสนา (ไม่มีการบังคับในศาสนา) และความประนีประนอม"]'::jsonb,'["ถูกต้องตามหลักอิสลาม ส่งเสริมการให้อภัยและการประนีประนอม", "ถูกต้อง ความดีความชั่วของมนุษย์วัดจากการปฏิบัติตามคำสอนของพระเจ้า", "ถูกต้อง อัลกุรอานสอนให้ดำรงความยุติธรรมแม้จะขัดกับประโยชน์ของตนหรือญาติ", "ถูกต้อง “ไม่มีการบังคับในศาสนา” แต่ทุกคนต้องรับผลจากการกระทำของตน", "ไม่ถูกต้อง (คำตอบ) อิสลามไม่มีนักบวชที่ใกล้ชิดพระเจ้ากว่าคนอื่น มุสลิมยำเกรงอัลลอฮ์เท่านั้น"]'::jsonb,'{"topic": "1.3", "n": 5}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-5');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-6','M6','M6-SO','M6-SO-S1','A-Level 70',null,2,'การปฏิบัติตนของศาสนิกชนในข้อใดไม่ถือเป็นการละเมิดข้อห้ามตามหลักศาสนาที่ตนนับถือ','["นายภาวีอยู่ในวรรณะศูทรและทำพิธีสัมสการ", "นายอารีนับถือศาสนาซิกข์และดื่มไวน์ในงานรื่นเริง", "นางสาวมีนาเป็นมุสลิมและไปดูดวงก่อนเริ่มทำงานใหม่", "นายนาวีเป็นชาวพุทธและถือศีลอดร่วมกับเพื่อนชาวมุสลิม", "นางสาวนารีเป็นชาวคริสต์และทำงานหนักทุกวันไม่มีวันหยุด"]'::jsonb,3,array[3]::smallint[],'["ข้อห้ามของแต่ละศาสนา: พราหมณ์–ฮินดู สังสการสำหรับวรรณะทวิชาติ (ศูทรไม่มีสิทธิ์) · ซิกข์ ห้ามเสพของมึนเมา · อิสลาม ห้ามดูดวง/เชื่อโชคลาง (ขัดหลักศรัทธา) · คริสต์ ให้ถือวันพระเจ้า (วันสะบาโต/วันอาทิตย์) เป็นวันพักผ่อน · พุทธ ไม่มีข้อห้ามการอดอาหารร่วมกับเพื่อน"]'::jsonb,'["ละเมิด ศูทรไม่ใช่วรรณะทวิชาติ จึงไม่มีสิทธิ์ทำพิธีสังสการ", "ละเมิด ซิกข์ห้ามดื่มของมึนเมาทุกชนิด", "ละเมิด มุสลิมห้ามดูดวงหรือเชื่อหมอดู เพราะการรู้อนาคต (สิ่งเร้นลับ) เป็นของอัลลอฮ์เท่านั้น", "ไม่ละเมิด (คำตอบ) พุทธศาสนาไม่มีข้อห้ามการอดอาหาร การถือศีลอดร่วมกับเพื่อนเป็นการเคารพและเข้าใจผู้อื่น", "ละเมิด บัญญัติ 10 ประการให้ระลึกถึงวันสะบาโต ถือเป็นวันบริสุทธิ์ หยุดพักจากการงาน"]'::jsonb,'{"topic": "1.3", "n": 6}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-6');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-7','M6','M6-SO','M6-SO-S1','A-Level 70',null,2,'คัมภีร์ในข้อใดมีเนื้อหาใกล้เคียงกับวจนะที่ศาสดาของศาสนานั้นเผยแผ่มากที่สุด','["พุทธธรรม – พุทธ", "พระเวท – พราหมณ์", "อัลกุรอาน – อิสลาม", "มนูธรรมศาสตร์ – ฮินดู", "พันธสัญญาเดิม – คริสต์"]'::jsonb,2,array[2]::smallint[],'["อัลกุรอานคือพระวจนะของอัลลอฮ์ที่ประทานผ่านนบีมุฮัมมัด และถูกบันทึกเป็นเล่มไม่นานหลังท่านเสียชีวิต จึงใกล้กับถ้อยคำที่ศาสดาเผยแผ่มากที่สุด ส่วนตัวเลือกอื่นเป็นงานอธิบาย/กฎหมาย หรือศาสนาที่ไม่มีศาสดา"]'::jsonb,'["ไม่ถูก “พุทธธรรม” เป็นหนังสืออธิบายหลักธรรมสมัยใหม่ (ของพระพรหมคุณาภรณ์) ไม่ใช่คัมภีร์หลัก (คัมภีร์หลักคือพระไตรปิฎก)", "ไม่ถูก พราหมณ์ไม่มีศาสดาผู้ก่อตั้ง พระเวทเชื่อว่าเป็นสิ่งที่ฤษีได้ยินจากเทพ (ศรุติ)", "ถูก อัลกุรอานถูกจดจำและรวบรวมเป็นเล่มเดียวไม่นานหลังนบีมุฮัมมัด จึงใกล้กับถ้อยคำที่ศาสดาเผยแผ่ที่สุด", "ไม่ถูก มนูธรรมศาสตร์เป็นคัมภีร์กฎหมาย/จารีต (สมฤติ) ไม่ใช่คำสอนของศาสดา และฮินดูไม่มีศาสดา", "ไม่ถูก พันธสัญญาเดิมเขียนก่อนสมัยพระเยซู คำสอนของพระเยซูอยู่ในพันธสัญญาใหม่ (พระวรสาร)"]'::jsonb,'{"topic": "1.3", "n": 7}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-7');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-8','M6','M6-SO','M6-SO-S1','A-Level 70',null,2,'ข้อใดกล่าวไม่ถูกต้อง','["ชาวซิกข์ไม่ตัดผมเพราะผมเป็นสิ่งที่พระเจ้าประทานมา", "ชาวมุสลิมห้ามคิดดอกเบี้ยจากเงินกู้เพราะจะทำให้เกียจคร้าน", "พระภิกษุต้องอยู่จำพรรษาเพราะจะได้ไม่ทำให้นาข้าวเสียหาย", "ชาวคริสต์รับขนมปังและเหล้าองุ่นเพื่อเฉลิมฉลองความอุดมสมบูรณ์ที่พระเจ้าประทานให้", "นักบวชเชนนิกายทิคัมพรไม่นุ่งผ้า มีเพียงไม้กวาดและผ้ากรองน้ำติดตัว เพราะไม่ต้องการเบียดเบียนสัตว์อื่น"]'::jsonb,3,array[3]::smallint[],'["ที่มาของหลักปฏิบัติ: ซิกข์ไว้ผมยาว (เกศ) เพราะถือว่าเป็นสิ่งที่พระเจ้าประทาน · อิสลามห้ามดอกเบี้ย (ริบา) เพราะเป็นการเอาเปรียบและได้ประโยชน์โดยไม่ต้องทำงาน · เข้าพรรษาเพราะชาวบ้านติเตียนว่าภิกษุเดินเหยียบข้าวกล้า · ศีลมหาสนิท (ขนมปังและเหล้าองุ่น) ระลึกถึงพระกายและพระโลหิตของพระเยซูในอาหารมื้อสุดท้าย · ทิคัมพรไม่นุ่งผ้า เพื่อละความยึดติดและไม่เบียดเบียน"]'::jsonb,'["ถูกต้อง การไม่ตัดผมเป็นหนึ่งใน “5 ก” ของซิกข์ ถือว่าผมเป็นสิ่งที่พระเจ้าประทาน", "ถูกต้องตามเฉลย อิสลามห้ามดอกเบี้ยเพราะเป็นการเอาเปรียบผู้อื่น และได้ผลประโยชน์โดยไม่ต้องทำงาน (ทำให้เกียจคร้าน)", "ถูกต้อง พระพุทธเจ้าทรงบัญญัติให้จำพรรษาในฤดูฝน เพื่อไม่ให้ภิกษุเดินทางเหยียบย่ำพืชผลของชาวบ้าน", "ไม่ถูกต้อง (คำตอบ) การรับขนมปังและเหล้าองุ่นคือศีลมหาสนิท ระลึกถึงพระกายและพระโลหิตของพระเยซู ไม่ใช่การฉลองความอุดมสมบูรณ์", "ถูกต้องตามเฉลย นักบวชเชนนิกายทิคัมพรไม่นุ่งผ้า พกเพียงสิ่งจำเป็นเพื่อป้องกันการทำร้ายสัตว์เล็ก"]'::jsonb,'{"topic": "1.3", "n": 8}'::jsonb,'imported_m6','imported',true,'expl','ตัวเลือก 2 และ 5 ใช้เหตุผลตามหนังสือเรียนไทยบางเล่ม (เช่น ทิคัมพรพกไม้กวาดขนนกยูงและภาชนะน้ำ) ครูอาจเสริมรายละเอียด',2569,'soc:69-8');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-9','M6','M6-SO','M6-SO-S1','A-Level 70',null,2,'ฟ้าเป็นชาวพุทธ ส่วนฝนเป็นชาวมุสลิม ข้อใดต่อไปนี้เป็น “ศรัทธา” ที่ถูกต้องตามศาสนา','["ฟ้าเชื่อมั่นว่าเธอจะมีชีวิตที่ดีขึ้นกว่าเดิมได้หากขยันทำงาน ฝนเชื่อมั่นในอัลกุรอาน", "ฟ้าเชื่อมั่นว่าเมื่อตายแล้วดับสูญ ฝนเชื่อมั่นในการละหมาด", "ฟ้าเชื่อมั่นในพระพุทธเจ้า ฝนเชื่อมั่นว่าเมื่อตายแล้วจะกลายเป็นหนึ่งเดียวกับพระเจ้า", "ฟ้าเชื่อมั่นว่าการสวดมนต์สม่ำเสมอจะทำให้พระคุ้มครอง ฝนเชื่อมั่นในพระเจ้าองค์เดียว", "ฟ้าเชื่อมั่นว่าเมื่อตายแล้วจะมีการเกิดใหม่ไม่สิ้นสุด ฝนเชื่อมั่นในญิบรีลผู้นำสาส์นมาแจ้งต่อนบีมุฮัมมัด"]'::jsonb,0,array[0]::smallint[],'["ศรัทธาในพุทธ (ศรัทธา 4): กัมมสัทธา (เชื่อกรรม) วิปากสัทธา (เชื่อผลของกรรม) กัมมัสสกตาสัทธา (เชื่อว่าสัตว์มีกรรมเป็นของตน) ตถาคตโพธิสัทธา (เชื่อการตรัสรู้ของพระพุทธเจ้า) · หลักศรัทธา 6 ของอิสลาม: อัลลอฮ์ มลาอิกะฮ์ คัมภีร์ ศาสนทูต วันสิ้นโลก กฎกำหนดสภาวการณ์"]'::jsonb,'["ถูก ฟ้าเชื่อว่าการกระทำ (ขยันทำงาน) ส่งผลดี = เชื่อกรรมและผลของกรรม ฝนเชื่อในคัมภีร์อัลกุรอาน = หลักศรัทธาข้อหนึ่ง", "ไม่ถูก “ตายแล้วสูญ” เป็นมิจฉาทิฏฐิในพุทธ และการละหมาดเป็นหลักปฏิบัติ ไม่ใช่หลักศรัทธา", "ไม่ถูก การรวมเป็นหนึ่งเดียวกับพระเจ้าไม่ใช่ความเชื่อของอิสลาม (เป็นแนวคิดฮินดู/ซิกข์)", "ไม่ถูก การเชื่อว่าสวดมนต์แล้วพระคุ้มครองเป็นความเชื่อเชิงอำนาจเหนือธรรมชาติ ไม่ใช่ศรัทธา 4", "ไม่ถูก พุทธสอนว่าการเกิดใหม่สิ้นสุดได้เมื่อบรรลุนิพพาน ไม่ใช่ไม่สิ้นสุด (ส่วนของฝนถูก)"]'::jsonb,'{"topic": "1.3", "n": 9}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-9');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-10','M6','M6-SO','M6-SO-S1','A-Level 70',null,2,'ข้อใด ไม่ถูกต้อง เกี่ยวกับเป้าหมายสูงสุดของแต่ละศาสนา','["ศาสนาพุทธ มุ่งไปสู่การดับทุกข์", "ศาสนาพราหมณ์-ฮินดู มุ่งไปสู่โมกษะเพื่อการดับสูญ", "ศาสนาอิสลาม มุ่งไปสู่การได้พบพระอัลลอฮ์บนสวรรค์", "ศาสนาซิกข์มุ่งไปสู่การหลอมรวมเป็นหนึ่งเดียวกับพระเจ้า", "ศาสนาคริสต์มุ่งไปสู่ชีวิตนิรันดรในอาณาจักรของพระเจ้า"]'::jsonb,1,array[1]::smallint[],'["เป้าหมายสูงสุด: พุทธ – นิพพาน (ดับทุกข์) · พราหมณ์–ฮินดู – โมกษะ คืออาตมันรวมเป็นหนึ่งเดียวกับปรมาตมัน/พรหมัน พ้นจากการเวียนว่ายตายเกิด ไม่ใช่การดับสูญ · อิสลาม – สวรรค์ (ได้พบอัลลอฮ์) · ซิกข์ – รวมเป็นหนึ่งกับพระเจ้า · คริสต์ – ชีวิตนิรันดร์ในอาณาจักรของพระเจ้า"]'::jsonb,'["ถูกต้อง พุทธมุ่งสู่นิพพาน คือความดับทุกข์", "ไม่ถูกต้อง (คำตอบ) โมกษะคือการที่อาตมันกลับไปรวมกับปรมาตมัน ไม่ใช่การดับสูญ", "ถูกต้อง อิสลามมุ่งสู่สวรรค์และการได้พบอัลลอฮ์ในโลกหน้า", "ถูกต้อง ซิกข์มุ่งสู่การรวมเป็นหนึ่งเดียวกับพระเจ้า", "ถูกต้อง คริสต์มุ่งสู่ชีวิตนิรันดร์ในอาณาจักรของพระเจ้า"]'::jsonb,'{"topic": "1.3", "n": 10}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-10');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-11','M6','M6-SO','M6-SO-S2','A-Level 70',null,2,'ข้อใดต่อไปนี้เป็นความผิดฐานยักยอกทรัพย์','["นางกชพรรณนำรถประจำตำแหน่งที่บริษัทมอบให้ใช้ปฏิบัติงานไปขายต่อ", "นายขจรเกียรติกระชากกระเป๋าแบรนด์เนมที่นางสาวกชกรเพิ่งซื้อมา", "นายขจรศักดิ์ลักลอบหยิบแหวนเพชรที่นางสาวกชณิชาวางไว้บนโต๊ะไปขายต่อ", "นายขจรเดชขู่นางสาวกชวิภาว่าหากไม่เอาเงินมาให้จะนำรูปส่วนตัวไปเผยแพร่เพื่อประจาน", "กลุ่มคนร้ายจำนวน 4 คน บุกปล้นเงินสดจากธนาคารไทยเจริญเป็นจำนวน 30,000,000 บาท"]'::jsonb,0,array[0]::smallint[],'["ความผิดเกี่ยวกับทรัพย์ (ป.อ.): ยักยอก = ครอบครองทรัพย์ของผู้อื่นอยู่แล้วเบียดบังเป็นของตน · ลักทรัพย์ = เอาทรัพย์ผู้อื่นไปโดยทุจริต · วิ่งราวทรัพย์ = ลักทรัพย์โดยฉกฉวยซึ่งหน้า · รีดเอาทรัพย์ = ขู่ว่าจะเปิดเผยความลับ · ปล้นทรัพย์ = ชิงทรัพย์ร่วมกันตั้งแต่ 3 คนขึ้นไป"]'::jsonb,'["ถูก (ยักยอก) นางกชพรรณครอบครองรถของบริษัทอยู่แล้วโดยชอบ แต่เบียดบังไปขาย", "ไม่ใช่ เป็นการวิ่งราวทรัพย์ (ฉกฉวยเอาซึ่งหน้า)", "ไม่ใช่ เป็นการลักทรัพย์ (ทรัพย์ไม่ได้อยู่ในความครอบครองของผู้กระทำ)", "ไม่ใช่ เป็นการรีดเอาทรัพย์ (ขู่ว่าจะเปิดเผยความลับ/ภาพส่วนตัว)", "ไม่ใช่ เป็นการปล้นทรัพย์ (ร่วมกันชิงทรัพย์ตั้งแต่ 3 คนขึ้นไป)"]'::jsonb,'{"topic": "2.2", "n": 11}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-11');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-12','M6','M6-SO','M6-SO-S2','A-Level 70',null,2,'ข้อใด ไม่ใช่ การกระทำผิดทางอาญาในราชอาณาจักรไทย','["นางดารณีวางยาพิษในอาหารของนายรัฐพลจนเป็นเหตุให้นายรัฐพลถึงแก่ความตาย ขณะอยู่บนเรือสัญชาติไทยในน่านน้ำสากล", "นายอภิสิทธิ์เจตนาผลักนายอภิชัยซึ่งว่ายน้ำไม่เป็นตกลงไปในทะเลชายฝั่งประเทศไทยจนเป็นเหตุให้นายอภิชัยจมน้ำถึงแก่ความตาย", "นางสาวอภิรดีทำร้ายร่างกายนางสาวอิสรีย์บนอากาศยานสัญชาติไทย เนื่องจากไม่พอใจที่อีกฝ่ายไม่หลีกทางให้", "นายสุรเดชขโมยโทรศัพท์มือถือของนายสุรชัยภายในห้องน้ำสถานกงสุลไทยในต่างประเทศเพื่อนำไปเป็นของตน", "นางสาวธรรมรักษ์ขับรถยนต์บนถนนเพชรเกษมด้วยความเร็ว 150 กิโลเมตรต่อชั่วโมง เฉี่ยวชนนางสาวอรอุมาถึงแก่ความตาย"]'::jsonb,3,array[3]::smallint[],'["ความผิดในราชอาณาจักร (ป.อ. ม.4): ครอบคลุมดินแดน น่านน้ำ (ทะเลอาณาเขต) ห้วงอากาศของไทย และถือว่าความผิดบนเรือไทยหรืออากาศยานไทยไม่ว่าอยู่ที่ใดเป็นความผิดในราชอาณาจักร · สถานทูต/สถานกงสุลไทยในต่างประเทศไม่ใช่ดินแดนไทย"]'::jsonb,'["เป็นความผิดในราชอาณาจักร เรือสัญชาติไทยแม้อยู่ในน่านน้ำสากลถือเป็นราชอาณาจักร", "เป็นความผิดในราชอาณาจักร ทะเลชายฝั่ง (ทะเลอาณาเขต) เป็นส่วนหนึ่งของราชอาณาจักร", "เป็นความผิดในราชอาณาจักร อากาศยานสัญชาติไทยถือเป็นราชอาณาจักร", "ไม่ใช่ (คำตอบ) สถานกงสุลไทยในต่างประเทศอยู่ในดินแดนของประเทศนั้น ไม่ใช่ราชอาณาจักรไทย", "เป็นความผิดในราชอาณาจักร เกิดบนถนนในประเทศไทย"]'::jsonb,'{"topic": "2.2", "n": 12}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-12');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-13','M6','M6-SO','M6-SO-S2','A-Level 70',null,2,'สถานการณ์ใดต่อไปนี้ไม่สามารถฟ้องหย่าได้','["สามีเดินทางไปทำงาน ณ ประเทศออสเตรเลียเป็นเวลากว่า 4 ปี โดยไม่มีผู้ใดทราบแน่ชัดว่าเป็นตายร้ายดีอย่างไร", "สามีต้องคำพิพากษาถึงที่สุดให้จำคุก 2 ปี ในคดีลักทรัพย์ซึ่งภรรยามีส่วนร่วมกระทำความผิดโดยเป็นผู้ดูต้นทาง", "สามีบันดาลโทสะและกล่าววาจาหมิ่นประมาทบุพการีของภรรยาด้วยถ้อยคำหยาบคายอย่างร้ายแรงในที่สาธารณะ", "สามีและภรรยาสมัครใจแยกกันอยู่เพราะเหตุที่ไม่อาจอยู่ร่วมกันได้โดยปกติสุขตลอดมาเกิน 5 ปี", "สามีก่อหนี้สินจากการพนัน จำนวน 10,000,000 บาท เป็นเหตุให้เจ้าหนี้ติดตามทวงถามและข่มขู่ภรรยาทุกวัน"]'::jsonb,1,array[1]::smallint[],'["เหตุฟ้องหย่า (ป.พ.พ. ม.1516) เช่น หมิ่นประมาท/เหยียดหยามบุพการีของอีกฝ่าย · จากไปเกิน 3 ปีโดยไม่มีใครทราบว่าเป็นตายร้ายดี · ต้องคำพิพากษาให้จำคุกเกิน 1 ปีในความผิดที่อีกฝ่ายไม่ได้มีส่วนร่วมหรือยินยอม · สมัครใจแยกกันอยู่เกิน 3 ปี · ประพฤติชั่วทำให้อีกฝ่ายเดือดร้อนเกินควร"]'::jsonb,'["ฟ้องหย่าได้ สามีจากไปเกิน 3 ปีโดยไม่มีใครทราบว่าเป็นตายร้ายดี", "ฟ้องหย่าไม่ได้ (คำตอบ) ภรรยามีส่วนร่วมกระทำความผิด (ดูต้นทาง) จึงอ้างเหตุสามีถูกจำคุกมาฟ้องหย่าไม่ได้", "ฟ้องหย่าได้ การหมิ่นประมาทหรือเหยียดหยามบุพการีของอีกฝ่ายเป็นเหตุฟ้องหย่า", "ฟ้องหย่าได้ สมัครใจแยกกันอยู่เพราะอยู่ร่วมกันไม่ได้โดยปกติสุขเกิน 3 ปี (โจทย์ 5 ปี)", "ฟ้องหย่าได้ การเล่นพนันจนเป็นหนี้และทำให้ภรรยาถูกข่มขู่ เป็นการประพฤติชั่วที่ทำให้อีกฝ่ายเดือดร้อนเกินควร"]'::jsonb,'{"topic": "2.2", "n": 13}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-13');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-14','M6','M6-SO','M6-SO-S2','A-Level 70',null,2,'นายธนโชติและนางธนรัตน์เป็นคู่สมรสที่จดทะเบียนสมรสโดยชอบด้วยกฎหมายทรัพย์สินในข้อใดมีสถานะทางกฎหมายแตกต่างจากข้ออื่น','["บ้านเดี่ยวที่นายธนโชติทำสัญญาซื้อขายและได้กรรมสิทธิ์มาก่อนสมรส", "ทรัพย์มรดกที่นางธนรัตน์ได้รับจากมารดาซึ่งถึงแก่กรรมในระหว่างสมรส", "ดอกเบี้ยที่งอกเงยขึ้นในระหว่างสมรสจากเงินออมส่วนตัวของนางธนรัตน์", "เสื้อผ้าที่นายธนโชติจัดซื้อด้วยเงินได้ระหว่างสมรสเพื่อใช้สอยส่วนตัว", "ทองคำและเงินสดที่เป็นของหมั้นที่นายธนโชติมอบให้แก่นางธนรัตน์"]'::jsonb,2,array[2]::smallint[],'["ทรัพย์สินระหว่างสามีภรรยา: สินส่วนตัว (ม.1471) = ทรัพย์ที่มีก่อนสมรส เครื่องใช้สอยส่วนตัว มรดก/ของที่ได้โดยเสน่หาระหว่างสมรส ของหมั้น · สินสมรส (ม.1474) = ทรัพย์ที่ได้มาระหว่างสมรส มรดก/ของให้ที่ระบุเป็นสินสมรส และ “ดอกผลของสินส่วนตัว”"]'::jsonb,'["สินส่วนตัว ทรัพย์ที่มีก่อนสมรส", "สินส่วนตัว มรดกที่ได้ระหว่างสมรส (ถ้าไม่ระบุว่าให้เป็นสินสมรส)", "สินสมรส (คำตอบ) ดอกเบี้ยเป็นดอกผลของสินส่วนตัว กฎหมายกำหนดให้ดอกผลของสินส่วนตัวเป็นสินสมรส", "สินส่วนตัว เครื่องใช้สอยส่วนตัว เช่น เสื้อผ้า ตามสมควรแก่ฐานานุรูป", "สินส่วนตัว ของหมั้นเป็นสินส่วนตัวของฝ่ายหญิง"]'::jsonb,'{"topic": "2.2", "n": 14}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-14');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-15','M6','M6-SO','M6-SO-S2','A-Level 70',null,2,'ในปี พ.ศ. 2568 มีการปะทะด้วยอาวุธตามแนวชายแดนไทยและกัมพูชา องค์กรใดของสหประชาชาติที่มีหน้าที่หลักในการระงับความขัดแย้งและรักษาสันติภาพจากกรณีดังกล่าว','["คณะมนตรีความมั่นคงแห่งสหประชาชาติ", "คณะมนตรีภาวะทรัสตี", "ศาลยุติธรรมระหว่างประเทศ", "คณะมนตรีเศรษฐกิจและสังคมสหประชาชาติ", "สำนักงานเลขาธิการสหประชาชาติ"]'::jsonb,0,array[0]::smallint[],'["คณะมนตรีความมั่นคงแห่งสหประชาชาติ (UNSC) มีหน้าที่หลักในการธำรงสันติภาพและความมั่นคงระหว่างประเทศ ระงับข้อพิพาท และอาจกำหนดมาตรการต่าง ๆ รวมถึงปฏิบัติการรักษาสันติภาพ"]'::jsonb,'["ถูก UNSC รับผิดชอบหลักด้านสันติภาพและความมั่นคง และตัดสินใจมาตรการระงับความขัดแย้ง", "ไม่ถูก คณะมนตรีภาวะทรัสตีดูแลดินแดนในภาวะทรัสตี ปัจจุบันระงับการทำงานแล้ว", "ไม่ถูก ศาลยุติธรรมระหว่างประเทศพิจารณาคดีพิพาทระหว่างรัฐเมื่อรัฐยินยอม ไม่ได้มีหน้าที่หลักรักษาสันติภาพ", "ไม่ถูก ECOSOC ดูแลด้านเศรษฐกิจ สังคม และการพัฒนา", "ไม่ถูก สำนักงานเลขาธิการทำงานบริหาร/ธุรการ เลขาธิการเสนอเรื่องต่อ UNSC ได้ แต่ไม่มีอำนาจตัดสินใจหลัก"]'::jsonb,'{"topic": "2.3", "n": 15}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-15');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-16','M6','M6-SO','M6-SO-S2','A-Level 70',null,2,'ในกรณีที่มีการกล่าวหาว่ารัฐมนตรีกระทำการฝ่าฝืนหรือไม่ปฏิบัติตามมาตรฐานทางจริยธรรมอย่างร้ายแรง องค์กรใดมีอำนาจหน้าที่ในการไต่สวน และหากคดีมีมูล จะต้องยื่นคำร้องต่อศาลใดเพื่อวินิจฉัย','["คณะกรรมการป้องกันและปราบปรามทุจริตแห่งชาติ และ ศาลฎีกา", "คณะกรรมการป้องกันและปราบปรามทุจริตแห่งชาติ และ ศาลปกครองสูงสุด", "คณะกรรมการการเลือกตั้ง และศาลปกครองสูงสุด", "คณะกรรมการสิทธิมนุษยชนแห่งชาติ และ ศาลปกครองสูงสุด", "คณะกรรมการสิทธิมนุษยชนแห่งชาติ และ ศาลฎีกา"]'::jsonb,0,array[0]::smallint[],'["รัฐธรรมนูญ พ.ศ. 2560 ม.235: คณะกรรมการ ป.ป.ช. ไต่สวนกรณีผู้ดำรงตำแหน่งทางการเมือง (รวมรัฐมนตรี) ฝ่าฝืนมาตรฐานทางจริยธรรมอย่างร้ายแรง ถ้าเห็นว่ามีมูลให้ยื่นคำร้องต่อศาลฎีกาเพื่อวินิจฉัย"]'::jsonb,'["ถูก ป.ป.ช. ไต่สวน แล้วยื่นต่อศาลฎีกา", "ไม่ถูก ศาลที่วินิจฉัยคือศาลฎีกา ไม่ใช่ศาลปกครองสูงสุด", "ไม่ถูก กกต. ดูแลการเลือกตั้ง ไม่ใช่ผู้ไต่สวนจริยธรรมร้ายแรงของรัฐมนตรี", "ไม่ถูก กสม. ตรวจสอบการละเมิดสิทธิมนุษยชน", "ไม่ถูก กสม. ไม่ใช่องค์กรไต่สวนกรณีนี้"]'::jsonb,'{"topic": "2.3", "n": 16}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-16');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-17','M6','M6-SO','M6-SO-S2','A-Level 70',null,2,'ข้อใดต่อไปนี้สะท้อนคุณลักษณะความเป็นพลเมืองดีน้อยที่สุด','["นายอิ่มตั้งใจเรียนหนังสือในโรงเรียน", "นางสาวอุ่นถ่ายรูปเพื่อนเพื่อเก็บเป็นที่ระลึกเสมอ", "นายเอมรับฟังความคิดเห็นทางการเมืองของเพื่อน", "นางสาวอิงร่วมระดมทุนเพื่อช่วยแก้ปัญหาน้ำท่วม", "นางอุ๋ยปฏิบัติตามกฎของบริษัทอย่างเคร่งครัด"]'::jsonb,1,array[1]::smallint[],'["พลเมืองดี: ทำหน้าที่ของตน เคารพสิทธิและความคิดเห็นผู้อื่น ช่วยเหลือสังคม เคารพกติกา การถ่ายรูปเพื่อนเก็บเป็นที่ระลึกเป็นเรื่องส่วนตัว ไม่ได้สะท้อนความเป็นพลเมืองดี"]'::jsonb,'["สะท้อน การตั้งใจเรียนคือการทำหน้าที่ของนักเรียน", "สะท้อนน้อยที่สุด (คำตอบ) เป็นกิจกรรมส่วนตัว ไม่เกี่ยวกับหน้าที่ต่อสังคม (และถ้าเผยแพร่โดยไม่ขออนุญาตอาจละเมิดความเป็นส่วนตัว)", "สะท้อน การรับฟังความคิดเห็นที่ต่างกันเป็นคุณลักษณะประชาธิปไตย", "สะท้อน การช่วยเหลือผู้ประสบภัยคือการมีจิตสาธารณะ", "สะท้อน การเคารพกฎระเบียบขององค์กร"]'::jsonb,'{"topic": "2.1", "n": 17}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-17');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-18','M6','M6-SO','M6-SO-S2','A-Level 70',null,2,'จงพิจารณาข้อมูลต่อไปนี้','["ประเทศ ก. → ประเทศ ข. → ประเทศ ค.", "ประเทศ ก. → ประเทศ ค. → ประเทศ ข.", "ประเทศ ข. → ประเทศ ค. → ประเทศ ก.", "ประเทศ ค. → ประเทศ ก. → ประเทศ ข.", "ประเทศ ค. → ประเทศ ข. → ประเทศ ก."]'::jsonb,1,array[1]::smallint[],'["ระดับความเป็นประชาธิปไตยดูจาก: การเลือกตั้งเสรีและเป็นธรรม เสรีภาพในการแสดงออกและการนับถือศาสนา สื่อเสรีตรวจสอบรัฐ และการถ่วงดุลโดยศาล/องค์กรอิสระ · ก ครบทุกด้าน · ค มีเสรีภาพแต่จำกัดการวิจารณ์รัฐบาล · ข บังคับศาสนา สื่ออยู่ใต้รัฐ ฝ่ายค้านไร้อำนาจ"]'::jsonb,'["ไม่ถูก ประเทศ ข มีข้อจำกัดมากกว่า ค (บังคับนับถือศาสนา สื่ออยู่ใต้การดูแลของรัฐ)", "ถูก ก (เสรีภาพเต็มที่ ตรวจสอบได้) → ค (เสรีภาพบางส่วน จำกัดการวิจารณ์รัฐบาล) → ข (จำกัดเสรีภาพมากที่สุด)", "ไม่ถูก ก เป็นประชาธิปไตยมากที่สุด ไม่ใช่น้อยที่สุด", "ไม่ถูก ค มีข้อจำกัดมากกว่า ก", "ไม่ถูก กลับลำดับ"]'::jsonb,'{"table": [["ประเทศ", "ข้อมูล"], ["ประเทศ ก", "มีการเลือกตั้งทั่วไปตามวาระอย่างสุจริตและเที่ยงธรรม พลเมืองสามารถเลือกนับถือศาสนาและแสดงความคิดเห็นทางการเมืองได้อย่างเสรี สื่อมวลชนสามารถนำเสนอข่าวและตรวจสอบการทำงานของรัฐบาลได้ ศาลและองค์กรอิสระมีอำนาจตรวจสอบฝ่ายบริหารโดยไม่ขึ้นต่อรัฐบาล"], ["ประเทศ ข", "มีการเลือกตั้งตามรัฐธรรมนูญ การใช้สิทธิและเสรีภาพของพลเมืองอยู่ภายใต้กรอบที่รัฐกำหนด โดยกำหนดให้ประชาชนต้องนับถือศาสนาประจำชาติ หากไม่นับถือศาสนาประจำชาติจะถูกจำกัดสิทธิบางประการ สื่อมวลชนสามารถดำเนินการภายใต้การดูแลของรัฐ มีพรรคฝ่ายค้านแต่ไม่สามารถคัดค้านนโยบายสำคัญของรัฐบาลได้"], ["ประเทศ ค", "มีการเลือกตั้งตามวาระ พลเมืองสามารถแสดงความคิดเห็นทางการเมืองได้ แต่การวิพากษ์วิจารณ์รัฐบาลถูกจำกัด ประชาชนมีสิทธิเลือกนับถือศาสนาตามที่รัฐธรรมนูญกำหนด สื่อมวลชนสามารถนำเสนอความคิดเห็นที่หลากหลายได้ยกเว้นการวิพากษ์วิจารณ์รัฐบาล ศาลและองค์กรอิสระมีที่มาตามรัฐธรรมนูญ แต่มักมีความล่าช้าในการตรวจสอบฝ่ายบริหาร"]], "after": "จงเรียงลำดับประเทศที่มีแนวโน้มเป็นประชาธิปไตยมากที่สุดไปน้อยที่สุด", "topic": "2.3", "n": 18}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-18');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-19','M6','M6-SO','M6-SO-S2','A-Level 70',null,2,'ในช่วงทศวรรษที่ผ่านมา อุตสาหกรรมซีรีส์วายของประเทศไทยได้มีการขยายตัวอย่างต่อเนื่องจนก้าวขึ้นมามีบทบาทสำคัญในฐานะ Soft Power ของประเทศ จากบริบทดังกล่าว ข้อใดสะท้อนถึงลักษณะของวัฒนธรรมได้น้อยที่สุด','["วัฒนธรรมไทยมีการปรับตัวและยอมรับความหลากหลายทางสังคม", "วัฒนธรรมไทยทำหน้าที่เป็นสื่อกลางในการถ่ายทอดวิถีชีวิตร่วมสมัย", "วัฒนธรรมไทยยังคงรักษาบรรทัดฐานและค่านิยมดั้งเดิมไว้อย่างเคร่งครัด", "วัฒนธรรมไทยมีบทบาทในการขับเคลื่อนระบบเศรษฐกิจของประเทศ", "วัฒนธรรมไทยได้ถูกนำมาประยุกต์และสร้างสรรค์ให้เป็นนวัตกรรมทางสังคมโดยคนรุ่นใหม่"]'::jsonb,2,array[2]::smallint[],'["ลักษณะของวัฒนธรรม: เปลี่ยนแปลงและปรับตัวได้ ถ่ายทอดได้ เป็นแบบแผนการดำเนินชีวิต และสร้างมูลค่าทางเศรษฐกิจได้ (Soft Power) การขยายตัวของซีรีส์วายสะท้อนการปรับตัวและยอมรับความหลากหลาย ไม่ใช่การรักษาค่านิยมดั้งเดิมอย่างเคร่งครัด"]'::jsonb,'["สะท้อน ซีรีส์วายแสดงการปรับตัวและยอมรับความหลากหลายทางเพศ", "สะท้อน สื่อบันเทิงถ่ายทอดวิถีชีวิตร่วมสมัย", "สะท้อนน้อยที่สุด (คำตอบ) ถ้ายึดค่านิยมดั้งเดิมอย่างเคร่งครัด ซีรีส์วายคงไม่ได้รับการยอมรับและเติบโต", "สะท้อน อุตสาหกรรมวัฒนธรรมสร้างรายได้ให้ประเทศ", "สะท้อน คนรุ่นใหม่สร้างสรรค์วัฒนธรรมเป็นนวัตกรรม"]'::jsonb,'{"topic": "2.1", "n": 19}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-19');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-20','M6','M6-SO','M6-SO-S2','A-Level 70',null,2,'ข้อใดต่อไปนี้ไม่สะท้อนแนวคิดเรื่องความล้าหลังทางวัฒนธรรม','["ปัจจุบันฐานข้อมูลงานวิจัยอยู่ในรูปแบบออนไลน์ที่เข้าถึงได้ทั่วโลกแต่มหาวิทยาลัยหลายแห่งยังคงกำหนดให้นิสิตส่งวิทยานิพนธ์ฉบับพิมพ์ปกแข็งเพื่อจัดเก็บในห้องสมุด", "แม้บัตรประจำตัวประชาชนไทยเป็นระบบ Smart Card แต่หน่วยงานบางแห่งยังคงเรียกเก็บสำเนาเอกสารกระดาษเพื่อประกอบการทำธุรกรรม", "ปัจจุบันมีเทคโนโลยีการลงลายมือชื่ออิเล็กทรอนิกส์ (E-signature) ที่ทันสมัยแต่ผู้บริหารสถานศึกษายังคงยึดติดกับธรรมเนียมการลงนามเอกสารรูปแบบกระดาษ", "นางสาวรสรินทร์รณรงค์ให้คนหันมาใช้กล้องฟิล์มแทนสมาร์ตโฟนเพื่อส่งเสริมค่านิยมการใช้ชีวิตที่เน้นความช้าและค่อยเป็นค่อยไป (Slow Life)", "เทคโนโลยียานยนต์ไร้คนขับเริ่มมีการใช้งานจริงแล้ว แต่บริษัทประกันภัย ส่วนใหญ่ยังไม่มีกรมธรรม์ที่ครอบคลุมความคุ้มครองกรณีอุบัติเหตุจากระบบดังกล่าว"]'::jsonb,3,array[3]::smallint[],'["ความล้าหลังทางวัฒนธรรม (Cultural lag – วิลเลียม อ็อกเบิร์น) คือ วัฒนธรรมที่ไม่ใช่วัตถุ (ระเบียบ ธรรมเนียม กฎหมาย ความคิด) ปรับตัวตามเทคโนโลยี/วัตถุไม่ทัน"]'::jsonb,'["สะท้อน มีฐานข้อมูลออนไลน์แล้ว แต่ระเบียบยังให้ส่งเล่มพิมพ์", "สะท้อน มีบัตร Smart Card แต่ระเบียบยังเรียกสำเนากระดาษ", "สะท้อน มี E-signature แต่ธรรมเนียมการทำงานยังยึดกระดาษ", "ไม่สะท้อน (คำตอบ) เป็นการ “เลือก” ใช้ชีวิตช้าโดยสมัครใจเพื่อค่านิยม ไม่ใช่ระเบียบหรือธรรมเนียมที่ตามเทคโนโลยีไม่ทัน", "สะท้อน เทคโนโลยีไร้คนขับมาแล้ว แต่ระบบประกันภัย (สถาบัน/กติกา) ยังไม่ปรับตาม"]'::jsonb,'{"topic": "2.1", "n": 20}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-20');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-21','M6','M6-SO','M6-SO-S3','A-Level 70',null,2,'ณ ปี พ.ศ. 2568 ประเทศไทยมีความตกลงการค้าเสรี (Free Trade Agreement: FTA) ระดับภูมิภาคทั้งสิ้น 9 ฉบับกับหลากหลายกลุ่มประเทศทั่วโลกข้อใดไม่ใช่ภูมิภาคที่ประเทศไทยมีความตกลงการค้าเสรีระดับภูมิภาคด้วย','["เอเชียตะวันออกเฉียงใต้", "ออสเตรเลียและโอเชียเนีย", "ยุโรป", "เอเชียใต้", "แอฟริกา"]'::jsonb,4,array[4]::smallint[],'["FTA ระดับภูมิภาคของไทย (ณ 2568) เช่น AFTA (อาเซียน) อาเซียน–จีน อาเซียน–ญี่ปุ่น อาเซียน–เกาหลี อาเซียน–อินเดีย อาเซียน–ออสเตรเลีย–นิวซีแลนด์ อาเซียน–ฮ่องกง RCEP และไทย–EFTA (ประเทศยุโรป ลงนามต้นปี 2568) ยังไม่มี FTA ระดับภูมิภาคกับแอฟริกา"]'::jsonb,'["มี เช่น เขตการค้าเสรีอาเซียน (AFTA)", "มี เช่น อาเซียน–ออสเตรเลีย–นิวซีแลนด์ (AANZFTA) และ RCEP", "มี ไทย–EFTA (สวิตเซอร์แลนด์ นอร์เวย์ ไอซ์แลนด์ ลิกเตนสไตน์) ลงนามเมื่อต้นปี 2568", "มี อาเซียน–อินเดีย (อินเดียอยู่ในเอเชียใต้)", "ไม่มี (คำตอบ) ไทยยังไม่มีความตกลงการค้าเสรีระดับภูมิภาคกับแอฟริกา"]'::jsonb,'{"topic": "3.4", "n": 21}'::jsonb,'imported_m6','imported',false,null,'ข้อนี้ขึ้นกับสถานะ ณ ปี 2568 ตามโจทย์ ถ้าในอนาคตมีความตกลงใหม่ คำตอบอาจเปลี่ยน',2569,'soc:69-21');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-22','M6','M6-SO','M6-SO-S3','A-Level 70',null,2,'บริษัทเทคโนโลยีหลายแห่งปรับเพิ่มการผลิตเซมิคอนดักเตอร์ เนื่องจากเป็นสินค้าที่มีความต้องการมากขึ้น การตัดสินใจนี้สะท้อนหลักเศรษฐศาสตร์ในข้อใด','["ทฤษฎีอรรถประโยชน์", "การแทรกแซงโดยรัฐบาล", "การเจริญเติบโตทางเศรษฐกิจ", "ทฤษฎีการได้เปรียบเชิงเปรียบเทียบ", "อุปสงค์การอุปโภคบริโภค"]'::jsonb,4,array[4]::smallint[],'["อุปสงค์ (ความต้องการซื้อที่มีกำลังซื้อ) ของผู้บริโภคเพิ่มขึ้น ทำให้ผู้ผลิตตัดสินใจเพิ่มการผลิตเพื่อตอบสนอง = หลักอุปสงค์–อุปทาน (กลไกราคา)"]'::jsonb,'["ทฤษฎีอรรถประโยชน์อธิบายความพอใจของผู้บริโภคจากการบริโภค ไม่ใช่การตัดสินใจเพิ่มการผลิต", "โจทย์ไม่มีการแทรกแซงจากรัฐ เป็นการตัดสินใจของบริษัทตามตลาด", "การเจริญเติบโตทางเศรษฐกิจวัดจากผลผลิตรวมของประเทศ ไม่ใช่การตัดสินใจของบริษัท", "การได้เปรียบเชิงเปรียบเทียบอธิบายว่าประเทศควรผลิตสินค้าที่มีต้นทุนค่าเสียโอกาสต่ำกว่าเพื่อค้าขาย", "ถูก ความต้องการ (อุปสงค์) เซมิคอนดักเตอร์ที่เพิ่มขึ้น ทำให้ผู้ผลิตเพิ่มการผลิต"]'::jsonb,'{"topic": "3.1", "n": 22}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-22');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-23','M6','M6-SO','M6-SO-S3','A-Level 70',null,2,'จากข้อมูลตลาดแรงงานในปี พ.ศ. 2567 ประชากรที่มีอายุอยู่ในวัยแรงงานทั้งหมด 50 ล้านคน ซึ่งรวมนิสิตนักศึกษาอยู่ด้วย ส่วนจำนวนผู้ที่มีงานทำทั้งหมด 45 ล้านคน จำนวนผู้ที่ไม่มีงานทำและกำลังหางานอยู่ทั้งหมด 2 ล้านคน อัตราการว่างงานของปี พ.ศ. 2567 มีค่าประมาณเท่าใด','["2%", "4%", "10%", "11%", "15%"]'::jsonb,1,array[1]::smallint[],'["อัตราการว่างงาน = ผู้ว่างงาน ÷ กำลังแรงงาน × 100 · กำลังแรงงาน = ผู้มีงานทำ + ผู้ว่างงาน (ไม่รวมนักศึกษาที่ไม่ได้หางาน) = 45 + 2 = 47 ล้านคน · 2 ÷ 47 × 100 ≈ 4.26% ≈ 4%"]'::jsonb,'["ไม่ถูก ระวังสับสนระหว่าง “ผู้ว่างงาน 2 ล้านคน” กับ “2%” อัตราการว่างงานต้องหารด้วยกำลังแรงงาน", "ถูก กำลังแรงงาน 47 ล้านคน ว่างงาน 2 ล้านคน → ประมาณ 4.3% ≈ 4%", "ไม่ถูก 10% มาจาก (50 − 45) ÷ 50 ซึ่งนับนักศึกษาที่ไม่อยู่ในกำลังแรงงานเป็นผู้ว่างงาน", "ไม่ถูก 11% มาจาก (50 − 45) ÷ 45 ซึ่งนับนักศึกษาเป็นผู้ว่างงานและใช้ตัวหารผิด", "ไม่ถูก ไม่ตรงกับการคำนวณที่ถูกต้อง (กำลังแรงงาน 47 ล้านคน ว่างงาน 2 ล้านคน)"]'::jsonb,'{"topic": "3.2", "n": 23}'::jsonb,'imported_m6','imported',true,'numeric','Exam Gym ม.6 · 5620e4c',2569,'soc:69-23');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-24','M6','M6-SO','M6-SO-S3','A-Level 70',null,2,'ข้อใดไม่ถือเป็นกิจกรรมทางเศรษฐกิจในทางเศรษฐศาสตร์','["นายไก่ ทำผัดซีอิ๊วเพื่อไปขายในตลาดนัด", "นายไข่ ซื้อข้าวเหนียวหมูปิ้งเพื่อเป็นอาหารเช้า", "นายสดใส เป็นผู้รับเหมาและประสบความสำเร็จในการเซ็นส่งมอบงานก่อสร้างให้แก่โครงการหมู่บ้านจัดสรรทันตามเวลาที่กำหนด", "นายใหม่ ทำหน้าที่ตัดแบ่งขนมเค้กให้เพื่อน ๆ", "นายใหญ่ เข้าคูหาในวันเลือกตั้งเพื่อกากบาทเลือกพรรคการเมืองที่ชอบ"]'::jsonb,4,array[4]::smallint[],'["กิจกรรมทางเศรษฐกิจ = การผลิต การบริโภค การกระจาย/แจกจ่าย และการแลกเปลี่ยน สินค้าและบริการ การไปเลือกตั้งเป็นกิจกรรมทางการเมือง"]'::jsonb,'["เป็นการผลิตและแลกเปลี่ยน (ทำผัดซีอิ๊วไปขาย)", "เป็นการบริโภค (ซื้ออาหารเช้า)", "เป็นการผลิตบริการ (รับเหมาก่อสร้าง)", "เป็นการกระจาย/แจกจ่ายสินค้า (แบ่งเค้กให้เพื่อน)", "ไม่ใช่ (คำตอบ) การลงคะแนนเลือกตั้งเป็นกิจกรรมทางการเมือง ไม่ใช่การผลิต บริโภค หรือแลกเปลี่ยน"]'::jsonb,'{"topic": "3.3", "n": 24}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-24');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-25','M6','M6-SO','M6-SO-S3','A-Level 70',null,2,'ในเดือนมกราคม พ.ศ. 2568 ค่าเงินบาทอยู่ที่ 1 ยูโร เท่ากับ 38 บาท แต่ในเดือนมีนาคมพ.ศ. 2568 เงินบาทอ่อนค่าลงมาเป็น 1 ยูโร เท่ากับ 40 บาท บริษัทไทยต้องนำเข้าอะไหล่จากเยอรมนี จำนวน 5,000 ยูโร จงคำนวณว่า บริษัทต้องจ่ายเงินบาทเพิ่มขึ้นหรือลดลงกี่บาท เพื่อให้ได้จำนวนอะไหล่เท่าเดิมเมื่อเทียบระหว่างเดือนมกราคมและเดือนมีนาคม','["เพิ่มขึ้น 5,000 บาท", "ลดลง 5,000 บาท", "เพิ่มขึ้น 10,000 บาท", "ลดลง 10,000 บาท", "เท่าเดิม ไม่เพิ่มขึ้นหรือลดลง"]'::jsonb,2,array[2]::smallint[],'["มกราคม: 5,000 × 38 = 190,000 บาท · มีนาคม: 5,000 × 40 = 200,000 บาท · เงินบาทอ่อนค่า ผู้นำเข้าต้องจ่ายเงินบาทเพิ่มขึ้น 10,000 บาท"]'::jsonb,'["ไม่ถูก ต่างกัน 2 บาทต่อยูโร × 5,000 ยูโร = 10,000 บาท ไม่ใช่ 5,000", "ไม่ถูก บาทอ่อนค่า ผู้นำเข้าต้องจ่ายเพิ่ม ไม่ใช่ลดลง", "ถูก 200,000 − 190,000 = 10,000 บาท ต้องจ่ายเพิ่มขึ้น", "ไม่ถูก ทิศทางผิด บาทอ่อนค่าทำให้สินค้านำเข้าแพงขึ้น", "ไม่ถูก อัตราแลกเปลี่ยนเปลี่ยน จำนวนเงินบาทที่จ่ายจึงเปลี่ยน"]'::jsonb,'{"topic": "3.4", "n": 25}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-25');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-26','M6','M6-SO','M6-SO-S3','A-Level 70',null,2,'Coop Switzerland เป็นหนึ่งในสหกรณ์ค้าปลีกรูปแบบบริษัทที่ใหญ่ที่สุดในสมาพันธรัฐสวิส (Swiss Confederation) มีนโยบายส่งเสริมสินค้าออร์แกนิก (Organic) ที่มีคุณภาพสูงกว่ามาตรฐานทั่วไป (Premium) จากเกษตรกรในท้องถิ่น และเปิดโอกาสให้สมาชิกสามารถเสนอแนวคิดและร่วมปรับปรุงคุณภาพสินค้าผ่านการประชุมประจำปี
หลักการข้อใดต่อไปนี้สะท้อนสิ่งที่ Coop Switzerland ปฏิบัติตามข้อมูลข้างต้นได้ถูกต้องชัดเจนที่สุด','["การควบคุมโดยสมาชิกตามหลักประชาธิปไตย", "การเป็นสมาชิกโดยสมัครใจและเปิดกว้าง", "การปกครองตนเองและความเป็นอิสระ", "การร่วมมือระหว่างสหกรณ์", "การเอื้ออาทรต่อชุมชน"]'::jsonb,0,array[0]::smallint[],'["หลักการสหกรณ์สากล 7 ข้อ: 1) เปิดรับสมาชิกโดยสมัครใจ 2) ควบคุมโดยสมาชิกตามหลักประชาธิปไตย 3) สมาชิกมีส่วนร่วมทางเศรษฐกิจ 4) ปกครองตนเองและเป็นอิสระ 5) การศึกษา ฝึกอบรม และสารสนเทศ 6) ร่วมมือระหว่างสหกรณ์ 7) เอื้ออาทรต่อชุมชน · การให้สมาชิกเสนอความคิดและร่วมปรับปรุงผ่านที่ประชุมประจำปี = ควบคุมโดยสมาชิกตามหลักประชาธิปไตย"]'::jsonb,'["ถูก สมาชิกมีส่วนร่วมตัดสินใจผ่านที่ประชุมประจำปี เป็นหลักการควบคุมโดยสมาชิกตามหลักประชาธิปไตยที่เห็นชัดที่สุดในโจทย์", "โจทย์ไม่ได้กล่าวถึงการรับสมาชิกใหม่หรือการเปิดกว้าง", "โจทย์ไม่ได้กล่าวถึงความเป็นอิสระจากรัฐหรือองค์กรภายนอก", "โจทย์ไม่ได้กล่าวถึงความร่วมมือกับสหกรณ์อื่น", "การส่งเสริมเกษตรกรท้องถิ่นใกล้เคียงหลักนี้ แต่ประเด็นที่โจทย์เน้นชัดที่สุดคือการมีส่วนร่วมของสมาชิก"]'::jsonb,'{"topic": "3.3", "n": 26}'::jsonb,'imported_m6','imported',true,'expl','ตัวเลือก 5 (เอื้ออาทรต่อชุมชน) มีส่วนจริงจากการซื้อสินค้าจากเกษตรกรท้องถิ่น เฉลย ทปอ. คือข้อ 1',2569,'soc:69-26');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-27','M6','M6-SO','M6-SO-S3','A-Level 70',null,2,'นายเสวีคิดค่ายารักษาโรคหัวใจในราคาสูงกว่าปกติถึงสามเท่า เนื่องจากเป็นของจำเป็นมาก และไม่สามารถหาได้ตามร้านยาทั่วไป นางประไพมีมารดาป่วยเป็นโรคหัวใจ นางประไพศรัทธาในความรู้ของนายเสวีจึงเชื่อใจยอมซื้อยามารักษามารดา
เหตุการณ์นี้สะท้อนภาวะ “ตลาดล้มเหลว” ในทางเศรษฐศาสตร์ รูปแบบใดบ้าง
ก. เป็นการตั้งราคาสูงเกินไปในตลาดแข่งขันสมบูรณ์
ข. การผูกขาดตลาดจากผู้ขายปลีกรายเดียว อำนาจจึงตกแก่ผู้ขาย
ค. ความล้มเหลวจากข้อมูลไม่สมมาตร ซึ่งผู้ขายมีข้อมูลมากกว่าผู้ซื้อ','["รูปแบบ ก.", "รูปแบบ ก. และ ข.", "รูปแบบ ข.", "รูปแบบ ข. และ ค.", "รูปแบบ ก. และ ข. และ ค."]'::jsonb,3,array[3]::smallint[],'["ตลาดล้มเหลว (market failure) เช่น การผูกขาด/อำนาจตลาด ข้อมูลข่าวสารไม่สมมาตร ผลกระทบภายนอก สินค้าสาธารณะ · ยาหายากที่มีผู้ขายรายเดียว = ผูกขาด · ผู้ซื้อเชื่อความรู้ของผู้ขายเพราะตนรู้น้อยกว่า = ข้อมูลไม่สมมาตร"]'::jsonb,'["ไม่ถูก โจทย์ไม่ใช่ตลาดแข่งขันสมบูรณ์ (สินค้าหาซื้อที่อื่นไม่ได้)", "ไม่ถูก ก ไม่ถูก เพราะไม่ใช่ตลาดแข่งขันสมบูรณ์", "ไม่ครบ ขาดเรื่องข้อมูลไม่สมมาตร (นางประไพเชื่อใจความรู้ของนายเสวี)", "ถูก ข ผู้ขายรายเดียวมีอำนาจตั้งราคา และ ค ผู้ขายมีข้อมูลมากกว่าผู้ซื้อ", "ไม่ถูก ก ไม่ถูก"]'::jsonb,'{"topic": "3.1", "n": 27}'::jsonb,'imported_m6','imported',true,'figure','Exam Gym ม.6 · 5620e4c',2569,'soc:69-27');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-28','M6','M6-SO','M6-SO-S3','A-Level 70',null,2,'ราคาโต๊ะทำงานยี่ห้อ I-KAE รุ่น Retired ในปี พ.ศ. 2566 เท่ากับ 2,500 บาท ในปี พ.ศ. 2567 ราคาสินค้าโต๊ะรุ่นเดิม เท่ากับ 2,350 บาท จงคำนวณอัตราการเปลี่ยนแปลงของระดับราคาทั่วไป และระบุว่าภาวะเศรษฐกิจเป็นเงินเฟ้อหรือเงินฝืด','["เกิดภาวะเงินฝืด 4%", "เกิดภาวะเงินฝืด 6%", "เกิดภาวะเงินเฟ้อ 4%", "เกิดภาวะเงินเฟ้อ 6%", "ไม่สามารถระบุได้ว่าเกิดภาวะเงินเฟ้อ หรือ เงินฝืด"]'::jsonb,4,array[4]::smallint[],'["เงินเฟ้อ/เงินฝืด คือการเปลี่ยนแปลงของ “ระดับราคาสินค้าทั่วไป” วัดจากดัชนีราคาผู้บริโภคที่รวมสินค้าและบริการจำนวนมาก ราคาสินค้าชนิดเดียว (โต๊ะลดลง 6%) จึงสรุปภาวะเงินเฟ้อหรือเงินฝืดไม่ได้"]'::jsonb,'["ไม่ถูก ราคาโต๊ะลดลง 6% ไม่ใช่ 4% และใช้สินค้าชนิดเดียวสรุปภาวะเศรษฐกิจไม่ได้", "กับดัก ราคาโต๊ะลดลง (2,500 − 2,350) ÷ 2,500 = 6% จริง แต่เป็นราคาสินค้าชนิดเดียว ไม่ใช่ระดับราคาทั่วไป", "ไม่ถูก ราคาลดลง ไม่ได้เพิ่มขึ้น", "ไม่ถูก ราคาลดลง ไม่ได้เพิ่มขึ้น", "ถูก ต้องใช้ดัชนีราคาของสินค้าและบริการหลายชนิด ข้อมูลสินค้าชนิดเดียวสรุปเงินเฟ้อหรือเงินฝืดไม่ได้"]'::jsonb,'{"topic": "3.2", "n": 28}'::jsonb,'imported_m6','imported',true,'ref','Exam Gym ม.6 · 5620e4c',2569,'soc:69-28');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-29','M6','M6-SO','M6-SO-S3','A-Level 70',null,2,'รัฐบาลกำหนด “ราคาขั้นสูง (Price Ceiling)” สำหรับไข่ไก่ในปี พ.ศ. 2567 เพื่อช่วยลดภาระค่าครองชีพของประชาชน สถานการณ์ใดต่อไปนี้เกิดได้ชัดเจนที่สุด หากราคาขั้นสูงที่กำหนด “ต่ำกว่าราคาดุลยภาพ” ของตลาด','["ไข่ไก่ล้นตลาด", "อุปทานไข่ไก่เพิ่มขึ้น", "ไข่ไก่ขาดตลาด", "ราคาไข่ไก่กลับสู่ดุลยภาพตลาด", "ไม่น่าเกิดขึ้นได้สักข้อ"]'::jsonb,2,array[2]::smallint[],'["ราคาขั้นสูง (price ceiling) ที่ต่ำกว่าราคาดุลยภาพ: ผู้ซื้ออยากซื้อมากขึ้น ผู้ขายอยากขายน้อยลง → อุปสงค์ส่วนเกิน = สินค้าขาดตลาด (อาจเกิดตลาดมืด)"]'::jsonb,'["ไม่ถูก สินค้าล้นตลาดเกิดจากราคาขั้นต่ำที่สูงกว่าดุลยภาพ", "ไม่ถูก ราคาต่ำลงทำให้ปริมาณเสนอขายลดลง ไม่ใช่อุปทานเพิ่ม", "ถูก ราคาที่ถูกกดต่ำกว่าดุลยภาพทำให้ปริมาณเสนอซื้อมากกว่าปริมาณเสนอขาย ไข่ไก่จึงขาดตลาด", "ไม่ถูก รัฐกำหนดเพดานไว้ ราคาจึงกลับสู่ดุลยภาพไม่ได้ตามกฎหมาย", "ไม่ถูก ข้อ 3 เกิดขึ้นได้ชัดเจน"]'::jsonb,'{"topic": "3.1", "n": 29}'::jsonb,'imported_m6','imported',true,'expl','Exam Gym ม.6 · 5620e4c',2569,'soc:69-29');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-30','M6','M6-SO','M6-SO-S3','A-Level 70',null,2,'เงินฟรังก์สวิสแข็งค่าขึ้นเมื่อเทียบกับดอลลาร์สหรัฐ สถานการณ์ในข้อใดต่อไปนี้มีโอกาสเกิดขึ้นมากที่สุด','["ผู้ส่งออกสวิตเซอร์แลนด์ได้รับรายได้เป็นเงินฟรังก์สวิสมากขึ้นเมื่อขายสินค้าเดิมไปสหรัฐอเมริกา", "นักท่องเที่ยวจากสวิตเซอร์แลนด์มีค่าใช้จ่ายเพื่อการท่องเที่ยวในสหรัฐอเมริกาลดลง", "ราคาสินค้านำเข้าจากสหภาพยุโรปมีราคาแพงขึ้น", "บริษัทจดทะเบียนในสวิตเซอร์แลนด์ต้องใช้เงินฟรังก์สวิสมากขึ้นในการชำระเงินค่าสินค้าเป็นดอลลาร์สหรัฐ", "ต้นทุนการผลิตของบริษัทในคิวบาสูงขึ้นโดยอัตโนมัติ"]'::jsonb,1,array[1]::smallint[],'["ฟรังก์สวิสแข็งค่า = 1 ฟรังก์แลกดอลลาร์ได้มากขึ้น · ชาวสวิสซื้อสินค้า/บริการในสหรัฐฯ ถูกลง (ท่องเที่ยว นำเข้า) · ผู้ส่งออกสวิสได้เงินฟรังก์น้อยลงเมื่อแลกรายได้ดอลลาร์"]'::jsonb,'["ไม่ถูก ขายได้ดอลลาร์เท่าเดิม แต่แลกเป็นฟรังก์ได้น้อยลง", "ถูก ฟรังก์แลกดอลลาร์ได้มากขึ้น ค่าใช้จ่ายในสหรัฐฯ เมื่อคิดเป็นฟรังก์จึงลดลง", "ไม่ถูก โจทย์เปรียบเทียบฟรังก์กับดอลลาร์ ไม่ได้บอกค่าเงินยูโร และค่าเงินที่แข็งขึ้นมักทำให้สินค้านำเข้าถูกลง", "ไม่ถูก ใช้ฟรังก์ “น้อยลง” ในการชำระหนี้ดอลลาร์", "ไม่ถูก ไม่เกี่ยวข้องโดยตรงกับต้นทุนการผลิตในคิวบา"]'::jsonb,'{"topic": "3.4", "n": 30}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-30');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-31','M6','M6-SO','M6-SO-S4','A-Level 70',null,2,'หากอาณาจักรปัลลวะได้มอบมรดกทางอารยธรรมด้านอักษรศาสตร์ให้แก่ดินแดนในแถบเอเชียตะวันออกเฉียงใต้ ชนชาติใดในดินแดนเอเชียตะวันตกที่ได้มอบมรดกทางอารยธรรมลักษณะเดียวกันนี้ให้แก่ดินแดนในโลกตะวันตก','["ฮิบรู", "ฟินิเชียน", "สุเมเรียน", "อัสซีเรียน", "เปอร์เซียน"]'::jsonb,1,array[1]::smallint[],'["อักษรปัลลวะ (อินเดียใต้) เป็นต้นแบบตัวอักษรหลายภาษาในเอเชียตะวันออกเฉียงใต้ ทำนองเดียวกัน ชาวฟินิเชียนคิดตัวอักษรแทนเสียง (alphabet) ที่กรีกและโรมันรับไปพัฒนาเป็นอักษรของโลกตะวันตก"]'::jsonb,'["ไม่ถูก ชาวฮิบรูมีมรดกเด่นด้านศาสนา (ศาสนายูดาย คัมภีร์ไบเบิลภาคพันธสัญญาเดิม)", "ถูก ฟินิเชียนสร้างอักษรแทนเสียงประมาณ 22 ตัว เป็นต้นแบบอักษรกรีกและโรมัน", "ไม่ถูก สุเมเรียนคิดอักษรลิ่ม (คูนิฟอร์ม) แต่ไม่ได้เป็นต้นแบบอักษรตะวันตกโดยตรง", "ไม่ถูก อัสซีเรียนเด่นด้านการทหารและห้องสมุด", "ไม่ถูก เปอร์เซียเด่นด้านการปกครองจักรวรรดิ ถนน และศาสนาโซโรอัสเตอร์"]'::jsonb,'{"topic": "4.3", "n": 31}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-31');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-32','M6','M6-SO','M6-SO-S4','A-Level 70',null,2,'ข้อใดกล่าวถูกต้องเกี่ยวกับสภาพภูมิศาสตร์และการสร้างสรรค์อารยธรรมในยุคโบราณ','["อารยธรรมสุเมเรียนพัฒนาขึ้นได้เพราะแม่น้ำไทกริส-ยูเฟรติส มีวัฏจักรของอุทกภัยที่คาดการณ์ได้เป็นประจำทุกปี", "อารยธรรมอียิปต์รุ่งเรืองขึ้นจากการค้าทางทะเล เพราะผลผลิตทางการเกษตรที่ได้จากที่ราบลุ่มแม่น้ำไนล์มีปริมาณจำกัด", "อารยธรรมจีนรับการถ่ายทอดทางภูมิปัญญาและเทคโนโลยีจากอารยธรรมอื่นน้อย เนื่องจากมีปราการธรรมชาติล้อมรอบเกือบทุกด้าน", "อารยธรรมกรีกมีความเป็นเอกภาพทางการเมืองระหว่างนครรัฐต่าง ๆ เนื่องจากตั้งอยู่บนคาบสมุทรและมีภูเขาล้อมรอบ ป้องกันการรุกรานจากศัตรูภายนอก", "อารยธรรมอินเดียสามารถสร้างการปกครองในระดับจักรวรรดิได้เพราะมีภูมิประเทศและภูมิอากาศคล้ายคลึงกัน และประชากรมีลักษณะร่วมทางวัฒนธรรมเดียวกัน"]'::jsonb,2,array[2]::smallint[],'["ภูมิศาสตร์กับอารยธรรม: แม่น้ำไนล์ท่วมสม่ำเสมอคาดการณ์ได้ แต่ไทกริส–ยูเฟรติสท่วมรุนแรงคาดเดายาก · จีนมีปราการธรรมชาติ (ทะเลทราย ภูเขา ทะเล) จึงพัฒนาอารยธรรมของตนเองค่อนข้างโดดเดี่ยว · กรีกถูกภูเขาแบ่งเป็นนครรัฐอิสระ · อินเดียมีความหลากหลายสูง"]'::jsonb,'["ไม่ถูก น้ำท่วมของไทกริส–ยูเฟรติสรุนแรงและคาดเดายาก ต่างจากแม่น้ำไนล์", "ไม่ถูก ลุ่มแม่น้ำไนล์อุดมสมบูรณ์มาก ผลผลิตเกษตรเป็นฐานความรุ่งเรืองของอียิปต์", "ถูก จีนมีทะเลทราย ภูเขา และทะเลล้อมรอบ จึงรับอิทธิพลจากภายนอกน้อย", "ไม่ถูก ภูเขาแบ่งกรีกเป็นนครรัฐอิสระ ทำให้ขาดเอกภาพทางการเมือง", "ไม่ถูก อินเดียมีภูมิประเทศ ภูมิอากาศ และวัฒนธรรมหลากหลายมาก"]'::jsonb,'{"topic": "4.3", "n": 32}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-32');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-33','M6','M6-SO','M6-SO-S4','A-Level 70',null,2,'ศึกษาเอกสารชั้นต้นต่อไปนี้ และตอบคำถามด้านล่าง
คำประกาศอิสรภาพของอาณานิคมอเมริกัน ค.ศ. 1776
เราถือว่าความจริงเหล่านี้ประจักษ์ชัดแจ้งอยู่แล้ว กล่าวคือ มนุษย์เกิดมาเท่าเทียมกัน พระผู้สร้างประทานสิทธิบางประการอันถ่ายโอนแก่กันไม่ได้ให้แก่เรา สิทธิดังกล่าวรวมถึงชีวิต เสรีภาพ และการแสวงหาความสุข เพื่อพิทักษ์สิทธิเหล่านั้น มนุษย์จึงได้สถาปนารัฐบาลขึ้นซึ่งได้รับอำนาจอันชอบธรรมจากผู้ใต้ปกครอง หากการปกครองได้กลายเป็นตัวการในการทำลายจุดมุ่งหมายดังกล่าวนี้ เมื่อนั้นประชาชนก็ทรงสิทธิที่จะเปลี่ยนแปลงหรือล้มล้างการปกครองนั้นได้ และสถาปนารัฐบาลใหม่ขึ้นมา โดยวางอยู่บนหลักการพื้นฐานเหล่านั้น และจัดการใช้อำนาจในลักษณะที่ประชาชนเห็นว่ายังก่อให้เกิดผลแก่ความปลอดภัยและความสุขของตนได้
ข้อใดไม่อาจตีความได้จากเนื้อความที่ปรากฏในเอกสารข้างต้น','["การยืนยันหลักการเสรีนิยมว่าด้วยอำนาจอธิปไตยเป็นของประชาชน", "การพิทักษ์สิทธิที่พระเจ้าได้มอบให้แก่ประชาชนถือเป็นพันธกิจหลักของรัฐบาล", "การให้ความสำคัญกับ “ความปลอดภัย” หมายถึงการคุ้มครองชีวิตและเสรีภาพของประชาชน", "การประกาศเอกราชของชาวอาณานิคมมีสาเหตุจากอารมณ์และความรู้สึกของปัจเจกบุคคลร่วมด้วย", "การมีส่วนร่วมทางการเมืองอย่างเสมอภาคของทุกเพศและทุกชนชั้นเป็นพื้นฐานของหลักการ “มนุษย์เกิดมาเท่าเทียมกัน”"]'::jsonb,4,array[4]::smallint[],'["การตีความหลักฐานชั้นต้น ต้องอ้างอิงจากเนื้อความที่ปรากฏ คำประกาศอิสรภาพ ค.ศ. 1776 กล่าวถึงความเท่าเทียม สิทธิที่พระผู้สร้างประทาน รัฐบาลได้อำนาจจากผู้ใต้ปกครอง และสิทธิล้มล้างรัฐบาลที่ทำลายสิทธิ แต่ไม่ได้พูดถึงการมีส่วนร่วมทางการเมืองของทุกเพศทุกชนชั้น"]'::jsonb,'["ตีความได้ “รัฐบาลได้รับอำนาจอันชอบธรรมจากผู้ใต้ปกครอง” = อำนาจอธิปไตยเป็นของประชาชน", "ตีความได้ “เพื่อพิทักษ์สิทธิเหล่านั้น มนุษย์จึงสถาปนารัฐบาล”", "ตีความได้ เอกสารกล่าวถึงความปลอดภัยและความสุขของประชาชน ซึ่งสัมพันธ์กับสิทธิในชีวิตและเสรีภาพ", "ตีความได้ตามเฉลย เอกสารอ้างถึงสิ่งที่ “ประชาชนเห็นว่า” ก่อให้เกิดความสุขของตน สะท้อนความรู้สึกของปัจเจกด้วย", "ตีความไม่ได้ (คำตอบ) เอกสารไม่ได้กล่าวถึงการมีส่วนร่วมทางการเมืองของทุกเพศทุกชนชั้น (ในความเป็นจริงขณะนั้นผู้หญิงและทาสยังไม่มีสิทธิทางการเมือง)"]'::jsonb,'{"topic": "4.1", "n": 33}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-33');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-34','M6','M6-SO','M6-SO-S4','A-Level 70',null,2,'การเข้ามาช่วยเหลือประเทศในเอเชียในการพัฒนาเศรษฐกิจและสร้างสาธารณูปโภคช่วงทศวรรษ 1960s ของสหรัฐอเมริกาเป็นการดำเนินตามนโยบายในข้อใด','["สงครามตัวแทน (Proxy War)", "แผนการมาร์แชลล์ (Marshall Plan)", "การหมุนวนหาเอเชีย (Pivot to Asia)", "นโยบายสกัดกั้น (Containment Policy)", "การอยู่ร่วมกันอย่างสันติ (Peaceful Coexistence)"]'::jsonb,3,array[3]::smallint[],'["นโยบายสกัดกั้น/ปิดล้อม (Containment) ของสหรัฐฯ ในสงครามเย็น: ช่วยเหลือเศรษฐกิจ การทหาร และสาธารณูปโภคแก่ประเทศต่าง ๆ เพื่อป้องกันการขยายตัวของคอมมิวนิสต์ (ในเอเชียทศวรรษ 1960 เช่น ไทย)"]'::jsonb,'["ไม่ถูก สงครามตัวแทนคือการที่มหาอำนาจสนับสนุนฝ่ายต่าง ๆ ให้รบกันแทน ไม่ใช่การช่วยพัฒนาเศรษฐกิจ", "ไม่ถูก แผนมาร์แชลล์ (ค.ศ. 1948–1952) ฟื้นฟูยุโรปตะวันตกหลังสงครามโลกครั้งที่ 2", "ไม่ถูก Pivot to Asia เป็นนโยบายสมัยประธานาธิบดีโอบามา (ทศวรรษ 2010)", "ถูก ความช่วยเหลือของสหรัฐฯ ในเอเชียช่วงทศวรรษ 1960 มุ่งสกัดกั้นการขยายตัวของคอมมิวนิสต์", "ไม่ถูก การอยู่ร่วมกันอย่างสันติเป็นนโยบายของสหภาพโซเวียตสมัยครุสชอฟ"]'::jsonb,'{"topic": "4.3", "n": 34}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-34');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-35','M6','M6-SO','M6-SO-S4','A-Level 70',null,2,'ข้อใดกล่าวถูกต้อง','["การฆ่าล้างเผ่าพันธุ์ชาวยิวของระบอบนาซีเยอรมนีเป็นผลจากการรับแนวคิดสังคมแบบดาร์วิน (Social Darwinism)", "การถอนตัวออกจากสันนิบาตชาติของเยอรมนีเป็นการดำเนินการตามนโยบายโดดเดี่ยวตนเอง (Isolationism)", "การก่อตั้งสมาคมอาเซียนเป็นตอบสนองต่อหลักการอยู่ร่วมกันอย่างสันติ (Peaceful Co-existence)", "การดำเนินนโยบายปิดล้อม (Containment Policy) ของสหรัฐอเมริกานำไปสู่การสร้างกำแพงเบอร์ลิน", "การก่อตั้งโรงเรียนดาราวิทยาลัยโดยมิชชันนารีคณะเพรสไบทีเรียนเป็นไปตามหลักการเสรีภาพ เสมอภาค และภราดรภาพ (Liberty Equality Fraternity)"]'::jsonb,0,array[0]::smallint[],'["แนวคิดสังคมแบบดาร์วิน (Social Darwinism) นำทฤษฎีวิวัฒนาการมาอธิบายสังคมว่าเชื้อชาติที่ “เหมาะสม” จะอยู่รอด ถูกใช้สนับสนุนลัทธิเหยียดเชื้อชาติของนาซี"]'::jsonb,'["ถูก นาซีใช้แนวคิดเชื้อชาติเหนือกว่าที่มีรากจาก Social Darwinism เป็นข้ออ้างในการฆ่าล้างเผ่าพันธุ์ชาวยิว", "ไม่ถูก เยอรมนีถอนตัวจากสันนิบาตชาติ (ค.ศ. 1933) เพื่อเสริมกำลังทหารและขยายอำนาจ ไม่ใช่การโดดเดี่ยวตนเอง (ซึ่งเป็นนโยบายของสหรัฐฯ ช่วงระหว่างสงคราม)", "ไม่ถูก อาเซียน (ค.ศ. 1967) ตั้งขึ้นท่ามกลางสงครามเย็นเพื่อความร่วมมือและความมั่นคงของภูมิภาค การอยู่ร่วมกันอย่างสันติเป็นแนวคิดของโซเวียต", "ไม่ถูก เยอรมนีตะวันออกสร้างกำแพงเบอร์ลิน (ค.ศ. 1961) เพื่อหยุดการอพยพไปฝั่งตะวันตก ไม่ใช่ผลจากนโยบายของสหรัฐฯ", "ไม่ถูก มิชชันนารีตั้งโรงเรียนเพื่อการศึกษาและเผยแผ่ศาสนา คำขวัญเสรีภาพ เสมอภาค ภราดรภาพเป็นของการปฏิวัติฝรั่งเศส"]'::jsonb,'{"topic": "4.3", "n": 35}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-35');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-36','M6','M6-SO','M6-SO-S4','A-Level 70',null,2,'ข้อใด ไม่ใช่ สาเหตุหลักของความขัดแย้งในการอ้างสิทธิเหนือทะเลจีนใต้ของประเทศต่างๆในปัจจุบัน','["การช่วงชิงแหล่งอาหาร", "การช่วงชิงแหล่งพลังงาน", "การชิงความได้เปรียบทางการค้า", "การพิพาททางชาติพันธุ์และศาสนา", "การชิงความได้เปรียบทางการทหาร"]'::jsonb,3,array[3]::smallint[],'["ความขัดแย้งในทะเลจีนใต้เกิดจากการแย่งชิงทรัพยากร (ประมง น้ำมัน ก๊าซธรรมชาติ) เส้นทางการค้าทางทะเล และความได้เปรียบทางยุทธศาสตร์/ทหาร ไม่ได้มีสาเหตุหลักจากชาติพันธุ์หรือศาสนา"]'::jsonb,'["เป็นสาเหตุ ทะเลจีนใต้เป็นแหล่งประมงสำคัญ", "เป็นสาเหตุ มีแหล่งน้ำมันและก๊าซธรรมชาติ", "เป็นสาเหตุ เป็นเส้นทางเดินเรือพาณิชย์สำคัญของโลก", "ไม่ใช่สาเหตุหลัก (คำตอบ) ข้อพิพาทเป็นเรื่องอธิปไตยและผลประโยชน์ ไม่ใช่ชาติพันธุ์หรือศาสนา", "เป็นสาเหตุ ประเทศต่าง ๆ ต้องการฐานที่มั่นทางทหารและยุทธศาสตร์"]'::jsonb,'{"topic": "4.3", "n": 36}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-36');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-37','M6','M6-SO','M6-SO-S4','A-Level 70',null,2,'ข้อใดเป็นปัจจัยสำคัญที่ทำให้สมเด็จพระมหาสมณเจ้า กรมพระยาวชิรญาณวโรรสทรงริเริ่มการอธิบายคำสอนในพระพุทธศาสนาด้วยการวิเคราะห์ และเน้นความสัมพันธ์ระหว่างพุทธศาสนากับความมีเหตุผลแบบวิทยาศาสตร์และความเป็นอารยะ','["การฉลองสมโภชพระนครครบ 100 ปี", "การตราพระราชบัญญัติคณะสงฆ์ ร.ศ. 121", "การล่าอาณานิคมของชาติตะวันตกในภูมิภาค", "การตราพระราชบัญญัติประถมศึกษา พ.ศ. 2464", "การก่อตั้งโรงเรียนราษฎร์หลายแห่งโดยคณะมิชชันนารี"]'::jsonb,2,array[2]::smallint[],'["สมัยล่าอาณานิคม มิชชันนารีตะวันตกวิจารณ์ว่าพระพุทธศาสนาไม่ทันสมัย สมเด็จพระมหาสมณเจ้า กรมพระยาวชิรญาณวโรรส จึงอธิบายพุทธศาสนาอย่างมีเหตุผลสอดคล้องกับวิทยาศาสตร์ เพื่อแสดงว่าสยามมีความเป็นอารยะ ไม่ด้อยกว่าตะวันตก"]'::jsonb,'["ไม่ถูก การฉลองพระนคร 100 ปีเป็นงานสมโภช ไม่ได้เป็นแรงผลักดันการตีความพุทธศาสนาแนวเหตุผล", "ไม่ถูก พ.ร.บ.คณะสงฆ์ ร.ศ. 121 เป็นการจัดระเบียบการปกครองคณะสงฆ์ ไม่ใช่สาเหตุของแนวคิดเหตุผลนิยม", "ถูก ภัยจากลัทธิอาณานิคมและการวิจารณ์ของตะวันตก ทำให้ชนชั้นนำสยามต้องแสดงความเป็นอารยะ รวมถึงการอธิบายศาสนาแบบมีเหตุผล", "ไม่ถูก พ.ร.บ.ประถมศึกษา พ.ศ. 2464 เกี่ยวกับการศึกษาภาคบังคับ", "ไม่ถูก โรงเรียนมิชชันนารีเป็นส่วนหนึ่งของบริบท แต่ปัจจัยหลักที่กว้างกว่าคือลัทธิอาณานิคม"]'::jsonb,'{"topic": "4.2", "n": 37}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-37');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-38','M6','M6-SO','M6-SO-S4','A-Level 70',null,2,'ศึกษาเอกสารชั้นต้นต่อไปนี้ และตอบคำถามด้านล่าง
“…ท่านทั้งปวงจะได้ความทราบเป็นจริง ด้วยการที่ ฯข้าฯ รับน้ำพระพิพัฒน์สัตยาปีละสองครั้งมิได้ขาด คือสำแดงปฏิญญาว่า ฯข้าฯ ไม่ประทุษร้ายแก่ท่านผู้หาความผิดมิได้ แลไม่พาโลโสคลุมด้วยการไม่ตรงแก่ท่านผู้หนึ่งผู้ใดเลย ก็การธรรมเนียมที่เจ้าแผ่นดินจะรับน้ำพระพิพัฒน์สัตยาเอาอย่าง ฯข้าฯ ประพฤตินี้แต่ก่อนมาก็หาเคยมีไม่ ก็ไม่มีใครติดใจบังคับให้ ฯข้าฯ ทำ ฯข้าฯ ยอมทำความสัตย์ให้ท่านทั้งปวงความชอบใจของฯข้าฯ เอง…”
(ส่วนหนึ่งของพระบรมราโชวาทรัชกาลที่ 4 ในวันเฉลิมพระชนมพรรษาครบ 60 พรรษา)
จากข้อความข้างต้น ข้อใดคือพระราชประสงค์หลักของพระบาทสมเด็จพระจอมเกล้าเจ้าอยู่หัว ในการเปลี่ยนแปลงพระราชพิธีถือน้ำพระพิพัฒน์สัตยา','["เพื่อให้แตกหักกับโบราณราชประเพณีในยุคสมัยของการสร้าง “สยามใหม่”", "เพื่อสร้างเสถียรภาพและเพิ่มความไว้วางใจระหว่างองค์พระมหากษัตริย์กับขุนนาง", "เพื่อสร้างภาพลักษณ์ความทันสมัยของอารยธรรมไทยให้เป็นที่ประจักษ์แก่ชาติมหาอำนาจ", "เพื่อต่อต้านและลดอิทธิพลของแนวคิดนิยมตะวันตกในหมู่ขุนนาง “หัวก้าวหน้า” ในราชสำนัก", "เพื่อใช้โบราณราชประเพณีในการส่งเสริมสถานะของพระมหากษัตริย์ในช่วงการรวมอำนาจเข้าสู่ศูนย์กลาง"]'::jsonb,1,array[1]::smallint[],'["เดิมขุนนางต้องถือน้ำพระพิพัฒน์สัตยาถวายความจงรักภักดีต่อกษัตริย์ฝ่ายเดียว รัชกาลที่ 4 ทรงเปลี่ยนให้พระมหากษัตริย์ทรงรับน้ำด้วย เป็นการแสดงความสัตย์ต่อขุนนางว่าจะไม่ประทุษร้ายผู้ไม่มีความผิด = สร้างความไว้วางใจซึ่งกันและกัน"]'::jsonb,'["ไม่ถูก ยังคงพระราชพิธีไว้ เพียงปรับให้กษัตริย์ร่วมถือน้ำด้วย ไม่ใช่การแตกหักกับประเพณี", "ถูก พระองค์ทรงสัตยาบันต่อขุนนางว่าจะไม่ทำร้ายผู้ไม่มีความผิด เป็นการสร้างความไว้วางใจและเสถียรภาพ", "ไม่ถูก ข้อความพูดกับ “ท่านทั้งปวง” (ขุนนาง) ไม่ได้มุ่งแสดงต่อชาติมหาอำนาจ", "ไม่ถูก ไม่มีหลักฐานในข้อความว่าเป็นการต่อต้านขุนนางหัวก้าวหน้า", "ไม่ถูก การที่กษัตริย์ทรงรับน้ำด้วยเป็นการลดทอนความเป็นเจ้าเหนือหัวฝ่ายเดียว ไม่ใช่การเสริมสถานะ"]'::jsonb,'{"topic": "4.2", "n": 38}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-38');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-39','M6','M6-SO','M6-SO-S4','A-Level 70',null,2,'ศึกษาเอกสารชั้นต้นต่อไปนี้ และตอบคำถามด้านล่าง
“นี่พี่น้องของเราไทยลานนา อยู่ด้วยกันนานมาแต่ก่อนเก่า ได้ร่วมแรงร่วมใจสร้างไทยเรา เป็นพงศ์เผ่าญาติสนิทและมิตรแท้ นี่ไทยใหญ่อยู่ใกล้ ๆ ทางทิศเหนือเป็นชาติเชื้อพี่ชายของไทยแน่ ยังรักษาความเป็นไทยไม่ผันแปร ขยายแผ่สาขาตระกูลไทย นี่คือไทยลานช้างอยู่ข้างเคียง เคยร่วมเรียงอยู่เป็นสุขทุกสมัย แม่น้ำโขงกั้นเขตประเทศไว้ แต่ไม่กั้นดวงใจที่รักกัน…”
(ส่วนหนึ่งของเนื้อเพลง “ระบำชุมนุมเผ่าไทย” จากละครเรื่องอานุภาพแห่งความเสียสละ ของพลตรีหลวงวิจิตรวาทการ)
ข้อความข้างต้นสัมพันธ์กับการดำเนินการในข้อใดมากที่สุด','["การรณรงค์ก่อตั้งประชาคมอาเซียนในช่วงสงครามเย็น", "การเผยแพร่อุดมการณ์ชาตินิยมในสมัยจอมพล ป.พิบูลสงคราม", "การต่อต้านลัทธิคอมมิวนิสต์ในอินโดจีนภายใต้รัฐบาลสฤษดิ์ ธนะรัชต์", "การเปลี่ยนสนามรบเป็นสนามการค้าของรัฐบาลพลเอกชาติชาย ชุณหะวัณ", "การก่อตั้งระบบมณฑลเทศาภิบาลในรัชสมัยพระบาทสมเด็จพระจุลจอมเกล้าเจ้าอยู่หัว"]'::jsonb,1,array[1]::smallint[],'["สมัยจอมพล ป. พิบูลสงคราม (รัฐบาลแรก พ.ศ. 2481–2487) ส่งเสริมชาตินิยมและแนวคิด “มหาอาณาจักรไทย/รวมเผ่าไทย” หลวงวิจิตรวาทการแต่งละครและเพลงปลุกใจ เช่น ระบำชุมนุมเผ่าไทย กล่าวถึงไทยลานนา ไทยใหญ่ ไทยลานช้าง ว่าเป็นพี่น้องเผ่าเดียวกัน"]'::jsonb,'["ไม่ถูก อาเซียนตั้งปี พ.ศ. 2510 และไม่ใช่เรื่องการรวมเผ่าไทย", "ถูก เนื้อเพลงเน้นความเป็นพี่น้องของชนชาติไทย เป็นการเผยแพร่อุดมการณ์ชาตินิยมของหลวงวิจิตรวาทการในสมัยจอมพล ป.", "ไม่ถูก ไม่มีเนื้อหาต่อต้านคอมมิวนิสต์", "ไม่ถูก นโยบายเปลี่ยนสนามรบเป็นสนามการค้าเป็นเรื่องเศรษฐกิจในอินโดจีน พ.ศ. 2531–2534", "ไม่ถูก มณฑลเทศาภิบาลเป็นการปฏิรูปการปกครองสมัย ร.5 ก่อนยุคของหลวงวิจิตรวาทการ"]'::jsonb,'{"topic": "4.2", "n": 39}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-39');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-40','M6','M6-SO','M6-SO-S4','A-Level 70',null,2,'ข้อใดกล่าวไม่ถูกต้อง เกี่ยวกับพัฒนาการทางศิลปะและสถาปัตยกรรมในประเทศไทย','["พระเจดีย์ประธานสามองค์ในวัดพระศรีสรรเพชญ์ จังหวัดพระนครศรีอยุธยา ได้รับอิทธิพลจากศิลปะลังกา", "พระปรางค์วัดอรุณราชวรารามวรมหาวิหาร กรุงเทพมหานคร เป็นการผสมผสานของศิลปะเขมรจีนและไทย", "พระศรีศากยะทศพลญาณ พระประธานพุทธมณฑลสุทรรศน์ จังหวัดนครปฐม สร้างตามรูปแบบพุทธศิลป์สมัยสุโขทัย", "พระอุโบสถตามศิลปะแบบพระราชนิยมของพระบาทสมเด็จพระนั่งเกล้าเจ้าอยู่หัวได้รับอิทธิพลจากศิลปะจีน", "พระพุทธรูปทรงเครื่องในสมัยอยุธยาคือพระพุทธรูปที่มีเครื่องทรงตามแบบเทพเจ้าในศาสนาพราหมณ์-ฮินดู"]'::jsonb,4,array[4]::smallint[],'["พระพุทธรูปทรงเครื่องในสมัยอยุธยาสะท้อนคติ “พระพุทธเจ้าในฐานะพระจักรพรรดิราช/ราชาธิราช” ทรงเครื่องอย่างกษัตริย์ ไม่ใช่เครื่องทรงเทพเจ้าฮินดู"]'::jsonb,'["ถูกต้อง เจดีย์ทรงระฆังสามองค์วัดพระศรีสรรเพชญ์ได้รับอิทธิพลศิลปะลังกา", "ถูกต้อง พระปรางค์วัดอรุณฯ มีรูปทรงปรางค์ (เขมร) ประดับกระเบื้องเคลือบ/ถ้วยชาม (จีน) ผสมงานช่างไทย", "ถูกต้อง พระศรีศากยะทศพลญาณ พุทธมณฑล เป็นพระลีลาตามแบบพุทธศิลป์สุโขทัย", "ถูกต้อง ศิลปะแบบพระราชนิยมในรัชกาลที่ 3 ได้รับอิทธิพลจีน เช่น หน้าบันประดับกระเบื้อง ไม่มีช่อฟ้าใบระกา", "ไม่ถูกต้อง (คำตอบ) พระพุทธรูปทรงเครื่องทรงเครื่องอย่างกษัตริย์/พระจักรพรรดิ ไม่ใช่ตามแบบเทพเจ้าพราหมณ์–ฮินดู"]'::jsonb,'{"topic": "4.2", "n": 40}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-40');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-41','M6','M6-SO','M6-SO-S5','A-Level 70',null,2,'ข้อใดถูกต้องเกี่ยวกับการกำหนดสัญลักษณ์ที่ใช้ในแผนที่','["ข้อมูลการแลกเปลี่ยนสินค้าระหว่างประเทศ แสดงด้วยสัญลักษณ์ประเภทเส้น", "ข้อมูลความกดอากาศ แสดงด้วยสัญลักษณ์ประเภทพื้นที่", "ความหนาแน่นประชากร แสดงด้วยสัญลักษณ์แทนข้อมูลเชิงคุณภาพ", "การย้ายถิ่นของประชากร แสดงด้วยสัญลักษณ์ประเภทจุด", "ชนิดของป่าไม้แสดงด้วยสัญลักษณ์แทนข้อมูลเชิงปริมาณ"]'::jsonb,0,array[0]::smallint[],'["สัญลักษณ์แผนที่: จุด เส้น พื้นที่ และข้อมูลเชิงคุณภาพ (ชนิด/ประเภท) กับเชิงปริมาณ (จำนวน ความหนาแน่น) · ข้อมูลการเคลื่อนที่/การไหล (การค้า การย้ายถิ่น) ใช้ “เส้นแสดงการไหล” · ความกดอากาศใช้เส้นไอโซบาร์"]'::jsonb,'["ถูก การแลกเปลี่ยนสินค้าระหว่างประเทศแสดงด้วยเส้นแสดงทิศทาง/ปริมาณการไหล", "ไม่ถูก ความกดอากาศแสดงด้วยเส้นเท่าความกดอากาศ (ไอโซบาร์) เป็นสัญลักษณ์เส้น", "ไม่ถูก ความหนาแน่นประชากรเป็นข้อมูลเชิงปริมาณ", "ไม่ถูก การย้ายถิ่นแสดงด้วยสัญลักษณ์เส้น (ลูกศรแสดงทิศทาง)", "ไม่ถูก ชนิดของป่าไม้เป็นข้อมูลเชิงคุณภาพ"]'::jsonb,'{"topic": "5.1", "n": 41}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-41');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-42','M6','M6-SO','M6-SO-S5','A-Level 70',null,2,'หลักการแปลภาพด้วยสายตา ข้อใดถูกต้อง','["น้ำใสสะท้อนคลื่นแสงได้ดี จึงมีสีอ่อนกว่าน้ำที่มีตะกอนมาก", "พื้นที่เพาะปลูกมีรูปแบบการจัดเรียงที่เป็นระเบียบมากกว่าป่าไม้ธรรมชาติ", "แม่น้ำลำคลองที่เกิดขึ้นเองตามธรรมชาติ มีรูปทรงเรขาคณิตและมีขอบเขตชัดเจน", "รูปที่ถ่ายในเวลาเที่ยงวัน ใช้ประเมินความสูงของวัตถุได้ดีกว่ารูปที่ถ่ายในช่วงเช้า", "ภูมิประเทศที่มีความสูงต่ำแตกต่างกัน จะมองเห็นเงาของภูมิประเทศได้ยากกว่าภูมิประเทศที่ราบเรียบ"]'::jsonb,1,array[1]::smallint[],'["การแปลภาพถ่ายทางอากาศ/ภาพจากดาวเทียมด้วยสายตา ใช้องค์ประกอบ: สี/ความเข้ม รูปร่าง ขนาด รูปแบบการจัดเรียง เนื้อภาพ เงา ที่ตั้ง · พื้นที่เกษตรจัดเรียงเป็นระเบียบ · น้ำใสดูดกลืนแสงมากจึงสีเข้ม · เงาช่วยประเมินความสูง"]'::jsonb,'["ไม่ถูก น้ำใสดูดกลืนแสงมาก จึงมีสีเข้มกว่าน้ำขุ่นที่มีตะกอนซึ่งสะท้อนแสงมากกว่า", "ถูก พื้นที่เพาะปลูกมีรูปแบบเป็นแปลง แถว ระเบียบ ต่างจากป่าธรรมชาติที่ไม่เป็นระเบียบ", "ไม่ถูก ทางน้ำธรรมชาติคดเคี้ยวไม่เป็นรูปเรขาคณิต ส่วนคลองที่มนุษย์ขุดจะเป็นเส้นตรง", "ไม่ถูก ตอนเที่ยงวันเงาสั้นที่สุด ภาพช่วงเช้าที่มีเงายาวช่วยประเมินความสูงได้ดีกว่า", "ไม่ถูก ภูมิประเทศสูงต่ำต่างกันเกิดเงาชัดกว่า จึงมองเห็นง่ายกว่าพื้นที่ราบ"]'::jsonb,'{"topic": "5.1", "n": 42}'::jsonb,'imported_m6','imported',true,'figure','Exam Gym ม.6 · 5620e4c',2569,'soc:69-42');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-43','M6','M6-SO','M6-SO-S5','A-Level 70',null,2,'ข้อใด ไม่ถูกต้อง เกี่ยวกับการเกิดพายุหมุนเขตร้อน','["บริเวณตาพายุจะเป็นบริเวณที่ลมสงบและไม่มีฝน", "พายุหมุนเขตร้อนทำให้เกิดน้ำท่วมฉับพลัน น้ำป่าไหลหลาก ดินถล่ม", "คลื่นพายุซัดฝั่งเกิดจากพายุหมุนเขตร้อนระดับพายุโซนร้อนขึ้นไป", "พายุหมุนเขตร้อนที่ก่อตัวในทะเล จะเพิ่มความรุนแรงเป็นพายุไต้ฝุ่นเสมอ", "พายุหมุนเขตร้อนเกิดในบริเวณระหว่างละติจูดที่ 5 – 30 องศาเหนือและใต้"]'::jsonb,3,array[3]::smallint[],'["พายุหมุนเขตร้อนก่อตัวเหนือทะเลอุ่นระหว่างละติจูดประมาณ 5–30 องศา แบ่งระดับตามความเร็วลม: พายุดีเปรสชัน → พายุโซนร้อน → ไต้ฝุ่น ไม่ใช่ทุกลูกจะพัฒนาเป็นไต้ฝุ่น ตาพายุลมสงบ"]'::jsonb,'["ถูกต้อง ตาพายุเป็นบริเวณที่อากาศจมตัว ลมสงบ ท้องฟ้าค่อนข้างโปร่ง", "ถูกต้อง ฝนตกหนักจากพายุทำให้น้ำท่วมฉับพลัน น้ำป่า และดินถล่ม", "ถูกต้อง คลื่นพายุซัดฝั่งมักเกิดจากพายุที่มีกำลังแรงระดับโซนร้อนขึ้นไป", "ไม่ถูกต้อง (คำตอบ) พายุหลายลูกอ่อนกำลังลงหรือสลายก่อนถึงระดับไต้ฝุ่น ไม่ใช่ “เสมอ”", "ถูกต้อง บริเวณใกล้เส้นศูนย์สูตร (0–5 องศา) แรงคอริออลิสน้อย พายุจึงก่อตัวยาก"]'::jsonb,'{"topic": "5.2", "n": 43}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-43');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-44','M6','M6-SO','M6-SO-S5','A-Level 70',null,2,'ข้อใด ไม่ถูกต้อง เกี่ยวกับการเกิดมลพิษทางอากาศ','["บริเวณที่มีลมแรง มลพิษทางอากาศจะต่ำกว่าบริเวณที่มีลมสงบ", "ฝุ่นละออง PM 2.5 มีส่วนก่อให้เกิดโรคมะเร็งปอด โรคหัวใจ และโรคระบบทางเดินหายใจ", "ก๊าซคาร์บอนมอนอกไซด์เป็นมลพิษทางอากาศที่เกิดจากยานพาหนะที่มีการเผาไหม้ไม่สมบูรณ์", "มลพิษทางอากาศที่เกิดในทวีปแอฟริกาตอนเหนือ มีสาเหตุหลักมาจากการใช้ถ่านหินในโรงงานอุตสาหกรรม", "มลพิษทางอากาศที่เกิดในเมืองลอสแอนเจลิส มีความรุนแรงเนื่องจากมีลักษณะภูมิประเทศที่แวดล้อมด้วยภูเขา"]'::jsonb,3,array[3]::smallint[],'["ปัจจัยมลพิษทางอากาศ: แหล่งกำเนิด (ยานพาหนะ อุตสาหกรรม การเผา ฝุ่นทะเลทราย) และสภาพอากาศ/ภูมิประเทศ (ลมสงบ แอ่งที่ราบล้อมด้วยภูเขา อุณหภูมิผกผัน) · แอฟริกาเหนือมีทะเลทรายสะฮารา มลพิษหลักคือฝุ่นจากพายุทราย"]'::jsonb,'["ถูกต้อง ลมแรงช่วยพัดพาและกระจายมลพิษ", "ถูกต้อง PM2.5 เข้าสู่ปอดและกระแสเลือด เพิ่มความเสี่ยงโรคปอด หัวใจ และระบบทางเดินหายใจ", "ถูกต้อง การเผาไหม้ไม่สมบูรณ์ของเครื่องยนต์ทำให้เกิดคาร์บอนมอนอกไซด์", "ไม่ถูกต้อง (คำตอบ) แอฟริกาตอนเหนือมีมลพิษหลักจากฝุ่นทรายของทะเลทรายสะฮารา ไม่ใช่การใช้ถ่านหินในอุตสาหกรรม", "ถูกต้อง ลอสแอนเจลิสอยู่ในแอ่งล้อมด้วยภูเขา มลพิษสะสม (หมอกควันเคมี) ได้ง่าย"]'::jsonb,'{"topic": "5.4", "n": 44}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-44');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-45','M6','M6-SO','M6-SO-S5','A-Level 70',null,2,'ปัจจุบันประเทศใดตั้งอยู่ในทวีปที่มีประชากรอาศัยอยู่มากเป็นอันดับสองของโลก','["Morocco", "Bolivia", "Croatia", "Honduras", "Türkiye"]'::jsonb,0,array[0]::smallint[],'["ทวีปที่มีประชากรมากที่สุด: เอเชีย อันดับสอง: แอฟริกา (ประมาณ 1,500 ล้านคน) โมร็อกโกอยู่ในแอฟริกาตอนเหนือ"]'::jsonb,'["ถูก โมร็อกโกอยู่ทวีปแอฟริกา ซึ่งมีประชากรมากเป็นอันดับสองรองจากเอเชีย", "ไม่ถูก โบลิเวียอยู่ทวีปอเมริกาใต้", "ไม่ถูก โครเอเชียอยู่ทวีปยุโรป", "ไม่ถูก ฮอนดูรัสอยู่ทวีปอเมริกาเหนือ (อเมริกากลาง)", "ไม่ถูก ตุรกี (Türkiye) ส่วนใหญ่อยู่ในทวีปเอเชีย (มีส่วนน้อยในยุโรป) ซึ่งเป็นอันดับหนึ่ง"]'::jsonb,'{"topic": "5.3", "n": 45}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-45');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-46','M6','M6-SO','M6-SO-S5','A-Level 70',null,2,'ข้อใดเรียงลำดับประเทศในภูมิภาคเอเชียตะวันออกเฉียงใต้ตามความหนาแน่นของประชากรในช่วงปีปัจจุบัน จากมากไปหาน้อย ได้ถูกต้อง','["เวียดนาม มาเลเซีย ลาว", "ไทย เวียดนาม อินโดนีเซีย", "สิงคโปร์ กัมพูชา เวียดนาม", "มาเลเซีย ฟิลิปปินส์ เมียนมา", "อินโดนีเซีย ฟิลิปปินส์ กัมพูชา"]'::jsonb,0,array[0]::smallint[],'["ความหนาแน่นประชากรโดยประมาณ (คน/ตร.กม.): สิงคโปร์ ~8,000 · ฟิลิปปินส์ ~380 · เวียดนาม ~300 · อินโดนีเซีย ~150 · ไทย ~135 · มาเลเซีย ~100 · กัมพูชา ~95 · เมียนมา ~80 · ลาว ~30"]'::jsonb,'["ถูก เวียดนาม (~300) > มาเลเซีย (~100) > ลาว (~30)", "ไม่ถูก เวียดนามหนาแน่นกว่าไทย", "ไม่ถูก เวียดนามหนาแน่นกว่ากัมพูชา", "ไม่ถูก ฟิลิปปินส์หนาแน่นกว่ามาเลเซีย", "ไม่ถูก ฟิลิปปินส์หนาแน่นกว่าอินโดนีเซีย"]'::jsonb,'{"topic": "5.3", "n": 46}'::jsonb,'imported_m6','imported',false,null,'ตัวเลขความหนาแน่นเป็นค่าประมาณ ใช้เพื่อเรียงลำดับเท่านั้น',2569,'soc:69-46');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-47','M6','M6-SO','M6-SO-S5','A-Level 70',null,2,'ข้อใดแสดงความสัมพันธ์ที่ ไม่ถูกต้อง ระหว่างภูมิศาสตร์กับกิจกรรมทางเศรษฐกิจ','["โคเนื้อพันธุ์บราห์มัน ทนอากาศร้อนชื้นได้ดี", "ข้าวสาลี ปลูกได้ทั้งในฤดูใบไม้ผลิและฤดูหนาว", "ปาล์มน้ำมัน เจริญเติบโตได้ดีในเขตฝนตกชุกสม่ำเสมอตลอดปี", "การทำนาขั้นบันไดในทวีปเอเชียส่วนใหญ่เลือกทำในพื้นที่ที่มีความลาดชันสูง", "แหล่งประมงสำคัญของโลก มักอยู่บริเวณที่กระแสน้ำอุ่นกับกระแสน้ำเย็นมาบรรจบกัน"]'::jsonb,3,array[3]::smallint[],'["เกษตรกับภูมิศาสตร์: โคบราห์มันทนร้อนชื้น · ข้าวสาลีมีพันธุ์ฤดูใบไม้ผลิและฤดูหนาว · ปาล์มน้ำมันชอบฝนชุกสม่ำเสมอ · แหล่งประมงสำคัญอยู่ที่กระแสน้ำอุ่นและเย็นมาบรรจบกัน · นาขั้นบันไดทำบนพื้นที่ลาดเชิงเขาเพราะขาดที่ราบ ไม่ได้เลือกพื้นที่ชันมาก"]'::jsonb,'["ถูกต้อง โคพันธุ์บราห์มันทนความร้อนและความชื้นได้ดี", "ถูกต้อง มีข้าวสาลีฤดูใบไม้ผลิและข้าวสาลีฤดูหนาว", "ถูกต้อง ปาล์มน้ำมันต้องการฝนตกชุกสม่ำเสมอตลอดปี", "ไม่ถูกต้อง (คำตอบ) นาขั้นบันไดเป็นการปรับพื้นที่ลาดเชิงเขาเพราะขาดที่ราบ ไม่ใช่การ “เลือก” พื้นที่ลาดชันสูง (พื้นที่ชันมากเสี่ยงการพังทลาย)", "ถูกต้อง บริเวณกระแสน้ำอุ่นพบกระแสน้ำเย็นมีแพลงก์ตอนมาก จึงเป็นแหล่งประมงสำคัญ"]'::jsonb,'{"topic": "5.3", "n": 47}'::jsonb,'imported_m6','imported',true,'expl','ตัวเลือก 4 กำกวมเล็กน้อย (นาขั้นบันไดอยู่บนที่ลาดจริง) คำตอบได้จากการตัดตัวเลือกอื่นที่ถูกชัดเจน',2569,'soc:69-47');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-48','M6','M6-SO','M6-SO-S5','A-Level 70',null,2,'ข้อใดกล่าวถูกต้องเกี่ยวกับการตั้งถิ่นฐานในเมือง','["มีลักษณะรวมกลุ่มของประชากรที่เชื้อสายเดียวกันเท่านั้น", "ประชากรตั้งถิ่นฐานแบบกระจายครอบคลุมพื้นที่กว้างขวาง", "มักพบย่านธุรกิจกลางได้ในบริเวณจุดตัดของถนนสายสำคัญ", "ประชากรในเขตเทศบาลตำบลไม่ถือเป็นประชากรในเขตเมือง", "มักเป็นการตั้งถิ่นฐานที่พื้นที่อยู่อาศัยและที่ดินทำกินอยู่ในพื้นที่เดียวกัน"]'::jsonb,2,array[2]::smallint[],'["การตั้งถิ่นฐานในเมือง: ประชากรหนาแน่น หลากหลายเชื้อสาย อาชีพนอกภาคเกษตร มักมีย่านธุรกิจกลาง (CBD) บริเวณจุดตัดเส้นทางคมนาคมสำคัญ ในสถิติไทยเขตเทศบาล (รวมเทศบาลตำบล) นับเป็นเขตเมือง"]'::jsonb,'["ไม่ถูก เมืองมีประชากรหลากหลายเชื้อสาย", "ไม่ถูก การตั้งถิ่นฐานแบบกระจายเป็นลักษณะชนบท เมืองเป็นแบบรวมกลุ่มหนาแน่น", "ถูก ย่านธุรกิจกลางมักอยู่บริเวณจุดตัดถนนสายหลักที่เข้าถึงง่าย", "ไม่ถูก สถิติประชากรไทยนับประชากรในเขตเทศบาลทุกประเภทเป็นประชากรในเขตเมือง", "ไม่ถูก ที่อยู่อาศัยกับที่ดินทำกินอยู่ด้วยกันเป็นลักษณะชนบท/เกษตรกรรม"]'::jsonb,'{"topic": "5.3", "n": 48}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-48');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-49','M6','M6-SO','M6-SO-S5','A-Level 70',null,2,'ข้อใดกล่าวถูกต้องเกี่ยวกับการท่องเที่ยว','["การจัดประชุมนานาชาติ ถือเป็นการส่งเสริมการท่องเที่ยวเชิงวิชาการ", "ทวีปแอฟริกามีนักท่องเที่ยวเดินทางไปมาก เนื่องจากยังมีความเป็นธรรมชาติสูง", "การท่องเที่ยวเชิงบำบัดรักษา เป็นการสร้างจิตสำนึกในการอนุรักษ์ทรัพยากรการท่องเที่ยวอย่างยั่งยืน", "การท่องเที่ยวเป็นการสร้างงานให้ประชาชน และสร้างรายได้ให้ธุรกิจที่เกี่ยวข้อง เป็นการกระจายรายได้อย่างเป็นธรรม", "ในช่วงก่อนสถานการณ์โควิด-19 นักท่องเที่ยวจากภูมิภาคเอเชียตะวันออกเดินทางมาท่องเที่ยวในประเทศไทยมากที่สุด"]'::jsonb,4,array[4]::smallint[],'["การท่องเที่ยว: การประชุมนานาชาติจัดเป็น “การท่องเที่ยวเพื่อการประชุมและนิทรรศการ (MICE)” · ท่องเที่ยวเชิงบำบัดรักษา = เน้นสุขภาพ · ก่อนโควิด-19 (ปี 2562) นักท่องเที่ยวต่างชาติมาไทยมากที่สุดจากเอเชียตะวันออก (จีน)"]'::jsonb,'["ไม่ถูก การจัดประชุมนานาชาติเป็นการท่องเที่ยวเชิงธุรกิจ/MICE ไม่ใช่การท่องเที่ยวเชิงวิชาการ", "ไม่ถูก แอฟริกามีนักท่องเที่ยวน้อยกว่าทวีปอื่นหลายทวีป (เช่น ยุโรป เอเชีย)", "ไม่ถูก การท่องเที่ยวเชิงบำบัดรักษามุ่งดูแลสุขภาพ การสร้างจิตสำนึกอนุรักษ์เป็นลักษณะของการท่องเที่ยวเชิงนิเวศ", "ไม่ถูก การท่องเที่ยวสร้างงานและรายได้ แต่รายได้ไม่ได้กระจายอย่างเป็นธรรมเสมอไป", "ถูก ก่อนโควิด-19 นักท่องเที่ยวจากเอเชียตะวันออก (โดยเฉพาะจีน) มาไทยมากที่สุด"]'::jsonb,'{"topic": "5.3", "n": 49}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-49');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-69-50','M6','M6-SO','M6-SO-S5','A-Level 70',null,2,'ข้อใดกล่าวถูกต้องเกี่ยวกับกฎหมาย/ความร่วมมือระหว่างประเทศเพื่อการอนุรักษ์สิ่งแวดล้อม','["อนุสัญญาเวียนนา เพื่ออนุรักษ์ความหลากหลายทางชีวภาพอย่างยั่งยืน", "อนุสัญญาบาเซิล เพื่อรณรงค์ให้เลิกใช้สาร CFC ที่จะไปทำลายชั้นโอโซน", "อนุสัญญาแรมซาร์ ได้รับการรับรองจากที่ประชุมที่ญี่ปุ่น เพื่ออนุรักษ์พื้นที่ชุ่มน้ำทั่วโลก", "อนุสัญญาอาบีจาน เพื่อปกป้องมหาสมุทรและน่านน้ำในภูมิภาคเอเชียตะวันตกเฉียงใต้", "อนุสัญญาไซเตส ควบคุมการนำเข้า ส่งออก หรือนำผ่านของสัตว์ป่าที่ใกล้สูญพันธุ์"]'::jsonb,4,array[4]::smallint[],'["อนุสัญญาด้านสิ่งแวดล้อม: เวียนนา (ปกป้องชั้นโอโซน) · มอนทรีออล (ลด/เลิกสาร CFCs) · บาเซิล (ควบคุมการเคลื่อนย้ายของเสียอันตรายข้ามแดน) · แรมซาร์ (พื้นที่ชุ่มน้ำ ทำที่เมืองแรมซาร์ อิหร่าน ค.ศ. 1971) · อาบีจาน (ทะเลและชายฝั่งแอฟริกาตะวันตก–กลาง–ใต้) · ไซเตส (CITES ค้าสัตว์ป่าพืชป่าใกล้สูญพันธุ์)"]'::jsonb,'["ไม่ถูก อนุสัญญาเวียนนาเกี่ยวกับการปกป้องชั้นโอโซน ความหลากหลายทางชีวภาพคือ CBD", "ไม่ถูก อนุสัญญาบาเซิลควบคุมการเคลื่อนย้ายของเสียอันตรายข้ามพรมแดน การเลิกใช้ CFCs คือพิธีสารมอนทรีออล", "ไม่ถูก อนุสัญญาแรมซาร์ทำขึ้นที่เมืองแรมซาร์ ประเทศอิหร่าน ไม่ใช่ญี่ปุ่น", "ไม่ถูก อนุสัญญาอาบีจานคุ้มครองทะเลและชายฝั่งของแอฟริกา ไม่ใช่เอเชียตะวันตกเฉียงใต้", "ถูก CITES ควบคุมการนำเข้า ส่งออก และนำผ่านพืชและสัตว์ป่าที่ใกล้สูญพันธุ์"]'::jsonb,'{"topic": "5.4", "n": 50}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'soc:69-50');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-1','M6','M6-SO','M6-SO-S1','A-Level 70',null,2,'จากบทเพลง “ใจเป็นนาย กายเป็นบ่าว” ของศิลปิน เล็ก รัชเมศฐ์ ในท่อนที่ว่า
“ตาที่ยังคงบอดเพราะคำว่ารัก ตัวที่ยังจมปลักกับภาพความหลัง คล้ายดังเรือไม่คืนฝั่งถูกขังกลางคลื่นความงมงาย ยอมให้ยังต้องเจ็บจากการคิดถึง จนเหมือนเป็นอันหนึ่งกับความปวดร้าว ร่างก็เป็นได้แค่บ่าวให้ใจบงการชักนำ”
เนื้อเพลงดังกล่าวสอดคล้องกับหลักธรรมนิวรณ์ 5 ที่เป็นสาเหตุให้เกิดทุกข์และเป็นธรรมที่ควรละทางพระพุทธศาสนาในข้อใดมากที่สุด','["อุทธัจจกุกกุจจะ และ ถีนมิทธะ", "พยาบาท และ กามฉันทะ", "ถีนมิทธะ และ วิจิกิจฉา", "วิจิกิจฉา และ พยาบาท", "กามฉันทะ และ อุทธัจจกุกกุจจะ"]'::jsonb,4,array[4]::smallint[],'["นิวรณ์ 5 คือสิ่งที่กั้นจิตไม่ให้บรรลุความดี ได้แก่ กามฉันทะ (ความพอใจติดใจในสิ่งที่น่าใคร่ รวมถึงความรัก) พยาบาท (ความขุ่นเคืองคิดร้าย) ถีนมิทธะ (ความหดหู่ง่วงเหงา) อุทธัจจกุกกุจจะ (ความฟุ้งซ่านรำคาญใจ) วิจิกิจฉา (ความลังเลสงสัย) เนื้อเพลง “ตาบอดเพราะคำว่ารัก” = กามฉันทะ และ “จมปลักกับภาพความหลัง เจ็บจากการคิดถึง ใจบงการ” = จิตฟุ้งซ่าน กังวล รำคาญใจ = อุทธัจจกุกกุจจะ"]'::jsonb,'["มีอุทธัจจกุกกุจจะถูก แต่ถีนมิทธะคือความง่วงเหงาหดหู่ซึม ซึ่งเพลงไม่ได้พูดถึงความง่วงหรือความเกียจคร้าน", "กามฉันทะถูก แต่พยาบาทคือความโกรธ คิดร้ายผู้อื่น เพลงไม่ได้แสดงความแค้นหรืออยากทำร้ายใคร", "ไม่ตรงทั้งคู่ เพลงไม่ได้พูดถึงความง่วงซึม (ถีนมิทธะ) หรือความลังเลไม่แน่ใจ (วิจิกิจฉา)", "ไม่ตรงทั้งคู่ เพลงไม่ได้แสดงความลังเลสงสัย หรือความโกรธแค้น", "ถูก “ตาบอดเพราะรัก” คือความติดใจในความรัก (กามฉันทะ) ส่วน “จมกับความหลัง คิดถึงจนเจ็บ ใจบงการกาย” คือจิตฟุ้งซ่าน วนคิด รำคาญใจ (อุทธัจจกุกกุจจะ)"]'::jsonb,'{"topic": "1.1", "n": 1}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-1');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-2','M6','M6-SO','M6-SO-S1','A-Level 70',null,2,'จากกรณีที่อาจารย์เบียร์ “คนตื่นธรรม” ได้ถ่ายทอดพระธรรมคำสั่งสอนของพระพุทธเจ้าออกทางสื่อสังคมออนไลน์ และมีกระแสการตอบโต้ในประเด็นว่าขัดแย้งหรือไม่ตรงกับหลักธรรมต่าง ๆ ทางพุทธศาสนานั้น จากประเด็นนี้ ควรแนะนำให้พุทธศาสนิกชนศึกษาคัมภีร์พระพุทธศาสนาตามข้อใดจึงถือว่าเหมาะสมและสอดคล้องกับสถานการณ์ดังกล่าวมากที่สุด','["พระไตรปิฎก และ อรรถกถา", "วินัยปิฎก และ อนุฎีกา", "อรรถกถา และ ฎีกา", "พุทธวจน และ ฎีกา", "ฎีกา และ อนุฎีกา"]'::jsonb,0,array[0]::smallint[],'["เมื่อมีข้อสงสัยว่าคำสอนใดตรงหลักพระพุทธศาสนาหรือไม่ ควรตรวจสอบกับคัมภีร์ชั้นต้นที่สุด ลำดับชั้นคัมภีร์: พระไตรปิฎก (บาลี/ปฐมภูมิ พุทธพจน์) → อรรถกถา (ทุติยภูมิ อธิบายพระไตรปิฎก) → ฎีกา (ตติยภูมิ อธิบายอรรถกถา) → อนุฎีกา (จตุตถภูมิ อธิบายฎีกา) จึงควรศึกษาพระไตรปิฎกคู่กับอรรถกถา"]'::jsonb,'["ถูก พระไตรปิฎกเป็นหลักฐานชั้นต้นที่บันทึกพุทธพจน์ และอรรถกถาเป็นคำอธิบายชั้นรองที่ใกล้ที่สุด จึงเหมาะที่สุดในการตรวจสอบว่าคำสอนตรงหลักหรือไม่", "วินัยปิฎกเป็นเพียงปิฎกเดียว ว่าด้วยวินัยสงฆ์ ไม่ครอบคลุมหลักธรรม (สุตตันตปิฎก อภิธรรมปิฎก) และอนุฎีกาเป็นคัมภีร์ชั้นที่ 4 ห่างจากพุทธพจน์มาก", "ไม่มีพระไตรปิฎกซึ่งเป็นหลักฐานชั้นต้น มีแต่คัมภีร์ชั้นอธิบาย (ชั้น 2 และ 3)", "“พุทธวจน” ไม่ใช่ชื่อชั้นคัมภีร์ตามจารีต (เป็นชื่อเรียกการคัดพุทธพจน์ของบางกลุ่ม) และฎีกาเป็นคัมภีร์ชั้นที่ 3", "ฎีกาและอนุฎีกาเป็นคัมภีร์ชั้นที่ 3 และ 4 อธิบายต่อจากอรรถกถา ห่างจากพุทธพจน์มากที่สุด"]'::jsonb,'{"topic": "1.2", "n": 2}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-2');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-3','M6','M6-SO','M6-SO-S1','A-Level 70',null,2,'พุทธศาสนิกชนในข้อใดที่ปฏิบัติตนเกี่ยวกับพิธีทอดกฐินไม่ถูกต้อง','["นายประยูรเข้าร่วมการทอดกฐินสามัคคีของชุมชนที่วัดในวันขึ้น 13 ค่ำ เดือน 12", "นางสาวประกอบเป็นประธานในพิธีทอดกฐินโดยจัดกฐินหลวงไปทอดถวายที่วัดประจำจังหวัด", "นางสาวประพีร์บอกบุญกับชาวบ้านอย่างเร่งด่วนเพื่อทำการถวายจุลกฐินให้วัดที่ยังไม่ได้รับกฐิน", "นางประภาเข้าร่วมเฝ้าทูลละอองธุลีพระบาทในการที่พระเจ้าอยู่หัวเสด็จพระราชดำเนินทอดกฐินต้น", "นายประสิทธิ์ทำการจองกฐินพระราชทานต่อกรมการศาสนาเพื่อนำไปทอดถวายที่พระอารามหลวง"]'::jsonb,1,array[1]::smallint[],'["กฐินแบ่งเป็นกฐินหลวง (เกี่ยวกับพระมหากษัตริย์: เสด็จฯ ทอดเอง/กฐินต้น หรือพระราชทานผ้าให้ผู้อื่นไปทอดแทน = กฐินพระราชทาน ที่พระอารามหลวง) และกฐินราษฎร์ (ประชาชนทอดเอง เช่น กฐินสามัคคี จุลกฐิน) ช่วงทอดกฐิน: แรม 1 ค่ำ เดือน 11 ถึงขึ้น 15 ค่ำ เดือน 12 บุคคลทั่วไปจะ “จัดกฐินหลวง” เองไม่ได้ ต้องขอพระราชทาน (จองกฐินพระราชทาน) ผ่านกรมการศาสนา"]'::jsonb,'["ปฏิบัติถูก กฐินสามัคคีเป็นกฐินราษฎร์ และวันขึ้น 13 ค่ำ เดือน 12 อยู่ในช่วงเวลาทอดกฐิน (ไม่เกินขึ้น 15 ค่ำ เดือน 12)", "ปฏิบัติไม่ถูก (คำตอบ) บุคคลทั่วไปจะตั้งตนเป็นประธาน “จัดกฐินหลวง” เองไม่ได้ เพราะกฐินหลวงเป็นกฐินของพระมหากษัตริย์ ถ้าต้องการทอดที่พระอารามหลวงต้องขอรับพระราชทานผ้ากฐิน (กฐินพระราชทาน) ก่อน", "ปฏิบัติถูก จุลกฐินคือกฐินที่ต้องทำให้เสร็จภายในวันเดียว มักจัดอย่างเร่งด่วนให้วัดที่ยังไม่มีผู้มาทอด", "ปฏิบัติถูก กฐินต้นคือกฐินที่พระมหากษัตริย์เสด็จฯ ไปทอดเป็นการส่วนพระองค์ ประชาชนเข้าเฝ้าทูลละอองธุลีพระบาทได้", "ปฏิบัติถูก การจองกฐินพระราชทานต้องติดต่อกรมการศาสนา และนำไปทอดที่พระอารามหลวง"]'::jsonb,'{"topic": "1.2", "n": 3}'::jsonb,'imported_m6','imported',false,null,'ตรวจคำอธิบายประเภทกฐินหลวง/กฐินต้นกับหนังสือเรียนที่ใช้',2568,'soc:68-3');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-4','M6','M6-SO','M6-SO-S1','A-Level 70',null,2,'ข้อใดกล่าวไม่ถูกต้องเกี่ยวกับเหตุการณ์สำคัญและหลักธรรมของพระพุทธศาสนา','["โกณฑัญญะ ดวงตาเห็นธรรมและขอบวชภายหลังได้ฟังพระธรรมเทศนา “ธัมมจักกัปปวัตตนสูตร”", "ปัญจวัคคีย์ทั้ง 5 ได้ฟัง “อนัตตลักขณสูตร” ที่ว่าหลักอนัตตา จนบรรลุอรหันต์", "ปฐมเทศนาในช่วงต้นที่ทรงสอนแก่ปัญจวัคคีย์ คือ การเน้นย้ำว่าทางสุดโต่งไม่ทำให้พ้นทุกข์", "พระปัจฉิมโอวาทที่ตรัสสอนแก่สาวก คือ หลักคำสอนในความเสื่อมและความไม่ประมาท", "มหาสาวกสันนิบาตได้รับฟัง “โอวาทปาติโมกข์” ในวันเพ็ญเดือนมาฆะจนบรรลุอรหันต์ทั้งหมด"]'::jsonb,4,array[4]::smallint[],'["เหตุการณ์สำคัญในพุทธประวัติ: ปฐมเทศนา “ธัมมจักกัปปวัตตนสูตร” (ทางสายกลาง ละที่สุด 2 อย่าง) โกณฑัญญะได้ดวงตาเห็นธรรมและขอบวช · “อนัตตลักขณสูตร” ทำให้ปัญจวัคคีย์บรรลุอรหันต์ · โอวาทปาติโมกข์แสดงในวันมาฆบูชาแก่พระอรหันต์ 1,250 รูปที่เป็นพระอรหันต์อยู่แล้ว · ปัจฉิมโอวาท: สังขารมีความเสื่อมเป็นธรรมดา จงยังความไม่ประมาทให้ถึงพร้อม"]'::jsonb,'["ถูก โกณฑัญญะได้ดวงตาเห็นธรรม (เป็นโสดาบัน) หลังฟังธัมมจักกัปปวัตตนสูตร แล้วขอบวชเป็นภิกษุรูปแรก", "ถูก อนัตตลักขณสูตรแสดงเรื่องขันธ์ 5 เป็นอนัตตา ปัญจวัคคีย์ฟังแล้วบรรลุอรหันต์ทั้ง 5 รูป", "ถูก ปฐมเทศนาเริ่มด้วยการชี้ว่าที่สุด 2 อย่าง (กามสุขัลลิกานุโยค และอัตตกิลมถานุโยค) ไม่ใช่ทางพ้นทุกข์ แล้วแสดงทางสายกลาง", "ถูก ปัจฉิมโอวาทสอนเรื่องความเสื่อมของสังขารและความไม่ประมาท", "ไม่ถูก (คำตอบ) พระสงฆ์ 1,250 รูปในวันมาฆบูชาเป็นพระอรหันต์อยู่แล้วก่อนมาประชุม (จาตุรงคสันนิบาต) ไม่ได้บรรลุเพราะฟังโอวาทปาติโมกข์"]'::jsonb,'{"topic": "1.1", "n": 4}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-4');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-5','M6','M6-SO','M6-SO-S1','A-Level 70',null,2,'จากบทเพลง “โลกที่แบกไว้” ของศิลปิน มนัสวีร์ แก้วใส ในท่อนที่ว่า
“โอ้ว เธอเบื่อและท้อเกินกว่าจะมีใครเข้าใจ โลกนี้มันโหดร้ายกับเธอเกินไป กับเธอมากไป เธอคงแบกความหวังมากเกินไป เธอเริ่มเหนื่อยและล้าทั้งหัวใจ ใครคงฝากความหวังไว้มากมายกับเธอ และไม่รู้ต้องไปอีกเท่าไหร่ และไม่รู้ต้องเดินอีกไกลแค่ไหน กว่าจะถึงจุดหมายที่เธอวาดเอาไว้”
จากเนื้อเพลงดังกล่าวควรใช้หลักธรรมในข้อใด เพื่อเป็นการพิจารณาตนเองให้เกิดความเข้าใจต่อสิ่งที่เกิดขึ้นมากที่สุด','["หลักนิวรณ์ 5", "หลักอุบาสกธรรม 5", "หลักสติปัฏฐาน 4", "หลักสารณียธรรม 6", "หลักอปริหายธรรม 7"]'::jsonb,2,array[2]::smallint[],'["สติปัฏฐาน 4 (กาย เวทนา จิต ธรรม) คือการตั้งสติพิจารณาสิ่งที่เกิดขึ้นกับตนตามความเป็นจริง เหมาะกับคนที่เหนื่อยล้า ท้อ แบกความคาดหวัง เพื่อให้รู้เท่าทันความรู้สึกและเข้าใจสิ่งที่เกิดขึ้น"]'::jsonb,'["นิวรณ์ 5 เป็น “สิ่งที่ควรละ” เพราะกั้นจิต ไม่ใช่วิธีพิจารณาตนเองให้เข้าใจสิ่งที่เกิดขึ้น", "อุบาสกธรรม 5 เป็นคุณสมบัติของอุบาสกที่ดี (มีศรัทธา มีศีล ไม่ถือมงคลตื่นข่าว ฯลฯ) ไม่เกี่ยวกับการพิจารณาความทุกข์ใจ", "ถูก สติปัฏฐาน 4 คือการมีสติรู้เท่าทันกาย ความรู้สึก (เวทนา) จิต และธรรม ช่วยให้เข้าใจความเหนื่อยท้อที่เกิดขึ้นตามความเป็นจริง", "สาราณียธรรม 6 เป็นหลักการอยู่ร่วมกันให้ระลึกถึงกัน (เมตตากาย วาจา ใจ แบ่งปัน มีศีลและความเห็นร่วมกัน) ใช้กับหมู่คณะ ไม่ใช่การพิจารณาตนเอง", "อปริหานิยธรรม 7 เป็นหลักป้องกันความเสื่อมของหมู่คณะ/บ้านเมือง (ประชุมกันเนืองนิตย์ ฯลฯ) ไม่ใช่หลักพิจารณาใจตนเอง"]'::jsonb,'{"topic": "1.1", "n": 5}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-5');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-6','M6','M6-SO','M6-SO-S1','A-Level 70',null,2,'การทำพลีในหลักธรรมโภคอาทิยะ 5 ของพระพุทธศาสนาสอดคล้องกับหลักปฏิบัติ 5 ประการในข้อใดของศาสนาอิสลาม','["การถือศีลอด", "การละหมาด", "การปฏิญาณตน", "การบริจาคซะกาต", "การประกอบพิธีฮัจญ์"]'::jsonb,3,array[3]::smallint[],'["โภคอาทิยะ 5 (ประโยชน์ที่ควรถือเอาจากทรัพย์) ข้อ “ทำพลี” คือการสละทรัพย์สงเคราะห์ผู้อื่น 5 อย่าง (ญาติพลี อติถิพลี ปุพพเปตพลี ราชพลี เทวตาพลี) ซึ่งตรงกับการบริจาคซะกาต (การจ่ายทรัพย์ส่วนหนึ่งช่วยผู้มีสิทธิ์รับ) ในหลักปฏิบัติ 5 ของอิสลาม"]'::jsonb,'["การถือศีลอดเป็นการฝึกขันติ ควบคุมตนในเดือนรอมฎอน ไม่ใช่การสละทรัพย์", "การละหมาดเป็นการนมัสการอัลลอฮ์วันละ 5 เวลา ไม่เกี่ยวกับการใช้ทรัพย์", "การปฏิญาณตน (ชะฮาดะฮ์) เป็นการกล่าวยืนยันศรัทธา ไม่ใช่การแบ่งปันทรัพย์", "ถูก ซะกาตคือการจ่ายทรัพย์ตามอัตราที่กำหนดให้ผู้มีสิทธิ์รับ ตรงกับ “พลี” ที่เป็นการสละทรัพย์สงเคราะห์ผู้อื่น", "พิธีฮัจญ์คือการเดินทางไปประกอบพิธีที่นครมักกะฮ์ แม้ใช้ทรัพย์แต่ไม่ใช่การสงเคราะห์ผู้อื่น"]'::jsonb,'{"topic": "1.3", "n": 6}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-6');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-7','M6','M6-SO','M6-SO-S1','A-Level 70',null,2,'ข้อใดกล่าวถูกต้องเกี่ยวกับคำสอนหรือหลักปฏิบัติในศาสนาต่าง ๆ ที่สำคัญ','["ศาสนาสิข เชื่อในพระเป็นเจ้าองค์เดียวเท่านั้นเป็นสัจจะสูงสุด และสิ่งต่าง ๆ ก็เป็นสัจจะ", "ศาสนาอิสลาม เชื่อในคัมภีร์อัลกุรอาน และห้ามแปลเป็นภาษาอื่น นอกจากภาษาอาหรับ", "ศาสนาคริสต์ นิกายออร์ทอดอกซ์ เชื่อในศรัทธาของบุคคลที่มีต่อพระเจ้ามากกว่าพิธีกรรม", "ศาสนาพราหมณ์ - ฮินดู มีหลักปฏิบัติให้คนในทุกวรรณะต้องทำพิธีสังสการเพื่อให้เป็นผู้บริสุทธิ์", "ศาสนาพุทธ เชื่อมั่นในกฎแห่งกรรม สาเหตุและผลการกระทำ ปฏิเสธการศึกษาความรู้จากคัมภีร์"]'::jsonb,0,array[0]::smallint[],'["ลักษณะสำคัญของศาสนาต่าง ๆ: ซิกข์นับถือพระเจ้าองค์เดียว (เอกเทวนิยม) · อัลกุรอานมีฉบับแปลความหมายเป็นภาษาต่าง ๆ ได้ (ต้นฉบับภาษาอาหรับเป็นหลัก) · นิกายออร์ทอดอกซ์เคร่งพิธีกรรมดั้งเดิม · พิธีสังสการสำหรับวรรณะทวิชาติ (พราหมณ์ กษัตริย์ แพศย์) · พุทธศาสนาไม่ได้ปฏิเสธการศึกษาคัมภีร์"]'::jsonb,'["ถูก ศาสนาซิกข์เชื่อในพระเจ้าองค์เดียวเป็นสัจจะสูงสุด (สัตนาม) และสิ่งที่พระองค์สร้างก็เป็นจริง", "ไม่ถูก อิสลามไม่ได้ห้ามแปลอัลกุรอาน มีการแปลความหมายเป็นภาษาต่าง ๆ รวมทั้งภาษาไทย เพียงแต่ถือว่าต้นฉบับภาษาอาหรับเท่านั้นที่เป็นคัมภีร์แท้", "ไม่ถูก ออร์ทอดอกซ์เน้นรักษาพิธีกรรมและประเพณีดั้งเดิมอย่างเคร่งครัด แนวคิด “ศรัทธาสำคัญกว่าพิธีกรรม” เป็นจุดเด่นของโปรเตสแตนต์", "ไม่ถูก พิธีสังสการไม่ได้ใช้กับทุกวรรณะ แต่จำกัดเฉพาะวรรณะทวิชาติ วรรณะศูทรไม่มีสิทธิ์ทำพิธีส่วนใหญ่", "ไม่ถูก พุทธศาสนาเชื่อกฎแห่งกรรมก็จริง แต่ไม่ได้ปฏิเสธการศึกษาคัมภีร์ (กาลามสูตรสอนเพียงว่าอย่าเชื่อเพียงเพราะอ้างตำรา)"]'::jsonb,'{"topic": "1.3", "n": 7}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-7');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-8','M6','M6-SO','M6-SO-S1','A-Level 70',null,2,'ข้อใดเป็นหลักความเชื่อที่สอดคล้องกันระหว่างศาสนาพุทธและศาสนาพราหมณ์ - ฮินดู','["ความเชื่อในเรื่องอาตมัน และนิพพาน มีความเหมือนกันที่แตกดับและสูญสลายไป", "ความเชื่อในเรื่องโยคะว่าเป็นหลักปฏิบัติที่สามารถนำไปสู่การหลุดพ้นข้ามสังสารวัฏได้", "ความเชื่อในเรื่องอำนาจของกรรม และการกระทำที่จะส่งผลทั้งในชาติปัจจุบันและชาติหน้า", "ความเชื่อในเรื่องคัมภีร์ฤคเวท และพระไตรปิฎก ที่ต่างเป็นต้นกำเนิดของบทสวดมนต์ในศาสนา", "ความเชื่อในเรื่องหลักอาศรม 4 กับดรุณธรรม 6 ที่เป็นคติในการดำเนินชีวิตตามช่วงวัยของศาสนา"]'::jsonb,2,array[2]::smallint[],'["จุดร่วมของพุทธและพราหมณ์–ฮินดู คือความเชื่อเรื่องกรรมและการเวียนว่ายตายเกิด (สังสารวัฏ) ส่วนจุดต่าง: ฮินดูเชื่ออาตมัน (ตัวตนถาวร) พุทธสอนอนัตตา · คัมภีร์ต่างกัน (พระเวท vs พระไตรปิฎก) · อาศรม 4 เป็นคติฮินดู"]'::jsonb,'["ไม่ถูก อาตมันในฮินดูเป็นตัวตนนิรันดร์ไม่แตกดับ ส่วนพุทธสอนอนัตตา และนิพพานไม่ใช่การสูญสลาย แต่เป็นความดับทุกข์", "ไม่ถูก โยคะเป็นมรรควิธีสู่โมกษะของฮินดู พุทธศาสนามีทางพ้นทุกข์คือมรรคมีองค์ 8 / ไตรสิกขา ไม่ได้ถือโยคะเป็นหลักความเชื่อร่วม", "ถูก ทั้งสองศาสนาเชื่อเรื่องกรรม การกระทำส่งผลทั้งในชาตินี้และชาติหน้า", "ไม่ถูก ฤคเวทเป็นคัมภีร์ฮินดู พระไตรปิฎกเป็นคัมภีร์พุทธ ไม่ใช่ความเชื่อร่วมกัน และพระไตรปิฎกไม่ได้กำเนิดจากพระเวท", "ไม่ถูก อาศรม 4 เป็นช่วงชีวิตของฮินดู ส่วนดรุณธรรม 6 เป็นธรรมของพุทธสำหรับคนหนุ่มสาว (ทางแห่งความเจริญ) ไม่ใช่หลักเดียวกัน"]'::jsonb,'{"topic": "1.3", "n": 8}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-8');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-9','M6','M6-SO','M6-SO-S1','A-Level 70',null,2,'ข้อใดกล่าวถูกต้องเกี่ยวกับพิธีรับเข้าศาสนาของศาสนาต่าง ๆ','["ศาสนาสิข ต้องเข้าร่วมพิธีสังคัต เพื่อเข้ารับศาสนา โดยไม่มีการนับถือวรรณะ", "ศาสนาอิสลาม ใช้การเข้าสุนัตของผู้ศรัทธา เพื่อเป็นเครื่องยืนยันการรับเข้าศาสนา", "ศาสนาคริสต์ เข้าร่วมการประกอบพิธีศีลอนุกรมในการประกอบพิธีรับพระจิตเสด็จเข้าสู่จิตใจ", "ศาสนาพุทธ ใช้พิธีการแสดงตนเป็นพุทธมามกะ โดยการศรัทธาต่อพระรัตนตรัยและการถือศีล 5", "ศาสนาพราหมณ์ - ฮินดู ใช้พิธีอุปนยันเป็นการรับเข้าศาสนา โดยการคล้องสายสิญจน์และโกนจุก"]'::jsonb,3,array[3]::smallint[],'["พิธีรับเข้าศาสนา: พุทธ = แสดงตนเป็นพุทธมามกะ (ประกาศถึงพระรัตนตรัยเป็นสรณะ รับศีล) · อิสลาม = กล่าวปฏิญาณตน (ชะฮาดะฮ์) · คริสต์ = ศีลล้างบาป · ซิกข์ = พิธีรับน้ำอมฤต (ปาหุล) · พราหมณ์–ฮินดู = อุปนยัน (พิธีคล้องสายธุรำ เข้าสู่วัยศึกษา) สำหรับวรรณะทวิชาติ"]'::jsonb,'["ไม่ถูก “สังคัต” หมายถึงที่ชุมนุม/การรวมตัวของชาวซิกข์ พิธีรับเข้าศาสนาซิกข์คือพิธีรับน้ำอมฤต (ปาหุล)", "ไม่ถูก การเข้าสุนัต (ขลิบ) เป็นการปฏิบัติตามแบบอย่างศาสดา การรับเข้าอิสลามคือการกล่าวปฏิญาณตน (ชะฮาดะฮ์)", "ไม่ถูก ศีลอนุกรมคือพิธีบวชเป็นบาทหลวง การรับเข้าศาสนาคริสต์คือศีลล้างบาป (ส่วนการรับพระจิตคือศีลกำลัง)", "ถูก ชาวพุทธแสดงตนเป็นพุทธมามกะ โดยประกาศถึงพระรัตนตรัยเป็นที่พึ่งและรับศีล 5", "ไม่ถูก อุปนยันเป็นพิธีเข้าสู่วัยศึกษาโดยคล้อง “สายธุรำ” (ยัชโญปวีต) ไม่ใช่สายสิญจน์ และโกนจุกเป็นอีกพิธีหนึ่ง"]'::jsonb,'{"topic": "1.3", "n": 9}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-9');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-10','M6','M6-SO','M6-SO-S1','A-Level 70',null,2,'บุคคลในข้อใดปฏิบัติตนถูกต้องตามหลักจริยธรรมของความเป็นมุสลิมที่ควรปฏิบัติ','["นายบีกล่าวสรรเสริญองค์อัลลอฮ์ว่าทรงมีความงดงาม", "นายเอฟไม่กราบบุคคลทุกคน ยกเว้นการเคารพต่อองค์อัลลอฮ์", "นางสาวจีปั้นรูปเคารพองค์อัลลอฮ์เพื่อนมัสการทุกครั้งในการละหมาด", "นายดีนินทาต่อเพื่อนมุสลิมที่ประพฤติปฏิบัติตนนอกลู่นอกทางศาสนา", "นางซีแสดงความจงรักภักดีต่อองค์อัลลอฮ์และกล่าวว่าเคยพบกับพระองค์มาก่อน"]'::jsonb,1,array[1]::smallint[],'["จริยธรรมมุสลิม: นอบน้อม (สุญูด/กราบ) ต่ออัลลอฮ์เท่านั้น · ห้ามสร้างรูปเคารพแทนอัลลอฮ์ · ห้ามนินทา (ฆีบะฮ์) · อัลลอฮ์ไม่มีรูปลักษณ์ให้เปรียบ และไม่มีใครเห็นพระองค์ในโลกนี้"]'::jsonb,'["ไม่ถูกตามแนวข้อสอบ การกล่าวถึงพระองค์ในเชิงรูปลักษณ์ภายนอกไม่สอดคล้องกับหลักที่ว่าอัลลอฮ์ไม่มีรูปร่างให้เปรียบเทียบได้", "ถูก มุสลิมจะกราบ (สุญูด) ต่ออัลลอฮ์เท่านั้น ไม่กราบมนุษย์หรือสิ่งอื่น", "ไม่ถูก ห้ามสร้างรูปเคารพเด็ดขาด เพราะเป็นการตั้งภาคี (ชิรก์)", "ไม่ถูก การนินทาเป็นสิ่งต้องห้าม แม้อีกฝ่ายจะประพฤตินอกลู่นอกทาง", "ไม่ถูก ไม่มีมนุษย์คนใดพบเห็นอัลลอฮ์ในโลกนี้ การกล่าวว่าเคยพบพระองค์จึงขัดหลักศรัทธา"]'::jsonb,'{"topic": "1.3", "n": 10}'::jsonb,'imported_m6','imported',true,'expl','ตัวเลือก 1: มีหะดีษกล่าวว่า “อัลลอฮ์ทรงงดงาม (ญะมีล)” ในความหมายด้านคุณลักษณะ ครูควรอธิบายว่าข้อสอบมุ่งประเด็นการไม่เปรียบพระองค์ด้วยรูปลักษณ์',2568,'soc:68-10');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-11','M6','M6-SO','M6-SO-S2','A-Level 70',null,2,'“นายเอกไปร่วมงานมงคลสมรสกับคุณพ่อคุณแม่ เมื่อนายเอกเข้าไปในสถานที่จัดงาน คุณพ่อและคุณแม่ของนายเอกได้แนะนำให้นายเอกรู้จักกับคุณป้าโบว์ซึ่งเป็นแม่ของเจ้าสาว แต่นายเอกนั่งเฉยและไม่ยกมือไหว้คุณป้าโบว์”
จากเหตุการณ์ข้างต้น พฤติกรรมของนายเอกมีลักษณะสอดคล้องกับบรรทัดฐานทางสังคมของบุคคลใดมากที่สุด','["ฟ้าขับรถมอเตอร์ไซค์บนทางเท้าเพราะรีบไปทำงาน", "เจ๋งให้ทิปพนักงานร้านอาหารเนื่องจากได้รับการบริการที่ดี", "ซีนับถือศาสนาคริสต์แต่ไม่ได้ไปโบสถ์ในวันอาทิตย์เพราะติดเรียนภาษาอังกฤษ", "แอมแต่งกายด้วยเสื้อสีชมพูไปร่วมงานศพของเพื่อนสนิท เพราะเป็นสีที่ผู้เสียชีวิตชอบมาก", "แคทจดทะเบียนสมรสกับบาส ซึ่งภายหลังทราบว่าบาสเป็นน้าชายที่สืบสายโลหิตเดียวกัน"]'::jsonb,3,array[3]::smallint[],'["บรรทัดฐานทางสังคม 3 ประเภท: วิถีประชา (มารยาท ธรรมเนียม ฝ่าฝืนแล้วถูกตำหนิ) · จารีต/กฎศีลธรรม (ฝ่าฝืนแล้วถูกต่อต้านรุนแรง) · กฎหมาย (มีบทลงโทษโดยรัฐ) นายเอกไม่ไหว้ผู้ใหญ่ = ฝ่าฝืนวิถีประชา"]'::jsonb,'["ขับมอเตอร์ไซค์บนทางเท้าเป็นการฝ่าฝืนกฎหมาย (มีโทษตามกฎหมายจราจร) ไม่ใช่วิถีประชา", "การให้ทิปเป็นการปฏิบัติตามธรรมเนียม (ทำตามวิถีประชา) ไม่ใช่การฝ่าฝืน ต่างจากนายเอกที่ฝ่าฝืน", "การไม่ไปโบสถ์ตามหลักศาสนาเกี่ยวกับศรัทธาและการปฏิบัติทางศาสนา ไม่ใช่มารยาททางสังคมแบบการไหว้", "ถูก การแต่งชุดสีชมพูไปงานศพเป็นการฝ่าฝืนธรรมเนียมการแต่งกาย (วิถีประชา) ถูกมองว่าไม่เหมาะสม เช่นเดียวกับการไม่ไหว้ผู้ใหญ่", "การสมรสกับน้าชายร่วมสายโลหิตขัดต่อจารีต/ศีลธรรมของสังคมอย่างรุนแรง ไม่ใช่เพียงเรื่องมารยาท (ส่วนกฎหมายห้ามสมรสระหว่างญาติสืบสายโลหิตโดยตรงและพี่น้อง ตาม ป.พ.พ. มาตรา 1450)"]'::jsonb,'{"topic": "2.1", "n": 11}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-11');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-12','M6','M6-SO','M6-SO-S2','A-Level 70',null,2,'“ในยุคโลกาภิวัฒน์ วัฒนธรรมต่างชาติเข้ามามีบทบาทในชีวิตประจำวันของคนไทยมากขึ้น”
จากข้อความดังกล่าว บุคคลใดต่อไปนี้มีการเลือกรับวัฒนธรรมต่างชาติได้เหมาะสมที่สุด','["ไก่ร่วมรณรงค์ให้คนในชุมชนหันมาใช้สินค้าท้องถิ่นแทนสินค้านำเข้า", "กุ้งส่งเสริมให้ชุมชนเปลี่ยนแปลงวัฒนธรรมท้องถิ่นให้สอดคล้องกับกระแสโลก", "ปูจำกัดการเข้าถึงวัฒนธรรมต่างชาติในชุมชน เพื่อป้องกันการสูญเสียเอกลักษณ์ของท้องถิ่น", "ปลาสนับสนุนการใช้เทคโนโลยีจากต่างประเทศโดยลดความสำคัญของประเพณีท้องถิ่นที่ล้าสมัย", "ไข่ส่งเสริมการจัดกิจกรรมแลกเปลี่ยนวัฒนธรรมในชุมชน เพื่อสร้างความเข้าใจและเรียนรู้วัฒนธรรมต่างชาติ"]'::jsonb,4,array[4]::smallint[],'["การเลือกรับวัฒนธรรมต่างชาติอย่างเหมาะสม คือ เปิดรับเรียนรู้และแลกเปลี่ยนด้วยความเข้าใจ โดยยังรักษาเอกลักษณ์ของตน ไม่ปิดกั้น และไม่ละทิ้งวัฒนธรรมเดิม"]'::jsonb,'["เป็นการส่งเสริมสินค้าท้องถิ่น ไม่ได้เป็นการ “เลือกรับ” วัฒนธรรมต่างชาติ", "การเปลี่ยนวัฒนธรรมท้องถิ่นให้ตามกระแสโลก เสี่ยงทำให้สูญเสียเอกลักษณ์ ไม่ใช่การเลือกรับ", "การจำกัดการเข้าถึงเป็นการปิดกั้น ไม่ได้เรียนรู้หรือเลือกรับสิ่งดี", "การลดความสำคัญของประเพณีท้องถิ่นเป็นการละทิ้งวัฒนธรรมของตน", "ถูก การจัดกิจกรรมแลกเปลี่ยนวัฒนธรรมทำให้เข้าใจและเรียนรู้วัฒนธรรมต่างชาติ พร้อมคงวัฒนธรรมของตน"]'::jsonb,'{"topic": "2.1", "n": 12}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-12');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-13','M6','M6-SO','M6-SO-S2','A-Level 70',null,2,'จากกราฟด้านล่าง ข้อใดวิเคราะห์แนวโน้มของการเข้าสู่สังคมผู้สูงอายุในอีก 15 ปีข้างหน้าได้อย่างเหมาะสมที่สุด','["ผู้สูงอายุลดลง เนื่องจากค่านิยมในการแต่งงานของวัยรุ่นลดลง", "ผู้สูงอายุเพิ่มขึ้น เพราะปัจจัยทางด้านการแพทย์และเทคโนโลยีดีขึ้น", "ผู้สูงอายุลดลง เนื่องจากอัตราการเกิดมีจำนวนลดลงอย่างเห็นได้ชัด", "ผู้สูงอายุลดลง เนื่องจากภาวะทางเศรษฐกิจที่เคร่งเครียดมากในปัจจุบัน", "ผู้สูงอายุเพิ่มขึ้น เนื่องจากวัยแรงงานมีค่านิยมในการรักสุขภาพเพิ่มมากขึ้น"]'::jsonb,1,array[1]::smallint[],'["อ่านพีระมิดประชากรไทย 2024: กลุ่มอายุ 40–64 ปี มีสัดส่วนมากที่สุด (ส่วนป่องของกราฟ) อีก 15 ปีคนกลุ่มนี้จะเข้าสู่วัยสูงอายุ ขณะที่ฐาน (เด็ก 0–14 ปี) แคบลง แสดงว่าเด็กเกิดน้อย และคนอายุยืนขึ้นจากการแพทย์ที่ดีขึ้น → ผู้สูงอายุเพิ่มขึ้น"]'::jsonb,'["ไม่ถูก กราฟแสดงว่าผู้สูงอายุจะเพิ่มขึ้น ไม่ใช่ลดลง เพราะกลุ่มวัยกลางคนจำนวนมากกำลังจะเข้าสู่วัยสูงอายุ", "ถูก ผู้สูงอายุเพิ่มขึ้น และการแพทย์/เทคโนโลยีที่ดีขึ้นทำให้คนอายุยืนขึ้น เป็นเหตุผลทางประชากรที่สำคัญ", "ไม่ถูก การเกิดลดลงทำให้ “สัดส่วน” ผู้สูงอายุสูงขึ้น ไม่ใช่ทำให้ผู้สูงอายุลดลง", "ไม่ถูก ทิศทางผิด (ผู้สูงอายุเพิ่มขึ้น) และเศรษฐกิจตึงเครียดไม่ได้ทำให้จำนวนผู้สูงอายุลดลง", "ทิศทาง “เพิ่มขึ้น” ถูก แต่เหตุผลอ่อน การรักสุขภาพของวัยแรงงานไม่ใช่ปัจจัยหลักที่กราฟแสดง ปัจจัยหลักคือคนกลุ่มใหญ่กำลังแก่ตัวและอายุยืนขึ้นจากการแพทย์"]'::jsonb,'{"img": "a68-13-pyramid.png", "topic": "2.1", "n": 13, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/a68-13-pyramid.png"}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-13');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-14','M6','M6-SO','M6-SO-S2','A-Level 70',null,2,'ชุมชนหนึ่งมีการจัดเวทีประชาคมเพื่อหารือเกี่ยวกับปัญหาการจัดการขยะในพื้นที่ ซึ่งมีตัวแทนจากทุกกลุ่มในชุมชนเข้าร่วมแสดงความคิดเห็น หากนักเรียนได้รับเชิญให้เข้าร่วมการแสดงความคิดเห็นในเวทีนี้ด้วย ท่านจะปฏิบัติตนตามข้อใดในฐานะของพลเมืองดีที่เหมาะสมที่สุด','["รอให้ผู้ใหญ่แสดงความคิดเห็นก่อน แล้วจึงแสดงความคิดเห็นในตอนท้ายโดยไม่โต้แย้ง", "ฟังความคิดเห็นของผู้อื่นแต่ไม่แสดงความคิดเห็น เพราะเชื่อว่าปัญหานี้เป็นหน้าที่ของผู้ใหญ่", "สนับสนุนแนวทางของคนส่วนใหญ่โดยไม่คำนึงถึงความเหมาะสม หรือผลกระทบของแนวทางนั้น", "ตั้งคำถามและแสดงความคิดเห็นในเชิงสร้างสรรค์ โดยเสนอแนวทางที่นักเรียนสามารถช่วยแก้ไขปัญหาได้", "แสดงความไม่เห็นด้วยกับความคิดเห็นที่ไม่ตรงกับตนเองให้ชัดเจน แต่ไม่จำเป็นต้องอธิบายเหตุผลเพื่อกระชับเวลาให้ผู้อื่น"]'::jsonb,3,array[3]::smallint[],'["พลเมืองดีในระบอบประชาธิปไตย: มีส่วนร่วม แสดงความคิดเห็นอย่างมีเหตุผลและสร้างสรรค์ รับฟังผู้อื่น และเสนอทางแก้ที่ตนช่วยได้"]'::jsonb,'["การรอให้ผู้ใหญ่พูดก่อนและไม่โต้แย้งเลย ทำให้ไม่ได้มีส่วนร่วมเต็มที่", "การไม่แสดงความคิดเห็นเพราะคิดว่าเป็นหน้าที่ผู้ใหญ่ ขัดกับการมีส่วนร่วมของพลเมือง", "การตามเสียงส่วนใหญ่โดยไม่คิดถึงความเหมาะสมหรือผลกระทบ ไม่ใช่การใช้วิจารณญาณ", "ถูก ตั้งคำถามและเสนอความคิดเห็นเชิงสร้างสรรค์ พร้อมแนวทางที่ตนช่วยแก้ไขได้ คือพลเมืองที่มีส่วนร่วมอย่างแท้จริง", "การคัดค้านโดยไม่ให้เหตุผล ขัดกับหลักการใช้เหตุผลและเคารพความคิดเห็นผู้อื่น"]'::jsonb,'{"topic": "2.1", "n": 14}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-14');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-15','M6','M6-SO','M6-SO-S2','A-Level 70',null,2,'สถานการณ์ใดต่อไปนี้กล่าวถูกต้อง เกี่ยวกับสภาพการเป็นบุคคลตามกฎหมายแพ่งและพาณิชย์','["เด็กชายบอลอายุ 14 ปี ได้รับมรดกจากคุณปู่จำนวนหนึ่ง จึงทำพินัยกรรมไว้เป็นผลทำให้พินัยกรรมที่ทำตกเป็นโมฆียะ", "นายคิวเป็นผู้ป่วยจิตเวชที่ศาลมีคำสั่งให้เป็นคนไร้ความสามารถ ซึ่งเขายังคงสามารถเซ็นสัญญาซื้อขายทรัพย์สินได้หากผู้ขายยอมรับ", "นางสาวเจี๊ยบอายุ 18 ปี สมรสโดยชอบด้วยกฎหมาย จึงสามารถทำนิติกรรมและสัญญาได้เอง โดยไม่ต้องได้รับความยินยอมจากผู้ปกครอง", "นายเก่งอายุ 20 ปี บรรลุนิติภาวะแล้ว แต่ศาลมีคำสั่งให้เป็นคนเสมือนไร้ความสามารถจึงจำเป็นต้องมีผู้อนุบาลในการทำนิติกรรมและสัญญาแทน", "นางสาวนกอายุ 16 ปี ได้รับเงินเดือนจากการทำงาน และเก็บสะสมเงินเพื่อไปซื้อรถมอเตอร์ไซค์ โดยไม่ต้องได้รับความยินยอมจากบิดามารดา เพราะถือว่าใช้เงินจากการทำงานของตนเอง"]'::jsonb,2,array[2]::smallint[],'["ความสามารถของบุคคลตาม ป.พ.พ.: บรรลุนิติภาวะเมื่ออายุ 20 ปีบริบูรณ์ หรือโดยการสมรสที่ชอบด้วยกฎหมาย (ม.19–20) · ผู้เยาว์ทำพินัยกรรมได้เมื่ออายุ 15 ปีบริบูรณ์ ถ้าอายุไม่ถึงพินัยกรรมเป็นโมฆะ · คนไร้ความสามารถมี “ผู้อนุบาล” ทำนิติกรรมเองเป็นโมฆียะ · คนเสมือนไร้ความสามารถมี “ผู้พิทักษ์”"]'::jsonb,'["ไม่ถูก ผู้เยาว์อายุต่ำกว่า 15 ปีบริบูรณ์ทำพินัยกรรม พินัยกรรมนั้นตกเป็น “โมฆะ” (ไม่ใช่โมฆียะ)", "ไม่ถูก คนไร้ความสามารถทำนิติกรรมเองเป็นโมฆียะ ต้องให้ผู้อนุบาลทำแทน แม้คู่สัญญาจะยอมรับก็ไม่ทำให้สมบูรณ์", "ถูก การสมรสที่ชอบด้วยกฎหมายทำให้บรรลุนิติภาวะ จึงทำนิติกรรมและสัญญาได้เองโดยไม่ต้องขอความยินยอม", "ไม่ถูก คนเสมือนไร้ความสามารถมี “ผู้พิทักษ์” (ไม่ใช่ผู้อนุบาล) และทำนิติกรรมได้เอง เว้นแต่บางประเภทที่ต้องได้รับความยินยอมจากผู้พิทักษ์", "ไม่ถูก ผู้เยาว์ทำนิติกรรมที่ไม่จำเป็นต่อการดำรงชีพ เช่น ซื้อรถจักรยานยนต์ ต้องได้รับความยินยอมจากผู้แทนโดยชอบธรรม แม้ใช้เงินที่หามาเอง"]'::jsonb,'{"topic": "2.2", "n": 15}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-15');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-16','M6','M6-SO','M6-SO-S2','A-Level 70',null,2,'ปฏิญญาสากลว่าด้วยเรื่องสิทธิมนุษยชน มีผลต่อการกำหนดกฎหมายในประเทศต่าง ๆ อย่างไร','["เป็นกฎหมายที่บังคับใช้กับทุกประเทศโดยตรง", "ใช้เป็นพันธะผูกพันในแง่ของกฎหมายระหว่างประเทศ", "สามารถทำให้ประเทศที่ไม่ปฏิบัติตามหลักปฏิญญาสากลถูกลงโทษทางทหาร", "สามารถทำให้ประเทศต่าง ๆ ต้องยกเลิกกฎหมายทั้งหมดที่ขัดกับสิทธิมนุษยชน", "เป็นแนวทางพื้นฐานให้ประเทศต่าง ๆ รับรองสิทธิมนุษยชนในกฎหมายภายในประเทศ"]'::jsonb,4,array[4]::smallint[],'["ปฏิญญาสากลว่าด้วยสิทธิมนุษยชน (UDHR, ค.ศ. 1948) เป็น “ปฏิญญา” ไม่ใช่สนธิสัญญา จึงไม่มีผลผูกพันทางกฎหมายโดยตรง แต่เป็นมาตรฐานและแนวทางให้ประเทศต่าง ๆ นำไปรับรองสิทธิในกฎหมายภายใน"]'::jsonb,'["ไม่ถูก ปฏิญญาไม่ใช่กฎหมายที่บังคับใช้กับทุกประเทศโดยตรง", "ไม่ถูก ปฏิญญาไม่มีพันธะผูกพันทางกฎหมายระหว่างประเทศแบบสนธิสัญญา (กติการะหว่างประเทศที่ทำตามมาภายหลังจึงมีผลผูกพันเฉพาะรัฐภาคี)", "ไม่ถูก ไม่มีบทลงโทษทางทหารต่อประเทศที่ไม่ปฏิบัติตามปฏิญญา", "ไม่ถูก ไม่สามารถบังคับให้ประเทศยกเลิกกฎหมายทั้งหมดที่ขัดได้", "ถูก ปฏิญญาเป็นแนวทางพื้นฐานที่ประเทศต่าง ๆ ใช้รับรองสิทธิมนุษยชนในรัฐธรรมนูญและกฎหมายภายใน"]'::jsonb,'{"topic": "2.3", "n": 16}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-16');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-17','M6','M6-SO','M6-SO-S2','A-Level 70',null,2,'“บุคคล 5 คน รวมตัวกันในสวนสาธารณะแห่งหนึ่ง เพื่อประท้วงเกี่ยวกับนโยบายของรัฐ ซึ่งเป็นการประท้วงโดยปราศจากอาวุธ แต่ถูกเจ้าหน้าที่รัฐห้ามปราม โดยให้เหตุผลว่าต้องทำเอกสารขออนุญาตจากหน่วยงานของรัฐก่อน หากไม่ขออนุญาตจะเป็นการกระทำที่ผิดกฎหมาย ทั้งนี้เหตุการณ์ดังกล่าวเกิดขึ้นในสภาวการณ์ปกติ”
จากสถานการณ์ข้างต้นข้อใดวิเคราะห์ได้ถูกต้อง','["การห้ามการชุมนุมเป็นสิ่งที่รัฐสามารถทำได้หากพบว่าเป็นการละเมิดสิทธิของคนอื่น", "การห้ามชุมนุมที่ไม่ได้รับอนุญาตเป็นการใช้อำนาจรัฐในการรักษาความสงบเรียบร้อย", "การกระทำของเจ้าหน้าที่รัฐดังกล่าวเป็นการละเมิดสิทธิในการชุมนุมที่รัฐธรรมนูญคุ้มครอง", "การจำกัดสิทธิในการชุมนุมถือเป็นการบังคับใช้กฎหมายที่เหมาะสมในสถานการณ์ที่เกิดความวุ่นวาย", "การจำกัดสิทธิในการชุมนุมไม่ได้ละเมิดรัฐธรรมนูญหากเป็นไปเพื่อการป้องกันความปลอดภัยของประชาชน"]'::jsonb,2,array[2]::smallint[],'["รัฐธรรมนูญ พ.ศ. 2560 มาตรา 44 รับรองเสรีภาพในการชุมนุมโดยสงบและปราศจากอาวุธ จำกัดได้เฉพาะโดยกฎหมาย · พ.ร.บ.การชุมนุมสาธารณะ พ.ศ. 2558 ใช้ระบบ “แจ้ง” การชุมนุมล่วงหน้า ไม่ใช่ระบบขออนุญาต และสถานการณ์เป็นภาวะปกติ"]'::jsonb,'["ไม่ถูกกับกรณีนี้ โจทย์ไม่ได้ระบุว่าการชุมนุมละเมิดสิทธิผู้อื่น เจ้าหน้าที่อ้างเพียงว่าไม่ได้ขออนุญาต", "ไม่ถูก กฎหมายไม่ได้กำหนดให้ต้อง “ขออนุญาต” การห้ามด้วยเหตุนี้จึงไม่ใช่การใช้อำนาจที่ชอบ", "ถูก การชุมนุมโดยสงบปราศจากอาวุธในภาวะปกติได้รับความคุ้มครองตามรัฐธรรมนูญ การบังคับให้ขออนุญาตก่อนจึงเป็นการละเมิดสิทธิ", "ไม่ถูก โจทย์ระบุว่าเป็นสภาวการณ์ปกติ ไม่มีความวุ่นวาย", "ไม่ถูก โจทย์ไม่มีเหตุด้านความปลอดภัย การห้ามโดยอ้างแค่การไม่ขออนุญาตจึงขัดรัฐธรรมนูญ"]'::jsonb,'{"topic": "2.3", "n": 17}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-17');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-18','M6','M6-SO','M6-SO-S2','A-Level 70',null,2,'ข้อใดกล่าวถูกต้องที่สุด เกี่ยวกับลักษณะของรัฐเดี่ยว','["รัฐที่มีการกระจายอำนาจในการปกครองไปยังท้องถิ่น แต่ยังคงมีอำนาจในการตัดสินใจจากศูนย์กลางในการกำหนดนโยบายที่สำคัญ", "รัฐที่มีรัฐบาลกลางที่มอบอำนาจให้แก่รัฐบาลท้องถิ่นในเรื่องการศึกษา การสาธารณสุขและบริการพื้นฐานอื่น ๆ", "รัฐที่มีการปกครองจากรัฐบาลกลางและรัฐบาลท้องถิ่นที่มีอำนาจการปกครองแยกกันอย่างชัดเจนในหลาย ๆ ด้าน", "รัฐที่ประกอบด้วยรัฐสมาชิกหลาย ๆ รัฐ โดยมีรัฐบาลกลางที่มีอำนาจในการตัดสินใจในเรื่องของนโยบายต่างประเทศและความมั่นคง", "รัฐที่มีการรวมตัวของประเทศหลายประเทศ โดยมีองค์กรกลางที่มีอำนาจในการตัดสินใจในด้านเศรษฐกิจ การทหาร และการต่างประเทศ"]'::jsonb,0,array[0]::smallint[],'["รัฐเดี่ยว (เช่น ไทย) มีรัฐบาลกลางเป็นศูนย์อำนาจสูงสุด อาจกระจายอำนาจให้ท้องถิ่น แต่ศูนย์กลางยังกำหนดนโยบายสำคัญ · รัฐรวม/สหพันธรัฐ (เช่น สหรัฐฯ มาเลเซีย) แบ่งอำนาจระหว่างรัฐบาลกลางกับรัฐบาลมลรัฐชัดเจนตามรัฐธรรมนูญ"]'::jsonb,'["ถูก รัฐเดี่ยวกระจายอำนาจให้ท้องถิ่นได้ แต่อำนาจตัดสินใจนโยบายสำคัญยังอยู่ที่ส่วนกลาง", "ไม่ถูก การมี “รัฐบาลกลางกับรัฐบาลท้องถิ่น” ที่ได้รับมอบอำนาจด้านต่าง ๆ เป็นลักษณะใกล้เคียงสหพันธรัฐ", "ไม่ถูก รัฐบาลกลางกับรัฐบาลท้องถิ่นที่มีอำนาจแยกกันชัดเจนหลายด้านคือสหพันธรัฐ", "ไม่ถูก รัฐที่ประกอบด้วยรัฐสมาชิกหลายรัฐคือรัฐรวม (สหพันธรัฐ)", "ไม่ถูก การรวมตัวของหลายประเทศภายใต้องค์กรกลางคือสมาพันธรัฐ/การรวมกลุ่มระหว่างประเทศ"]'::jsonb,'{"topic": "2.3", "n": 18}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-18');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-19','M6','M6-SO','M6-SO-S2','A-Level 70',null,2,'“ในปี พ.ศ. 2564 ประเทศไทยเผชิญกับสถานการณ์การแพร่ระบาดของโรคติดต่อร้ายแรงรัฐบาลได้ออกพระราชกำหนดฉุกเฉินเพื่อควบคุมสถานการณ์ โดยมีการกำหนดข้อจำกัดเกี่ยวกับการเดินทางและการชุมนุมสาธารณะ พร้อมทั้งเพิ่มอำนาจให้เจ้าหน้าที่รัฐดำเนินมาตรการพิเศษ เช่น การควบคุมพื้นที่”
จากสถานการณ์ข้างต้น ข้อใดต่อไปนี้กล่าวถูกต้องที่สุดเกี่ยวกับการออกกฎหมายฉบับดังกล่าว','["ออกโดยรัฐสภา เพราะเป็นการตรากฎหมายโดยรัฐสภา", "ออกโดยคณะรัฐมนตรี เพราะเป็นหน้าที่ของคณะรัฐมนตรีในการบริหารกำกับจัดการสถานการณ์ฉุกเฉิน", "ออกโดยศาล เพราะเป็นการตีความกฎหมายของศาลเพื่อควบคุมสถานการณ์", "ออกโดยองค์กรอิสระ เพราะเป็นอำนาจพิเศษที่องค์กรอิสระได้รับในสถานการณ์วิกฤต", "ออกโดยศาลรัฐธรรมนูญ เพราะเป็นอำนาจที่สามารถดำเนินการโดยตรงเพื่อความมั่นคงและสงบเรียบร้อย"]'::jsonb,1,array[1]::smallint[],'["พระราชกำหนด (พ.ร.ก.) ตราขึ้นโดยพระมหากษัตริย์ตามคำแนะนำของคณะรัฐมนตรี ในกรณีฉุกเฉินจำเป็นรีบด่วนเพื่อความปลอดภัยสาธารณะ ความมั่นคง หรือป้องปัดภัยพิบัติ แล้วต้องเสนอรัฐสภาพิจารณาอนุมัติภายหลัง"]'::jsonb,'["ไม่ถูก กฎหมายที่รัฐสภาตราคือพระราชบัญญัติ พระราชกำหนดออกโดยฝ่ายบริหาร", "ถูก คณะรัฐมนตรีเป็นผู้เสนอให้ตราพระราชกำหนดในสถานการณ์ฉุกเฉิน เพราะต้องดำเนินการอย่างรวดเร็ว", "ไม่ถูก ศาลมีหน้าที่ตีความและพิจารณาคดี ไม่ได้ออกกฎหมาย", "ไม่ถูก องค์กรอิสระไม่มีอำนาจตรากฎหมาย", "ไม่ถูก ศาลรัฐธรรมนูญวินิจฉัยความชอบด้วยรัฐธรรมนูญ ไม่ได้ออกกฎหมาย"]'::jsonb,'{"topic": "2.3", "n": 19}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-19');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-20','M6','M6-SO','M6-SO-S2','A-Level 70',null,2,'“เด็กหญิงดวงดาวเป็นนักเรียนที่มีความสามารถในการเรียนรู้ มีความต้องการศึกษาต่อในระดับชั้นมัธยมศึกษาตอนต้น และยังมีน้องอีก 2 คนที่กำลังจะขึ้นชั้นประถมศึกษา เธอจึงกังวลว่าค่าใช้จ่ายในการเรียนจะสูงเกินกว่าที่ครอบครัวของเธอจะสามารถจ่ายได้”
จากสถานการณ์ข้างต้น ข้อใดกล่าวถึงสิทธิและเสรีภาพในการศึกษาตามรัฐธรรมนูญที่มีความสอดคล้องกับหน้าที่ของรัฐได้เหมาะสมที่สุด','["รัฐมีหน้าที่จัดการศึกษาฟรีให้กับทุกคนไม่น้อยกว่า 12 ปี โดยไม่คำนึงถึงฐานะทางเศรษฐกิจ", "รัฐมีหน้าที่ต้องจัดสิทธิในการศึกษาในทุกระดับสำหรับประชาชนที่ขาดแคลนทุนทรัพย์", "รัฐมีหน้าที่จัดสรรการศึกษาให้แก่ผู้ที่มีความสามารถในด้านต่าง ๆ และมีทรัพยากรเพียงพอ", "รัฐมีหน้าที่ส่งเสริมการศึกษาระดับสูง ให้กับผู้ที่สามารถจ่ายค่าเล่าเรียนได้อย่างมีประสิทธิภาพ", "รัฐมีหน้าที่กำหนดสิทธิในการศึกษาโดยจำกัดเฉพาะคนที่สามารถแสดงศักยภาพในการเรียนได้"]'::jsonb,0,array[0]::smallint[],'["รัฐธรรมนูญ พ.ศ. 2560 มาตรา 54: รัฐต้องดำเนินการให้เด็กทุกคนได้รับการศึกษาเป็นเวลา 12 ปี ตั้งแต่ก่อนวัยเรียนจนจบการศึกษาภาคบังคับอย่างมีคุณภาพโดยไม่เก็บค่าใช้จ่าย ดวงดาวจะเรียน ม.ต้น และน้องเรียนประถม ซึ่งอยู่ในช่วงนี้"]'::jsonb,'["ถูก ตรงกับหน้าที่ของรัฐตามมาตรา 54 ที่ต้องจัดการศึกษาโดยไม่เก็บค่าใช้จ่ายเป็นเวลา 12 ปี โดยไม่คำนึงถึงฐานะ", "ไม่ถูก รัฐธรรมนูญไม่ได้กำหนดให้รัฐต้องจัดการศึกษาฟรี “ทุกระดับ” (มีกองทุนช่วยผู้ขาดแคลนทุนทรัพย์ แต่ไม่ใช่สิทธิทุกระดับ)", "ไม่ถูก การศึกษาเป็นสิทธิของทุกคน ไม่ได้จำกัดเฉพาะผู้มีความสามารถหรือมีทรัพยากร", "ไม่ถูก การให้เฉพาะผู้จ่ายค่าเล่าเรียนได้ขัดกับหลักความเสมอภาค", "ไม่ถูก การจำกัดเฉพาะคนแสดงศักยภาพได้ขัดกับสิทธิในการศึกษาของทุกคน"]'::jsonb,'{"topic": "2.3", "n": 20}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-20');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-21','M6','M6-SO','M6-SO-S3','A-Level 70',null,2,'“เมื่อเริ่มเข้าสู่ช่วงฤดูหนาว ลมทะเลสงบ ชาวประมงในหลาย ๆ จังหวัดตามแนวชายฝั่งจะสามารถวางอวนจับสัตว์น้ำได้มากขึ้น โดยเฉพาะปูม้าซึ่งเป็นอาหารทะเลยอดนิยม และมีราคาสูง แต่เนื่องจากเศรษฐกิจไม่ค่อยดี จึงทำให้อาหารทะเลขายไม่ค่อยดี ต่อให้ชาวประมงสามารถจับปูม้าได้มากขึ้นแต่ก็ยังคงขายปูม้าไม่หมด ทำให้เกิดการเน่าเสียและเกิดภาวะขาดทุน”
จากสถานการณ์ดังกล่าว ภาครัฐควรใช้มาตรการจัดการในข้อใดเพื่อลดผลกระทบให้กับทั้งชาวประมงและผู้บริโภค','["จัดจำหน่ายน้ำมันราคาถูกให้กับเรือประมง", "ประกันราคาด้วยการรับซื้อปูม้าจากชาวประมง", "ใช้มาตรการพยุงราคาขายปูม้าให้สูงกว่าราคาดุลยภาพ", "ควบคุมราคาขายปูม้าในตลาดให้มีราคาต่ำกว่าราคาดุลยภาพ", "ปล่อยสินเชื่อเพื่อเสริมสภาพคล่องสำหรับผู้ประกอบการธุรกิจประมง"]'::jsonb,0,array[0]::smallint[],'["เลือกมาตรการที่ช่วย “ทั้งสองฝ่าย” : ลดต้นทุนการผลิตของชาวประมง (เช่น น้ำมันราคาถูก) ทำให้ชาวประมงขาดทุนน้อยลงและขายในราคาที่ผู้บริโภคซื้อได้ ส่วนการพยุง/ประกันราคาช่วยผู้ผลิตแต่ผู้บริโภคจ่ายแพง และการกดราคาช่วยผู้บริโภคแต่ทำร้ายผู้ผลิต"]'::jsonb,'["ถูก น้ำมันเป็นต้นทุนหลักของเรือประมง การลดต้นทุนช่วยชาวประมงขาดทุนน้อยลง และไม่ทำให้ราคาที่ผู้บริโภคจ่ายสูงขึ้น", "ช่วยชาวประมงฝ่ายเดียว รัฐต้องใช้งบซื้อสินค้าที่ตลาดไม่ต้องการ และไม่ช่วยผู้บริโภค", "การพยุงราคาสูงกว่าดุลยภาพทำให้ผู้บริโภคจ่ายแพงขึ้นและสินค้าล้นตลาดยิ่งขึ้น", "การกดราคาต่ำกว่าดุลยภาพช่วยผู้บริโภค แต่ชาวประมงยิ่งขาดทุน", "สินเชื่อช่วยสภาพคล่องผู้ประกอบการ แต่ไม่แก้ปัญหาขายไม่ออกและไม่ช่วยผู้บริโภค"]'::jsonb,'{"topic": "3.1", "n": 21}'::jsonb,'imported_m6','imported',true,'expl','เฉลยตาม ทปอ. คือข้อ 1 ครูควรเน้นเหตุผล “ช่วยทั้งสองฝ่าย” เพราะนักเรียนมักเลือกข้อ 2',2568,'soc:68-21');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-22','M6','M6-SO','M6-SO-S3','A-Level 70',null,2,'“ถ้าราคาสินค้า A ในตลาดมีราคา 250 บาทซึ่งมีปริมาณความต้องการซื้อสินค้า A ของผู้บริโภคเท่ากับ 80 หน่วย แต่กลับมีปริมาณความต้องการขายสินค้า A ของผู้ผลิตเท่ากับ 60 หน่วย”
จากสถานการณ์ดังกล่าว ตลาดสินค้า A จะเกิดการปรับตัวอย่างไรในอนาคต','["ราคาสินค้า A ลดลง ปริมาณเสนอซื้อจะลดลง แต่ปริมาณเสนอขายจะเพิ่มสูงขึ้น", "ราคาสินค้า A ลดลง ปริมาณเสนอซื้อจะเพิ่มสูงขึ้น แต่ปริมาณเสนอขายจะลดลง", "ราคาสินค้า A จะคงที่ ทั้งปริมาณเสนอซื้อและปริมาณเสนอขายจะเท่ากันพอดี", "ราคาสินค้า A เพิ่มสูงขึ้น ปริมาณเสนอซื้อจะลดลง แต่ปริมาณเสนอขายจะเพิ่มสูงขึ้น", "ราคาสินค้า A เพิ่มสูงขึ้น ปริมาณเสนอซื้อจะเพิ่มสูงขึ้น แต่ปริมาณเสนอขายจะลดลง"]'::jsonb,3,array[3]::smallint[],'["ที่ราคา 250 บาท ปริมาณเสนอซื้อ 80 > ปริมาณเสนอขาย 60 = อุปสงค์ส่วนเกิน (สินค้าขาดตลาด) ราคาจะสูงขึ้น เมื่อราคาสูงขึ้น ปริมาณเสนอซื้อลดลง ปริมาณเสนอขายเพิ่มขึ้น จนเข้าสู่ดุลยภาพ"]'::jsonb,'["ไม่ถูก สินค้าขาดตลาดทำให้ราคาสูงขึ้น ไม่ใช่ลดลง", "ไม่ถูก ราคาไม่ลดลง และทิศทางการปรับของปริมาณไม่สอดคล้องกับกฎอุปสงค์–อุปทาน", "ไม่ถูก ตลาดยังไม่อยู่ในดุลยภาพ (80 ≠ 60) ราคาจึงไม่คงที่", "ถูก อุปสงค์ส่วนเกินดันราคาขึ้น ราคาสูงขึ้นทำให้ผู้ซื้อซื้อน้อยลง (กฎอุปสงค์) และผู้ขายขายมากขึ้น (กฎอุปทาน)", "ไม่ถูก ราคาสูงขึ้นปริมาณเสนอซื้อต้องลดลง และปริมาณเสนอขายต้องเพิ่มขึ้น"]'::jsonb,'{"topic": "3.1", "n": 22}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-22');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-23','M6','M6-SO','M6-SO-S3','A-Level 70',null,2,'การที่รัฐบาลยังคงยืนยันในการปรับขึ้นค่าจ้างแรงงานขั้นต่ำเป็น 400 บาทในทุกพื้นที่ทั่วประเทศนั้น อาจส่งผลกระทบต่อตลาดแรงงานของแต่ละพื้นที่ในอนาคตอย่างไร','["อัตราค่าจ้างแรงงานดุลยภาพจะปรับตัวลดลง", "สถานการณ์การว่างงานในแต่ละพื้นที่จะเพิ่มสูงขึ้น", "ปัญหาการขาดแคลนแรงงานในแต่ละพื้นที่จะลดลง", "การลงทุนพัฒนาบุคลากรในองค์กรของภาคธุรกิจจะลดลง", "ปริมาณการจ้างแรงงานจะมากกว่าปริมาณเสนอขายแรงงาน"]'::jsonb,1,array[1]::smallint[],'["ค่าจ้างขั้นต่ำเป็น “ราคาขั้นต่ำ” ของตลาดแรงงาน ถ้ากำหนดสูงกว่าค่าจ้างดุลยภาพของพื้นที่ จะเกิดอุปทานแรงงานส่วนเกิน (คนอยากทำงานมากกว่าที่นายจ้างจ้าง) = การว่างงานเพิ่มขึ้น"]'::jsonb,'["ไม่ถูก การกำหนดค่าจ้างขั้นต่ำไม่ได้ทำให้ค่าจ้างดุลยภาพลดลง ค่าจ้างดุลยภาพขึ้นกับอุปสงค์และอุปทานแรงงาน", "ถูก ค่าจ้างสูงกว่าดุลยภาพ นายจ้างลดการจ้าง แต่คนอยากทำงานมากขึ้น จึงเกิดการว่างงาน โดยเฉพาะพื้นที่ที่ค่าจ้างดุลยภาพต่ำ", "ไม่ถูก ค่าจ้างสูงกว่าดุลยภาพทำให้เกิดแรงงานส่วนเกิน ไม่ใช่แก้ปัญหาขาดแคลนแรงงาน", "อาจเกิดได้บ้าง แต่ไม่ใช่ผลโดยตรงของตลาดแรงงานตามหลักราคาขั้นต่ำ", "ไม่ถูก กลับกัน ปริมาณการจ้าง (อุปสงค์แรงงาน) จะ “น้อยกว่า” ปริมาณเสนอขายแรงงาน"]'::jsonb,'{"topic": "3.2", "n": 23}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-23');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-24','M6','M6-SO','M6-SO-S3','A-Level 70',null,2,'ประเทศ A ต้องเผชิญกับวิกฤตการณ์การแพร่ระบาดของโควิด-19 ซึ่งส่งผลกระทบอย่างรุนแรงต่อเศรษฐกิจทั้งด้านการท่องเที่ยว การส่งออก และการบริโภคภายในประเทศ รัฐบาลจึงต้องช่วยเหลือประชาชนและกระตุ้นเศรษฐกิจผ่านมาตรการต่าง ๆ ที่เป็นนโยบายการคลัง ยกเว้น ข้อใด','["การสนับสนุนธุรกิจ SMEs ผ่านกองทุนฟื้นฟู", "การลดงบประมาณรายจ่ายและการเพิ่มภาษี", "การลงทุนเพิ่มในโครงสร้างพื้นฐานขนาดใหญ่", "การกู้เงินเพื่อใช้จ่ายเยียวยาให้กับผู้ได้รับผลกระทบ", "การจัดทำงบประมาณแบบขาดดุลเพื่อเพิ่มการใช้จ่ายของรัฐ"]'::jsonb,1,array[1]::smallint[],'["นโยบายการคลังแบบขยายตัว (ใช้กระตุ้นเศรษฐกิจช่วงวิกฤต): เพิ่มรายจ่ายรัฐ ลดภาษี กู้เงินมาใช้จ่าย งบประมาณขาดดุล · นโยบายการคลังแบบหดตัว (ลดรายจ่าย เพิ่มภาษี) ใช้ชะลอเศรษฐกิจที่ร้อนแรง จึงไม่ใช่มาตรการช่วยเหลือ/กระตุ้น"]'::jsonb,'["เป็นการใช้เงินรัฐช่วยเหลือธุรกิจ จัดเป็นมาตรการกระตุ้นได้", "ถูก (คำตอบ) การลดรายจ่ายและเพิ่มภาษีเป็นนโยบายการคลังแบบหดตัว ทำให้เศรษฐกิจชะลอลง ขัดกับเป้าหมายช่วยเหลือและกระตุ้นเศรษฐกิจ", "การลงทุนในโครงสร้างพื้นฐานเป็นการเพิ่มรายจ่ายรัฐ = การคลังแบบขยายตัว", "การกู้เงินมาเยียวยาเป็นการเพิ่มรายจ่ายรัฐ = การคลังแบบขยายตัว", "งบประมาณขาดดุล (รายจ่าย > รายได้) คือหัวใจของการคลังแบบขยายตัว"]'::jsonb,'{"topic": "3.2", "n": 24}'::jsonb,'imported_m6','imported',true,'expl','ข้อ 2 เป็นนโยบายการคลังจริง แต่เป็นแบบหดตัว คำถามจึงหมายถึง “มาตรการการคลังเพื่อช่วยเหลือ/กระตุ้น”',2568,'soc:68-24');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-25','M6','M6-SO','M6-SO-S3','A-Level 70',null,2,'จากสถานการณ์ที่กำหนดให้ในตารางด้านล่าง ตลาด A และตลาด B จัดเป็นตลาดประเภทใด เพราะเหตุใดจึงเป็นเช่นนั้น','["ตลาด A และตลาด B เป็นตลาดกึ่งแข่งขันกึ่งผูกขาด เพราะมีการสร้างเอกลักษณ์เฉพาะของสินค้าในแต่ละตลาด", "ตลาด A และตลาด B ต่างก็เป็นตลาดผู้ขายน้อยราย เพราะมีการแข่งขันในด้านการตลาดและความแตกต่างของสินค้า", "ตลาด A คือ ตลาดกึ่งแข่งขันกึ่งผูกขาด เพราะมีผู้ขายหลายรายที่แข่งขันกันอย่างเสรี ส่วนตลาด B คือ ตลาดผู้ขายน้อยราย เพราะสินค้าที่ขายของแต่ละร้านต่างก็มีเอกลักษณ์เฉพาะ", "ตลาด A คือ ตลาดผู้ขายน้อยราย เพราะตลาด A มีผู้ขายอยู่เป็นจำนวนน้อย ส่วนตลาด B คือ ตลาดแข่งขันสมบูรณ์ เพราะตลาด B มีผู้ขายอยู่เป็นจำนวนมาก", "ตลาด A คือ ตลาดผู้ขายน้อยราย เพราะมีผู้ขายไม่กี่รายและมีการแข่งขันกันในด้านกลยุทธ์การตลาด ส่วนตลาด B คือ ตลาดกึ่งแข่งขันกึ่งผูกขาด เพราะมีผู้ขายจำนวนมากและเน้นความแตกต่างกันของสินค้า"]'::jsonb,4,array[4]::smallint[],'["ตลาดผู้ขายน้อยราย (oligopoly): ผู้ขายไม่กี่ราย แข่งขันด้วยโปรโมชั่น/กลยุทธ์การตลาด สินค้าคล้ายกัน · ตลาดกึ่งแข่งขันกึ่งผูกขาด (monopolistic competition): ผู้ขายจำนวนมาก สินค้าประเภทเดียวกันแต่แตกต่างกันด้วยเอกลักษณ์ ดีไซน์"]'::jsonb,'["ไม่ถูก ตลาด A มีผู้ขายเพียงไม่กี่รายจึงเป็นผู้ขายน้อยราย ไม่ใช่กึ่งแข่งขันกึ่งผูกขาด", "ไม่ถูก ตลาด B มีร้านค้าจำนวนมาก จึงไม่ใช่ผู้ขายน้อยราย", "ไม่ถูก สลับกัน: A ผู้ขายไม่กี่ราย = ผู้ขายน้อยราย ส่วน B ร้านค้ามากและสินค้าแตกต่าง = กึ่งแข่งขันกึ่งผูกขาด", "A ถูก แต่ B ไม่ใช่ตลาดแข่งขันสมบูรณ์ เพราะสินค้ามีเอกลักษณ์แตกต่างกัน (ตลาดแข่งขันสมบูรณ์สินค้าต้องเหมือนกันทุกประการ)", "ถูก A ผู้ขายไม่กี่รายแข่งด้านกลยุทธ์การตลาด = ผู้ขายน้อยราย และ B ผู้ขายจำนวนมาก สินค้าแตกต่าง = กึ่งแข่งขันกึ่งผูกขาด"]'::jsonb,'{"table": [["ตลาด A", "ตลาด B"], ["มีจำนวนผู้ขายเพียงไม่กี่รายที่ครอบครองรายได้จากการขายสินค้า โดยผู้ขายแต่ละรายต่างแข่งขันกันในด้านโปรโมชั่นและกลยุทธ์การตลาด แต่สินค้าต่าง ๆ ที่มีอยู่กลับมีลักษณะใกล้เคียงกัน", "มีร้านค้าอยู่เป็นจำนวนมาก แต่ละร้านต่างก็ขายสินค้าที่มีเอกลักษณ์เฉพาะ ซึ่งอาจจะมีสีสัน และดีไซน์ที่ต่างกัน ถึงแม้ว่าจะเป็นสินค้าประเภทเดียวกันก็ตาม"]], "topic": "3.1", "n": 25}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-25');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-26','M6','M6-SO','M6-SO-S3','A-Level 70',null,2,'ในชุมชนชนบทแห่งหนึ่ง ชาวบ้านนิยมปลูกพืชเชิงเดี่ยว จึงต้องเผชิญกับปัญหาราคาผลผลิตที่ตกต่ำ และความเสี่ยงจากภัยพิบัติทางธรรมชาติอยู่เสมอ หากชุมชนต้องการแก้ปัญหาโดยใช้หลักเศรษฐกิจพอเพียงควรเลือกใช้แนวทางในข้อใดจึงเหมาะสมที่สุด','["ส่งเสริมให้ชาวบ้านเพิ่มพื้นที่เพาะปลูกพืชเพื่อชดเชยรายได้", "สนับสนุนให้ชาวบ้านขายที่ดินและย้ายไปหางานทำใหม่ในเขตเมือง", "ช่วยกันจัดหาสารเคมีและเทคโนโลยีสมัยใหม่เพื่อช่วยเพิ่มผลผลิตในระยะสั้น", "จัดตั้งกองทุนหมู่บ้านเพื่อให้ชาวบ้านมีแหล่งกู้เงินเพื่อนำมาลงทุนเพาะปลูกเพิ่มเติม", "ส่งเสริมการปลูกพืชหลากหลายชนิดเพื่อลดความเสี่ยงและเพิ่มความมั่นคงทางอาหาร"]'::jsonb,4,array[4]::smallint[],'["ปรัชญาของเศรษฐกิจพอเพียง: ความพอประมาณ ความมีเหตุผล การมีภูมิคุ้มกันในตัวที่ดี (บนเงื่อนไขความรู้และคุณธรรม) การปลูกพืชหลากหลายชนิดช่วยกระจายความเสี่ยง พึ่งพาตนเองด้านอาหาร = ภูมิคุ้มกัน"]'::jsonb,'["การขยายพื้นที่ปลูกพืชเชิงเดี่ยวยิ่งเพิ่มความเสี่ยงเรื่องราคาและภัยธรรมชาติ", "การขายที่ดินทิ้งถิ่นไม่ใช่การพึ่งพาตนเองหรือแก้ปัญหาอย่างยั่งยืน", "การพึ่งสารเคมีเพื่อผลผลิตระยะสั้นไม่ยั่งยืน และไม่ได้ลดความเสี่ยง", "การกู้เงินมาลงทุนเพิ่มในพืชเดิมเพิ่มภาระหนี้ ไม่ได้สร้างภูมิคุ้มกัน", "ถูก การปลูกพืชหลากหลายลดความเสี่ยงด้านราคาและภัยพิบัติ และสร้างความมั่นคงทางอาหาร ตรงหลักภูมิคุ้มกันของเศรษฐกิจพอเพียง"]'::jsonb,'{"topic": "3.3", "n": 26}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-26');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-27','M6','M6-SO','M6-SO-S3','A-Level 70',null,2,'ในรอบหนึ่งปี ประเทศ A ประสบปัญหาเงินเฟ้อที่สูงขึ้นอย่างรวดเร็ว ซึ่งพบว่าเป็นผลมาจากราคาน้ำมันในตลาดโลกเพิ่มสูงขึ้น ส่งผลต่อราคาน้ำมันภายในประเทศปรับตัวสูงขึ้น และประชาชนมีความต้องการซื้อสินค้าและบริการเพิ่มมากขึ้นหลังจากเศรษฐกิจเริ่มฟื้นตัว แต่สินค้าในตลาดกลับมีไม่เพียงพอ ประกอบกับผู้ประกอบการบางรายถือโอกาสขึ้นราคาสินค้า เนื่องจากราคาวัตถุดิบและพลังงานเพิ่มสูงขึ้น รัฐบาลจะมีมาตรการในการแก้ปัญหาได้อย่างไร','["การเพิ่มภาษีสินค้าฟุ่มเฟือยเพื่อลดการใช้จ่ายของประชาชน", "ออกนโยบายแจกเงินเยียวยาให้ประชาชนเพื่อเพิ่มกำลังซื้อในช่วงเงินเฟ้อ", "ปรับขึ้นอัตราดอกเบี้ยนโยบายเพื่อลดปริมาณเงินหมุนเวียนในระบบเศรษฐกิจ", "ตรึงราคาน้ำมันและสนับสนุนเงินชดเชยให้บริษัทพลังงานเพื่อลดต้นทุนการผลิตสินค้า", "ลดภาษีนำเข้าสินค้าพลังงานและวัตถุดิบที่จำเป็น เพื่อช่วยลดต้นทุนการผลิตของผู้ประกอบการ"]'::jsonb,2,array[2,4]::smallint[],'["เงินเฟ้อในโจทย์มีทั้งแบบ “ต้นทุนผลักดัน” (ราคาน้ำมัน/วัตถุดิบสูง) และ “อุปสงค์ฉุดดึง” (ความต้องการซื้อเพิ่มหลังเศรษฐกิจฟื้น สินค้าไม่พอ) ทปอ. ให้คะแนนทั้งข้อ 3 (ขึ้นดอกเบี้ยลดอุปสงค์) และข้อ 5 (ลดต้นทุนการผลิต)"]'::jsonb,'["เพิ่มภาษีสินค้าฟุ่มเฟือยกระทบเฉพาะสินค้าบางกลุ่ม ไม่ได้แก้สาเหตุหลัก (ราคาพลังงาน สินค้าขาดแคลน)", "แจกเงินเพิ่มกำลังซื้อทำให้อุปสงค์สูงขึ้นอีก เงินเฟ้อยิ่งรุนแรง", "ถูก (ทปอ. ให้คะแนน) ขึ้นอัตราดอกเบี้ยนโยบายลดปริมาณเงินและการใช้จ่าย แก้เงินเฟ้อแบบอุปสงค์ฉุดดึง", "การตรึงราคาและอุดหนุนบริษัทพลังงานเป็นภาระการคลังสูงและบิดเบือนตลาด ไม่ใช่คำตอบที่ ทปอ. ให้คะแนน", "ถูก (ทปอ. ให้คะแนน) ลดภาษีนำเข้าพลังงานและวัตถุดิบช่วยลดต้นทุนการผลิต แก้เงินเฟ้อแบบต้นทุนผลักดัน"]'::jsonb,'{"topic": "3.2", "n": 27}'::jsonb,'imported_m6','imported',true,'expl','ทปอ. ประกาศเฉลยข้อนี้ 2 คำตอบ (3 หรือ 5) ระบบให้คะแนนทั้งสองตัวเลือก',2568,'soc:68-27');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-28','M6','M6-SO','M6-SO-S3','A-Level 70',null,2,'ในปีที่ผ่านมา ประเทศ A และประเทศ B มีข้อมูลทางเศรษฐกิจดังตารางด้านล่าง จากข้อมูลดังกล่าว ข้อใดกล่าวถูกต้องเกี่ยวกับผลิตภัณฑ์ประชาชาติ (GNP) ของประเทศ A และประเทศ B','["ประเทศ A มี GNP น้อยกว่าประเทศ B อยู่ 4,800 ล้านหน่วย", "ประเทศ B มี GNP มากกว่าประเทศ A อยู่ 5,800 ล้านหน่วย", "ประเทศ B มี GNP มากกว่าประเทศ A อยู่ 4,200 ล้านหน่วย", "ประเทศ A มี GNP เท่ากับ 11,200 ล้านหน่วย ส่วนประเทศ B มี GNP เท่ากับ 17,000 ล้านหน่วย", "ประเทศ A มี GNP เท่ากับ 8,800 ล้านหน่วย ส่วนประเทศ B มี GNP เท่ากับ 13,000 ล้านหน่วย"]'::jsonb,0,array[0]::smallint[],'["GNP = GDP + รายได้ที่พลเมืองได้จากต่างประเทศ − รายได้ที่ชาวต่างชาติได้จากในประเทศ · ประเทศ A = 10,000 + 500 − 700 = 9,800 · ประเทศ B = 15,000 + 800 − 1,200 = 14,600 · ผลต่าง = 4,800 ล้านหน่วย"]'::jsonb,'["ถูก A มี GNP 9,800 และ B มี 14,600 ล้านหน่วย A น้อยกว่า B อยู่ 4,800 ล้านหน่วย", "ไม่ถูก ผลต่างคือ 4,800 ไม่ใช่ 5,800", "ไม่ถูก ผลต่างคือ 4,800 ไม่ใช่ 4,200", "ไม่ถูก ตัวเลขนี้เกิดจากการบวกทั้งสองรายการ (10,000+500+700 และ 15,000+800+1,200) ซึ่งผิดสูตร", "ไม่ถูก ตัวเลขนี้เกิดจากการลบทั้งสองรายการ (10,000−500−700 และ 15,000−800−1,200) ซึ่งผิดสูตร"]'::jsonb,'{"table": [["ประเทศ A", "ประเทศ B"], ["• ผลิตภัณฑ์มวลรวมภายในประเทศ (GDP) เท่ากับ 10,000 ล้านหน่วย\n• รายได้ที่พลเมืองของประเทศได้รับจากการลงทุนในต่างประเทศ เท่ากับ 500 ล้านหน่วย\n• รายได้ของคนต่างชาติที่ได้รับจากการเข้ามาลงทุนในประเทศ เท่ากับ 700 ล้านหน่วย", "• ผลิตภัณฑ์มวลรวมภายในประเทศ (GDP) เท่ากับ 15,000 ล้านหน่วย\n• รายได้ที่พลเมืองของประเทศได้รับจากการลงทุนในต่างประเทศ เท่ากับ 800 ล้านหน่วย\n• รายได้ของคนต่างชาติที่ได้รับจากการเข้ามาลงทุนในประเทศ เท่ากับ 1,200 ล้านหน่วย"]], "topic": "3.2", "n": 28}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-28');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-29','M6','M6-SO','M6-SO-S3','A-Level 70',null,2,'ประเทศไทยและประเทศ A ได้ทำความตกลงเขตการค้าเสรี (FTA) ภายใต้ข้อตกลงนี้พบว่าปริมาณการส่งออกข้าวของไทยไปยังประเทศ A เพิ่มขึ้นอย่างมาก ในขณะที่ประเทศ A สามารถส่งออกชิ้นส่วนอิเล็กทรอนิกส์มายังประเทศไทยในต้นทุนที่ต่ำลง ข้อใดเป็นผลดีที่เกิดขึ้นกับผู้ผลิตในภาคอุตสาหกรรมจากการร่วมมือกันทางเศรษฐกิจระหว่างประเทศดังกล่าว','["การลดภาษีช่วยเพิ่มต้นทุนการผลิตและกระตุ้นให้เกิดการพัฒนาเทคโนโลยี", "การเพิ่มกำแพงภาษีศุลกากรทำให้ราคาสินค้าสูงขึ้นและทำให้ผู้ผลิตเสียผลประโยชน์", "การขยายตัวของการค้าเสรีช่วยส่งเสริมให้เกิดการแข่งขันในอุตสาหกรรมภายในประเทศ", "การแลกเปลี่ยนสินค้าและบริการระหว่างกันมีส่วนช่วยลดต้นทุนการผลิตของผู้ผลิตในแต่ละประเทศ", "การเพิ่มปริมาณการค้าระหว่างประเทศส่งผลให้ทั้งสองประเทศพึ่งพาตนเองได้น้อยลง"]'::jsonb,3,array[3]::smallint[],'["เขตการค้าเสรี (FTA) ลด/ยกเลิกภาษีระหว่างกัน ผู้ผลิตภาคอุตสาหกรรมของไทยนำเข้าชิ้นส่วนอิเล็กทรอนิกส์ได้ถูกลง = ต้นทุนการผลิตต่ำลง"]'::jsonb,'["ไม่ถูก การลดภาษีช่วย “ลด” ต้นทุนการผลิต ไม่ใช่เพิ่ม", "ไม่ถูก FTA คือการลดกำแพงภาษี ไม่ใช่เพิ่ม", "การแข่งขันที่เพิ่มขึ้นเป็นผลที่เกิดได้ แต่ไม่ใช่ “ผลดีต่อผู้ผลิต” ที่โจทย์เน้นเรื่องชิ้นส่วนราคาถูก", "ถูก การแลกเปลี่ยนสินค้าระหว่างกันทำให้ผู้ผลิตได้วัตถุดิบ/ชิ้นส่วนราคาถูกลง ลดต้นทุนการผลิต", "ไม่ถูก เป็นผลเชิงลบ และไม่ใช่ผลดีต่อผู้ผลิต"]'::jsonb,'{"topic": "3.4", "n": 29}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-29');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-30','M6','M6-SO','M6-SO-S3','A-Level 70',null,2,'ประเทศไทยได้เข้าร่วมความตกลงหุ้นส่วนทางเศรษฐกิจระดับภูมิภาค (RCEP) โดยหลังจากการเข้าร่วมพบว่า ประเทศไทยสามารถส่งออกสินค้าเกษตรและสินค้าอุตสาหกรรมได้เพิ่มมากขึ้น แต่ในขณะเดียวกันผู้ประกอบการรายย่อยบางส่วนภายในประเทศต้องเผชิญกับการแข่งขันที่รุนแรงจากสินค้านำเข้าที่มีราคาถูกกว่า ข้อใดเป็นผลกระทบเชิงบวกที่เกิดขึ้นกับภาคธุรกิจของประเทศไทย','["ผู้ประกอบการธุรกิจขนาดย่อม (SMEs) ภายในประเทศไม่สามารถขยายกิจการได้", "ช่วยเพิ่มอำนาจในการต่อรองให้กับผู้ประกอบการธุรกิจรายย่อยในเวทีการค้าโลก", "ช่วยเพิ่มโอกาสในการส่งออกสินค้าและทำให้ธุรกิจภายในประเทศบางส่วนต้องเกิดการปรับตัว", "ขีดความสามารถในการแข่งขันของผู้ประกอบการธุรกิจรายย่อยภายในประเทศลดลง", "ลดกำแพงภาษีส่งผลให้ธุรกิจภายในประเทศทุกประเภทได้รับประโยชน์อย่างเท่าเทียมกัน"]'::jsonb,2,array[2]::smallint[],'["RCEP เป็นความตกลงการค้าเสรีระดับภูมิภาค (อาเซียน + จีน ญี่ปุ่น เกาหลีใต้ ออสเตรเลีย นิวซีแลนด์) ผลบวก: เปิดตลาดส่งออก และกระตุ้นให้ธุรกิจในประเทศปรับตัวพัฒนาขีดความสามารถ"]'::jsonb,'["เป็นผลกระทบเชิงลบ ไม่ใช่เชิงบวก", "ไม่ถูก โจทย์ระบุว่ารายย่อยเผชิญการแข่งขันรุนแรง ไม่ได้มีอำนาจต่อรองเพิ่มขึ้น", "ถูก เพิ่มโอกาสส่งออก และแรงกดดันจากการแข่งขันทำให้ธุรกิจต้องปรับตัว ซึ่งเป็นผลดีระยะยาว", "เป็นผลกระทบเชิงลบ", "ไม่ถูก ธุรกิจไม่ได้ประโยชน์เท่าเทียมกันทุกประเภท บางส่วนเสียเปรียบจากสินค้านำเข้าราคาถูก"]'::jsonb,'{"topic": "3.4", "n": 30}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-30');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-31','M6','M6-SO','M6-SO-S4','A-Level 70',null,2,'หากต้องการศึกษาเอกสารการเมืองการปกครองของอังกฤษ ที่แสดงจำนวนประชากรบนที่ดินจำนวนหมู่บ้าน จำนวนทรัพย์สิน และสามารถบ่งบอกถึงความสัมพันธ์ระหว่างกษัตริย์และขุนนางกับข้าติดที่ดินของประเทศอังกฤษ ควรศึกษาจากเอกสารหลักฐานทางประวัติศาสตร์สมัยกลางในข้อใด','["สนธิสัญญาแวร์ซาย", "หนังสือแห่งกาลเวลา", "มหากาพย์ชองซองเดอโรลองค์", "บันทึกดูมสเดย์", "พระราชโองการของสมเด็จพระราชินีนาถวิกตอเรีย"]'::jsonb,3,array[3]::smallint[],'["บันทึกดูมสเดย์ (Domesday Book, ค.ศ. 1086) จัดทำในสมัยพระเจ้าวิลเลียมผู้พิชิต สำรวจที่ดิน ประชากร หมู่บ้าน ทรัพย์สินทั่วอังกฤษ เป็นหลักฐานชั้นต้นสมัยกลางที่สะท้อนระบบฟิวดัล (กษัตริย์–ขุนนาง–ข้าติดที่ดิน)"]'::jsonb,'["ไม่ถูก สนธิสัญญาแวร์ซาย (ค.ศ. 1919) เป็นสนธิสัญญาหลังสงครามโลกครั้งที่ 1 สมัยใหม่", "ไม่ถูก ไม่ใช่เอกสารสำรวจที่ดินและประชากรของอังกฤษ (หนังสือประเภทบทสวดตามเวลาในสมัยกลางเป็นหนังสือศาสนา)", "ไม่ถูก มหากาพย์ซองเดอโรลองด์เป็นวรรณกรรมของฝรั่งเศสเรื่องวีรกรรมอัศวิน ไม่ใช่เอกสารการปกครอง", "ถูก บันทึกดูมสเดย์เป็นบันทึกสำรวจที่ดิน ประชากร ทรัพย์สิน ของอังกฤษ สะท้อนความสัมพันธ์ในระบบฟิวดัล", "ไม่ถูก สมเด็จพระราชินีนาถวิกตอเรียครองราชย์ในคริสต์ศตวรรษที่ 19 ไม่ใช่สมัยกลาง"]'::jsonb,'{"topic": "4.1", "n": 31}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-31');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-32','M6','M6-SO','M6-SO-S4','A-Level 70',null,2,'ข้อใดต่อไปนี้เป็นความก้าวหน้าทางวิทยาการของอารยธรรมอินเดีย','["ค้นพบจุดบนดวงอาทิตย์และสามารถอธิบายว่าโลกเป็นวัตถุที่เคลื่อนที่ในอวกาศ", "ประดิษฐ์เลข 0 ทำให้มีหลักหน่วย หลักสิบ หลักร้อย หลักพัน และค้นหาตำแหน่งดาวได้", "รู้จักคุณสมบัติของแม่เหล็ก จนพัฒนาประดิษฐ์เข็มทิศ และนำมาใช้ทางการทหาร", "ประดิษฐ์ลูกคิด และสามารถคำนวณอัตราส่วนระหว่างเส้นผ่านศูนย์กลางกับเส้นรอบวงได้", "คิดค้นหมึกจากเขม่าต้นรัก จนพัฒนาการพิมพ์บนแผ่นไม้แกะสลัก"]'::jsonb,1,array[1]::smallint[],'["อารยธรรมอินเดียคิดเลข 0 และระบบเลขฐานสิบแบบหลักตำแหน่ง (ต่อมาชาวอาหรับนำไปเผยแพร่ในยุโรป) และมีความรู้ด้านดาราศาสตร์ · เข็มทิศ ลูกคิด หมึก การพิมพ์แกะไม้ เป็นผลงานจีน"]'::jsonb,'["ไม่ใช่ผลงานเด่นของอินเดีย การอธิบายว่าโลกเคลื่อนที่รอบดวงอาทิตย์เป็นของโคเพอร์นิคัส (ยุโรป)", "ถูก อินเดียประดิษฐ์เลข 0 ทำให้เกิดระบบหลักหน่วย สิบ ร้อย พัน และใช้คำนวณทางดาราศาสตร์", "ไม่ถูก เข็มทิศเป็นผลงานของจีน", "ไม่ถูก ลูกคิดเป็นผลงานของจีน (โจทย์รวมกับการคำนวณค่าพาย จึงหมายถึงจีน)", "ไม่ถูก หมึกและการพิมพ์ด้วยแม่พิมพ์ไม้แกะสลักเป็นผลงานของจีน"]'::jsonb,'{"topic": "4.3", "n": 32}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-32');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-33','M6','M6-SO','M6-SO-S4','A-Level 70',null,2,'ข้อใดเป็นองค์กรระหว่างประเทศที่เกิดจากการรวมกลุ่มของชาติคอมมิวนิสต์','["องค์การสนธิสัญญาแอตแลนติกเหนือ", "องค์การระหว่างประเทศโอเปก", "สมาคมนาฟตา", "องค์การสันนิบาตชาติ", "องค์การสนธิสัญญาวอร์ซอ"]'::jsonb,4,array[4]::smallint[],'["สงครามเย็น: ฝ่ายคอมมิวนิสต์ (นำโดยสหภาพโซเวียต) ตั้งองค์การสนธิสัญญาวอร์ซอ (ค.ศ. 1955) เพื่อตอบโต้ NATO ของฝ่ายโลกเสรี (ค.ศ. 1949)"]'::jsonb,'["ไม่ถูก NATO เป็นพันธมิตรทางทหารของฝ่ายโลกเสรี นำโดยสหรัฐอเมริกา", "ไม่ถูก OPEC เป็นกลุ่มประเทศผู้ส่งออกน้ำมัน ไม่ใช่การรวมกลุ่มของชาติคอมมิวนิสต์", "ไม่ถูก NAFTA เป็นเขตการค้าเสรีอเมริกาเหนือ (สหรัฐฯ แคนาดา เม็กซิโก)", "ไม่ถูก สันนิบาตชาติตั้งหลังสงครามโลกครั้งที่ 1 เพื่อรักษาสันติภาพ", "ถูก องค์การสนธิสัญญาวอร์ซอเป็นพันธมิตรทางทหารของสหภาพโซเวียตและประเทศคอมมิวนิสต์ยุโรปตะวันออก"]'::jsonb,'{"topic": "4.3", "n": 33}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-33');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-34','M6','M6-SO','M6-SO-S4','A-Level 70',null,2,'ข้อใดไม่ใช่สาเหตุที่ชาวยุโรปตื่นตัวในการเข้าร่วมสงครามครูเสด','["ความศรัทธาต่อศาสนาอย่างแรงกล้า และสันตะปาปาประกาศยกบาปให้กับผู้เข้าร่วมสงคราม", "ประชาชนต้องการเสี่ยงโชคและผจญภัยเพื่อแสวงหาความมั่นคั่งและร่ำรวยในดินแดนตะวันออก", "ขุนนางระดับล่างและสามัญชนไม่มีที่ดินของตนเองต้องการครอบครองที่ดินในดินแดนตะวันออก", "พ่อค้าชาวอิตาลีต้องการขยายการค้าขายไปยังดินแดนตะวันออกภายใต้การคุ้มครองของชาวคริสต์", "ขุนนางที่ลดลงและยากจน สถาบันกษัตริย์ที่แข็งแกร่ง และระบบฟิวดัลที่เสื่อมอำนาจลง"]'::jsonb,4,array[4]::smallint[],'["สาเหตุสงครามครูเสด: ศรัทธาทางศาสนา (สันตะปาปาประกาศยกบาป) ความต้องการผจญภัย/ความมั่งคั่ง ความต้องการที่ดิน การขยายการค้าของพ่อค้าอิตาลี · ส่วน “ขุนนางเสื่อมลง สถาบันกษัตริย์เข้มแข็ง ระบบฟิวดัลเสื่อม” เป็น “ผล” ของสงครามครูเสด"]'::jsonb,'["เป็นสาเหตุ ความศรัทธาและการยกบาปจูงใจให้คนเข้าร่วม", "เป็นสาเหตุ หลายคนต้องการความร่ำรวยและการผจญภัยในตะวันออก", "เป็นสาเหตุ ขุนนางชั้นล่างและสามัญชนต้องการที่ดินเป็นของตน", "เป็นสาเหตุ พ่อค้าอิตาลี (เวนิส เจนัว) ต้องการขยายเส้นทางการค้า", "ไม่ใช่สาเหตุ (คำตอบ) เป็นผลที่ตามมาหลังสงคราม ขุนนางจำนวนมากเสียชีวิต/ยากจน อำนาจกษัตริย์เพิ่มขึ้น ระบบฟิวดัลเสื่อม"]'::jsonb,'{"topic": "4.3", "n": 34}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-34');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-35','M6','M6-SO','M6-SO-S4','A-Level 70',null,2,'ข้อใดไม่ใช่ผลงานที่สอดคล้องกับนักวิทยาศาสตร์ในยุคการปฏิวัติทางวิทยาศาสตร์','["นิโคเลาส์ โคเพอร์นิคัส อธิบายว่า โลกมีสัณฐานเป็นวงรี และโลกไม่ได้หยุดนิ่งหรือเป็นศูนย์กลางของระบบสุริยะ", "กาลิเลโอ กาลิเลอิ ประดิษฐ์กล้องโทรทรรศน์แบบหักเห ทำให้มองเห็นพื้นผิวขรุขระของดวงจันทร์ว่าแตกต่างไปจากโลก", "เรอเน เดการ์ต อธิบายว่า การวิเคราะห์ทางคณิตศาสตร์สามารถนำมาใช้ในการพิสูจน์และตรวจสอบข้อเท็จจริงได้", "เซอร์ไอแซก นิวตัน อธิบายเกี่ยวกับการเคลื่อนที่ของโลก ดวงจันทร์ ดาวเคราะห์ และดวงอาทิตย์ได้ด้วยวิธีการทางวิทยาศาสตร์", "เบนจามิน แฟรงคลิน ค้นพบการเกิดฟ้าแลบ ฟ้าร้อง ฟ้าผ่า และประดิษฐ์สายล่อฟ้านำไฟฟ้าจากก้อนเมฆมาใช้ประโยชน์"]'::jsonb,0,array[0]::smallint[],'["ยุคปฏิวัติทางวิทยาศาสตร์: โคเพอร์นิคัสเสนอว่าดวงอาทิตย์เป็นศูนย์กลาง โลกโคจรรอบดวงอาทิตย์ (แต่ยังคิดว่าวงโคจรเป็นวงกลม) · เคปเลอร์เป็นผู้อธิบายวงโคจรรูปวงรี · กาลิเลโอใช้กล้องโทรทรรศน์ · เดการ์ตใช้คณิตศาสตร์และเหตุผล · นิวตันอธิบายการเคลื่อนที่และแรงโน้มถ่วง"]'::jsonb,'["ไม่สอดคล้อง (คำตอบ) โคเพอร์นิคัสไม่ได้อธิบายเรื่องวงรี ผู้อธิบายว่าวงโคจรเป็นวงรีคือโยฮันเนส เคปเลอร์", "สอดคล้อง กาลิเลโอพัฒนากล้องโทรทรรศน์แบบหักเหแสง และพบว่าดวงจันทร์มีผิวขรุขระ", "สอดคล้อง เดการ์ตเน้นการใช้คณิตศาสตร์และเหตุผลในการพิสูจน์ความจริง", "สอดคล้อง นิวตันอธิบายการเคลื่อนที่ของดาวต่าง ๆ ด้วยกฎการเคลื่อนที่และกฎแรงโน้มถ่วง", "ตามเฉลยถือว่าสอดคล้อง แฟรงคลินทดลองเรื่องไฟฟ้าในฟ้าผ่าและประดิษฐ์สายล่อฟ้า"]'::jsonb,'{"topic": "4.3", "n": 35}'::jsonb,'imported_m6','imported',true,'expl','ตัวเลือก 5: แฟรงคลินอยู่ในคริสต์ศตวรรษที่ 18 (ต่อเนื่องจากยุคปฏิวัติวิทยาศาสตร์) ครูอาจอธิบายเพิ่ม',2568,'soc:68-35');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-36','M6','M6-SO','M6-SO-S4','A-Level 70',null,2,'“ลุศักราช 1132 ปีขาลโทศก ถึง ณ เดือนหก ฝ่ายเจ้าพระฝางซึ่งเป็นใหญ่ในหัวเมืองฝ่ายเหนือทั้งปวงนั้น ประพฤติพาลทุจริตทุศีลกรรมลามกบริโภคสุรา กับทั้งพวกสงฆ์อลัชชี ซึ่งเป็นนายทัพนายกองทั้งปวงนั้น แลชวนกันกระทำมนุษย์วิคหฆาตกกรรมปาราชิก แล้วยังนุ่งห่มผ้ากาสาวพัสตรอยู่ หาละจากเพศสมณะไม่”
จากข้อความในพระราชพงศาวดาร ฉบับพระราชหัตถเลขา (ภาคจบ) (2505: 333) ข้อความใดต่อไปนี้ไม่ถูกต้อง','["เกิดขึ้นในสมัยสมเด็จพระเจ้าตากสินมหาราช", "เกิดขึ้นในพุทธศักราช 2313", "ตรงกับคริสต์ศตวรรษที่ 18", "ตรงกับพุทธศตวรรษที่ 23", "1132 เป็นจุลศักราช"]'::jsonb,3,array[3]::smallint[],'["จุลศักราช (จ.ศ.) + 1181 = พุทธศักราช → จ.ศ. 1132 = พ.ศ. 2313 · พ.ศ. − 543 = ค.ศ. 1770 = คริสต์ศตวรรษที่ 18 · พ.ศ. 2301–2400 = พุทธศตวรรษที่ 24 · เหตุการณ์ปราบชุมนุมเจ้าพระฝางเกิดในสมัยสมเด็จพระเจ้าตากสินมหาราช"]'::jsonb,'["ถูกต้อง เหตุการณ์ปราบชุมนุมเจ้าพระฝางอยู่ในสมัยกรุงธนบุรี", "ถูกต้อง จ.ศ. 1132 + 1181 = พ.ศ. 2313", "ถูกต้อง พ.ศ. 2313 − 543 = ค.ศ. 1770 อยู่ในคริสต์ศตวรรษที่ 18 (ค.ศ. 1701–1800)", "ไม่ถูกต้อง (คำตอบ) พ.ศ. 2313 อยู่ในพุทธศตวรรษที่ 24 (พ.ศ. 2301–2400) ไม่ใช่ 23", "ถูกต้อง “ลุศักราช 1132 ปีขาลโทศก” เป็นการนับแบบจุลศักราช"]'::jsonb,'{"topic": "4.1", "n": 36}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-36');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-37','M6','M6-SO','M6-SO-S4','A-Level 70',null,2,'“ในช่วงพุทธศตวรรษที่ 13 – 19 แคว้น (A) มีเรื่องราวปรากฏในตำนานจามเทวีวงศ์ เป็นรัฐที่มีความเจริญทางด้านพระพุทธศาสนา พบหลักฐานการใช้ภาษามอญโบราณ ขณะในช่วงเวลาเดียวกัน แคว้น (B) เป็นรัฐสำคัญที่มีแม่น้ำเจ้าพระยา แม่น้ำลพบุรี และแม่น้ำป่าสักไหลผ่านรับพระพุทธศาสนาเถรวาทมาจากแคว้น (C) และศาสนาพราหมณ์ ฮินดู และพุทธศาสนานิกายมหายานมาจากขอม มีโบราณสถานสำคัญคือพระปรางค์สามยอด ซึ่งบันทึกชาวจีนเรียกแคว้น (C) ว่าโถโลโปตี มีร่องรอยกระจัดกระจายไปทั่วภาคกลาง ภาคใต้ และภาคตะวันออกเฉียงเหนือ ซึ่งส่วนใหญ่เกี่ยวข้องกับพระพุทธศาสนา”
จากข้อความที่กำหนดให้ ข้อใดเรียงลำดับคำตอบที่ถูกต้องของรัฐโบราณในดินแดนไทยตามอักษร A, B และ C','["ลังกาสุกะ, หริภุญชัย, ทวารวดี", "ทวารวดี, โยนกนคร, ฟูนัน", "หริภุญชัย, ละโว้, ทวารวดี", "ละโว้, ตามพรลิงค์, โยนกนคร", "ละโว้, หริภุญชัย, ฟูนัน"]'::jsonb,2,array[2]::smallint[],'["รัฐโบราณในดินแดนไทย: หริภุญชัย (ลำพูน) – ตำนานจามเทวีวงศ์ ใช้ภาษามอญโบราณ · ละโว้ (ลพบุรี) – ลุ่มน้ำเจ้าพระยา ลพบุรี ป่าสัก มีพระปรางค์สามยอด รับอิทธิพลขอม · ทวารวดี – บันทึกจีนเรียก “โถโลโปตี” หลักฐานพระพุทธศาสนากระจายทั่วภาคกลาง ใต้ อีสาน"]'::jsonb,'["ไม่ถูก ลังกาสุกะอยู่ภาคใต้ (ปัตตานี) ไม่ใช่รัฐในตำนานจามเทวี", "ไม่ถูก โยนกนครอยู่ภาคเหนือตอนบน ไม่มีพระปรางค์สามยอด และฟูนันอยู่ในกัมพูชา/เวียดนามตอนใต้", "ถูก A = หริภุญชัย (จามเทวีวงศ์ มอญโบราณ) B = ละโว้ (พระปรางค์สามยอด) C = ทวารวดี (โถโลโปตี)", "ไม่ถูก ละโว้ไม่ใช่รัฐในตำนานจามเทวี ตามพรลิงค์อยู่ภาคใต้ (นครศรีธรรมราช)", "ไม่ถูก A ไม่ใช่ละโว้ และ C ไม่ใช่ฟูนัน (บันทึกจีนเรียกฟูนันว่า “ฟูหนำ”)"]'::jsonb,'{"topic": "4.2", "n": 37}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-37');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-38','M6','M6-SO','M6-SO-S4','A-Level 70',null,2,'“นายปกรณ์เป็นนิสิตคณะอักษรศาสตร์ จุฬาลงกรณ์มหาวิทยาลัย ได้ไปรักษาพยาบาลอาการเจ็บป่วยจากการถูกพิษสุนัขบ้ากัดที่สถานเสาวภา และได้ไปเยี่ยมอาการของคุณป้าที่โรงพยาบาลจุฬาลงกรณ์ จากนั้นก่อนกลับบ้านได้แวะไปฝากเงินที่ธนาคารออมสิน ไปจ่ายค่าน้ำประปาที่ร้านสะดวกซื้อ แวะเที่ยวงานกาชาดที่สวนลุมพินี ซึ่งเคยจะเป็นสยามรัฐพิพิธภัณฑ์ และเดินทางมาขึ้นรถไฟกลับบ้านที่สถานีรถไฟกรุงเทพ (หัวลำโพง)”
จากข้อความที่กำหนดให้ เรื่องราวของนายปกรณ์นั้นสะท้อนให้เห็นมรดกการพัฒนาจากพระราชกรณียกิจของพระมหากษัตริย์พระองค์ใด','["พระมหาเจษฎาราชเจ้า", "สมเด็จพระภัทรมหาราช", "สมเด็จพระมหาธีรราชเจ้า", "สมเด็จพระปิยมหาราช", "พระสยามเทวมหามกุฏวิทยมหาราช"]'::jsonb,2,array[2]::smallint[],'["มรดกสมัยรัชกาลที่ 6 (สมเด็จพระมหาธีรราชเจ้า): จุฬาลงกรณ์มหาวิทยาลัย สถานเสาวภา (สภากาชาดไทย) โรงพยาบาลจุฬาลงกรณ์ คลังออมสิน (ธนาคารออมสิน) การประปากรุงเทพ สวนลุมพินี (เดิมจะใช้จัดสยามรัฐพิพิธภัณฑ์) สถานีรถไฟกรุงเทพ (หัวลำโพง)"]'::jsonb,'["ไม่ถูก พระมหาเจษฎาราชเจ้า คือรัชกาลที่ 3", "ไม่ถูก สมเด็จพระภัทรมหาราช คือรัชกาลที่ 9", "ถูก สมเด็จพระมหาธีรราชเจ้า คือรัชกาลที่ 6 สิ่งที่นายปกรณ์ใช้บริการล้วนเป็นมรดกจากรัชสมัยนี้", "ไม่ถูก สมเด็จพระปิยมหาราช คือรัชกาลที่ 5 (ทรงวางรากฐานหลายด้าน แต่สถานที่ในโจทย์ก่อตั้ง/เปิดในรัชกาลที่ 6)", "ไม่ถูก พระสยามเทวมหามกุฏวิทยมหาราช คือรัชกาลที่ 4"]'::jsonb,'{"topic": "4.2", "n": 38}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-38');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-39','M6','M6-SO','M6-SO-S4','A-Level 70',null,2,'หากมีภัณฑารักษ์บรรยายถึงพระพุทธรูปสำคัญองค์หนึ่ง ซึ่งมีลักษณะเฉพาะ คือ พระเกศมีรัศมีเป็นเปลว ขมวดพระเกศาเล็ก พระพักตร์รูปไข่ พระขนงโก่ง พระนาสิกงุ้ม พระโอษฐ์ยิ้มเล็กน้อยพระอังสาใหญ่ ครองจีวรห่มเฉียง ชายจีวรยาวลงมาถึงพระนาภี เป็นปางมารวิชัย มีข้อความถึงผู้สร้าง โดยสร้างขึ้นเพื่อเป็นพุทธบูชา และเพื่อได้ผลบุญให้เกิดมาได้พบพระศรีอริยเมตไตรยความว่า “พระเจ้านายญี่บุญแลแม่จันแลนางเริ่มนางไรแล้วเจ้าไสอานนท์ลูกชายสายใจชื่อนางยอดตูทั้งหลายขอพบพระศรีอาริยไมตรีเจ้าหั้น”
จากการอธิบายพุทธศิลป์ดังกล่าว พระพุทธรูปองค์นี้มีพุทธศิลป์สอดคล้องกับศิลปะใด','["ศิลปะสมัยสุโขทัย", "ศิลปะสมัยล้านนา", "ศิลปะสมัยอยุธยา", "ศิลปะสมัยล้านช้าง", "ศิลปะสมัยรัตนโกสินทร์"]'::jsonb,0,array[0]::smallint[],'["พุทธศิลป์สุโขทัย: พระรัศมีเป็นเปลว ขมวดพระเกศาเล็ก พระพักตร์รูปไข่ พระขนงโก่ง พระนาสิกงุ้ม พระโอษฐ์อมยิ้ม พระอังสาใหญ่ ครองจีวรห่มเฉียง ชายจีวรยาวถึงพระนาภี ปางมารวิชัย"]'::jsonb,'["ถูก ลักษณะที่บรรยายทั้งหมด (รัศมีเปลว พักตร์รูปไข่ ชายจีวรยาวถึงพระนาภี) เป็นเอกลักษณ์ของพระพุทธรูปสุโขทัย", "ไม่ถูก ล้านนารุ่นแรก (สิงห์ 1) พระพักตร์กลม รัศมีดอกบัวตูม ชายจีวรสั้นเหนือพระถัน แม้ถ้อยคำในจารึกจะคล้ายภาษาถิ่น แต่โจทย์ถามลักษณะพุทธศิลป์", "ไม่ถูก พระพุทธรูปอยุธยามักพระพักตร์เป็นเหลี่ยม เคร่งขรึม และนิยมพระพุทธรูปทรงเครื่อง", "ไม่ถูก พระพุทธรูปล้านช้างพระนาสิกโด่งงุ้มมาก พระกรรณยาวโค้ง เอกลักษณ์ต่างจากที่บรรยาย", "ไม่ถูก พระพุทธรูปรัตนโกสินทร์เน้นความเหมือนจริงมากขึ้น (เช่น สมัย ร.4) ไม่ใช่ลักษณะที่บรรยาย"]'::jsonb,'{"topic": "4.2", "n": 39}'::jsonb,'imported_m6','imported',false,null,'ถ้อยคำจารึกคล้ายภาษาถิ่นเหนือ อาจทำให้นักเรียนเลือกล้านนา ครูควรเน้นว่าตอบจากลักษณะพุทธศิลป์',2568,'soc:68-39');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-40','M6','M6-SO','M6-SO-S4','A-Level 70',null,2,'“ในสมัยกรุงศรีอยุธยา (A) ได้รับอิทธิพลจากขอมเกี่ยวกับสถานะของสถาบันพระมหากษัตริย์ว่าเป็นสมมติเทพ โดยปรากฏหลักฐานทางศิลปกรรมการแกะสลักไม้หน้าบันพระอุโบสถวัดหน้าพระเมรุเป็นรูป (B) อย่างไรก็ตาม จากหลักฐานทางประวัติศาสตร์แสดงให้เห็นว่าพื้นที่ของกรุงศรีอยุธยา มีการตั้งถิ่นฐานของมนุษย์มาก่อนมีชุมชน โดยปรากฏหลักฐาน ณ วัดพนัญเชิงตามพระราชพงศาวดารกรุงเก่า ฉบับหลวงประเสริฐกล่าวว่า พระพุทธรูป (C) สร้างขึ้นเมื่อ จ.ศ. 686 ก่อนการสถาปนากรุงศรีอยุธยาถึง 26 ปี”
จากข้อความที่กำหนดให้ ข้อใดเรียงลำดับคำตอบที่ถูกต้องตามอักษร A, B และ C','["สมเด็จพระเจ้าปราสาททอง, พระพรหมทรงหงส์, พระมงคลบพิตร", "สมเด็จพระรามาธิบดีที่ 1, พระนารายณ์ทรงครุฑ, พระพุทธไตรรัตนนายก", "สมเด็จพระบรมไตรโลกนาถ, พระอินทร์ทรงช้างเอราวัณ, พระมงคลบพิตร", "สมเด็จพระนารายณ์มหาราช, พระพิฆเนศวรทรงหนู, พระศรีสรรเพชญดาญาณ", "สมเด็จพระบรมไตรโลกนาถ, พระศิวะทรงโค, พระพุทธนิมิตวิชิตมารโมลีศรีสรรเพชญฯ"]'::jsonb,1,array[1]::smallint[],'["ต้นกรุงศรีอยุธยา (สมเด็จพระรามาธิบดีที่ 1) รับคติเทวราชาจากขอม · หน้าบันพระอุโบสถวัดหน้าพระเมรุเป็นรูปพระนารายณ์ทรงครุฑ (สื่อกษัตริย์คือพระนารายณ์อวตาร) · พระพุทธไตรรัตนนายก (หลวงพ่อโต) วัดพนัญเชิง สร้าง จ.ศ. 686 (พ.ศ. 1867) ก่อนสถาปนากรุงศรีอยุธยา (พ.ศ. 1893) 26 ปี"]'::jsonb,'["ไม่ถูก สมเด็จพระเจ้าปราสาททองเป็นกษัตริย์สมัยกลาง/ปลายอยุธยา พระมงคลบพิตรไม่ได้อยู่วัดพนัญเชิง", "ถูก A = พระรามาธิบดีที่ 1 (ผู้สถาปนา รับคติเทวราชา) B = พระนารายณ์ทรงครุฑ C = พระพุทธไตรรัตนนายก วัดพนัญเชิง", "ไม่ถูก หน้าบันวัดหน้าพระเมรุไม่ใช่พระอินทร์ทรงช้างเอราวัณ และพระมงคลบพิตรไม่ได้สร้างก่อนสถาปนากรุง", "ไม่ถูก พระศรีสรรเพชญ์หล่อในสมัยพระรามาธิบดีที่ 2 หลังสถาปนากรุง", "ไม่ถูก พระพุทธนิมิตวิชิตมารโมลีฯ เป็นพระประธานวัดหน้าพระเมรุ ไม่ใช่พระพุทธรูปที่วัดพนัญเชิง"]'::jsonb,'{"topic": "4.2", "n": 40}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-40');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-41','M6','M6-SO','M6-SO-S5','A-Level 70',null,2,'นักเรียนเข้าร่วมการแข่งขันวิ่งในสวนสัตว์เปิดเขาเขียว โดยเริ่มวิ่งจากกรงนกฟลามิงโกไปบ่อฮิปโปแคระ วัดระยะทางจริงบนพื้นผิวโลกได้ 0.5 กิโลเมตร และวิ่งจากบ่อฮิปโปแคระไปหุบเสือโคร่ง เป็นระยะทางจริงบนผิวโลก 2.0 กิโลเมตร ถ้าวัดระยะทางทั้งหมดจากแผนที่ได้ 5 เซนติเมตรอยากทราบว่าแผนที่นี้มีมาตราส่วนเท่าใด','["มาตราส่วน 1 : 2,500", "มาตราส่วน 1 : 5,000", "มาตราส่วน 1 : 25,000", "มาตราส่วน 1 : 50,000", "มาตราส่วน 1 : 250,000"]'::jsonb,3,array[3]::smallint[],'["มาตราส่วน = ระยะบนแผนที่ : ระยะจริง (หน่วยเดียวกัน) ระยะจริงรวม 0.5 + 2.0 = 2.5 กม. = 250,000 ซม. แผนที่ 5 ซม. → 5 : 250,000 = 1 : 50,000"]'::jsonb,'["ไม่ถูก 1:2,500 หมายถึง 5 ซม. = 125 เมตร", "ไม่ถูก 1:5,000 หมายถึง 5 ซม. = 250 เมตร", "ไม่ถูก 1:25,000 หมายถึง 5 ซม. = 1.25 กม. (ได้จากการใช้ระยะ 2.0 กม. อย่างเดียวหรือคำนวณหน่วยพลาด)", "ถูก 250,000 ซม. ÷ 5 ซม. = 50,000 → 1:50,000", "ไม่ถูก 1:250,000 หมายถึง 5 ซม. = 12.5 กม. (ลืมหารด้วย 5)"]'::jsonb,'{"topic": "5.1", "n": 41}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-41');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-42','M6','M6-SO','M6-SO-S5','A-Level 70',null,2,'ประเภทสัญลักษณ์ในภูมิประเทศข้อใดต่อไปนี้แตกต่างจากข้ออื่น','["ท่าเรือ ทางรถไฟ", "สนามบิน นาข้าว", "ถนน แม่น้ำ", "วัด โรงพยาบาล", "แหล่งน้ำ ป่าไม้"]'::jsonb,0,array[0,1,2,3,4]::smallint[],'["สัญลักษณ์บนแผนที่แบ่งเป็น จุด (เช่น วัด โรงพยาบาล สนามบิน ท่าเรือ) เส้น (ถนน ทางรถไฟ แม่น้ำ) และพื้นที่ (นาข้าว ป่าไม้ แหล่งน้ำขนาดใหญ่) ข้อนี้ ทปอ. ประกาศ “ฟรีทุกข้อ” คือทุกคำตอบได้คะแนน"]'::jsonb,'["ท่าเรือ (จุด) กับทางรถไฟ (เส้น) – คนละประเภท", "สนามบิน (จุด) กับนาข้าว (พื้นที่) – คนละประเภท", "ถนนและแม่น้ำ – เป็นสัญลักษณ์เส้นทั้งคู่", "วัดและโรงพยาบาล – เป็นสัญลักษณ์จุดทั้งคู่", "แหล่งน้ำและป่าไม้ – เป็นสัญลักษณ์พื้นที่ทั้งคู่"]'::jsonb,'{"topic": "5.1", "n": 42, "key_free": true}'::jsonb,'imported_m6','imported',false,null,'ทปอ. ประกาศเฉลย “ฟรีทุกข้อ” ระบบนับเป็นถูกไม่ว่าเลือกตัวเลือกใด',2568,'soc:68-42');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-43','M6','M6-SO','M6-SO-S5','A-Level 70',null,2,'ลักษณะกายภาพในข้อใดไม่สัมพันธ์กับการเคลื่อนที่ของแผ่นธรณีภาค','["สันเขาใต้มหาสมุทรแอตแลนติก กับ การเคลื่อนที่แยกจากกันของเปลือกโลกภาคพื้นมหาสมุทร", "เกรตริฟต์แวลลีย์กับ การเคลื่อนที่แยกจากกันของเปลือกโลกภาคพื้นทวีป", "ชั้นหินคดโค้งรูปประทุน รัฐแคลิฟอร์เนีย กับ การเคลื่อนที่เข้าหากันระหว่างเปลือกโลกภาคพื้นทวีป", "รอยเลื่อนแซนแอนเดรียส กับ การเคลื่อนที่สวนทางกันในแนวระนาบ", "หมู่เกาะภูเขาไฟกลางมหาสมุทรรูปโค้ง กับ การเคลื่อนที่เข้าหากันระหว่างเปลือกโลกภาคพื้นมหาสมุทร"]'::jsonb,2,array[2]::smallint[],'["การเคลื่อนที่ของแผ่นธรณี: แยกจากกัน (สันเขากลางมหาสมุทร หุบเขาทรุด) · เข้าหากัน (ทวีป–ทวีป → เทือกเขาหินคดโค้ง เช่น หิมาลัย · มหาสมุทร–มหาสมุทร → หมู่เกาะภูเขาไฟรูปโค้ง) · เลื่อนผ่านกันแนวระนาบ (รอยเลื่อนแซนแอนเดรียส รัฐแคลิฟอร์เนีย)"]'::jsonb,'["สัมพันธ์ถูก สันเขากลางมหาสมุทรแอตแลนติกเกิดจากแผ่นธรณีมหาสมุทรแยกจากกัน", "สัมพันธ์ถูก เกรตริฟต์แวลลีย์ (แอฟริกาตะวันออก) เกิดจากแผ่นธรณีทวีปแยกจากกัน", "ไม่สัมพันธ์ (คำตอบ) แคลิฟอร์เนียอยู่บนแนวรอยต่อแบบเลื่อนผ่านกัน ส่วนเทือกเขาหินคดโค้งจากทวีปชนทวีปพบที่หิมาลัย/แอลป์", "สัมพันธ์ถูก รอยเลื่อนแซนแอนเดรียสเกิดจากแผ่นธรณีเลื่อนสวนทางกันในแนวระนาบ", "สัมพันธ์ถูก หมู่เกาะภูเขาไฟรูปโค้ง (เช่น ญี่ปุ่น มาเรียนา) เกิดจากแผ่นมหาสมุทรมุดตัวเข้าหากัน"]'::jsonb,'{"topic": "5.2", "n": 43}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-43');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-44','M6','M6-SO','M6-SO-S5','A-Level 70',null,2,'ภูมิประเทศในข้อใดเกิดจากการกระทำของตัวการที่แตกต่างจากข้ออื่น','["ที่ราบน้ำท่วมถึง", "คันดินธรรมชาติ", "เนินตะกอนรูปพัด", "ดินดอนสามเหลี่ยม", "ร่องธาร"]'::jsonb,4,array[4]::smallint[],'["ธารน้ำทำให้เกิดภูมิประเทศ 2 แบบ: จากการทับถมของตะกอน (ที่ราบน้ำท่วมถึง คันดินธรรมชาติ เนินตะกอนรูปพัด ดินดอนสามเหลี่ยม) และจากการกัดกร่อน (ร่องธาร หุบเขารูปตัววี) ร่องธารจึงเกิดจากกระบวนการต่างจากข้ออื่น"]'::jsonb,'["เกิดจากการทับถมของตะกอนเมื่อแม่น้ำล้นตลิ่ง", "เกิดจากการทับถมของตะกอนริมตลิ่งเมื่อน้ำล้นตลิ่งบ่อย ๆ", "เกิดจากการทับถมของตะกอนบริเวณที่ธารน้ำไหลจากที่สูงลงสู่ที่ราบ", "เกิดจากการทับถมของตะกอนบริเวณปากแม่น้ำ", "แตกต่าง (คำตอบ) ร่องธารเกิดจากการกัดกร่อนของน้ำที่ไหลบนผิวดิน ไม่ใช่การทับถม"]'::jsonb,'{"topic": "5.2", "n": 44}'::jsonb,'imported_m6','imported',false,null,'โจทย์ใช้คำว่า “ตัวการ” แต่ความต่างจริงคือ “กระบวนการ” (กัดกร่อน vs ทับถม) ครูอาจอธิบายเพิ่ม',2568,'soc:68-44');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-45','M6','M6-SO','M6-SO-S5','A-Level 70',null,2,'กิจกรรมทางเศรษฐกิจในข้อใดไม่สัมพันธ์กับลักษณะทางกายภาพ','["ภูมิภาคเอเชียกลางมีสภาพอากาศแบบเมดิเตอร์เรเนียนจึงเป็นเขตปลูกพืชผลไม้ที่สำคัญ", "เขตละติจูดกลางของทวีปอเมริกาเหนือมีอุณหภูมิอบอุ่นพอเหมาะ จึงเป็นเขตปลูกข้าวสาลีที่สำคัญ", "บริเวณละติจูดต่ำของทวีปอเมริกาใต้มีอากาศร้อนชื้นและได้รับอิทธิพลจากลมค้าจึงเป็นเขตปลูกพืชเศรษฐกิจ", "บริเวณละติจูดกลางของทวีปอเมริกาใต้มีอากาศอบอุ่น ปริมาณฝนไม่สูงและมีทุ่งหญ้าจึงเป็นเขตเลี้ยงสัตว์เศรษฐกิจ", "เขตเกาะและชายฝั่งทะเลที่มีความชื้นสูงของทวีปออสเตรเลียและโอเชียเนียมีความชื้นสูง มีปริมาณฝนมากจึงเป็นเขตปลูกไม้ผล"]'::jsonb,0,array[0]::smallint[],'["ภูมิอากาศเมดิเตอร์เรเนียนพบบริเวณชายฝั่งทะเลเมดิเตอร์เรเนียน แคลิฟอร์เนีย ชิลีตอนกลาง แอฟริกาใต้ตอนปลาย ออสเตรเลียตอนใต้ ไม่พบในเอเชียกลางซึ่งเป็นภาคพื้นทวีปที่แห้งแล้ง (ทะเลทราย/ทุ่งหญ้ากึ่งแห้งแล้ง)"]'::jsonb,'["ไม่สัมพันธ์ (คำตอบ) เอเชียกลางเป็นภูมิอากาศแบบแห้งแล้ง/ทุ่งหญ้ากึ่งแห้งแล้ง ไม่ใช่เมดิเตอร์เรเนียน", "สัมพันธ์ เขตละติจูดกลางของอเมริกาเหนือ (ทุ่งหญ้าแพรรี) เป็นแหล่งปลูกข้าวสาลีสำคัญ", "สัมพันธ์ เขตร้อนชื้นของอเมริกาใต้ปลูกพืชเศรษฐกิจเขตร้อน เช่น กาแฟ อ้อย โกโก้", "สัมพันธ์ ทุ่งหญ้าปัมปัส (อาร์เจนตินา) เป็นเขตเลี้ยงสัตว์สำคัญ", "สัมพันธ์ เกาะและชายฝั่งที่ชื้นและฝนมากเหมาะกับไม้ผลเขตร้อน"]'::jsonb,'{"topic": "5.3", "n": 45}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-45');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-46','M6','M6-SO','M6-SO-S5','A-Level 70',null,2,'เพราะเหตุใดดินแดนในแถบเมดิเตอร์เรเนียนจึงได้ชื่อว่าเป็นดินแดนสวนผลไม้ของโลก','["อุณหภูมิสูงสม่ำเสมอ ร้อนชื้นฝนตกชุก", "อากาศอบอุ่น ปริมาณน้ำใต้ดินเหมาะสมต่อการเพาะปลูก", "มีความแห้งแล้งหนาวเย็น ปลูกได้ทั้งฤดูใบไม้ผลิและฤดูหนาว", "แสงแดดจัดในฤดูร้อน ฤดูหนาวอบอุ่น และฝนตกค่อนข้างชุก", "อากาศแบบมรสุม มีน้ำมากในฤดูเพาะปลูก และเก็บเกี่ยวในฤดูแล้ง"]'::jsonb,3,array[3]::smallint[],'["ภูมิอากาศเมดิเตอร์เรเนียน: ฤดูร้อนแดดจัดและแห้ง ฤดูหนาวอบอุ่นและมีฝน เหมาะกับไม้ผล เช่น องุ่น มะกอก ส้ม จึงได้ชื่อว่าเป็น “สวนผลไม้ของโลก”"]'::jsonb,'["ไม่ถูก ร้อนชื้นฝนตกชุกตลอดปีเป็นลักษณะภูมิอากาศเขตร้อน (ป่าดิบชื้น)", "ไม่ถูก ไม่ได้อธิบายลักษณะเด่นของเมดิเตอร์เรเนียน (ร้อนแห้ง–หนาวชื้น)", "ไม่ถูก เมดิเตอร์เรเนียนไม่ได้แห้งแล้งหนาวเย็น", "ถูก แดดจัดในฤดูร้อน ฤดูหนาวอบอุ่นและมีฝน เป็นสภาพที่เหมาะกับไม้ผล", "ไม่ถูก อากาศแบบมรสุมเป็นลักษณะของเอเชียใต้/ตะวันออกเฉียงใต้"]'::jsonb,'{"topic": "5.3", "n": 46}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-46');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-47','M6','M6-SO','M6-SO-S5','A-Level 70',null,2,'ปัญหาปลาหมอคางดำมีความเกี่ยวข้องกับความตกลงในข้อใดมากที่สุด','["อนุสัญญาแรมซาร์", "อนุสัญญาว่าด้วยความหลากหลายทางชีวภาพ", "อนุสัญญาไซเตส", "พิธีสารเกียวโต", "พิธีสารมอนทรีออล"]'::jsonb,1,array[1]::smallint[],'["ปลาหมอคางดำเป็นชนิดพันธุ์ต่างถิ่นรุกราน (invasive alien species) กระทบความหลากหลายทางชีวภาพ จึงเกี่ยวกับอนุสัญญาว่าด้วยความหลากหลายทางชีวภาพ (CBD)"]'::jsonb,'["ไม่ตรงที่สุด อนุสัญญาแรมซาร์ว่าด้วยการอนุรักษ์พื้นที่ชุ่มน้ำ", "ถูก CBD ครอบคลุมการป้องกัน ควบคุม และกำจัดชนิดพันธุ์ต่างถิ่นที่คุกคามระบบนิเวศ", "ไม่ถูก CITES ควบคุมการค้าระหว่างประเทศของพืชและสัตว์ป่าที่ใกล้สูญพันธุ์", "ไม่ถูก พิธีสารเกียวโตเกี่ยวกับการลดก๊าซเรือนกระจก", "ไม่ถูก พิธีสารมอนทรีออลเกี่ยวกับการเลิกใช้สารทำลายชั้นโอโซน (เช่น CFCs)"]'::jsonb,'{"topic": "5.4", "n": 47}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-47');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-48','M6','M6-SO','M6-SO-S5','A-Level 70',null,2,'ข้อใดอธิบายกระบวนการเกิดแผ่นดินถล่มในภูมิประเทศลาดชันได้ถูกต้อง
ก. ฝนตกหนักติดต่อกันเป็นเวลานาน
ข. ชั้นดินมีแรงกระทำให้เลื่อนไหลมากกว่าแรงต้าน
ค. แรงยึดเหนี่ยวระหว่างช่องว่างเม็ดดินลดลง
ง. ความดันของน้ำในดินเพิ่มสูงขึ้น ความดันในช่องว่างเม็ดดินเพิ่มขึ้น
จ. น้ำซึมลงในดินจนกระทั่งดินอิ่มตัว แรงยึดระหว่างมวลดินลดลง','["ก, ข, ค, ง, จ", "ง, ก, ข, ค, จ", "ก, จ, ง, ค, ข", "จ, ก, ค, ข, ง", "จ, ก, ข, ค, ง"]'::jsonb,2,array[2]::smallint[],'["กระบวนการเกิดดินถล่ม: ฝนตกหนักต่อเนื่อง (ก) → น้ำซึมลงดินจนอิ่มตัว (จ) → ความดันน้ำในช่องว่างเม็ดดินเพิ่มขึ้น (ง) → แรงยึดเหนี่ยวระหว่างเม็ดดินลดลง (ค) → แรงที่ทำให้ดินเลื่อนไหลมากกว่าแรงต้าน ดินจึงถล่ม (ข)"]'::jsonb,'["ไม่ถูก ลำดับข้าม ข ไปก่อน จ ง ค ทั้งที่แรงเลื่อนไหลชนะแรงต้านต้องเป็นขั้นสุดท้าย", "ไม่ถูก ความดันน้ำในดินเพิ่มขึ้นไม่ได้เกิดก่อนฝนตก", "ถูก ก → จ → ง → ค → ข เป็นลำดับเหตุและผลจากฝนตก น้ำซึม ความดันเพิ่ม แรงยึดลด จนดินเลื่อนไหล", "ไม่ถูก น้ำซึมจนดินอิ่มตัวไม่ได้เกิดก่อนฝนตก", "ไม่ถูก เริ่มต้นด้วย จ (ดินอิ่มน้ำ) ก่อน ก (ฝนตก) ซึ่งกลับเหตุ–ผล"]'::jsonb,'{"topic": "5.2", "n": 48}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2568,'soc:68-48');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-49','M6','M6-SO','M6-SO-S5','A-Level 70',null,2,'ข้อใดเป็นสาเหตุสำคัญที่ทำให้เขตสะวันนาในประเทศแอฟริกาใต้มักเกิดไฟป่าเป็นประจำทุกปีในช่วงฤดูแล้ง','["การเผาป่าเพื่อล่าสัตว์", "กิ่งไม้เสียดสีกันจากแรงลมพัด", "ปฏิกิริยาเคมีในดินทำให้เกิดความร้อน", "การเผาพื้นที่เพาะปลูกภายหลังการเก็บเกี่ยว", "หญ้าหรือต้นไม้ทิ้งใบตายลงเกิดเป็นวัสดุเชื้อเพลิงจำนวนมาก"]'::jsonb,4,array[4]::smallint[],'["ทุ่งหญ้าสะวันนามีฤดูฝนและฤดูแล้งชัดเจน ในฤดูแล้งหญ้าและไม้ทิ้งใบแห้งตาย สะสมเป็นเชื้อเพลิงจำนวนมาก จึงเกิดไฟป่าได้ง่ายเป็นประจำทุกปี"]'::jsonb,'["การเผาเพื่อล่าสัตว์อาจเป็นต้นเหตุจุดไฟได้ แต่ไม่ใช่ “สาเหตุสำคัญ” ที่ทำให้เกิดเป็นประจำในเชิงภูมิศาสตร์", "กิ่งไม้เสียดสีกันเป็นสาเหตุที่พบได้น้อยมาก", "ไม่ถูก ปฏิกิริยาเคมีในดินไม่ใช่สาเหตุของไฟป่าในสะวันนา", "การเผาเศษวัสดุเกษตรพบได้ แต่ไม่ใช่ลักษณะเด่นของทุ่งหญ้าสะวันนาตามธรรมชาติ", "ถูก ในฤดูแล้งหญ้าและใบไม้แห้งสะสมเป็นเชื้อเพลิงจำนวนมาก เมื่อมีประกายไฟจึงลุกลามเป็นไฟป่าได้ทุกปี"]'::jsonb,'{"topic": "5.2", "n": 49}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-49');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SO-68-50','M6','M6-SO','M6-SO-S5','A-Level 70',null,2,'ข้อใดไม่ถูกต้องเกี่ยวกับความสัมพันธ์ของโครงสร้างประชากร','["ประเทศพัฒนาแล้ว - ประชากรวัยเด็กและวัยทำงานใกล้เคียงกัน", "ประเทศพัฒนาแล้ว - การเพิ่มขึ้นของประชากรเป็นไปอย่างรวดเร็ว", "ประเทศพัฒนาแล้ว - ประชากรวัยเด็กน้อยและวัยสูงอายุมาก", "ประเทศกำลังพัฒนา - พีระมิดฐานกว้าง ยอดแหลม", "ประเทศกำลังพัฒนา - มีประชากรวัยเด็กมาก"]'::jsonb,1,array[1]::smallint[],'["โครงสร้างประชากร: ประเทศกำลังพัฒนา – อัตราเกิดสูง เด็กมาก พีระมิดฐานกว้างยอดแหลม ประชากรเพิ่มเร็ว · ประเทศพัฒนาแล้ว – อัตราเกิดต่ำ ผู้สูงอายุมาก พีระมิดทรงระฆัง/ทรงโถ ประชากรเพิ่มช้าหรือลดลง"]'::jsonb,'["ถูกต้อง ประเทศพัฒนาแล้วมีโครงสร้างค่อนข้างคงที่ สัดส่วนแต่ละช่วงวัยใกล้เคียงกัน (พีระมิดทรงระฆัง)", "ไม่ถูกต้อง (คำตอบ) ประเทศพัฒนาแล้วประชากรเพิ่มขึ้นช้า บางประเทศลดลง เพราะอัตราเกิดต่ำ", "ถูกต้อง ประเทศพัฒนาแล้วเด็กน้อย ผู้สูงอายุมาก", "ถูกต้อง ประเทศกำลังพัฒนามีพีระมิดฐานกว้างยอดแหลม", "ถูกต้อง ประเทศกำลังพัฒนามีอัตราเกิดสูง เด็กจำนวนมาก"]'::jsonb,'{"topic": "5.3", "n": 50}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'soc:68-50');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-TH-69-1','M6','M6-TH','M6-TH-S1','A-Level 81',null,2,'อ่านข้อความต่อไปนี้แล้วตอบคำถามข้อที่ 1
ข้าวเม่า คือข้าวที่ทำจากข้าวเปลือกข้าวเหนียวที่ยังไม่แก่จัด นำมาคั่วแล้วตำให้เปลือกแตกหลุดออกไป มีลักษณะแบน นุ่ม สีออกเขียว ข้าวเม่านำมารับประทานเป็นของหวานและของกินเล่น ปรุงได้หลายแบบ ข้าวเม่าที่พรมน้ำเกลือเคล้าให้นุ่ม นำมาคลุกกับมะพร้าวขูดโรยน้ำตาลทราย เรียกว่า ข้าวเม่าคลุก นิยมรับประทานกับกล้วยไข่ ข้าวเม่าที่ผสมน้ำตาลและมะพร้าวขูดนำไปพอกกล้วยไข่ ชุบแป้งให้ติดกันเป็นแพ ทอดในน้ำมัน เรียกว่า ข้าวเม่าทอด ข้าวเม่าที่นำไปคั่ว เรียกว่า ข้าวเม่าราง รับประทานกับน้ำกะทิเป็นของหวาน หรือนำไปทำกระยาสารท
ข้อใดกล่าวไม่ถูกต้องเกี่ยวกับ “ข้าวเม่า” ในข้อความข้างต้น','["ข้าวเม่าทำจากข้าวเปลือกข้าวเหนียวที่ยังมีสีเขียว", "ข้าวเม่าสามารถนำมาประกอบอาหารได้หลายชนิด", "ข้าวเม่าคลุกกับมะพร้าวคั่วนิยมรับประทานกับกล้วยไข่", "ข้าวเม่าเมื่อนำไปคั่ว ใช้เป็นส่วนประกอบของการทำกระยาสารท", "ข้าวเม่าทอดมีวัตถุดิบสำคัญคือ ข้าวเม่า มะพร้าวขูด และกล้วยไข่"]'::jsonb,2,array[2]::smallint[],'["อ่านเพื่อเข้าใจรายละเอียด แล้วเทียบทีละตัวเลือก: ข้าวเม่าคลุกคือข้าวเม่าที่พรมน้ำเกลือแล้ว “คลุกกับมะพร้าวขูด” โรยน้ำตาลทราย ไม่ใช่มะพร้าวคั่ว"]'::jsonb,'["ตรงกับข้อความ ข้าวเปลือกข้าวเหนียวที่ยังไม่แก่จัด และข้าวเม่ามีสีออกเขียว", "ตรงกับข้อความ ข้าวเม่าปรุงได้หลายแบบ", "ไม่ถูกต้อง (คำตอบ) ข้าวเม่าคลุกใช้มะพร้าวขูด ไม่ใช่มะพร้าวคั่ว", "ตรงกับข้อความ ข้าวเม่าที่นำไปคั่ว (ข้าวเม่าราง) นำไปทำกระยาสารทได้", "ตรงกับข้อความ ข้าวเม่าทอดใช้ข้าวเม่า มะพร้าวขูด และกล้วยไข่"]'::jsonb,'{"topic": "1.1", "n": 1}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'thai:69-1');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-TH-69-2','M6','M6-TH','M6-TH-S1','A-Level 81',null,2,'อ่านข้อความต่อไปนี้แล้วตอบคำถามข้อที่ 2 – 3
จากกรณีที่มีนักสิทธิมนุษยชนถูกสังคมออนไลน์โจมตีอย่างหนักเนื่องจากได้แสดงความคิดเห็นในเชิงเรียกร้องสิทธิเสรีภาพของชาวกัมพูชาที่อาศัยอยู่ในพื้นที่พิพาทระหว่างไทยกับกัมพูชา กลุ่มความคิดแต่ละกลุ่มได้แสดงความคิดเห็นต่างกันออกไป ความคิดเห็นจากเครือข่ายสังคมออนไลน์กล่าวว่าอธิปไตยของชาติเป็นสิ่งสำคัญยิ่งกว่าสิ่งอื่นใด การกระทำที่จะส่งผลต่ออธิปไตยและความมั่นคงของชาติเป็นสิ่งที่ไม่สามารถยอมรับได้ และท่าทีเช่นนี้ไม่น่าจะแสดงออกมาโดยบุคคลสำคัญของชาติ ขอให้นักสิทธิมนุษยชนคนดังกล่าวออกมาขอโทษสังคมและงดเว้นการกระทำที่ส่งผลต่อความมั่นคงของชาติอีก หากทำไม่ได้ก็ควรย้ายไปอยู่ประเทศอื่นแทน ส่วนคณะกรรมการสิทธิมนุษยชนแห่งชาติ (กสม.) เน้นย้ำให้ทุกฝ่ายเคารพความเห็นต่างและศักดิ์ศรีความเป็นมนุษย์ของทุกคนที่แม้จะแตกต่างกันด้วยเชื้อชาติ ศาสนา ภาษา หรือสถานะทางสังคมอื่นใด แต่ต่างก็มีคุณค่าในตนเอง ทั้งนี้ ขอให้สังคมร่วมกันสร้างพื้นที่ปลอดภัยในการแสดงความคิดเห็นและการวิพากษ์วิจารณ์อย่างสร้างสรรค์ ไม่ยอมรับการสร้างความเกลียดชังและการละเมิดศักดิ์ศรีความเป็นมนุษย์ทุกรูปแบบ
ข้อความข้างต้นสรุปสาระสำคัญได้ตามข้อใด','["นักสิทธิมนุษยชนควรปกป้องอธิปไตยของชาติมากกว่าสิทธิของชาวต่างชาติ", "สังคมไทยเป็นสังคมประชาธิปไตย ดังนั้น เราสามารถแสดงความคิดเห็นได้ตามสิทธิและเสรีภาพ", "ทุกคนมีความรักชาติแต่ต้องยอมรับความเห็นต่างได้และเคารพศักดิ์ศรีความเป็นมนุษย์", "สังคมไทยเป็นสังคมแห่งความหลากหลาย เราจึงควรยอมรับความแตกต่างทางเชื้อชาติ", "คุณค่าของมนุษย์ขึ้นอยู่กับการกระทำมากกว่าเชื้อชาติ ศาสนา หรือสถานะทางสังคม"]'::jsonb,2,array[2]::smallint[],'["ข้อความเสนอสองฝ่าย ฝ่ายหนึ่งเน้นอธิปไตยและความรักชาติ อีกฝ่าย (กสม.) เน้นการเคารพความเห็นต่างและศักดิ์ศรีความเป็นมนุษย์ สาระสำคัญจึงต้องครอบคลุมทั้งสองฝ่าย"]'::jsonb,'["เป็นความเห็นของฝ่ายเดียว และไม่ใช่ข้อสรุปของข้อความ", "ข้อความไม่ได้สรุปว่าแสดงความเห็นได้ตามใจ แต่เน้นการเคารพกันและไม่สร้างความเกลียดชัง", "ถูก ครอบคลุมทั้งความรักชาติ (อธิปไตย) และการยอมรับความเห็นต่างกับศักดิ์ศรีความเป็นมนุษย์", "แคบเกินไป ประเด็นไม่ได้อยู่ที่ความแตกต่างทางเชื้อชาติเท่านั้น", "เป็นรายละเอียดหนึ่งของความเห็น กสม. ไม่ใช่สาระของข้อความทั้งหมด"]'::jsonb,'{"topic": "1.2", "n": 2}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'thai:69-2');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-TH-69-3','M6','M6-TH','M6-TH-S1','A-Level 81',null,2,'อ่านข้อความต่อไปนี้แล้วตอบคำถามข้อที่ 2 – 3
จากกรณีที่มีนักสิทธิมนุษยชนถูกสังคมออนไลน์โจมตีอย่างหนักเนื่องจากได้แสดงความคิดเห็นในเชิงเรียกร้องสิทธิเสรีภาพของชาวกัมพูชาที่อาศัยอยู่ในพื้นที่พิพาทระหว่างไทยกับกัมพูชา กลุ่มความคิดแต่ละกลุ่มได้แสดงความคิดเห็นต่างกันออกไป ความคิดเห็นจากเครือข่ายสังคมออนไลน์กล่าวว่าอธิปไตยของชาติเป็นสิ่งสำคัญยิ่งกว่าสิ่งอื่นใด การกระทำที่จะส่งผลต่ออธิปไตยและความมั่นคงของชาติเป็นสิ่งที่ไม่สามารถยอมรับได้ และท่าทีเช่นนี้ไม่น่าจะแสดงออกมาโดยบุคคลสำคัญของชาติ ขอให้นักสิทธิมนุษยชนคนดังกล่าวออกมาขอโทษสังคมและงดเว้นการกระทำที่ส่งผลต่อความมั่นคงของชาติอีก หากทำไม่ได้ก็ควรย้ายไปอยู่ประเทศอื่นแทน ส่วนคณะกรรมการสิทธิมนุษยชนแห่งชาติ (กสม.) เน้นย้ำให้ทุกฝ่ายเคารพความเห็นต่างและศักดิ์ศรีความเป็นมนุษย์ของทุกคนที่แม้จะแตกต่างกันด้วยเชื้อชาติ ศาสนา ภาษา หรือสถานะทางสังคมอื่นใด แต่ต่างก็มีคุณค่าในตนเอง ทั้งนี้ ขอให้สังคมร่วมกันสร้างพื้นที่ปลอดภัยในการแสดงความคิดเห็นและการวิพากษ์วิจารณ์อย่างสร้างสรรค์ ไม่ยอมรับการสร้างความเกลียดชังและการละเมิดศักดิ์ศรีความเป็นมนุษย์ทุกรูปแบบ
ข้อความข้างต้นไม่ปรากฏน้ำเสียงเช่นใด','["ตำหนิ", "เรียกร้อง", "ละอายใจ", "วิตกกังวล", "ผิดหวัง"]'::jsonb,2,array[2]::smallint[],'["หาน้ำเสียงที่ “ไม่ปรากฏ”: ตำหนิ (โจมตี “ไม่น่าจะแสดงออกมาโดยบุคคลสำคัญ”) เรียกร้อง (ให้ออกมาขอโทษ / ขอให้สังคมสร้างพื้นที่ปลอดภัย) วิตกกังวล (ต่ออธิปไตยและความมั่นคง) ผิดหวัง (ต่อท่าทีของบุคคลสำคัญ) ส่วนความละอายใจไม่มีผู้ใดแสดงออก"]'::jsonb,'["ปรากฏ สังคมออนไลน์ตำหนิท่าทีของนักสิทธิมนุษยชน", "ปรากฏ เรียกร้องให้ขอโทษ และ กสม. ขอให้ทุกฝ่ายเคารพกัน", "ไม่ปรากฏ (คำตอบ) ไม่มีฝ่ายใดแสดงความละอายใจ", "ปรากฏ ความกังวลต่ออธิปไตยและความมั่นคงของชาติ", "ปรากฏ “ไม่น่าจะแสดงออกมาโดยบุคคลสำคัญของชาติ” แสดงความผิดหวัง"]'::jsonb,'{"topic": "1.7", "n": 3}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'thai:69-3');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-TH-69-4','M6','M6-TH','M6-TH-S1','A-Level 81',null,2,'อ่านข้อความต่อไปนี้แล้วตอบคำถามข้อ 4 – 5
สมองเป็นศูนย์กลางการสั่งการและควบคุมการทำงานของระบบร่างกาย โดยใช้เส้นประสาทและสารเคมีเป็นสื่อในการส่งสัญญาณไปทั่วร่างกาย สารเคมีนั้นเรียกว่าสารสื่อประสาท (Neurotransmitter) การทำงานของสารสื่อประสาทเกิดขึ้นหลังจากที่สมองมีการสั่งการ ทำให้เซลล์ประสาทถูกกระตุ้นด้วยประจุไฟฟ้าที่เกิดจากการถ่ายเทเกลือแร่ระหว่างภายในและภายนอกเซลล์ประสาท แล้วส่งสัญญาณเพื่อกระตุ้นเซลล์ประสาทที่อยู่ข้างเคียง โดยการใช้สารสื่อประสาทส่งผ่านบริเวณช่องว่างระหว่างเซลล์ประสาทที่เรียกว่าไซแนปส์ (Synapse) สารสื่อประสาทที่ปล่อยออกมาบริเวณปลายเส้นประสาทนี้จะไปเกาะที่ตัวรับซึ่งแตกต่างกันตามชนิดของสารสื่อประสาทของอีกปลายประสาทหนึ่ง ทำให้เกิดการตอบสนองหรือยับยั้งการทำงานของระบบร่างกายได้ ตัวอย่างสารสื่อประสาทที่มีความสำคัญในการทำงานของร่างกาย เช่น อะดรีนาลิน (Adrenaline) เอนโดฟิน (Endorphin) เซโรโทนิน (Serotonin) ฯลฯ
ข้อใดคือสาระสำคัญของข้อความข้างต้น','["การทำงานของสารสื่อประสาท", "สารสื่อประสาทเป็นสารเคมีจำพวกหนึ่ง", "ร่างกายมนุษย์มีสารสื่อประสาทหลายชนิด", "สมองกับสารสื่อประสาทมีความสัมพันธ์กัน", "สารสื่อประสาทส่งสัญญาณบริเวณไซแนปส์"]'::jsonb,0,array[0]::smallint[],'["ข้อความอธิบายตั้งแต่สมองสั่งการผ่านเส้นประสาทและสารสื่อประสาท การส่งสัญญาณที่ไซแนปส์ ไปจนถึงตัวอย่างสาร ทุกส่วนเป็นเรื่องการทำงานของสารสื่อประสาท"]'::jsonb,'["ถูก ครอบคลุมทุกส่วนของข้อความ", "เป็นรายละเอียดเชิงนิยาม", "เป็นรายละเอียดส่วนท้าย (ตัวอย่างสาร)", "เป็นส่วนเกริ่นนำ ยังไม่ใช่สาระหลัก", "เป็นรายละเอียดหนึ่งของกระบวนการ"]'::jsonb,'{"topic": "1.2", "n": 4}'::jsonb,'imported_m6','imported',true,'stem','Exam Gym ม.6 · 5620e4c',2569,'thai:69-4');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-TH-69-5','M6','M6-TH','M6-TH-S1','A-Level 81',null,2,'อ่านข้อความต่อไปนี้แล้วตอบคำถามข้อ 4 – 5
สมองเป็นศูนย์กลางการสั่งการและควบคุมการทำงานของระบบร่างกาย โดยใช้เส้นประสาทและสารเคมีเป็นสื่อในการส่งสัญญาณไปทั่วร่างกาย สารเคมีนั้นเรียกว่าสารสื่อประสาท (Neurotransmitter) การทำงานของสารสื่อประสาทเกิดขึ้นหลังจากที่สมองมีการสั่งการ ทำให้เซลล์ประสาทถูกกระตุ้นด้วยประจุไฟฟ้าที่เกิดจากการถ่ายเทเกลือแร่ระหว่างภายในและภายนอกเซลล์ประสาท แล้วส่งสัญญาณเพื่อกระตุ้นเซลล์ประสาทที่อยู่ข้างเคียง โดยการใช้สารสื่อประสาทส่งผ่านบริเวณช่องว่างระหว่างเซลล์ประสาทที่เรียกว่าไซแนปส์ (Synapse) สารสื่อประสาทที่ปล่อยออกมาบริเวณปลายเส้นประสาทนี้จะไปเกาะที่ตัวรับซึ่งแตกต่างกันตามชนิดของสารสื่อประสาทของอีกปลายประสาทหนึ่ง ทำให้เกิดการตอบสนองหรือยับยั้งการทำงานของระบบร่างกายได้ ตัวอย่างสารสื่อประสาทที่มีความสำคัญในการทำงานของร่างกาย เช่น อะดรีนาลิน (Adrenaline) เอนโดฟิน (Endorphin) เซโรโทนิน (Serotonin) ฯลฯ
ข้อใดคือจุดประสงค์ของผู้เขียนจากข้อความข้างต้น','["ให้ความรู้เกี่ยวกับสารสื่อประสาท", "บอกความสำคัญของสารสื่อประสาท", "ยกตัวอย่างสารสื่อประสาทในร่างกายมนุษย์", "ชี้ให้เห็นความสำคัญของไซแนปส์", "อธิบายกระบวนการทำงานของสารสื่อประสาท"]'::jsonb,4,array[4]::smallint[],'["ผู้เขียนเล่าการทำงานของสารสื่อประสาทเป็นลำดับ (สมองสั่งการ → ส่งสัญญาณ → ไซแนปส์ → ตัวอย่างสาร) จุดประสงค์เฉพาะที่สุดจึงเป็นการอธิบายกระบวนการ"]'::jsonb,'["กว้างเกินไป ข้อความให้ความรู้จริง แต่ลักษณะเฉพาะคืออธิบายกระบวนการทำงาน", "ข้อความไม่ได้เน้นความสำคัญเป็นหลัก", "ตัวอย่างเป็นเพียงส่วนท้าย", "ไซแนปส์เป็นเพียงจุดหนึ่งของกระบวนการ", "ถูก ข้อความอธิบายลำดับการทำงานของสารสื่อประสาท"]'::jsonb,'{"topic": "1.4", "n": 5}'::jsonb,'imported_m6','imported',true,'expl','ตัวเลือก 1 ล่อใจ ครูควรชี้ว่าเมื่อมีตัวเลือกที่เฉพาะกว่าและตรงกับลักษณะข้อความ ให้เลือกตัวเลือกที่เฉพาะกว่า',2569,'thai:69-5');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-TH-69-6','M6','M6-TH','M6-TH-S1','A-Level 81',null,2,'อ่านคำประพันธ์ต่อไปนี้แล้วตอบคำถามข้อที่ 6
ไม่ต้องบินให้สูงอย่างใครเขา
จงบินเอาเท่าที่เราจะบินไหว
ท่าที่บินไม่จำเป็นต้องเหมือนใคร
แค่บินไปให้ถึงฝันเท่านั้นพอ
ข้อใดตีความคำประพันธ์ข้างต้นไม่ถูกต้อง','["เมธัสไม่อ่านหนังสือเตรียมสอบเข้ามหาวิทยาลัยและเปลี่ยนคณะที่ต้องการเรียนเมื่อเห็นคะแนนขั้นต่ำของปีที่ผ่านมา เพราะไม่ต้องการกดดันตนเองมากเกินไป", "เมธีวางเป้าหมายใหม่ว่าหากสอบเข้ามหาวิทยาลัยของรัฐไม่ได้ตามที่ตั้งใจก็ยังเลือกเรียนมหาวิทยาลัยอื่น ๆ เพื่อประกอบอาชีพครูในอนาคตได้", "เมธพยายามไม่เปรียบเทียบตนเองกับเพื่อนที่สอบติด TCAS รอบแรก จึงตั้งใจเรียนและอ่านหนังสือตามความถนัดของตนเพื่อสอบในรอบต่อ ๆ ไป", "เมธวินไม่สอบเรียนต่อเพราะต้องการพักการเรียน 1 ปีหลังจบชั้น ม.6 เพื่อค้นหาตนเองก่อน แล้วค่อยวางแผนชีวิตด้านการเรียนอีกครั้ง", "เมธาวีปรึกษาผู้ปกครองว่าจะขอสละสิทธิ์เข้าเรียนต่อมหาวิทยาลัยในกรุงเทพฯเพื่อไปเรียนมหาวิทยาลัยในจังหวัดของตน เพราะมีคุณภาพทัดเทียมกันและสอดคล้องกับรูปแบบการใช้ชีวิต"]'::jsonb,0,array[0]::smallint[],'["บทร้อยกรองร่วมสมัยสอนว่าไม่ต้องเปรียบเทียบกับใคร ไปตามกำลังและวิธีของตน แต่ต้อง “บินไปให้ถึงฝัน” ตัวเลือกที่ตีความผิดคือคนที่เลิกพยายามหรือทิ้งความฝันของตนเพราะคะแนนของผู้อื่น"]'::jsonb,'["ตีความไม่ถูกต้อง (คำตอบ) เมธัสไม่อ่านหนังสือและเปลี่ยนคณะเพราะเห็นคะแนนปีก่อน คือยอมทิ้งฝันโดยไม่พยายาม", "สอดคล้อง ปรับเส้นทางตามกำลังแต่ยังมุ่งสู่เป้าหมาย", "สอดคล้อง ไม่เปรียบเทียบกับเพื่อน และไปตามความถนัดของตน", "สอดคล้อง เลือกจังหวะของตนเองโดยไม่ต้องเหมือนใคร", "สอดคล้อง เลือกทางที่เหมาะกับตนเพื่อไปถึงเป้าหมาย"]'::jsonb,'{"topic": "1.3", "n": 6}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'thai:69-6');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-TH-69-7','M6','M6-TH','M6-TH-S1','A-Level 81',null,2,'อ่านคำประพันธ์ต่อไปนี้แล้วตอบคำถามข้อที่ 7
เรียงอิฐติดแน่นแผ่นละครั้ง
ยังเป็นวังใหญ่เยี่ยมเทียมสิงขร
หยาดละหยดวารินรดดินดอน
เป็นสาครใหญ่กว้างเวิ้งว้างเอย
ข้อใดตีความคำประพันธ์ข้างต้นไม่ถูกต้อง','["เมธาวีค่อย ๆ เลือกรายวิชาเพิ่มเติมที่จะลงเรียนในภาคเรียนที่ 1", "เมธเก็บเงินวันละ 5 บาท เป็นเวลา 2 เดือน เพราะจะนำไปซื้อของเล่นที่ชอบ", "เมธัสพยายามอ่านหนังสือวันละนิด ๆ เพื่อเตรียมตัวสอบเข้ามหาวิทยาลัย", "เมธวินวางแผนการทำรายงานโดยแบ่งเป็นส่วน ๆ และค่อย ๆ ทำตามแผนที่วางไว้จนงานเสร็จ", "เมธีเลือกปรับปริมาณอาหารลงทีละน้อย และออกกำลังกายเพื่อลดน้ำหนักแทนการอดอาหาร"]'::jsonb,0,array[0]::smallint[],'["“เรียงอิฐ…แผ่นละครั้ง ยังเป็นวังใหญ่” “หยาดละหยด…เป็นสาครใหญ่” สอนว่าการสะสมทีละน้อยอย่างต่อเนื่องนำไปสู่ผลยิ่งใหญ่ ตัวเลือกที่ไม่มีการสะสมทีละน้อยเพื่อไปสู่ผลจึงตีความผิด"]'::jsonb,'["ตีความไม่ถูกต้อง (คำตอบ) การค่อย ๆ เลือกวิชาไม่ใช่การสะสมทีละน้อยจนเกิดผลใหญ่", "สอดคล้อง เก็บเงินทีละน้อยจนได้ของที่ต้องการ", "สอดคล้อง อ่านหนังสือวันละนิดเพื่อเตรียมสอบ", "สอดคล้อง ทำทีละส่วนจนงานเสร็จ", "สอดคล้อง ลดอาหารทีละน้อยเพื่อลดน้ำหนัก"]'::jsonb,'{"topic": "1.3", "n": 7}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'thai:69-7');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-TH-69-8','M6','M6-TH','M6-TH-S1','A-Level 81',null,2,'อ่านคำประพันธ์ต่อไปนี้แล้วตอบคำถามข้อที่ 8 – 9
บัดนั้น พญาพิเภกยักษี
เห็นพระองค์ทรงโศกโศกี อสุรีกราบลงกับบาทา
ทูลว่าพระลักษมณ์สุริย์วงศ์ ยังไม่ปลงชีวังสังขาร์
อันโมกขศักดิ์อสุรา พรหมาประสิทธิ์ประสาทไว้
ทรงอานุภาพฤทธิรุทร ต้องใครจะฉุดนั้นไม่ไหว
แต่มียาคู่หอกชัย ให้ไว้สำหรับแก้กัน
แม้นละไว้จนรุ่งราตรี ต้องแสงพระรวีจะอาสัญ
ขอให้ลูกพระพายเทวัญ ไปห้ามพระสุริยันในชั้นฟ้า
อย่าเพ่อรีบรถบทจร ข้ามยุคุนธรภูผา
แล้วให้ไปเก็บตรีชวา ทั้งยาชื่อสังกรณี
ยังเขาสรรพยาบรรพต ปรากฏอยู่ยอดคีรีศรี
กับปัญจมหานที สรรพยาทั้งนี้มาให้ทัน
แม้นว่าได้บดชโลมลง องค์พระอนุชาไม่อาสัญ
จะดำรงคงชีพชีวัน หอกนั้นก็จะหลุดขึ้นมา ฯ
ข้อใดกล่าวถึงคำประพันธ์นี้ได้ถูกต้อง','["คำว่า “พระสุริยัน” ในที่นี้หมายถึง “เวลา” ตีความได้ว่าต้องส่งลูกพระพายไปหยุดเวลาของโลกไว้", "คำว่า “ยุคุนธรภูผา” ในที่นี้หมายถึง “อุปสรรค” ตีความได้ว่าอย่ามัวรอช้ารีบพาพระสุริยันข้ามอุปสรรคไปให้ได้", "คำว่า “ปัญจมหานที” ในที่นี้หมายถึง “แม่น้ำสำคัญ 5 สาย” ตีความได้ว่าต้องนำน้ำจากแม่น้ำสำคัญ 5 สายมาใช้ปรุงยา", "คำว่า “หอก” ในที่นี้หมายถึง “ปัญหาหนักอก” ตีความได้ว่าเมื่อนำยาที่ปรุงแล้วทาลงที่ร่างกาย โรคภัยจะหายไปทันที", "คำว่า “สรรพยาบรรพต” ในที่นี้หมายถึง สถานที่ที่พบสังกรณีตรีชวา"]'::jsonb,4,array[4]::smallint[],'["วรรณคดี: บทละครเรื่องรามเกียรติ์ ตอนพญาพิเภกทูลวิธีแก้หอกโมกขศักดิ์ที่ปักพระลักษมณ์ ต้องให้หนุมาน (ลูกพระพาย) ไปห้ามพระอาทิตย์ไม่ให้ขึ้นก่อนได้ยา และไปเก็บยาตรีชวา สังกรณี ที่เขาสรรพยา พร้อมปัญจมหานที มาบดชโลม"]'::jsonb,'["“พระสุริยัน” คือพระอาทิตย์ตามตัวอักษร (ถ้าต้องแสงอาทิตย์ยามรุ่ง พระลักษมณ์จะสิ้นชีวิต) ไม่ได้หมายถึงการหยุดเวลาของโลก", "“ยุคุนธร” เป็นชื่อภูเขาที่รถพระอาทิตย์ข้าม ไม่ได้หมายถึงอุปสรรค และบทให้ห้ามไม่ให้รีบข้าม", "ใกล้เคียงแต่ไม่ใช่คำตอบตามเฉลย บทกล่าวให้นำปัญจมหานทีมา “กับ” สรรพยา แล้ว “บดชโลม” แต่ไม่ได้บอกชัดว่าใช้น้ำนั้นปรุงยา", "“หอก” คือหอกโมกขศักดิ์จริงที่ปักอยู่ ไม่ใช่ปัญหาหนักอก และบทไม่ได้พูดถึงโรคภัย", "ถูก “ยังเขาสรรพยาบรรพต” คือภูเขาที่มีตรีชวาและสังกรณีขึ้นอยู่"]'::jsonb,'{"topic": "1.3", "n": 8}'::jsonb,'imported_m6','imported',true,'expl','ตัวเลือก 3 ใกล้เคียงคำตอบ ครูควรอธิบายเหตุผลที่เฉลยเลือกข้อ 5 และตรวจชื่อตอน/ฉบับพระราชนิพนธ์ที่ใช้ในหนังสือเรียน',2569,'thai:69-8');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-TH-69-9','M6','M6-TH','M6-TH-S2','A-Level 81',null,2,'อ่านคำประพันธ์ต่อไปนี้แล้วตอบคำถามข้อที่ 8 – 9
บัดนั้น พญาพิเภกยักษี
เห็นพระองค์ทรงโศกโศกี อสุรีกราบลงกับบาทา
ทูลว่าพระลักษมณ์สุริย์วงศ์ ยังไม่ปลงชีวังสังขาร์
อันโมกขศักดิ์อสุรา พรหมาประสิทธิ์ประสาทไว้
ทรงอานุภาพฤทธิรุทร ต้องใครจะฉุดนั้นไม่ไหว
แต่มียาคู่หอกชัย ให้ไว้สำหรับแก้กัน
แม้นละไว้จนรุ่งราตรี ต้องแสงพระรวีจะอาสัญ
ขอให้ลูกพระพายเทวัญ ไปห้ามพระสุริยันในชั้นฟ้า
อย่าเพ่อรีบรถบทจร ข้ามยุคุนธรภูผา
แล้วให้ไปเก็บตรีชวา ทั้งยาชื่อสังกรณี
ยังเขาสรรพยาบรรพต ปรากฏอยู่ยอดคีรีศรี
กับปัญจมหานที สรรพยาทั้งนี้มาให้ทัน
แม้นว่าได้บดชโลมลง องค์พระอนุชาไม่อาสัญ
จะดำรงคงชีพชีวัน หอกนั้นก็จะหลุดขึ้นมา ฯ
วิธีการอธิบายในข้อใดไม่ปรากฏในคำประพันธ์นี้','["มีการชี้แจงลำดับขั้นตอน", "มีการชี้สาเหตุและผลลัพธ์", "มีการขยายความ", "มีการยกตัวอย่าง", "มีการกล่าวซ้ำ"]'::jsonb,3,array[3]::smallint[],'["วิธีการอธิบาย: ลำดับขั้นตอน (ห้ามพระอาทิตย์ → เก็บยา → บดชโลม) สาเหตุและผล (ถ้าต้องแสงพระรวีจะสิ้นชีวิต / ถ้าได้ชโลมยา หอกจะหลุด) ขยายความ (หอกโมกขศักดิ์พรหมประสิทธิ์ให้ มีฤทธิ์จนใครก็ฉุดไม่ออก) กล่าวซ้ำ (เรื่องอาสัญ/ไม่อาสัญ) แต่ไม่มีการยกตัวอย่าง"]'::jsonb,'["ปรากฏ บอกเป็นลำดับว่าต้องทำอะไรก่อนหลัง", "ปรากฏ ถ้าถึงรุ่งเช้าจะอาสัญ ถ้าได้ชโลมยาหอกจะหลุด", "ปรากฏ ขยายความถึงฤทธิ์ของหอกโมกขศักดิ์", "ไม่ปรากฏ (คำตอบ) ไม่มีการยกตัวอย่างสิ่งใดมาประกอบ", "ปรากฏ กล่าวถึงการอาสัญ / ไม่อาสัญซ้ำ เพื่อย้ำความสำคัญ"]'::jsonb,'{"topic": "2.3", "n": 9}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'thai:69-9');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-TH-69-10','M6','M6-TH','M6-TH-S1','A-Level 81',null,2,'อ่านคำประพันธ์ต่อไปนี้แล้วตอบคำถามข้อที่ 10 – 11
ไม้เรียกผะกากุพ- ชะกะสีอรุณแสง
ปานแก้มแฉล้มแดง ดรุณีณยามอาย;
ดอกใหญ่และเกสร สุวคนธะมากมาย,
อยู่ทนบวางวาย มธุรสขจรไกล;
อีกทั้งสะพรั่งหนาม ดุจะเข็มประดับไว้,
ผึ้งเขียวสิบินไขว่ บมิใคร่จะห่างเหิน.
อันกุพฺชะกาหอม, บริโภคอร่อยเพลิน,
รสหวานสิหวานเชอญ นรลิ้มเพราะเลิดรส;
กินแล้วระงับตรี พิธะโทษะหายหมด,
คือลมและดีลด ทุษะเสมหะเสื่อมสรรพ์;
อีกทั้งเจริญกา- มะคุณาภิรมย์นันท์,
เย็นในอุราพลัน, และระงับพยาธี.
ข้อใดกล่าวถึงคำประพันธ์นี้ได้ถูกต้อง','["คำว่า “เข็ม” ตีความได้ว่า กุหลาบมีหนามเหมือนสตรีที่มีความรู้เป็นอาวุธป้องกันตัว", "คำว่า “แก้มแฉล้มแดง” ตีความได้ว่า ดอกกุหลาบที่กล่าวถึงมีลักษณะตูมแดงเหมือนแก้มของสตรีที่มีน้ำมีนวล", "คำว่า “ผึ้งเขียว” ตีความได้ว่า ดอกไม้ที่สวยงามมักถูกคนทรามมาเด็ดไปดอมดม", "คำว่า “รสหวาน” ตีความได้ว่า กุหลาบมีรสหวานเหมือนคำพูดที่ไพเราะของสตรีที่สามารถโน้มน้าวใจผู้ฟังให้ลุ่มหลง", "คำว่า “พยาธี” ในที่นี้หมายถึง พยาธิ หรือ ความเจ็บไข้"]'::jsonb,4,array[4]::smallint[],'["วรรณคดี: มัทนะพาธา พระราชนิพนธ์ในรัชกาลที่ 6 (อินทรวิเชียรฉันท์) บทพรรณนาดอกกุพชกะ (กุหลาบ) ทั้งรูป สี กลิ่น และสรรพคุณ “ระงับพยาธี” = ระงับความเจ็บไข้"]'::jsonb,'["ในบท “เข็ม” คือหนามที่แหลมดุจเข็ม เป็นการพรรณนาลักษณะของต้นกุหลาบ ไม่ได้กล่าวถึงความรู้ของสตรี", "“แก้มแฉล้มแดง ดรุณีณยามอาย” เปรียบสีของดอกกับแก้มสาวยามอาย ไม่ได้บอกว่าดอกตูม และบทกล่าวว่าเป็นดอกใหญ่", "ผึ้งที่มาตอมแสดงว่าดอกหอม ไม่ได้หมายถึงคนทราม", "“รสหวาน” คือรสของกุหลาบเมื่อบริโภค (สรรพคุณทางยา) ไม่ได้เปรียบกับคำพูดของสตรี", "ถูก “พยาธี” = พยาธิ คือความเจ็บไข้ กุหลาบช่วยระงับความเจ็บไข้"]'::jsonb,'{"topic": "1.3", "n": 10}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'thai:69-10');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-TH-69-11','M6','M6-TH','M6-TH-S2','A-Level 81',null,2,'อ่านคำประพันธ์ต่อไปนี้แล้วตอบคำถามข้อที่ 10 – 11
ไม้เรียกผะกากุพ- ชะกะสีอรุณแสง
ปานแก้มแฉล้มแดง ดรุณีณยามอาย;
ดอกใหญ่และเกสร สุวคนธะมากมาย,
อยู่ทนบวางวาย มธุรสขจรไกล;
อีกทั้งสะพรั่งหนาม ดุจะเข็มประดับไว้,
ผึ้งเขียวสิบินไขว่ บมิใคร่จะห่างเหิน.
อันกุพฺชะกาหอม, บริโภคอร่อยเพลิน,
รสหวานสิหวานเชอญ นรลิ้มเพราะเลิดรส;
กินแล้วระงับตรี พิธะโทษะหายหมด,
คือลมและดีลด ทุษะเสมหะเสื่อมสรรพ์;
อีกทั้งเจริญกา- มะคุณาภิรมย์นันท์,
เย็นในอุราพลัน, และระงับพยาธี.
วิธีการอธิบายในข้อใดไม่ปรากฏในคำประพันธ์นี้','["มีการกล่าวซ้ำ", "มีการชี้สาเหตุและผลลัพธ์", "มีการขยายความ", "มีการยกตัวอย่าง", "มีการเปรียบเทียบ"]'::jsonb,3,array[3]::smallint[],'["ในบทมัทนะพาธา: กล่าวซ้ำ (“รสหวานสิหวาน”) สาเหตุและผล (บริโภคแล้วตรีพิธะโทษะหายหมด) ขยายความ (ตรีพิธะโทษะ “คือลมและดี… เสมหะ”) เปรียบเทียบ (“ปานแก้ม…”, หนาม “ดุจะเข็ม”) แต่ไม่มีการยกตัวอย่าง"]'::jsonb,'["ปรากฏ มีการซ้ำคำและซ้ำความ เช่น “รสหวานสิหวาน”", "ปรากฏ บอกผลของการบริโภคกุหลาบต่อโรค", "ปรากฏ ขยายความว่าตรีพิธะโทษะคือ ลม ดี และเสมหะ", "ไม่ปรากฏ (คำตอบ) ไม่มีการยกตัวอย่างประกอบ", "ปรากฏ เปรียบสีดอกกับแก้มสาว และหนามกับเข็ม"]'::jsonb,'{"topic": "2.3", "n": 11}'::jsonb,'imported_m6','imported',false,null,'บางตำราอาจนับ “ลม ดี เสมหะ” เป็นการยกตัวอย่าง ครูควรอธิบายว่าในที่นี้เป็นการขยายความ (บอกองค์ประกอบครบ) ตามเฉลย ทปอ.',2569,'thai:69-11');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-TH-69-12','M6','M6-TH','M6-TH-S1','A-Level 81',null,2,'อ่านข้อความต่อไปนี้แล้วตอบคำถามข้อที่ 12 – 13
นักวิทยาศาสตร์ค้นพบว่าการที่ดอกทานตะวันมีพฤติกรรมหันตามแสงเป็นผลจากการทำงานของฮอร์โมนออกซิน (auxin) ซึ่งเป็นสารควบคุมการเจริญเติบโตหลักในพืช ออกซินมีบทบาทสำคัญในการยืดตัวของเซลล์พืชและกระจายตัวไปในส่วนที่ได้รับแสงน้อยกว่า ทำให้ด้านที่อยู่ในร่มเงาของลำต้นเติบโตเร็วกว่าและดันให้ลำต้นเอนไปทางแหล่งกำเนิดแสง ส่งผลให้ต้นทานตะวันสามารถหมุนตามดวงอาทิตย์ได้ตลอดวัน อย่างไรก็ตามเมื่อดอกทานตะวันโตเต็มที่และเริ่มออกดอกใหญ่ขึ้น การเคลื่อนไหวนี้ก็จะค่อย ๆ ลดลงและหันหน้าไปทางทิศตะวันออกเป็นหลัก เป็นเพราะช่วงเวลานี้ดอกทานตะวันมุ่งเน้นรับแสงอาทิตย์ในตอนเช้าเพื่อช่วยกระตุ้นกระบวนการสังเคราะห์แสง ดอกทานตะวันไม่ได้หันตามแสงอาทิตย์ตลอดไป แต่เลือกที่จะหันไปยังทิศทางที่ดีที่สุดสำหรับตัวมันเอง เช่นเดียวกับความรักที่ไม่ได้หมายถึงการตามหาใครสักคนไปตลอดชีวิต แต่เป็นการเติบโตไปด้วยกันและเลือกสิ่งที่เหมาะสมที่สุดเพื่อให้ความสัมพันธ์แข็งแรงและยั่งยืน ทั้งดอกทานตะวันและหัวใจของเราต่างต้องการแสงที่ทำให้เติบโตได้อย่างแท้จริง
ข้อใดคือใจความสำคัญของข้อความข้างต้น','["พฤติกรรมการหันตามแสงของดอกทานตะวัน", "ฮอร์โมนพืชที่ทำให้ดอกทานตะวันหันตามแสง", "ดอกทานตะวันจะลดการหันตามแสงเมื่อต้นเติบโตเต็มที่", "ดอกทานตะวันนิยมใช้เป็นสัญลักษณ์ของความรักและความมั่นคง", "การเติบโตที่ดีของดอกทานตะวันกับมนุษย์ต่างก็ต้องเลือกสิ่งที่เหมาะสม"]'::jsonb,4,array[4]::smallint[],'["ข้อความใช้ความรู้เรื่องทานตะวันหันตามแสงเป็นภาพเปรียบ แล้วสรุปว่า “เช่นเดียวกับความรัก… เลือกสิ่งที่เหมาะสมที่สุด” ใจความจึงอยู่ที่ทั้งทานตะวันและมนุษย์ต้องเลือกสิ่งที่เหมาะสมเพื่อเติบโต"]'::jsonb,'["เป็นข้อมูลส่วนต้น ไม่ใช่ใจความที่ผู้เขียนมุ่งสื่อ", "เป็นรายละเอียดทางวิทยาศาสตร์", "เป็นรายละเอียดส่วนกลาง", "ข้อความไม่ได้กล่าวถึงการใช้เป็นสัญลักษณ์", "ถูก ครอบคลุมทั้งภาพเปรียบ (ทานตะวัน) และสิ่งที่ถูกเปรียบ (มนุษย์/ความรัก)"]'::jsonb,'{"topic": "1.2", "n": 12}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'thai:69-12');
