insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-69-1','M6','M6-PH','M6-PH-S1','A-Level 64',null,2,'นักเรียนสองคนแข่งว่ายน้ำในสระความยาว 50 เมตร โดยอัตราเร็วของนักเรียนทั้งสองคนเปลี่ยนแปลงกับเวลาดังกราฟ จงหาว่าผู้ชนะจะแตะขอบสระก่อนผู้แพ้กี่วินาที','["ทั้งสองแตะขอบสระพร้อมกัน", "0.50", "2.8", "5.0", "6.3"]'::jsonb,3,array[3]::smallint[],'["ระยะทาง = พื้นที่ใต้กราฟ v–t · นักเรียน ก: 0–4 s ได้ ½(4)(2.0) = 4 m เหลือ 46 m ที่ 2.0 m/s ใช้ 23 s รวม 27 s · นักเรียน ข: 0–1.5 s ได้ ½(1.5)(1.6) = 1.2 m เหลือ 48.8 m ที่ 1.6 m/s ใช้ 30.5 s รวม 32 s · ก ชนะก่อน 32 − 27 = 5.0 s"]'::jsonb,'["ไม่ถูก ทั้งสองใช้เวลาต่างกัน (27 s กับ 32 s)", "ไม่ถูก ได้ถ้าเทียบเฉพาะช่วงเร่ง (4.0 − 1.5 = 2.5 s) หรือคิดพื้นที่ผิด", "ไม่ถูก ไม่ตรงกับผลต่างเวลา 32 − 27 = 5.0 s", "ถูก ก ใช้ 27 s ข ใช้ 32 s ต่างกัน 5.0 s", "ไม่ถูก ประมาณ 31.25 − 25 = 6.25 s ได้ถ้าลืมช่วงเร่งของทั้งคู่"]'::jsonb,'{"img": "phy-69-1.png", "topic": "1.2", "n": 1, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/phy-69-1.png"}'::jsonb,'imported_m6','imported',true,'numeric','Exam Gym ม.6 · 5620e4c',2569,'phy:69-1');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-69-2','M6','M6-PH','M6-PH-S1','A-Level 64',null,2,'ยิงวัตถุด้วยความเร็วต้น 12.0 เมตรต่อวินาที ในแนวทำมุม 53 องศา กับพื้นราบ พบว่าวัตถุเคลื่อนที่พ้นกล่องได้พอดี โดยความเร็วของวัตถุขณะเฉียดขอบกล่องทั้งสองครั้งมีทิศทำมุม 37 องศา กับแนวระดับ ดังรูป จงหาว่าวัตถุใช้เวลาเคลื่อนที่อยู่เหนือกล่องนานกี่วินาที (คำตอบติดตัวแปร g ขนาดของความเร่งเนื่องจากแรงโน้มถ่วงของโลก)','["10.8/g", "4.2/g", "1/g", "15/g", "2g"]'::jsonb,0,array[0]::smallint[],'["uₓ = 12.0 cos53° = 7.2 m/s (คงตัว) uᵧ = 12.0 sin53° = 9.6 m/s · ที่ขอบกล่อง vᵧ = ±uₓ tan37° = ±7.2 × 0.75 = ±5.4 m/s · เวลาเหนือกล่อง = [5.4 − (−5.4)]/g = 10.8/g"]'::jsonb,'["ถูก vᵧ เปลี่ยนจาก +5.4 เป็น −5.4 m/s ใช้เวลา 10.8/g", "ไม่ถูก ได้ถ้าใช้ผลต่าง 9.6 − 5.4 = 4.2 (เวลาจากจุดยิงถึงขอบกล่องแรก)", "ไม่ถูก ไม่สอดคล้องกับความเร็วแนวดิ่ง ±5.4 m/s ที่ขอบกล่อง", "ไม่ถูก ได้ถ้าใช้ vᵧ ที่ขอบกล่องเป็น 7.5 m/s (สลับ sin/cos)", "ไม่ถูก หน่วยไม่ใช่เวลา (เวลาต้องเป็นความเร็วหารด้วย g)"]'::jsonb,'{"img": "phy-69-2.png", "topic": "1.7", "n": 2, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/phy-69-2.png"}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'phy:69-2');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-69-3','M6','M6-PH','M6-PH-S1','A-Level 64',null,2,'สัมประสิทธิ์ความเสียดทานจลน์ระหว่างวัตถุชิ้นหนึ่งกับพื้นผิว A มีค่าเท่ากับ 0.30 เมื่อวัตถุกำลังเคลื่อนที่ด้วยความเร็วคงที่พบว่าใช้แรงดึงในแนวระดับเท่ากับ 8.0 นิวตัน ถ้าลากวัตถุชิ้นนี้บนพื้นผิว B ด้วยอัตราเร็วคงตัวพบว่าต้องออกแรง 12 นิวตัน จงหาสัมประสิทธิ์ความเสียดทานจลน์ระหว่างวัตถุชิ้นนี้กับพื้นผิว B','["0.45", "0.30", "0.15", "0.60", "0.90"]'::jsonb,0,array[0]::smallint[],'["ความเร็วคงตัว → แรงดึง = แรงเสียดทาน = μN โดย N เท่าเดิม · 8.0 = 0.30N → N = 26.7 N · μ_B = 12/26.7 = 0.45 (หรือ μ_B = 0.30 × 12/8.0)"]'::jsonb,'["ถูก μ_B = 0.30 × 12/8.0 = 0.45", "ไม่ถูก เป็นค่าของพื้นผิว A แต่พื้นผิว B ต้องใช้แรงมากกว่า", "ไม่ถูก ได้ถ้าคิดว่าแรงมากขึ้นแต่ μ ลดลง", "ไม่ถูก ได้ถ้าคูณ 2 แทนอัตราส่วน 12/8", "ไม่ถูก ได้ถ้าคูณ 0.30 ด้วย 3"]'::jsonb,'{"topic": "1.3", "n": 3}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'phy:69-3');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-69-4','M6','M6-PH','M6-PH-S1','A-Level 64',null,2,'อัดมวล 2.00 กิโลกรัมเข้ากับสปริงซึ่งวางตัวในแนวระดับ ทำให้สปริงหดสั้น 40.0 เซนติเมตร เมื่อปล่อยให้สปริงดีดตัวกลับและมวลหลุดออกจากสปริงที่จุดสมดุลของสปริง มวลเคลื่อนที่ผ่านพื้นที่มีแรงเสียดทานดังรูป และหยุดนิ่งพอดีที่ความสูง 3.00 เมตร ดังรูป หากค่าคงตัวของสปริงเท่ากับ 1,000 นิวตันต่อเมตร จงหางานเนื่องจากแรงเสียดทาน','["0 จูล", "21.2 จูล", "50.6 จูล", "58.8 จูล", "80.0 จูล"]'::jsonb,1,array[1]::smallint[],'["พลังงานศักย์ยืดหยุ่น ½kx² = ½(1,000)(0.400)² = 80.0 J · ที่จุดหยุด mgh = 2.00(9.8)(3.00) = 58.8 J · พลังงานที่เสียไปกับแรงเสียดทาน = 80.0 − 58.8 = 21.2 J (ความสูง 1.50 m เป็นข้อมูลระหว่างทาง ไม่ต้องใช้)"]'::jsonb,'["ไม่ถูก พื้นมีแรงเสียดทาน พลังงานกลจึงไม่คงตัว", "ถูก 80.0 − 58.8 = 21.2 J", "ไม่ถูก ได้ถ้าใช้ความสูง 1.50 m (80.0 − 29.4)", "ไม่ถูก เป็นพลังงานศักย์โน้มถ่วงที่จุดหยุด", "ไม่ถูก เป็นพลังงานในสปริงทั้งหมด"]'::jsonb,'{"img": "phy-69-4.png", "topic": "1.5", "n": 4, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/phy-69-4.png"}'::jsonb,'imported_m6','imported',true,'numeric','Exam Gym ม.6 · 5620e4c',2569,'phy:69-4');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-69-5','M6','M6-PH','M6-PH-S1','A-Level 64',null,2,'จากรูป แขวนมวล 10 กิโลกรัมเข้ากับระบบเชือกซึ่งแขวนติดกับเพดานและกำแพง จงหาว่าแรงตึงเชือก T มีค่าเท่ากับกี่นิวตัน','["98", "98/√3", "98√3", "100", "100/√3"]'::jsonb,0,array[0]::smallint[],'["ปมล่าง: น้ำหนัก 98 N ถูกเชือกสองเส้นทำมุม 60° กับแนวระดับรับไว้ 2T′ sin60° = 98 → T′ = 98/√3 N · ปมด้านข้าง (สมดุลแนวดิ่ง): T sin30° = T′ sin60° → T(½) = (98/√3)(√3/2) = 49 → T = 98 N"]'::jsonb,'["ถูก T = 98 N", "ไม่ถูก เป็นแรงตึงเชือกเส้นล่าง (T′) ไม่ใช่เส้น T", "ไม่ถูก ได้ถ้าสลับ sin กับ cos", "ไม่ถูก ได้ถ้าใช้ g = 10 m/s² (โจทย์ใช้ 9.8)", "ไม่ถูก ใช้ g = 10 และเป็นแรงตึงเส้นล่าง"]'::jsonb,'{"img": "phy-69-5.png", "topic": "1.4", "n": 5, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/phy-69-5.png"}'::jsonb,'imported_m6','imported',true,'numeric','Exam Gym ม.6 · 5620e4c',2569,'phy:69-5');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-69-6','M6','M6-PH','M6-PH-S1','A-Level 64',null,2,'ยิงลูกบอล A ด้วยความเร็ว 5.0 เมตรต่อวินาที ตามแกน x เข้าชนลูกบอล B ที่อยู่นิ่ง โดยลูกบอลทั้งสองมีมวลลูกละ 1.0 กิโลกรัม หลังชนลูกบอล A มีความเร็ว v_A เมตรต่อวินาที ทำมุม 37 องศา กับแกน x และลูกบอล B มีความเร็ว v_B เมตรต่อวินาที ทำมุม 53 องศากับแกน x ดังรูป จงหาว่าอัตราเร็ว v_A มีค่ากี่เมตรต่อวินาที','["1.5", "3.0", "4.0", "4.5", "6.0"]'::jsonb,2,array[2]::smallint[],'["อนุรักษ์โมเมนตัม 2 มิติ (มวลเท่ากัน) · แกน y: v_A sin37° = v_B sin53° → 0.6v_A = 0.8v_B · แกน x: 5.0 = 0.8v_A + 0.6v_B · แก้ได้ v_A = 4.0 m/s, v_B = 3.0 m/s"]'::jsonb,'["ไม่ถูก ไม่สอดคล้องกับสมการโมเมนตัม", "ไม่ถูก 3.0 m/s คือ v_B", "ถูก v_A = 4.0 m/s (v_B = 3.0 m/s)", "ไม่ถูก ได้ถ้าใช้ sin กับ cos สลับในบางแกน", "ไม่ถูก มากกว่าความเร็วต้น 5.0 m/s ขัดกับโมเมนตัมแกน x"]'::jsonb,'{"img": "phy-69-6.png", "topic": "1.6", "n": 6, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/phy-69-6.png"}'::jsonb,'imported_m6','imported',true,'numeric','Exam Gym ม.6 · 5620e4c',2569,'phy:69-6');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-69-7','M6','M6-PH','M6-PH-S1','A-Level 64',null,2,'วัตถุมวล m ผูกติดกับสปริงเบาวางอยู่บนพื้นราบลื่น วัตถุมีการสั่นกลับไปกลับมารอบจุดสมดุลด้วยความถี่เชิงมุม 2.0 เรเดียนต่อวินาที และมีแอมพลิจูด 1.2 เมตร พบว่าที่เวลา t = 0 วินาที วัตถุมีการกระจัดเท่ากับ +0.6 เมตร และกำลังเคลื่อนที่ไปทิศ +x จงหาอัตราเร็วของวัตถุในหน่วยเมตรต่อวินาที ที่เวลา t = π/12 วินาที','["2.4", "2.0", "1.8", "1.2", "0.6"]'::jsonb,3,array[3]::smallint[],'["x = A sin(ωt + φ) · ที่ t = 0: 0.6 = 1.2 sin φ และ v > 0 → φ = π/6 · ที่ t = π/12: เฟส = 2.0(π/12) + π/6 = π/3 · v = Aω cos(π/3) = 1.2(2.0)(½) = 1.2 m/s"]'::jsonb,'["ไม่ถูก 2.4 m/s คืออัตราเร็วสูงสุด (Aω) ที่จุดสมดุล", "ไม่ถูก ไม่ตรงกับเฟส π/3", "ไม่ถูก ไม่ตรงกับเฟส π/3", "ถูก v = Aω cos(π/3) = 1.2 m/s", "ไม่ถูก เป็นการกระจัดที่ t = 0 ไม่ใช่อัตราเร็ว"]'::jsonb,'{"topic": "1.8", "n": 7}'::jsonb,'imported_m6','imported',true,'numeric','Exam Gym ม.6 · 5620e4c',2569,'phy:69-7');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-69-8','M6','M6-PH','M6-PH-S1','A-Level 64',null,2,'ติดมวล 50 กรัมที่ปลายสปริงเบา ซึ่งมีค่าคงตัว 16 นิวตันต่อเมตร และมีความยาวปกติ 20 เซนติเมตร จากนั้นทำให้มวลเคลื่อนที่เป็นวงกลมบนพื้นลื่นในแนวระดับด้วยอัตราเร็วคงที่โดยปลายอีกด้านหนึ่งของสปริงถูกตรึงไว้ที่จุดศูนย์กลาง พบว่ารัศมีของการเคลื่อนที่มีค่าเท่ากับ 25 เซนติเมตร วัตถุมีอัตราเร็วกี่เมตรต่อวินาที','["0.8", "2.0", "3.2", "2√5", "4.0"]'::jsonb,1,array[1]::smallint[],'["แรงสปริงเป็นแรงสู่ศูนย์กลาง: k(r − L₀) = mv²/r → 16(0.05) = 0.050v²/0.25 → v² = 4 → v = 2.0 m/s"]'::jsonb,'["ไม่ถูก 0.8 N คือแรงสปริง ไม่ใช่อัตราเร็ว", "ถูก v = 2.0 m/s", "ไม่ถูก แทนกลับแล้ว mv²/r ไม่เท่ากับแรงสปริง 0.8 N", "ไม่ถูก ได้ถ้าใช้ระยะยืดเป็น 0.25 m (ทั้งรัศมี) แทน 0.05 m", "ไม่ถูก แทนกลับแล้ว mv²/r ≈ 2.0 N มากกว่าแรงสปริง 0.8 N"]'::jsonb,'{"topic": "1.7", "n": 8}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'phy:69-8');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-69-9','M6','M6-PH','M6-PH-S2','A-Level 64',null,2,'ที่เวลา t = 1.0 วินาที คลื่นอยู่ที่ตำแหน่งตามเส้นประ ต่อมาเมื่อ t = t₂ วินาที คลื่นอยู่ที่ตำแหน่งตามเส้นทึบ ดังรูป ถ้าความถี่ของคลื่นเท่ากับ 0.050 เฮิรตซ์ จงหาค่าที่เป็นไปได้ของ t₂','["9", "10", "11", "12", "13"]'::jsonb,2,array[2]::smallint[],'["จากกราฟ λ = 4 m และเส้นทึบเลื่อนจากเส้นประไป λ/2 (สันคลื่นจาก x = 1, 5 ไป x = 3, 7) ไม่ว่าคลื่นไปทางใด · คาบ T = 1/0.050 = 20 s → เวลาที่ผ่านไป = (n + ½)T = 10, 30, … s · t₂ = 1.0 + 10 = 11 s"]'::jsonb,'["ไม่ถูก t₂ ต้องมากกว่า 1.0 + 10 หรือเท่ากับ 11", "ไม่ถูก 10 s คือช่วงเวลาที่ผ่านไป ต้องบวกเวลาเริ่ม 1.0 s", "ถูก t₂ = 1.0 + T/2 = 11 s", "ไม่ถูก ช่วงเวลา 11 s ไม่ใช่ (n + ½)T (T = 20 s)", "ไม่ถูก ช่วงเวลา 12 s ไม่ใช่ (n + ½)T"]'::jsonb,'{"img": "phy-69-9.png", "topic": "2.1", "n": 9, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/phy-69-9.png"}'::jsonb,'imported_m6','imported',true,'numeric','Exam Gym ม.6 · 5620e4c',2569,'phy:69-9');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-69-10','M6','M6-PH','M6-PH-S2','A-Level 64',null,2,'ปล่อยเสียงจากแหล่งกำเนิดปรับความถี่ได้เข้าไปในท่อปลายปิด พบว่าความถี่ที่ทำให้เกิดการสั่นพ้อง เรียงจากน้อยสุดไปมาก คือ f₁, f₂, f₃, … ถ้าทราบว่า f₂ เท่ากับ 300 เฮิรตซ์ และอัตราเร็วเสียงในอากาศมีค่า 344 เมตรต่อวินาที ท่อนี้มีความยาวกี่เมตร','["0.29", "0.43", "0.57", "0.72", "0.86"]'::jsonb,4,array[4]::smallint[],'["ท่อปลายปิดสั่นพ้องเฉพาะฮาร์มอนิกคี่: f₁, 3f₁, 5f₁, … ความถี่ลำดับที่สองจึงเป็น 3f₁ = 300 Hz → f₁ = 100 Hz · L = v/(4f₁) = 344/400 = 0.86 m"]'::jsonb,'["ไม่ถูก ได้ถ้าใช้ L = v/(4f₂)", "ไม่ถูก ได้ถ้าคิดแบบท่อปลายเปิด f₂ = 2f₁ และใช้ v/(4f₁)", "ไม่ถูก ได้ถ้าคิดว่า f₂ = 2f₁ (ท่อปลายปิดไม่มีฮาร์มอนิกคู่)", "ไม่ถูก ได้ถ้าคิดว่า f₂ เป็นฮาร์มอนิกที่ 5/2", "ถูก f₁ = 100 Hz → L = 0.86 m"]'::jsonb,'{"topic": "2.2", "n": 10}'::jsonb,'imported_m6','imported',true,'numeric','Exam Gym ม.6 · 5620e4c',2569,'phy:69-10');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-69-11','M6','M6-PH','M6-PH-S2','A-Level 64',null,2,'แหล่งกำเนิดเสียงแหล่งหนึ่งให้คลื่นเสียงสม่ำเสมอในทุกทิศทาง พบว่าระดับความเข้มเสียงที่จุด A มีค่าสูงกว่าระดับความเข้มเสียงที่จุด B อยู่ 20 เดซิเบล ถ้าจุด A อยู่ห่างจากแหล่งกำเนิดเสียงเป็นระยะ 4.0 เมตร จงหาว่าจุด B อยู่ห่างจากแหล่งกำเนิดเสียงกี่เมตร','["40", "10", "20", "8", "16"]'::jsonb,0,array[0]::smallint[],'["ต่างกัน 20 dB → I_A/I_B = 10² = 100 · I ∝ 1/r² → r_B/r_A = √100 = 10 → r_B = 40 m"]'::jsonb,'["ถูก r_B = 10 × 4.0 = 40 m", "ไม่ถูก 10 คืออัตราส่วนระยะ ไม่ใช่ระยะ", "ไม่ถูก ได้ถ้าคิดว่าระดับเสียงแปรผันตรงกับระยะ", "ไม่ถูก ระยะเพิ่ม 2 เท่า ความเข้มลดเพียง 4 เท่า (≈ 6 dB) ไม่ใช่ 20 dB", "ไม่ถูก ระยะเพิ่ม 4 เท่า ความเข้มลด 16 เท่า (≈ 12 dB) ไม่ใช่ 20 dB"]'::jsonb,'{"topic": "2.2", "n": 11}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'phy:69-11');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-69-12','M6','M6-PH','M6-PH-S2','A-Level 64',null,2,'วางวัตถุที่ระยะ 20 เซนติเมตร หน้าเลนส์บางที่มีสมบัติกระจายแสง จะเกิดภาพเสมือนฝั่งเดียวกับวัตถุ ห่างจากเลนส์ 12 เซนติเมตร หากนำเลนส์บางที่มีสมบัติรวมแสงความยาวโฟกัส 20 เซนติเมตร มาวางประกบติดกับเลนส์อันแรกเพื่อทำเป็นเลนส์ประกอบ ถ้าวางวัตถุที่ระยะเดิมจากเลนส์ประกอบนี้จงหาว่าภาพที่เกิดจากเลนส์ประกอบเป็นภาพจริงหรือภาพเสมือน และอยู่ห่างจากเลนส์ประกอบกี่เซนติเมตร','["ภาพเสมือน, 15", "ภาพจริง, 15", "ภาพเสมือน, 30", "ภาพจริง, 30", "ภาพจริง, 60"]'::jsonb,2,array[2]::smallint[],'["เลนส์เว้า: 1/f₁ = 1/20 + 1/(−12) → f₁ = −30 cm · เลนส์ประกบ: 1/F = 1/20 − 1/30 = 1/60 → F = +60 cm · วัตถุ 20 cm (อยู่ในระยะโฟกัส): 1/v = 1/60 − 1/20 = −1/30 → v = −30 cm เป็นภาพเสมือน ห่าง 30 cm"]'::jsonb,'["ไม่ถูก ระยะภาพไม่ถูกต้อง", "ไม่ถูก วัตถุอยู่ใกล้กว่าโฟกัสของเลนส์ประกอบ (60 cm) จึงได้ภาพเสมือน", "ถูก ภาพเสมือน ห่าง 30 cm", "ไม่ถูก ระยะถูกแต่เครื่องหมายผิด v = −30 cm คือภาพเสมือน", "ไม่ถูก 60 cm คือความยาวโฟกัสของเลนส์ประกอบ ไม่ใช่ระยะภาพ"]'::jsonb,'{"topic": "2.3", "n": 12}'::jsonb,'imported_m6','imported',true,'figure','Exam Gym ม.6 · 5620e4c',2569,'phy:69-12');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-69-13','M6','M6-PH','M6-PH-S2','A-Level 64',null,2,'ผู้สังเกตที่อยู่นิ่งวัดความถี่เสียงไซเรนจากรถพยาบาลที่กำลังวิ่งตรงเข้าหาเขาได้ 700 เฮิรตซ์ ต่อมาขณะรถพยาบาลกำลังวิ่งห่างออกไป เขาวัดความถี่เสียงไซเรนได้ 580 เฮิรตซ์ อัตราส่วนของอัตราเร็วรถพยาบาลต่ออัตราเร็วเสียงในอากาศมีค่าเท่ากับข้อใด','["1/13", "2/29", "3/32", "4/29", "5/12"]'::jsonb,2,array[2]::smallint[],'["ดอปเพลอร์ (แหล่งกำเนิดเคลื่อนที่): f_เข้า = fv/(v − u), f_ออก = fv/(v + u) · 700/580 = (v + u)/(v − u) → 35(v − u) = 29(v + u) → 6v = 64u → u/v = 3/32"]'::jsonb,'["ไม่ถูก แทนกลับแล้วอัตราส่วนความถี่ (14/12) ไม่เท่ากับ 700/580", "ไม่ถูก แทนกลับแล้วอัตราส่วนความถี่ไม่เท่ากับ 700/580", "ถูก u/v = 6/64 = 3/32", "ไม่ถูก แทนกลับแล้วอัตราส่วนความถี่ (33/25) ไม่เท่ากับ 700/580", "ไม่ถูก ค่ามากเกินจริงสำหรับรถยนต์"]'::jsonb,'{"topic": "2.2", "n": 13}'::jsonb,'imported_m6','imported',true,'numeric','Exam Gym ม.6 · 5620e4c',2569,'phy:69-13');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-69-14','M6','M6-PH','M6-PH-S3','A-Level 64',null,2,'ประจุ q, q, Q วางอยู่ตามตำแหน่งดังรูป หากต้องการนำประจุ q อีกตัวหนึ่งจากระยะอนันต์มาวางที่ตำแหน่ง A จะต้องทำงานอย่างน้อยเท่าใด','["(kq/√2d)(√2Q + 2q)", "(kq/√2d)(Q + q + √2q)", "(kq/d)(Q + q)", "(kq/2d)(√2Q + 2q)", "(kq/2d)(2Q + q + √2q)"]'::jsonb,4,array[4]::smallint[],'["W = qV_A · ระยะจาก A: Q ห่าง d, q ซ้ายห่าง 2d, q บนห่าง √2d · V_A = kQ/d + kq/2d + kq/√2d · W = (kq/2d)(2Q + q + √2q)"]'::jsonb,'["ไม่ถูก ใช้ระยะของประจุบางตัวผิด", "ไม่ถูก ใช้ระยะ √2d กับทุกประจุ", "ไม่ถูก ลืมว่าประจุ q ทั้งสองอยู่ห่างจาก A ไม่เท่า d", "ไม่ถูก ใช้ระยะของ Q เป็น √2d ผิด", "ถูก W = kq(Q/d + q/2d + q/√2d) = (kq/2d)(2Q + q + √2q)"]'::jsonb,'{"img": "phy-69-14.png", "topic": "3.1", "n": 14, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/phy-69-14.png"}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'phy:69-14');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-69-15','M6','M6-PH','M6-PH-S3','A-Level 64',null,2,'จุด A และ B อยู่ห่างกันเป็นระยะ L ในบริเวณที่มีสนามไฟฟ้าสม่ำเสมอขนาด E โดยทิศของสนามไฟฟ้าทำมุม θ กับแนวเส้นตรง AB ดังรูป มีแรง F ลากจุดประจุ q มวล m จากหยุดนิ่งที่ B ไปยังจุด A พบว่าประจุมีอัตราเร็ว v','["−qEL − mv²/2", "+qEL cos θ − mv²/2", "−qEL cos θ + mv²/2", "+qEL cos θ + mv²/2", "−qEL sin θ + mv²/2"]'::jsonb,3,array[3]::smallint[],'["ทฤษฎีงาน–พลังงาน: W_F + W_E = ½mv² · B→A สวนทางองค์ประกอบสนามตามแนว AB: W_E = −qEL cos θ · W_F = ½mv² + qEL cos θ"]'::jsonb,'["ไม่ถูก งานต้องให้พลังงานจลน์เพิ่ม (+mv²/2) และสนามมีผลเพียง E cos θ ตามแนว AB", "ไม่ถูก เครื่องหมายของพลังงานจลน์ผิด", "ไม่ถูก นี่คือเครื่องหมายของงานจากสนามไฟฟ้ากลับข้าง (แรง F ต้องเอาชนะสนาม จึงเป็น +qEL cos θ)", "ถูก W_F = qEL cos θ + mv²/2", "ไม่ถูก องค์ประกอบตามแนว AB ใช้ cos θ ไม่ใช่ sin θ"]'::jsonb,'{"img": "phy-69-15.png", "after": "งานที่แรง F ทำเท่ากับข้อใด", "topic": "3.1", "n": 15, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/phy-69-15.png"}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'phy:69-15');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-69-16','M6','M6-PH','M6-PH-S3','A-Level 64',null,2,'เมื่อนำตัวต้านทาน R มาต่อกับเซลล์ไฟฟ้าหนึ่ง พบว่ามีกระแส I₀ ไหลผ่านตัวต้านทาน และเมื่อนำตัวต้านทาน R อีกตัวหนึ่งมาต่อขนานกับตัวต้านทานนี้ พบว่ามีกระแส I ไหลผ่านตัวต้านทานตัวแรก ค่าความต้านทานภายในของเซลล์ไฟฟ้าเป็นเท่าใด','["R", "R(2I − I₀)/(I₀ − I)", "R(I₀ − I)/(2I₀ − I)", "R(I − I₀)/(2I − I₀)", "R(I₀ − I)/(2I − I₀)"]'::jsonb,4,array[4]::smallint[],'["E = I₀(R + r) · ต่อขนานแล้วกระแสรวม 2I: E = IR + 2Ir · I₀R + I₀r = IR + 2Ir → r(2I − I₀) = R(I₀ − I) → r = R(I₀ − I)/(2I − I₀)"]'::jsonb,'["ไม่ถูก จะเป็นจริงเฉพาะกรณีพิเศษเท่านั้น", "ไม่ถูก กลับเศษกับส่วน", "ไม่ถูก ใช้กระแสรวมผิด (2I₀ แทน 2I)", "ไม่ถูก เครื่องหมายเศษกลับ ได้ค่าลบ", "ถูก r = R(I₀ − I)/(2I − I₀)"]'::jsonb,'{"topic": "3.2", "n": 16}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'phy:69-16');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-69-17','M6','M6-PH','M6-PH-S3','A-Level 64',null,2,'เร่งอิเล็กตรอนมวล m ประจุ e จากหยุดนิ่งเข้าไปในบริเวณที่มีสนามแม่เหล็กสม่ำเสมอ B และความเร็วตั้งฉากกับสนามแม่เหล็ก ทำให้อิเล็กตรอนเคลื่อนที่เป็นวงกลมที่มีรัศมี R จะต้องใช้ความต่างศักย์เท่าใดในการเร่งอิเล็กตรอน','["meB²/R²", "2m/(eB²R²)", "2m/(BRe)", "eBR/(2m)", "eB²R²/(2m)"]'::jsonb,4,array[4]::smallint[],'["วงกลมในสนามแม่เหล็ก R = mv/(eB) → v = eBR/m · เร่งด้วยความต่างศักย์ eV = ½mv² = e²B²R²/(2m) → V = eB²R²/(2m)"]'::jsonb,'["ไม่ถูก มิติไม่ใช่ความต่างศักย์", "ไม่ถูก เป็นส่วนกลับของคำตอบ", "ไม่ถูก สูตรไม่สอดคล้องกับ R = mv/eB", "ไม่ถูก ลืมยกกำลังสองของ BR (เป็นครึ่งหนึ่งของ v)", "ถูก V = eB²R²/(2m)"]'::jsonb,'{"topic": "3.3", "n": 17}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'phy:69-17');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-69-18','M6','M6-PH','M6-PH-S3','A-Level 64',null,2,'ลวดโลหะเส้นหนึ่งยาว l หากนำไปต่อกับความต่างศักย์ V₀ จะมีความเร็วลอยเลื่อน u หากเพิ่มความยาวลวดเป็นสองเท่าโดยความต่างศักย์เท่าเดิม ความเร็วลอยเลื่อนของอิเล็กตรอนในโลหะนี้จะเป็นเท่าใด','["เท่าเดิม", "2u", "u/2", "4u", "u/4"]'::jsonb,2,array[2]::smallint[],'["R = ρl/A ยาวขึ้น 2 เท่า (พื้นที่หน้าตัดเท่าเดิม) R เพิ่ม 2 เท่า → I = V₀/R ลดครึ่ง · I = nAeu → u ลดเหลือ u/2"]'::jsonb,'["ไม่ถูก กระแสลดลง ความเร็วลอยเลื่อนจึงลดลง", "ไม่ถูก ทิศของการเปลี่ยนแปลงกลับกัน", "ถูก u ∝ I ∝ 1/l จึงเหลือ u/2", "ไม่ถูก ไม่สอดคล้องกับ I = V/R", "ไม่ถูก ได้ถ้าคิดว่าพื้นที่หน้าตัดลดลงครึ่งหนึ่งด้วย (ลวดถูกดึงยืด) ซึ่งโจทย์ไม่ได้กล่าว"]'::jsonb,'{"topic": "3.2", "n": 18}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'phy:69-18');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-69-19','M6','M6-PH','M6-PH-S3','A-Level 64',null,2,'ขดลวดตัวนำมีพื้นที่ 100 ตารางเซนติเมตร มีสนามแม่เหล็กทะลุตั้งฉากกับระนาบขดลวด โดยสนามแม่เหล็กที่เวลาเริ่มต้นมีขนาด 0.60 เทสลา เมื่อเวลาผ่านไป 2.0 วินาที ขนาดของสนามแม่เหล็กลดลงเป็น 0.54 เทสลา โดยไม่เปลี่ยนทิศ ถ้าขนาดของสนามแม่เหล็กลดด้วยอัตราคงที่ ค่าอีเอ็มเอฟเหนี่ยวนำในขดลวดมีขนาดกี่โวลต์','["3.0 × 10⁻⁴", "6.0 × 10⁻⁴", "1.2 × 10⁻³", "1.2", "3.0"]'::jsonb,0,array[0]::smallint[],'["ℰ = A ΔB/Δt = (100 × 10⁻⁴ m²)(0.06 T)/(2.0 s) = 3.0 × 10⁻⁴ V"]'::jsonb,'["ถูก ℰ = 0.01 × 0.03 = 3.0 × 10⁻⁴ V", "ไม่ถูก ลืมหารด้วยเวลา 2.0 s", "ไม่ถูก ได้ถ้าคูณเวลาแทนการหาร", "ไม่ถูก ใช้ค่า B ไม่ใช่การเปลี่ยนแปลง หรือลืมแปลงหน่วยพื้นที่", "ไม่ถูก ลืมแปลง cm² เป็น m²"]'::jsonb,'{"topic": "3.3", "n": 19}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'phy:69-19');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-69-20','M6','M6-PH','M6-PH-S3','A-Level 64',null,2,'ชาร์จตัวเก็บประจุที่มีค่าความจุ C ด้วยความต่างศักย์ V จนเต็ม แล้วนำตัวเก็บประจุออกไปต่อขนานกับตัวเก็บประจุอีก 2 ตัวที่มีความจุ 2C และ 3C จนได้ตัวเก็บประจุสามตัวต่อขนานกัน จงหาค่าพลังงานสะสมรวมในตัวเก็บประจุทั้งสาม','["(1/12)CV²", "(1/6)CV²", "(1/2)CV²", "(11/12)CV²", "(11/6)CV²"]'::jsonb,0,array[0]::smallint[],'["ประจุคงตัว Q = CV กระจายไปยังความจุรวม 6C → V′ = V/6 · U = ½(6C)(V/6)² = CV²/12 (พลังงานส่วนที่เหลือเสียไปขณะประจุไหล)"]'::jsonb,'["ถูก U = Q²/(2 × 6C) = CV²/12", "ไม่ถูก ได้ถ้าคิดว่า U = Q²/(6C)", "ไม่ถูก เป็นพลังงานเริ่มต้นของตัวเก็บประจุ C พลังงานไม่คงตัวเมื่อต่อขนาน", "ไม่ถูก เป็นพลังงานที่เสียไป (½ − 1/12 = 5/12) คิดผิดอีกขั้น", "ไม่ถูก มากกว่าพลังงานเริ่มต้น เป็นไปไม่ได้"]'::jsonb,'{"topic": "3.1", "n": 20}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'phy:69-20');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-69-21','M6','M6-PH','M6-PH-S4','A-Level 64',null,2,'แก๊สอะตอมเดี่ยว A มีมวล m กิโลกรัมต่ออะตอม มีอัตราเร็วอาร์เอ็มเอส v_rms = u แก๊สอะตอมเดี่ยว B มีมวล M กิโลกรัมต่อโมล อยู่ในสภาวะเดียวกันกับแก๊ส A อัตราเร็วอาร์เอ็มเอสของแก๊ส B จะมีค่าเท่าใด กำหนดให้แก๊สทั้งสองเป็นแก๊สอุดมคติ','["u", "u√(m/M)", "u(m/M)", "u(mR/(Mk_B))", "u√(mR/(Mk_B))"]'::jsonb,4,array[4]::smallint[],'["v_rms = √(3k_BT/m) = √(3RT/M) · อุณหภูมิเดียวกัน: v_B/u = √[(RT/M)/(k_BT/m)] = √(mR/(Mk_B)) (m ต่ออะตอม แต่ M ต่อโมล จึงต้องใช้ R/k_B = N_A แปลงหน่วย)"]'::jsonb,'["ไม่ถูก มวลอนุภาคต่างกัน อัตราเร็วจึงต่างกัน", "ไม่ถูก ลืมว่า m เป็นมวลต่ออะตอมแต่ M เป็นมวลต่อโมล", "ไม่ถูก ขาดรากที่สอง และหน่วยมวลไม่สอดคล้อง", "ไม่ถูก ขาดรากที่สอง (v_rms ∝ 1/√มวล)", "ถูก v_B = u√(mR/(Mk_B))"]'::jsonb,'{"topic": "4.1", "n": 21}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'phy:69-21');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-69-22','M6','M6-PH','M6-PH-S4','A-Level 64',null,2,'กล่องมวล m วางทับกล่องมวล M ที่ลอยอยู่ในของเหลวความหนาแน่น ρ₀ พบว่ากล่องทั้งสองลอยอยู่นิ่งโดยปริมาตร 40% ของกล่อง M อยู่เหนือผิวของเหลว เมื่อนำกล่อง m ออก ปริมาตรของกล่อง M ที่อยู่เหนือผิวของเหลวจะเป็นเท่าใด','["(2m + 5M)/(3ρ₀)", "(3m + 2M)/(5ρ₀)", "(3m + 5M)/(2ρ₀)", "(5m + 2M)/(3ρ₀)", "(5m + 3M)/(2ρ₀)"]'::jsonb,3,array[3]::smallint[],'["มีกล่อง m: แรงลอยตัว ρ₀(0.6V)g = (m + M)g → V = 5(m + M)/(3ρ₀) · ไม่มี m: ปริมาตรจม = M/ρ₀ · เหนือผิว = V − M/ρ₀ = (5m + 2M)/(3ρ₀)"]'::jsonb,'["ไม่ถูก สลับสัมประสิทธิ์ของ m กับ M", "ไม่ถูก ได้ถ้าใช้ 40% เป็นส่วนที่จม", "ไม่ถูก ไม่สอดคล้องกับสมดุลแรงลอยตัว", "ถูก V_เหนือผิว = (5m + 2M)/(3ρ₀)", "ไม่ถูก ไม่สอดคล้องกับสมดุลแรงลอยตัว"]'::jsonb,'{"topic": "4.2", "n": 22}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'phy:69-22');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-69-23','M6','M6-PH','M6-PH-S4','A-Level 64',null,2,'ลวดโลหะมีมอดูลัสของยัง Y และมีพื้นที่หน้าตัด A เมื่อนำมวล M มาแขวนที่ปลายลวด พบว่าลวดมีความยาวเป็น L หากนำมวล m มาแขวนเพิ่ม ลวดจะยืดออกเพิ่มขึ้นเท่าใด','["MgL/(mg + YA)", "MgL/(Mg + YA)", "mgL/(YA)", "mgL/(mg + YA)", "mgL/(Mg + YA)"]'::jsonb,4,array[4]::smallint[],'["L เป็นความยาวขณะแขวน M แล้ว ความยาวเดิม L₀: L = L₀(1 + Mg/YA) → L₀ = LYA/(YA + Mg) · ยืดเพิ่ม ΔL = mgL₀/(YA) = mgL/(Mg + YA)"]'::jsonb,'["ไม่ถูก ใช้มวลสลับกัน", "ไม่ถูก เป็นระยะที่ลวดยืดเพราะ M (L − L₀) ไม่ใช่ส่วนที่เพิ่ม", "ไม่ถูก ใช้ L เป็นความยาวเดิม ซึ่ง L ยืดแล้ว", "ไม่ถูก ใช้มวลในตัวส่วนผิด", "ถูก ΔL = mgL/(Mg + YA)"]'::jsonb,'{"topic": "4.2", "n": 23}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'phy:69-23');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-69-24','M6','M6-PH','M6-PH-S5','A-Level 64',null,2,'เมื่อฉายแสงความยาวคลื่น λ₀ ลงบนโลหะชนิดหนึ่งที่มีค่าฟังก์ชันงาน W พบว่าเกิดโฟโตอิเล็กตรอนหลุดออกมาจากโลหะนี้ จงหาความยาวคลื่นเดอบรอยล์ของโฟโตอิเล็กตรอนที่มีพลังงานจลน์สูงสุด
(กำหนดให้อิเล็กตรอนมีมวล m และเคลื่อนที่แบบไม่สัมพัทธภาพ)','["h√(λ₀/(2mhc))", "h√(1/(2mW))", "h√(λ₀/(2m(hc − λ₀W)))", "h√(λ₀/(2m(hc + λ₀W)))", "λ₀"]'::jsonb,2,array[2]::smallint[],'["E_k,max = hc/λ₀ − W = (hc − λ₀W)/λ₀ · p = √(2mE_k) · λ = h/p = h√(λ₀/(2m(hc − λ₀W)))"]'::jsonb,'["ไม่ถูก ลืมหักฟังก์ชันงาน", "ไม่ถูก ใช้ฟังก์ชันงานเป็นพลังงานจลน์", "ถูก λ = h/√(2mE_k) กับ E_k = hc/λ₀ − W", "ไม่ถูก บวกฟังก์ชันงานแทนการลบ", "ไม่ถูก ความยาวคลื่นของอิเล็กตรอนไม่เท่ากับของแสง"]'::jsonb,'{"topic": "5.1", "n": 24}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'phy:69-24');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-69-25','M6','M6-PH','M6-PH-S5','A-Level 64',null,2,'ธาตุ X มีครึ่งชีวิต Tₓ และมีจำนวนอะตอมแรกเริ่ม N₀ เมื่อเวลาผ่านไป τ ธาตุ X จะมีค่ากัมมันตภาพเป็นเท่าใด','["(N₀ ln2/τ)(½)^(τ/Tₓ)", "(N₀ ln2/Tₓ)·2^(τ/Tₓ)", "(N₀ ln2/Tₓ)(½)^(τ/Tₓ)", "(N₀/τ)·2^(τ/Tₓ)", "(N₀/Tₓ)(½)^(τ/Tₓ)"]'::jsonb,2,array[2]::smallint[],'["กัมมันตภาพ A = λN โดย λ = ln2/Tₓ และ N = N₀(½)^(τ/Tₓ) → A = (N₀ ln2/Tₓ)(½)^(τ/Tₓ)"]'::jsonb,'["ไม่ถูก ค่าคงตัวการสลายต้องใช้ครึ่งชีวิต Tₓ ไม่ใช่เวลา τ", "ไม่ถูก ทำให้กัมมันตภาพเพิ่มขึ้นตามเวลา ซึ่งผิด", "ถูก A = λN = (ln2/Tₓ)N₀(½)^(τ/Tₓ)", "ไม่ถูก ขาด ln2 และเพิ่มขึ้นตามเวลา", "ไม่ถูก ขาด ln2 ในค่าคงตัวการสลาย"]'::jsonb,'{"topic": "5.2", "n": 25}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'phy:69-25');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-68-1','M6','M6-PH','M6-PH-S1','A-Level 64',null,2,'วัตถุเคลื่อนที่ในแนวตรงไปข้างหน้าเป็นเวลา 10.0 วินาที ได้ระยะทาง 75.0 เมตร และขณะนั้นอัตราเร็วมีค่า 2.0 เมตรต่อวินาที โดยตลอดช่วงการเคลื่อนที่นี้ วัตถุเคลื่อนที่ช้าลงด้วยความเร่งคงตัว
คำถาม ขนาดความเร่งของวัตถุมีค่ากี่เมตรต่อวินาที²','["0.7", "0.9", "1.1", "1.3", "1.5"]'::jsonb,2,array[2]::smallint[],'["ความเร่งคงตัว: s = (u + v)t/2 → 75.0 = (u + 2.0)(10.0)/2 ได้ u = 13.0 m/s แล้ว a = (v − u)/t = (2.0 − 13.0)/10.0 = −1.1 m/s² ขนาด 1.1 m/s²"]'::jsonb,'["ได้ถ้าใช้ระยะทางหารเวลากำลังสองแบบผิด ๆ (ไม่ใช่สูตรความเร่งคงตัว)", "ไม่ถูก ลองแทนกลับ: u = v + at จะไม่ให้ระยะทาง 75.0 m", "ถูก u = 13.0 m/s และ a = −1.1 m/s² (ช้าลง)", "ไม่ถูก ค่ามากเกินไป ระยะทางจะไม่ใช่ 75.0 m", "ได้ถ้าคิดว่า s = vt + ½at² โดยใช้เครื่องหมายผิด"]'::jsonb,'{"topic": "1.2", "n": 1}'::jsonb,'imported_m6','imported',true,'numeric','Exam Gym ม.6 · 5620e4c',2568,'phy:68-1');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-68-2','M6','M6-PH','M6-PH-S1','A-Level 64',null,2,'ปาก้อนหินออกไปในแนวระดับด้วยอัตราเร็ว 12.3 เมตรต่อวินาที จากจุดที่อยู่สูงจากพื้น 44.1 เมตร หากไม่พิจารณาแรงต้านของอากาศ
คำถาม ก้อนหินตกกระทบพื้นห่างจากจุดปาในแนวระดับกี่เมตร','["19.6", "24.6", "29.4", "36.9", "44.1"]'::jsonb,3,array[3]::smallint[],'["โพรเจกไทล์แนวระดับ: แนวดิ่ง 44.1 = ½(9.8)t² → t = 3.0 s · แนวระดับความเร็วคงตัว x = 12.3 × 3.0 = 36.9 m"]'::jsonb,'["ไม่ถูก เป็นค่า ½gt² ที่ t = 2 s", "ไม่ถูก เท่ากับ 12.3 × 2 (ใช้เวลาผิด)", "ไม่ถูก เป็นความเร็วแนวดิ่งขณะถึงพื้น (gt = 29.4 m/s) ไม่ใช่ระยะ", "ถูก x = uₓt = 12.3 × 3.0 = 36.9 m", "ไม่ถูก เป็นความสูงของจุดปา ไม่ใช่ระยะแนวระดับ"]'::jsonb,'{"topic": "1.7", "n": 2}'::jsonb,'imported_m6','imported',true,'numeric','Exam Gym ม.6 · 5620e4c',2568,'phy:68-2');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-68-3','M6','M6-PH','M6-PH-S1','A-Level 64',null,2,'วัตถุมวล 0.50 กิโลกรัม เริ่มเคลื่อนที่จากหยุดนิ่งด้วยความเร่งคงตัวลงมาตามแนวพื้นเอียง ซึ่งทำมุม 37 องศากับแนวระดับ
กำหนดให้ สัมประสิทธิ์ความเสียดทานจลน์ระหว่างวัตถุและพื้นเอียงมีค่า 0.50
คำถาม หลังจากเคลื่อนที่เป็นเวลา 2.50 วินาที อัตราเร็วของวัตถุจะมีค่ากี่เมตรต่อวินาที','["0.98", "1.96", "2.94", "3.92", "4.90"]'::jsonb,4,array[4]::smallint[],'["ตามพื้นเอียง: ma = mg sin37° − μmg cos37° → a = 9.8(0.6 − 0.5 × 0.8) = 1.96 m/s² · v = at = 1.96 × 2.50 = 4.90 m/s (ไม่ขึ้นกับมวล)"]'::jsonb,'["ไม่ถูก คิดเวลาเพียงครึ่งเดียว", "ไม่ถูก เป็นค่าความเร่ง a ไม่ใช่อัตราเร็ว", "ไม่ถูก ได้ถ้าคูณเวลา 1.5 s", "ไม่ถูก ได้ถ้าคูณเวลา 2.0 s", "ถูก v = at = 1.96 × 2.50 = 4.90 m/s"]'::jsonb,'{"topic": "1.3", "n": 3}'::jsonb,'imported_m6','imported',true,'numeric','Exam Gym ม.6 · 5620e4c',2568,'phy:68-3');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-68-4','M6','M6-PH','M6-PH-S1','A-Level 64',null,2,'แรงไม่คงตัวกระทำต่อวัตถุมวล 1.0 กิโลกรัม ให้เคลื่อนที่ไปตามแนวแรงเป็นเส้นตรงจากตำแหน่ง x = 0 ถึง x = 8.0 เมตร ดังรูป','["0", "1.0", "3.0", "5.0", "7.0"]'::jsonb,4,array[4]::smallint[],'["งาน = พื้นที่ใต้กราฟ F–x: สามเหลี่ยม 0–4 m = ½(4)(4) = 8 J, ช่วง 4–5 m = 0, ช่วง 5–6 m = ½(1)(5) = 2.5 J, ช่วง 6–8 m = 5 × 2 = 10 J รวม 20.5 J · Eₖ = 4.0 + 20.5 = 24.5 J = ½(1.0)v² → v = 7.0 m/s"]'::jsonb,'["ไม่ถูก แรงทำงานบวกตลอด วัตถุไม่หยุด", "ไม่ถูก ใช้พลังงานจลน์เริ่มต้นผิด", "ไม่ถูก เป็นอัตราเร็วเริ่มต้นโดยประมาณ (Eₖ 4 J → v ≈ 2.8 m/s) ยังไม่รวมงาน", "ไม่ถูก ได้ถ้าลืมพื้นที่บางช่วง", "ถูก Eₖ = 24.5 J จึงได้ v = 7.0 m/s"]'::jsonb,'{"img": "phy-68-4.png", "after": "ถ้า ณ ตำแหน่ง x = 0 เมตร วัตถุมีพลังงานจลน์เท่ากับ 4.0 จูล\nคำถาม อัตราเร็วของวัตถุขณะอยู่ที่ตำแหน่ง x = 8.0 เมตร จะมีค่ากี่เมตรต่อวินาที", "topic": "1.5", "n": 4, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/phy-68-4.png"}'::jsonb,'imported_m6','imported',true,'numeric','Exam Gym ม.6 · 5620e4c',2568,'phy:68-4');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-68-5','M6','M6-PH','M6-PH-S1','A-Level 64',null,2,'ไม้เมตรสม่ำเสมอมวล 0.20 กิโลกรัม ถูกตรึงที่ตำแหน่ง 40 เซนติเมตร และแขวนวัตถุมวล 0.30 กิโลกรัม ที่ตำแหน่ง 80 เซนติเมตร ของไม้เมตร
คำถาม ถ้าไม่ต้องการให้ไม้เมตรนี้หมุน จะต้องแขวนวัตถุมวลกี่กิโลกรัม ที่ตำแหน่ง 20 เซนติเมตร ของไม้เมตร','["0.30", "0.40", "0.50", "0.60", "0.70"]'::jsonb,4,array[4]::smallint[],'["โมเมนต์รอบจุดตรึง 40 cm: ทางขวามีน้ำหนักไม้ที่ 50 cm (0.20 × 10) และมวล 0.30 kg ที่ 80 cm (0.30 × 40) รวม 14 หน่วย ทางซ้าย m × 20 = 14 → m = 0.70 kg"]'::jsonb,'["ไม่ถูก ลืมโมเมนต์ของน้ำหนักไม้เมตร", "ไม่ถูก ค่ายังไม่สมดุล", "ไม่ถูก ค่ายังไม่สมดุล", "ไม่ถูก ได้ถ้าลืมน้ำหนักไม้เมตร (0.30 × 40/20)", "ถูก m = (0.20 × 10 + 0.30 × 40)/20 = 0.70 kg"]'::jsonb,'{"topic": "1.4", "n": 5}'::jsonb,'imported_m6','imported',true,'numeric','Exam Gym ม.6 · 5620e4c',2568,'phy:68-5');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-68-6','M6','M6-PH','M6-PH-S1','A-Level 64',null,2,'วัตถุ A มวล 1.0 กิโลกรัม เคลื่อนที่ไปทางขวาด้วยความเร็ว 5.0 เมตรต่อวินาที เข้าชนในแนวตรงกับวัตถุ B มวล 2.0 กิโลกรัม ซึ่งอยู่นิ่ง หลังการชนพบว่าวัตถุ A กระดอนกลับไปทางซ้ายด้วยความเร็ว 1.0 เมตรต่อวินาที
คำถาม พลังงานจลน์ของระบบเปลี่ยนแปลงอย่างไร','["ไม่มีการเปลี่ยนแปลง", "เพิ่มขึ้น 3.0 จูล", "เพิ่มขึ้น 9.5 จูล", "ลดลง 3.0 จูล", "ลดลง 9.5 จูล"]'::jsonb,3,array[3]::smallint[],'["อนุรักษ์โมเมนตัม: 1.0(5.0) = 1.0(−1.0) + 2.0v → v_B = 3.0 m/s · Eₖ ก่อน = ½(1)(25) = 12.5 J หลัง = ½(1)(1) + ½(2)(9) = 9.5 J จึงลดลง 3.0 J"]'::jsonb,'["ไม่ถูก การชนนี้ไม่ยืดหยุ่น Eₖ ไม่คงตัว", "ไม่ถูก การชนโดยไม่มีแหล่งพลังงานภายนอก Eₖ เพิ่มไม่ได้", "ไม่ถูก 9.5 J คือ Eₖ หลังชน ไม่ใช่ส่วนที่เปลี่ยน", "ถูก 12.5 − 9.5 = 3.0 J", "ไม่ถูก 9.5 J คือ Eₖ หลังชน ไม่ใช่ส่วนที่ลดลง"]'::jsonb,'{"topic": "1.6", "n": 6}'::jsonb,'imported_m6','imported',true,'flag','Exam Gym ม.6 · 5620e4c',2568,'phy:68-6');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-68-7','M6','M6-PH','M6-PH-S2','A-Level 64',null,2,'คลื่นผิวน้ำขบวนหนึ่งมีความยาวคลื่น 80 เมตร เคลื่อนที่จากน้ำลึกเข้าสู่น้ำตื้น โดยหน้าคลื่นทำมุม 60 องศากับแนวรอยต่อระหว่างน้ำลึกและน้ำตื้น พบว่าหน้าคลื่นในบริเวณน้ำตื้นทำมุม 30 องศากับแนวรอยต่อ
