insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-68-9','M6','M6-PH','M6-PH-S2','A-Level 64',null,2,'ในการทดลองหนึ่ง นักเรียนฉายแสงเอกรงค์ (แสงความถี่เดียว) ผ่านสลิตคู่เพื่อศึกษาภาพการแทรกสอดที่ปรากฏบนฉากรับที่อยู่ห่างออกไปมาก
