insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-68-10','M6','M6-PH','M6-PH-S1','A-Level 64',null,2,'แขวนมวล 0.10 กิโลกรัม กับปลายด้านล่างของสปริงที่วางตัวในแนวดิ่ง แล้วปล่อยให้มวลสั่นขึ้นลงในแนวดิ่ง จับเวลาการสั่นครบ 10 รอบได้ 17.3 วินาที เมื่อแขวนมวลเพิ่มเข้าไปอีก 0.20 กิโลกรัม แล้วปล่อยให้สั่นในลักษณะเดิม
คำถาม คาบของการสั่นจะเป็นกี่วินาที','["1.4", "1.7", "2.0", "2.7", "3.0"]'::jsonb,4,array[4]::smallint[],'["T = 2π√(m/k) จึง T ∝ √m · T₁ = 17.3/10 = 1.73 s มวลใหม่ 0.30 kg = 3 เท่า → T₂ = 1.73 × √3 ≈ 3.0 s"]'::jsonb,'["ไม่ถูก คาบต้องเพิ่มเมื่อมวลเพิ่ม", "ไม่ถูก เป็นคาบเดิม (1.73 s)", "ไม่ถูก คิดว่าคาบไม่ขึ้นกับมวลแบบเชิงเส้นผิดรูป", "ไม่ถูก ใช้ T ∝ √(มวลที่เพิ่ม 0.20 kg)", "ถูก T₂ = 1.73√3 ≈ 3.0 s"]'::jsonb,'{"topic": "1.8", "n": 10}'::jsonb,'imported_m6','imported',true,'numeric','Exam Gym ม.6 · 5620e4c',2568,'phy:68-10');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-PH-68-11','M6','M6-PH','M6-PH-S2','A-Level 64',null,2,'ทำการทดลองการสั่นพ้องของเสียงจากท่อทรงกระบอกปลายปิดข้างหนึ่งด้วยลูกสูบ ถ้าความถี่ของแหล่งกำเนิดเสียงมีค่า 1400 เฮิรตซ์ จะได้ยินเสียงดังที่สุด
