insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-CH-68-27','M6','M6-CH','M6-CH-S2','A-Level 65',null,2,'จากศักย์ไฟฟ้ามาตรฐานรีดักชันต่อไปนี้','["ก. เท่านั้น", "ข. เท่านั้น", "ค. เท่านั้น", "ก. และ ข. เท่านั้น", "ข. และ ค. เท่านั้น"]'::jsonb,4,array[4]::smallint[],'["ก ผิด Ag⁺ มี E° สูงกว่า จึงเป็นตัวออกซิไดส์ที่แรงกว่า · ข ถูก Mn มี E° ต่ำกว่า ถูกออกซิไดส์เป็นแอโนด · ค ถูก E°cell = 0.80 − (−0.76) = 1.56 V"]'::jsonb,'["ไม่ถูก ก ผิด", "ไม่ครบ ค ก็ถูก", "ไม่ครบ ข ก็ถูก", "ไม่ถูก ก ผิด", "ถูก ข และ ค ถูก"]'::jsonb,'{"table": [["ปฏิกิริยาครึ่งเซลล์รีดักชัน", "E° (V)"], ["Mn²⁺(aq) + 2e⁻ → Mn(s)", "–1.18"], ["Ag⁺(aq) + e⁻ → Ag(s)", "+0.80"], ["Zn²⁺(aq) + 2e⁻ → Zn(s)", "–0.76"]], "after": "พิจารณาข้อความต่อไปนี้\nก. Zn²⁺ เป็นตัวออกซิไดส์ที่แรงกว่า Ag⁺\nข. Mn เป็นแอโนดในเซลล์กัลวานิกจากการต่อครึ่งเซลล์ Ag⁺/Ag กับครึ่งเซลล์ Mn²⁺/Mn\nค. เซลล์ Zn(s) | Zn²⁺(aq) || Ag⁺(aq) | Ag(s) มี E°cell = 1.56 V\nข้อใดถูกต้อง", "topic": "2.5", "n": 27}'::jsonb,'imported_m6','imported',true,'labelseq','Exam Gym ม.6 · 5620e4c',2568,'chem:68-27');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-CH-68-28','M6','M6-CH','M6-CH-S3','A-Level 65',null,2,'สารประกอบออกไซด์ชนิดหนึ่งของโมลิบดีนัม (Mo) มีร้อยละโดยมวลของ Mo เท่ากับ 75 โดยสารประกอบนี้ 32 g ทำปฏิกิริยาพอดีกับแก๊สออกซิเจนปริมาตร 2.8 L ที่ STP ได้สารประกอบออกไซด์อีกชนิดหนึ่งซึ่งมีสูตรอย่างง่าย MoxOy เป็นผลิตภัณฑ์เพียงชนิดเดียว
