insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-CH-68-29','M6','M6-CH','M6-CH-S3','A-Level 65',null,2,'ยา A ละลายน้ำได้น้อย จึงต้องเตรียมสารละลายของยานี้ในกรดเจือจาง ดังสมการ
A(s) + 2H⁺(aq) → AH₂²⁺(aq)
ถ้าละลายยานี้จำนวนหนึ่งในสารละลาย HCl 50 mL ได้พอดี จากนั้นปรับปริมาตรเป็น 200.0 mL พบว่าสารละลายนี้มีความเข้มข้นของ AH₂²⁺ เท่ากับ 25 mM
ความเข้มข้นของสารละลาย HCl ที่ใช้เตรียมสารละลายของยามีค่าเท่าใด','["0.050 M", "0.10 M", "0.20 M", "0.50 M", "1.0 M"]'::jsonb,2,array[2]::smallint[],'["AH₂²⁺ = 0.025 M × 0.2000 L = 5.0 mmol → ใช้ H⁺ 10 mmol ใน HCl 50 mL → [HCl] = 10/50 = 0.20 M"]'::jsonb,'["ไม่ถูก ได้ถ้าใช้ปริมาตร 200 mL", "ไม่ถูก ลืมว่าใช้ H⁺ 2 โมลต่อยา 1 โมล", "ถูก [HCl] = 0.20 M", "ไม่ถูก ค่ามากเกินไป", "ไม่ถูก ค่ามากเกินไป"]'::jsonb,'{"topic": "3.3", "n": 29}'::jsonb,'imported_m6','imported',true,'numeric','Exam Gym ม.6 · 5620e4c',2568,'chem:68-29');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-CH-68-30','M6','M6-CH','M6-CH-S3','A-Level 65',null,2,'สารละลายในข้อใดมีจุดเดือด 101.02 °C
กำหนดให้ น้ำมีจุดเดือด 100.00 °C, Kb ของน้ำ = 0.51 °C·m⁻¹','["สารละลายกลูโคส (M = 180 g·mol⁻¹) ความเข้มข้น 3.0 m ในน้ำ", "สารละลายเอทานอล (M = 46 g·mol⁻¹) 4.6 g ในน้ำ 200.0 g", "สารละลายกลีเซอรอล (M = 92 g·mol⁻¹) 0.92 g ในน้ำ 100.0 g", "สารละลายกลูโคส 18.0 g ในน้ำ 50.0 g", "สารละลายกลีเซอรอลความเข้มข้น 0.23 g·mL⁻¹ ในน้ำ และมีความหนาแน่น 1.0 g·mL⁻¹"]'::jsonb,3,array[3]::smallint[],'["ΔTb = 1.02 = 0.51m → m = 2.0 mol·kg⁻¹ · กลูโคส 18.0 g = 0.100 mol ในน้ำ 0.0500 kg = 2.0 m"]'::jsonb,'["ไม่ถูก 3.0 m ให้ ΔTb = 1.53 °C", "ไม่ถูก 0.10 mol/0.200 kg = 0.50 m", "ไม่ถูก 0.010 mol/0.100 kg = 0.10 m", "ถูก 0.100 mol/0.0500 kg = 2.0 m", "ไม่ถูก 1 mL มีกลีเซอรอล 0.23 g ในน้ำ 0.77 g ≈ 3.2 m"]'::jsonb,'{"topic": "3.3", "n": 30}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'chem:68-30');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-1','M6','M6-BI','M6-BI-S1','A-Level 66',null,2,'พิจารณาสถานการณ์ต่อไปนี้
นักวิจัยวางแปลงสำรวจ 3 เส้นทาง บริเวณธารน้ำแข็งขนาดใหญ่ที่เริ่มละลายในเทือกเขาเซียร์ราเนวาดา รัฐแคลิฟอร์เนีย ของสหรัฐอเมริกา โดยพบว่า
เส้นทาง A: พบหินเปลือย ฝุ่นตะกอนบาง มีไลเคนและมอสประปราย และไม่พบหลักฐานเมล็ดในดิน
เส้นทาง B: พบหินกรวดผสมดินบาง เศษราก เมล็ดพักตัว หญ้าและไม้พุ่มเตี้ย
เส้นทาง C: พบดินลึก ไม้ต้นอายุน้อย ท่อนไม้ผุและเศษใบไม้ทับถมสะสม
ข้อใดอธิบายการเปลี่ยนแปลงแทนที่ของระบบนิเวศข้างต้นได้ถูกต้อง','["เส้นทาง A เกิดการเปลี่ยนแปลงแทนที่แบบปฐมภูมิ ส่วนเส้นทาง B และ C เกิดการเปลี่ยนแปลงแทนที่แบบทุติยภูมิ", "เส้นทาง A เกิดการเปลี่ยนแปลงแทนที่แบบทุติยภูมิ ส่วนเส้นทาง B และ C เกิดการเปลี่ยนแปลงแทนที่แบบปฐมภูมิ", "เส้นทาง A และ B เกิดการเปลี่ยนแปลงแทนที่แบบปฐมภูมิ ส่วนเส้นทาง C เกิดการเปลี่ยนแปลงแทนที่แบบทุติยภูมิ", "เส้นทางทั้งหมดเป็นการเปลี่ยนแปลงแทนที่แบบปฐมภูมิ", "เส้นทางทั้งหมดเป็นการเปลี่ยนแปลงแทนที่แบบทุติยภูมิ"]'::jsonb,0,array[0]::smallint[],'["เกณฑ์ที่ใช้คือมีดินและแหล่งพันธุ์ (เมล็ด ราก) เหลืออยู่หรือไม่ · A เป็นหินเปลือย ไม่มีดินและเมล็ด มีไลเคนและมอสเป็นผู้บุกเบิก จึงเป็นแบบปฐมภูมิ · B และ C มีดิน เศษราก เมล็ดพักตัว จึงเป็นแบบทุติยภูมิ"]'::jsonb,'["ถูก", "ไม่ถูก สลับกัน หินเปลือยที่มีไลเคนและมอสเป็นลักษณะของแบบปฐมภูมิ", "ไม่ถูก B มีดิน เศษรากและเมล็ดพักตัวแล้ว", "ไม่ถูก B และ C มีดินและแหล่งพันธุ์เดิม", "ไม่ถูก A ไม่มีดินและไม่มีเมล็ด"]'::jsonb,'{"topic": "1.1", "n": 1}'::jsonb,'imported_m6','imported',true,'expl','เฉลย ทปอ. คือข้อ 1 ซึ่งแบ่งตามการมีดินและเมล็ดในแต่ละเส้นทาง แต่ตำราบางเล่มจัดการแทนที่หลังธารน้ำแข็งถอยทั้งหมดเป็นแบบปฐมภูมิ ครูควรอธิบายเกณฑ์นี้ให้ชัด',2569,'bio:69-1');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-2','M6','M6-BI','M6-BI-S1','A-Level 66',null,2,'พื้นที่ชายฝั่งตะวันออกของกรีนแลนด์มีพื้นที่รวม 3,000 ตารางกิโลเมตร (ตร.กม.) สำรวจพบหมีขั้วโลก 450 ตัว โดยพบเฉพาะในพื้นที่ชายฝั่งติดทะเลน้ำแข็งตามแหล่งหากินของแมวน้ำ ซึ่งมีพื้นที่ 900 ตร.กม.
จากข้อมูลดังกล่าว ข้อใด**ไม่**ถูกต้อง','["การกระจายตัวของสมาชิกประชากรหมีขั้วโลกเป็นแบบสุ่ม (random dispersion)", "หมีขั้วโลกมีรูปแบบการรอดชีวิตใกล้เคียงตามกราฟรูปแบบ I", "ความหนาแน่นเชิงนิเวศของประชากรหมีขั้วโลกเท่ากับ 0.5 ตัว/ตร.กม.", "ความหนาแน่นแบบหยาบคำนวณได้จาก จำนวนหมีทั้งหมดหารด้วยพื้นที่ทั้งหมดของเขตศึกษานี้", "หากอุณหภูมิโลกสูงขึ้น อัตราการเพิ่มของประชากรหมีขั้วโลกอาจมีแนวโน้มลดลง"]'::jsonb,0,array[0]::smallint[],'["หมีพบเฉพาะบริเวณชายฝั่งที่มีแหล่งอาหาร จึงกระจายแบบกลุ่ม (clumped) ไม่ใช่แบบสุ่ม"]'::jsonb,'["ไม่ถูกต้อง จึงเป็นคำตอบ หมีอยู่รวมเฉพาะบริเวณที่มีแมวน้ำ เป็นการกระจายแบบกลุ่ม", "ถูกต้อง สัตว์เลี้ยงลูกด้วยน้ำนมขนาดใหญ่ที่ดูแลลูก ส่วนใหญ่ตายเมื่อแก่ (รูปแบบ I)", "ถูกต้อง 450 ÷ 900 = 0.5 ตัว/ตร.กม. (คิดเฉพาะพื้นที่ที่อาศัยได้จริง)", "ถูกต้อง ความหนาแน่นแบบหยาบ = 450 ÷ 3,000 = 0.15 ตัว/ตร.กม.", "ถูกต้อง ทะเลน้ำแข็งลดลง แหล่งล่าแมวน้ำจึงลดลง"]'::jsonb,'{"topic": "1.2", "n": 2}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'bio:69-2');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-3','M6','M6-BI','M6-BI-S1','A-Level 66',null,2,'ข้อใดกล่าวเกี่ยวกับวัฏจักรฟอสฟอรัสที่พบในระบบนิเวศ**ไม่**ถูกต้อง','["การผุพังของหินฟอสเฟตเป็นแหล่งสำคัญของฟอสฟอรัสในระบบนิเวศ", "พืชสามารถดูดซึมฟอสฟอรัสได้โดยตรงจากแก๊สฟอสฟีน (PH₃) ในอากาศ", "ฟอสฟอรัสเป็นธาตุอาหารที่สิ่งมีชีวิตต้องการในการสร้างกรดนิวคลีอิกและเยื่อหุ้มเซลล์", "วัฏจักรฟอสฟอรัสแตกต่างจากวัฏจักรไนโตรเจนตรงที่ไม่มีการหมุนเวียนผ่านบรรยากาศ", "ฟอสฟอรัสสามารถสะสมในตะกอนของแหล่งน้ำ และถูกปลดปล่อยกลับเข้าสู่ระบบเมื่อเกิดการผุพังของหิน"]'::jsonb,1,array[1]::smallint[],'["พืชดูดฟอสฟอรัสจากดินในรูปไอออนฟอสเฟต ไม่ได้ดูดจากแก๊สในอากาศ"]'::jsonb,'["ถูกต้อง", "ไม่ถูกต้อง จึงเป็นคำตอบ พืชดูดฟอสเฟตทางราก วัฏจักรฟอสฟอรัสไม่มีแก๊สในบรรยากาศเป็นแหล่งสำคัญ", "ถูกต้อง ฟอสฟอรัสอยู่ใน DNA RNA ATP และฟอสโฟลิพิด", "ถูกต้อง", "ถูกต้อง"]'::jsonb,'{"topic": "1.1", "n": 3}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'bio:69-3');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-4','M6','M6-BI','M6-BI-S1','A-Level 66',null,2,'พิจารณาสถานการณ์ต่อไปนี้ นักนิเวศวิทยาสำรวจพื้นที่อนุรักษ์แห่งหนึ่งพบสัตว์ 5 ชนิดดังนี้
ชนิด A มีเนื้อเยื่อ 2 ชั้น, acoelom, สมมาตรรัศมี, มีเนมาโทซิสต์
ชนิด B มีเนื้อเยื่อ 3 ชั้น, pseudocoelom, สมมาตรแบบครึ่งซีก, protostome
ชนิด C มีเนื้อเยื่อ 3 ชั้น, coelom แท้จริง, deuterostome, มีระบบท่อน้ำและผิวหนังเป็นหนาม
ชนิด D มีเนื้อเยื่อ 3 ชั้น, protostome, ลำตัวเป็นปล้อง, ระบบเลือดแบบเปิด
ชนิด E มีเนื้อเยื่อ 3 ชั้น, acoelom, สมมาตรแบบครึ่งซีก, regeneration ได้
ข้อใด**ไม่**ถูกต้อง','["ชนิด A คือดอกไม้ทะเล พบบริเวณชายฝั่งทะเล", "ชนิด B คือหนอนตัวกลมอะนิซาคิส พบในซากปลาซาบะริมฝั่งทะเล", "ชนิด C คือหอยนางรมหนาม ซึ่งพบที่ปากแม่น้ำและบริเวณน้ำตื้นชายฝั่งทะเล", "ชนิด D คือปูดำ พบบริเวณแหล่งน้ำกร่อย แนวป่าชายเลนและปากแม่น้ำที่ทะเลท่วมถึง", "ชนิด E คือหนอนตัวแบนทะเล พบได้ตามแนวปะการังหรือหินใต้ทะเลในแหล่งดำน้ำ"]'::jsonb,2,array[2]::smallint[],'["C มีระบบท่อน้ำและผิวหนังเป็นหนาม เป็นเอไคโนเดิร์ม (เช่น ดาวทะเล เม่นทะเล) ส่วนหอยนางรมเป็นมอลลัสก์ที่เป็นโพรโทสโทม"]'::jsonb,'["ถูกต้อง ดอกไม้ทะเลเป็นไนดาเรียน", "ถูกต้อง หนอนตัวกลมมีโพรงลำตัวเทียม", "ไม่ถูกต้อง จึงเป็นคำตอบ หอยไม่มีระบบท่อน้ำ และไม่ใช่ดิวเทอโรสโทม", "ถูกต้อง ปูเป็นอาร์โทรพอด ลำตัวเป็นปล้อง ระบบเลือดเปิด", "ถูกต้อง หนอนตัวแบนไม่มีช่องลำตัวและงอกใหม่ได้"]'::jsonb,'{"topic": "1.4", "n": 4}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'bio:69-4');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-5','M6','M6-BI','M6-BI-S1','A-Level 66',null,2,'ข้อใดกล่าวเกี่ยวกับกลุ่มพืชที่มีการปรับตัวเพื่อการดำรงชีวิตบนบกได้ถูกต้องทั้งหมด','["มอส (bryophyte) – มีท่อลำเลียงภายในลำต้นเพื่อลำเลียงน้ำและอาหาร\nเฟิร์น (pteridophyte) – มีราก ลำต้น ใบแท้จริง และสร้างสปอร์ในอับสปอร์", "เฟิร์น (pteridophyte) – ส่วนใหญ่มีท่อลำเลียง ทำให้สามารถมีขนาดใหญ่ขึ้นและอยู่ในที่แห้งได้มากขึ้น\nพืชดอก (angiosperm) – มีเมล็ดเปลือย ช่วยป้องกันการสูญเสียน้ำในระยะสืบพันธุ์", "มอส (bryophyte) – แกมีโทไฟต์เด่น ต้องอาศัยน้ำในการปฏิสนธิ\nเฟิร์น (pteridophyte) – ไม่มีท่อลำเลียงและสืบพันธุ์โดยการสร้างเมล็ด", "พืชเมล็ดเปลือย (gymnosperm) – ส่วนใหญ่มีโคน (cone) ใช้ในการสืบพันธุ์โดยไม่ต้องอาศัยน้ำ\nพืชดอก (angiosperm) – มีผลและเมล็ด ช่วยในการกระจายพันธุ์", "มอส (bryophyte) – มีดอกและผลเพื่อป้องกันการสูญเสียน้ำ\nเฟิร์น (pteridophyte) – ส่วนใหญ่มีเมล็ดที่ช่วยในการกระจายพันธุ์โดยไม่ต้องอาศัยน้ำ"]'::jsonb,3,array[3]::smallint[],'["พืชเมล็ดเปลือยสืบพันธุ์ด้วยโคน เรณูไปถึงออวุลได้โดยไม่ต้องใช้น้ำ · พืชดอกมีผลห่อหุ้มเมล็ดช่วยการกระจายพันธุ์"]'::jsonb,'["ไม่ถูก มอสไม่มีท่อลำเลียง", "ไม่ถูก พืชดอกมีเมล็ดที่มีผลห่อหุ้ม ไม่ใช่เมล็ดเปลือย", "ไม่ถูก เฟิร์นมีท่อลำเลียงและสืบพันธุ์ด้วยสปอร์ ไม่สร้างเมล็ด", "ถูก", "ไม่ถูก มอสไม่มีดอกและผล เฟิร์นไม่มีเมล็ด"]'::jsonb,'{"topic": "1.4", "n": 5}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'bio:69-5');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-6','M6','M6-BI','M6-BI-S2','A-Level 66',null,2,'น้ำเป็นสิ่งสำคัญสำหรับสิ่งมีชีวิตทุกชนิด คุณสมบัติของโมเลกุลน้ำ ข้อใดถูกต้อง','["อะตอมต่าง ๆ ภายในโมเลกุลน้ำยึดเหนี่ยวกันด้วยพันธะไอออนิก", "สภาพขั้วลบของโมเลกุลน้ำพบในบริเวณตำแหน่งของอะตอมไฮโดรเจน", "เมื่อโมเลกุลหนึ่งละลายและแตกตัวในน้ำ โมเลกุลน้ำจะหันด้านที่เป็นขั้วลบเข้าจับกับไอออนลบที่แตกตัวจากโมเลกุลนั้น", "เมื่อน้ำได้รับความร้อนจนเปลี่ยนสถานะจากของเหลวเป็นแก๊ส โมเลกุลของน้ำจะแตกตัวให้อะตอมออกซิเจนและไฮโดรเจน", "ในสถานะของเหลว โมเลกุลน้ำจะยึดเหนี่ยวกันด้วยพันธะไฮโดรเจนซึ่งเกิดขึ้นระหว่างอะตอมไฮโดรเจนและอะตอมออกซิเจน"]'::jsonb,4,array[4]::smallint[],'["พันธะไฮโดรเจนเกิดระหว่างอะตอม H ของโมเลกุลน้ำหนึ่งกับอะตอม O ของอีกโมเลกุลหนึ่ง"]'::jsonb,'["ไม่ถูก ภายในโมเลกุลเป็นพันธะโคเวเลนต์มีขั้ว", "ไม่ถูก ขั้วลบอยู่ที่อะตอมออกซิเจน", "ไม่ถูก น้ำหันด้านขั้วบวก (H) เข้าหาไอออนลบ", "ไม่ถูก การเดือดเป็นการแยกโมเลกุลออกจากกัน (ตัดพันธะไฮโดรเจน) โมเลกุลน้ำไม่ได้แตกเป็นอะตอม", "ถูก"]'::jsonb,'{"topic": "2.1", "n": 6}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'bio:69-6');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-7','M6','M6-BI','M6-BI-S2','A-Level 66',null,2,'พิจารณาภาพโมเลกุลสารประกอบและข้อความต่อไปนี้','["ก. และ ข. เท่านั้น", "ก. และ ค. เท่านั้น", "ข. และ ค. เท่านั้น", "ข. และ ง. เท่านั้น", "ค. และ ง. เท่านั้น"]'::jsonb,3,array[3]::smallint[],'["A คือซูโครส (กลูโคส + ฟรักโทส) · B คือแล็กโทส (กาแล็กโทส + กลูโคส) · ก ผิด ทั้งคู่มีคาร์บอน 12 อะตอม · ข ถูก พันธะไกลโคซิดิกเป็นพันธะโคเวเลนต์ · ค ผิด B ประกอบด้วยมอโนแซ็กคาไรด์ต่างชนิดกัน · ง ถูก ซูโครสเชื่อมด้วยพันธะ α-1,2"]'::jsonb,'["ไม่ถูก ก ผิด", "ไม่ถูก ก และ ค ผิด", "ไม่ถูก ค ผิด", "ถูก", "ไม่ถูก ค ผิด"]'::jsonb,'{"img": "bio-69-7.png", "after": "ก. โมเลกุล A มีจำนวนอะตอมคาร์บอนน้อยกว่าโมเลกุล B\nข. พันธะที่เชื่อมระหว่างมอโนแซ็กคาไรด์ในโมเลกุล A และ B คือพันธะโคเวเลนต์\nค. โมเลกุล B คือไดแซ็กคาไรด์ที่ประกอบด้วยมอโนแซ็กคาไรด์ชนิดเดียวกัน 2 โมเลกุล\nง. พันธะที่เชื่อมต่อกันระหว่างมอโนแซ็กคาไรด์ในโมเลกุล A คือพันธะไกลโคซิดิกแบบ α (แอลฟา)\nข้อใดถูกต้อง", "topic": "2.1", "n": 7, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/bio-69-7.png"}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2569,'bio:69-7');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-8','M6','M6-BI','M6-BI-S2','A-Level 66',null,2,'พิจารณาข้อความต่อไปนี้
ก. ไตรเพปไทด์ประกอบด้วยพันธะเพปไทด์ 3 พันธะ
ข. แอนติบอดี คือโปรตีนชนิดหนึ่งที่ทำงานในระบบภูมิคุ้มกันของสิ่งมีชีวิต
ค. กรดแอมิโนประกอบด้วยอะตอมของธาตุคาร์บอน ไฮโดรเจน ออกซิเจน และฟอสฟอรัสเป็นหลัก
ง. การพับม้วนเป็นเกลียวหรือแผ่นของโปรตีนในโครงสร้างทุติยภูมิ เกิดจากพันธะไฮโดรเจนระหว่างกรดแอมิโนในสายพอลิเพปไทด์
ข้อใดถูกต้อง','["ก. และ ข. เท่านั้น", "ก. และ ค. เท่านั้น", "ข. และ ค. เท่านั้น", "ข. และ ง. เท่านั้น", "ค. และ ง. เท่านั้น"]'::jsonb,3,array[3]::smallint[],'["ก ผิด กรดแอมิโน 3 โมเลกุลเชื่อมกันด้วยพันธะเพปไทด์ 2 พันธะ · ข ถูก · ค ผิด ธาตุหลักคือ C H O และ N · ง ถูก เกลียวแอลฟาและแผ่นบีตาเกิดจากพันธะไฮโดรเจน"]'::jsonb,'["ไม่ถูก ก ผิด", "ไม่ถูก ก และ ค ผิด", "ไม่ถูก ค ผิด", "ถูก", "ไม่ถูก ค ผิด"]'::jsonb,'{"topic": "2.1", "n": 8}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2569,'bio:69-8');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-9','M6','M6-BI','M6-BI-S2','A-Level 66',null,2,'พิจารณาภาพวัฏจักรของเซลล์ต่อไปนี้','["หากเซลล์ข้ามระยะ B ไป แต่ละโครโมโซมของเซลล์จะมีเพียง 1 โครมาทิด เมื่อเกิดการขดตัวในระยะ D₁", "เมื่อสิ้นสุดระยะ A เซลล์จะมีดีเอ็นเอเพิ่มขึ้นเป็น 2 เท่า", "ขั้นตอนในการเกิดกระบวนการสำคัญในระยะ D₅ ของเซลล์พืชเหมือนกับสิ่งที่เกิดขึ้นในเซลล์สัตว์", "ความหลากหลายทางพันธุกรรมที่เพิ่มขึ้นในเซลล์ลูก เป็นผลมาจากกระบวนการหนึ่งที่เกิดขึ้นในระยะ C", "หากซิสเตอร์โครมาทิดไม่แยกออกจากกันในระยะ D₂ โครโมโซมของเซลล์ลูกจะมีจำนวนไม่เท่ากันหลังจากสิ้นสุดระยะ D₅"]'::jsonb,0,array[0]::smallint[],'["A = G₁ · B = S (จำลองดีเอ็นเอ) · C = G₂ · D = การแบ่งนิวเคลียส D₁–D₄ (โพรเฟส เมทาเฟส แอนาเฟส เทโลเฟส) และ D₅ = การแบ่งไซโทพลาซึม · ถ้าข้ามระยะ S ดีเอ็นเอไม่ถูกจำลอง โครโมโซมจึงมีโครมาทิดเดียว"]'::jsonb,'["ถูก", "ไม่ถูก ดีเอ็นเอเพิ่มเป็น 2 เท่าในระยะ B (S) ไม่ใช่ระยะ A (G₁)", "ไม่ถูก เซลล์พืชสร้างแผ่นกั้นเซลล์ (cell plate) ส่วนเซลล์สัตว์เกิดร่องคอดเข้า", "ไม่ถูก ไมโทซิสให้เซลล์ลูกที่มีพันธุกรรมเหมือนเดิม ระยะ C (G₂) ไม่ได้เพิ่มความหลากหลาย", "ไม่ถูก ระยะ D₂ คือเมทาเฟส ซิสเตอร์โครมาทิดแยกกันในระยะ D₃ (แอนาเฟส)"]'::jsonb,'{"img": "bio-69-9.png", "after": "ข้อใดถูกต้อง", "topic": "2.2", "n": 9, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/bio-69-9.png"}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'bio:69-9');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-10','M6','M6-BI','M6-BI-S2','A-Level 66',null,2,'พิจารณาข้อความต่อไปนี้
ก. คาร์บอนไดออกไซด์ที่เกิดขึ้นในวัฏจักรเครบส์มีที่มาจากโมเลกุลโคเอนไซม์เอ
ข. สารประกอบตัวสุดท้ายที่เกิดขึ้นในวัฏจักรเครบส์ประกอบด้วยคาร์บอน 3 อะตอม
ค. สารพลังงานสูงที่เป็นผลผลิตของวัฏจักรเครบส์ประกอบด้วย ATP NADH และ FADH₂
ง. กรดซิตริกในวัฏจักรเครบส์เกิดขึ้นจากการรวมตัวกันระหว่างแอซิทิลโคเอนไซม์เอและกรดออกซาโลแอซิติก
ข้อใดถูกต้อง','["ก. และ ค. เท่านั้น", "ก. และ ง. เท่านั้น", "ข. และ ค. เท่านั้น", "ข. และ ง. เท่านั้น", "ค. และ ง. เท่านั้น"]'::jsonb,4,array[4]::smallint[],'["ก ผิด CO₂ มาจากคาร์บอนของสารในวัฏจักร ไม่ใช่จากโคเอนไซม์เอ (ซึ่งถูกปล่อยออกมาใช้ใหม่) · ข ผิด สารตัวสุดท้ายคือกรดออกซาโลแอซิติกซึ่งมีคาร์บอน 4 อะตอม · ค ถูก · ง ถูก"]'::jsonb,'["ไม่ถูก ก ผิด", "ไม่ถูก ก ผิด", "ไม่ถูก ข ผิด", "ไม่ถูก ข ผิด", "ถูก"]'::jsonb,'{"topic": "2.2", "n": 10}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2569,'bio:69-10');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-11','M6','M6-BI','M6-BI-S2','A-Level 66',null,2,'พิจารณาเหตุการณ์ต่อไปนี้ หากเอนไซม์ที่บรรจุอยู่ในไลโซโซมของเซลล์มนุษย์หยุดการทำงานอย่างฉับพลัน
ก. เซลล์หยุดการนำเข้าสารจากภายนอกทันที
ข. ไมโทคอนเดรียที่หมดอายุแล้วจะไม่ถูกย่อยทำลาย
ค. เวสิเคิลบรรจุสารที่นำเข้าสู่เซลล์จะเกิดการสะสมจนมีจำนวนมากขึ้นเรื่อย ๆ
ง. โมเลกุลคาร์โบไฮเดรตที่นำเข้ามาจากภายนอกเซลล์รวมตัวกันเป็นโมเลกุลที่ใหญ่ขึ้น
ข้อใดถูกต้อง','["ก. และ ข. เท่านั้น", "ก. และ ค. เท่านั้น", "ข. และ ค. เท่านั้น", "ข. และ ง. เท่านั้น", "ค. และ ง. เท่านั้น"]'::jsonb,2,array[2]::smallint[],'["ไลโซโซมย่อยออร์แกเนลล์ที่หมดอายุ (ออโทฟาจี) และย่อยสารในเวสิเคิลที่นำเข้าเซลล์ · ถ้าเอนไซม์หยุดทำงาน ข และ ค จึงเกิดขึ้น · ก ผิด การนำเข้าสาร (เอนโดไซโทซิส) ไม่ได้ใช้เอนไซม์ไลโซโซม · ง ผิด ไลโซโซมไม่ได้ทำหน้าที่สร้างพอลิเมอร์"]'::jsonb,'["ไม่ถูก ก ผิด", "ไม่ถูก ก ผิด", "ถูก", "ไม่ถูก ง ผิด", "ไม่ถูก ง ผิด"]'::jsonb,'{"topic": "2.2", "n": 11}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2569,'bio:69-11');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-12','M6','M6-BI','M6-BI-S3','A-Level 66',null,2,'พิจารณาสถานการณ์ต่อไปนี้
คุณครูวิชาชีววิทยาให้นักเรียน ก ข ค และ ง ยกตัวอย่างสิ่งมีชีวิต A B C D และ E ที่มีลักษณะดังตารางที่ 1 แล้วให้นักเรียนเขียนคำตอบในตารางที่ 2 ดังนี้
ตารางที่ 1','["นาย ก", "นาย ข", "นาย ค", "นาย ง", "นาย ก และ นาย ข ตอบถูกมากที่สุด"]'::jsonb,2,array[2]::smallint[],'["A ย่อยภายในเซลล์อย่างเดียว (โพรทิสต์ ฟองน้ำ) · B ย่อยภายนอกเซลล์โดยไม่มีทางเดินอาหาร (เห็ด รา) · C มีทั้งสองแบบและทางเดินอาหารไม่สมบูรณ์ (ไฮดรา พลานาเรีย) · D ทางเดินอาหารสมบูรณ์ มีตับและตับอ่อน (สัตว์มีกระดูกสันหลัง) · E มีกึ๋นและกระเพาะพักอาหาร (นก ไส้เดือนดิน) · นาย ค ถูก 4 ตัว (ผิดเฉพาะงู) มากที่สุด"]'::jsonb,'["ไม่ถูก นาย ก ถูก 3 ตัว (ผิดที่พลานาเรียและพารามีเซียม)", "ไม่ถูก นาย ข ถูก 3 ตัว (ผิดที่ฟองน้ำและไส้เดือนดินในช่อง D)", "ถูก", "ไม่ถูก นาย ง ถูก 2 ตัว (รา และไส้เดือนดิน)", "ไม่ถูก นาย ก และนาย ข ถูกเพียงคนละ 3 ตัว"]'::jsonb,'{"table": [["สิ่งมีชีวิต", "การย่อยอาหารภายนอกเซลล์", "การย่อยอาหารภายในเซลล์", "มีทางเดินอาหารแบบไม่สมบูรณ์", "มีทางเดินอาหารแบบสมบูรณ์", "อวัยวะที่เกี่ยวข้องกับการย่อยอาหาร"], ["A", "-", "✓", "-", "-", "-"], ["B", "✓", "-", "-", "-", "-"], ["C", "✓", "✓", "✓", "-", "-"], ["D", "✓", "-", "-", "✓", "ตับ ตับอ่อน"], ["E", "✓", "-", "-", "✓", "กึ๋น กระเพาะพักอาหาร"]], "after": "ตารางที่ 2 (สิ่งมีชีวิต A B C D E ตามลำดับ)\nนาย ก: ฟองน้ำ พลานาเรีย พารามีเซียม มนุษย์ ไก่\nนาย ข: อะมีบา ฟองน้ำ พลานาเรีย ไส้เดือนดิน นก\nนาย ค: พารามีเซียม เห็ด ไฮดรา กระต่าย งู\nนาย ง: ไฮดรา รา ฟองน้ำ ปลิงน้ำจืด ไส้เดือนดิน\nนักเรียนคนใดตอบถูกมากที่สุด", "topic": "3.1", "n": 12}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'bio:69-12');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-13','M6','M6-BI','M6-BI-S3','A-Level 66',null,2,'พิจารณาแผนผังและสถานการณ์ต่อไปนี้
จากแผนผังทางเดินอาหารของมนุษย์กำหนดให้ A B และ C เป็นอวัยวะที่มีการย่อยอาหารเกิดขึ้น','["อาหารที่นาย ก รับประทาน ถูกย่อยครั้งแรกที่อวัยวะ C", "อาหารที่นาย ข รับประทาน ถูกดูดซึมได้อย่างรวดเร็วที่อวัยวะ D", "อาหารที่นาย ค รับประทาน ถูกย่อยเชิงเคมีครั้งแรกที่อวัยวะ B ด้วยเอนไซม์ที่ทำงานได้ดีที่ pH ต่ำ", "อาหารที่นาย ง รับประทาน ถูกย่อยครั้งแรกด้วยเอนไซม์ที่สร้างจากตับอ่อน", "อาหารที่นาย จ รับประทาน ถูกย่อยเชิงกลครั้งแรกที่อวัยวะ A และไปสิ้นสุดกระบวนการย่อยอาหารที่อวัยวะ C"]'::jsonb,4,array[4]::smallint[],'["A = ปาก · B = กระเพาะอาหาร · C = ลำไส้เล็ก · D = ลำไส้ใหญ่ · ผักและน้ำมันถูกบดเคี้ยวครั้งแรกในปาก และไขมันถูกย่อยจนเสร็จในลำไส้เล็ก"]'::jsonb,'["ไม่ถูก กลูโคสเป็นมอโนแซ็กคาไรด์ ไม่ต้องย่อย ดูดซึมได้ทันที", "ไม่ถูก น้ำอ้อย (ซูโครส) ถูกย่อยและดูดซึมที่ลำไส้เล็ก (C) ไม่ใช่ลำไส้ใหญ่", "ไม่ถูก ข้าว (แป้ง) ถูกย่อยเชิงเคมีครั้งแรกในปากด้วยอะไมเลสในน้ำลาย", "ไม่ถูก โปรตีนในไข่ถูกย่อยครั้งแรกด้วยเพปซินในกระเพาะอาหาร", "ถูก"]'::jsonb,'{"img": "bio-69-13.png", "after": "นาย ก ข ค ง และ จ รับประทานอาหารดังต่อไปนี้\nนาย ก ดื่มกลูโคสตามคำสั่งของแพทย์\nนาย ข ดื่มน้ำอ้อยเพื่อดับกระหายระหว่างทำงานในไร่\nนาย ค รับประทานข้าวหมูทอดก่อนไปทำงาน\nนาย ง รับประทานไข่ต้มเป็นอาหารเช้า\nนาย จ รับประทานสลัดผักราดน้ำมันมะกอกทุกวันในช่วงเทศกาลกินเจ\nข้อใดถูกต้อง", "topic": "3.1", "n": 13, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/bio-69-13.png"}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'bio:69-13');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-14','M6','M6-BI','M6-BI-S3','A-Level 66',null,2,'กำหนดให้ A B C และ D เป็นอวัยวะในระบบสืบพันธุ์ของมนุษย์เพศหญิง ซึ่งมีตำแหน่งเชื่อมโยงกัน ดังแผนภาพ','["ที่อวัยวะ B มีการพัฒนาของไซโกตไปเป็นฟีตัส และที่อวัยวะ C มีการพัฒนาของฟีตัสไปเป็นเอ็มบริโอ", "กระบวนการคลีเวจเกิดขึ้นที่อวัยวะ B ส่วนกระบวนการแกสทรูเลชัน และกระบวนการออแกโนเจเนซิสเกิดขึ้นที่อวัยวะ C", "ที่อวัยวะ A โอโอไซต์ระยะที่สอง มีการแบ่งเซลล์แบบไมโอซิส II จนเสร็จสมบูรณ์แล้วพัฒนาเป็นเซลล์ไข่เพื่อเกิดการตกไข่ต่อไป", "การทำหมันคือการตัดอวัยวะ D ให้ขาดออกจากกัน เพื่อเป็นการตัดเส้นทางไม่ให้เซลล์สืบพันธุ์เพศผู้เดินทางไปถึงเซลล์สืบพันธุ์เพศเมียได้", "การปฏิสนธิสามารถเกิดขึ้นได้ที่อวัยวะ B เท่านั้น และหากไม่มีการปฏิสนธิเกิดขึ้นเนื้อเยื่อของอวัยวะ C และ D จะสลายและหลุดลอกกลายเป็นประจำเดือน"]'::jsonb,1,array[1]::smallint[],'["A = รังไข่ · B = ท่อนำไข่ · C = มดลูก · D = ช่องคลอด · ไซโกตเกิดคลีเวจระหว่างเคลื่อนที่ในท่อนำไข่ แล้วฝังตัวในมดลูก ซึ่งเกิดแกสทรูเลชันและออแกโนเจเนซิส"]'::jsonb,'["ไม่ถูก ลำดับคือไซโกต → เอ็มบริโอ → ฟีตัส และส่วนใหญ่พัฒนาในมดลูก", "ถูก", "ไม่ถูก ไมโอซิส II จะเสร็จสมบูรณ์เมื่อมีการปฏิสนธิ ซึ่งเกิดหลังการตกไข่", "ไม่ถูก การทำหมันหญิงตัดหรือผูกท่อนำไข่ (B) ไม่ใช่ D", "ไม่ถูก ประจำเดือนมาจากการหลุดลอกของผนังมดลูก (C) เท่านั้น ไม่ใช่ D"]'::jsonb,'{"img": "bio-69-14.png", "after": "ข้อใดถูกต้อง", "topic": "3.7", "n": 14, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/bio-69-14.png"}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'bio:69-14');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-15','M6','M6-BI','M6-BI-S3','A-Level 66',null,2,'จากแผนภาพการกำจัดของเสียในร่างกายมนุษย์ที่มีสุขภาพปกติ
กำหนดให้ A B และ C คือโครงสร้างภายในไต','["ที่บริเวณ A มีการกรองและการดูดกลับเกิดขึ้น", "ที่บริเวณ B มีการลำเลียงสารทั้งแบบแอกทีฟทรานสปอร์ต และแบบออสโมซิส", "เมื่อเลือดมีความเป็นกรดสูงจะมีการหลั่งไอออนบวกจากหลอดเลือดเข้าสู่บริเวณ A", "ไม่พบโปรตีนขนาดใหญ่ที่บริเวณ C เนื่องจากถูกดูดกลับเข้าหลอดเลือดได้หมดที่บริเวณ B", "เมื่อดื่มน้ำในปริมาณมากจะกระตุ้นการหลั่ง ADH จากต่อมใต้สมองส่วนหลัง ทำให้ C ดูดกลับน้ำเพิ่มขึ้น"]'::jsonb,1,array[1]::smallint[],'["A = โกลเมอรูลัสและโบว์แมนแคปซูล · B = ห่วงเฮนเล · C = ท่อรวม · ห่วงเฮนเลขาขึ้นลำเลียง Na⁺ Cl⁻ แบบแอกทีฟ ส่วนขาลงให้น้ำออกโดยออสโมซิส"]'::jsonb,'["ไม่ถูก A มีเฉพาะการกรอง การดูดกลับเกิดที่ท่อหน่วยไต", "ถูก", "ไม่ถูก H⁺ ถูกหลั่งเข้าสู่ท่อหน่วยไต (ส่วนต้นและส่วนปลาย) ไม่ใช่ที่ A", "ไม่ถูก โปรตีนขนาดใหญ่กรองผ่านโกลเมอรูลัสไม่ได้ตั้งแต่แรก", "ไม่ถูก ดื่มน้ำมากทำให้การหลั่ง ADH ลดลง และดูดน้ำกลับน้อยลง"]'::jsonb,'{"img": "bio-69-15.png", "after": "ข้อใดถูกต้อง", "topic": "3.4", "n": 15, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/bio-69-15.png"}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'bio:69-15');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-16','M6','M6-BI','M6-BI-S3','A-Level 66',null,2,'จากตารางแสดงผลของการขาดฮอร์โมน และผลของการมีฮอร์โมนมากเกินไป','["การสร้างฮอร์โมน A ที่ต่อมใต้สมองส่วนหน้าไม่ถูกควบคุมโดยฮอร์โมนที่สร้างจากไฮโพทาลามัส", "เมื่อร่างกายขาดไอโอดีนจะทำให้ต่อมไทรอยด์ไม่สามารถสร้างฮอร์โมน B ได้ทำให้เป็นโรคคอพอกเป็นพิษ", "ฮอร์โมน C เกี่ยวข้องกับการสะสมไกลโคเจนที่ตับและกล้ามเนื้อ การหลั่งฮอร์โมน C ถูกกระตุ้นโดยฮอร์โมนที่สร้างจากต่อมใต้สมองส่วนหน้า", "D เป็นฮอร์โมนที่สร้างจากต่อมใต้สมองส่วนหลัง ทำหน้าที่กระตุ้นการหดตัวของกล้ามเนื้อผนังมดลูกขณะคลอด", "E เป็นฮอร์โมนที่สร้างจากต่อมพาราไทรอยด์ การหลั่งฮอร์โมน E ทำให้มีการดูดกลับแคลเซียมในไตเพิ่มขึ้น และมีการดูดซึมแคลเซียมในลำไส้เล็กเพิ่มขึ้น"]'::jsonb,4,array[4]::smallint[],'["A = โกรทฮอร์โมน · B = ไทรอกซิน · C = อินซูลิน · D = ออกซิโทซิน · E = พาราทอร์โมน ซึ่งเพิ่มแคลเซียมในเลือดโดยเพิ่มการดูดกลับที่ไตและการดูดซึมที่ลำไส้ (ผ่านวิตามิน D)"]'::jsonb,'["ไม่ถูก การหลั่งโกรทฮอร์โมนถูกควบคุมโดยฮอร์โมนจากไฮโพทาลามัส", "ไม่ถูก การขาดไอโอดีนทำให้เป็นคอพอกธรรมดา ไม่ใช่คอพอกเป็นพิษ", "ไม่ถูก การหลั่งอินซูลินถูกกระตุ้นโดยระดับกลูโคสในเลือด ไม่ใช่ฮอร์โมนจากต่อมใต้สมองส่วนหน้า", "ไม่ถูก ออกซิโทซินสร้างที่ไฮโพทาลามัส แล้วหลั่งจากต่อมใต้สมองส่วนหลัง", "ถูก"]'::jsonb,'{"table": [["ฮอร์โมน", "ผลของการขาดฮอร์โมน", "ผลของการมีฮอร์โมนมากเกินไป"], ["A", "?", "อะโครเมกาลี"], ["B", "มิกซีดีมา", "?"], ["C", "เบาหวาน", "?"], ["D", "ไม่มีการขับน้ำนม", "?"], ["E", "?", "แคลเซียมในเลือดสูง"]], "after": "ข้อใดถูกต้อง", "topic": "3.8", "n": 16}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'bio:69-16');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-17','M6','M6-BI','M6-BI-S3','A-Level 66',null,2,'ข้อใดกล่าวเกี่ยวกับฮอร์โมนและสารเคมีที่ใช้สื่อสารระหว่างเซลล์ได้ถูกต้อง','["ตับอ่อน กระเพาะอาหาร ลำไส้เล็ก และรก เป็นอวัยวะที่สามารถสร้างฮอร์โมนได้", "ฮอร์โมนและสารสื่อประสาทถูกลำเลียงไปยังเป้าหมายผ่านระบบหมุนเวียนเลือดเช่นเดียวกัน", "ฮอร์โมนไทรอกซินในกบมีหน้าที่เกี่ยวข้องกับการเจริญเติบโต โดยกระตุ้นกระบวนการพาร์ธีโนเจเนซิส", "ฮอร์โมนเอพิเนฟรินจะจับกับตัวรับที่อยู่ภายในเซลล์ ส่วนฮอร์โมนอีสโทรเจนจะจับกับตัวรับอยู่บริเวณเยื่อหุ้มเซลล์", "ฟีโรโมนไม่มีผลต่อร่างกายของสัตว์ตัวที่สร้างฟีโรโมนเอง แต่มีผลต่อสัตว์ตัวอื่นทั้งที่เป็นสปีชีส์เดียวกัน และต่างสปีชีส์"]'::jsonb,0,array[0]::smallint[],'["ตับอ่อนสร้างอินซูลินและกลูคากอน กระเพาะอาหารสร้างแกสตริน ลำไส้เล็กสร้างซีเครทิน และรกสร้าง hCG"]'::jsonb,'["ถูก", "ไม่ถูก สารสื่อประสาทแพร่ข้ามช่องไซแนปส์ ไม่ได้ไปทางเลือด", "ไม่ถูก ไทรอกซินในกบกระตุ้นเมทามอร์โฟซิส ไม่ใช่พาร์ธีโนเจเนซิส", "ไม่ถูก สลับกัน เอพิเนฟรินจับตัวรับที่เยื่อหุ้มเซลล์ อีสโทรเจน (สเตรอยด์) จับตัวรับภายในเซลล์", "ไม่ถูก ฟีโรโมนมีผลต่อสัตว์สปีชีส์เดียวกัน"]'::jsonb,'{"topic": "3.8", "n": 17}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'bio:69-17');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-18','M6','M6-BI','M6-BI-S3','A-Level 66',null,2,'นักวิทยาศาสตร์ได้ออกแบบลิ้นหัวใจเทียมแบบใหม่ เพื่อใช้สำหรับผู้ป่วยที่ลิ้นหัวใจไบคัสปิด (bicuspid valve) ผิดปกติ ลิ้นหัวใจเทียมนี้ต้องมีคุณลักษณะดังข้อใด','["ลิ้นหัวใจจะต้องปิด เมื่อเอเทรียม (atrium) บีบตัว เพื่อป้องกันเลือดไหลย้อนกลับเข้าสู่ปอด", "ลิ้นหัวใจจะต้องปิด เมื่อเวนทริเคิล (ventricle) บีบตัว เพื่อให้เลือดไหลเข้าสู่เอออร์ตา (aorta)", "ลิ้นหัวใจจะต้องเปิด เมื่อเวนทริเคิล (ventricle) บีบตัว เพื่อให้เลือดไหลเข้าสู่เอออร์ตา (aorta)", "ลิ้นหัวใจจะต้องปิดเมื่อเวนทริเคิล (ventricle) คลายตัวเพื่อกักเก็บเลือดไว้ในเอออร์ตา (aorta)", "ลิ้นหัวใจจะต้องเปิดอยู่เสมอ เพื่อให้เลือดไหลเวียนได้อย่างอิสระระหว่างเอเทรียม (atrium) และเวนทริเคิล (ventricle)"]'::jsonb,1,array[1]::smallint[],'["ลิ้นไบคัสปิดอยู่ระหว่างเอเทรียมซ้ายกับเวนทริเคิลซ้าย เมื่อเวนทริเคิลบีบตัวลิ้นต้องปิด เพื่อไม่ให้เลือดย้อนเข้าเอเทรียม และให้เลือดออกไปทางเอออร์ตา"]'::jsonb,'["ไม่ถูก ขณะเอเทรียมบีบตัว ลิ้นต้องเปิดให้เลือดลงเวนทริเคิล", "ถูก", "ไม่ถูก ถ้าเปิด เลือดจะย้อนกลับเข้าเอเทรียมซ้าย (ลิ้นที่เปิดสู่เอออร์ตาคือลิ้นเซมิลูนาร์)", "ไม่ถูก การกันเลือดย้อนจากเอออร์ตาเป็นหน้าที่ของลิ้นเซมิลูนาร์ และไบคัสปิดเปิดขณะเวนทริเคิลคลายตัว", "ไม่ถูก ถ้าเปิดตลอด เลือดจะไหลย้อนกลับ"]'::jsonb,'{"topic": "3.2", "n": 18}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'bio:69-18');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-19','M6','M6-BI','M6-BI-S3','A-Level 66',null,2,'หากแพทย์เจาะเลือดจากหลอดเลือดดำของมนุษย์แล้วนำเลือดใส่ในหลอดที่มีสารป้องกันการแข็งตัวของเลือด (anticoagulant) แล้วนำไปปั่นแยก ได้เป็น 3 ส่วน (A B และ C) ดังภาพ','["ก. ข. และ ค. เท่านั้น", "ก. ค. และ จ. เท่านั้น", "ข. ง. และ จ. เท่านั้น", "ค. ง. และ จ. เท่านั้น", "ก. ข. ค. และ จ. เท่านั้น"]'::jsonb,1,array[1]::smallint[],'["A = พลาสมา · B = เม็ดเลือดขาวและเพลตเลต · C = เม็ดเลือดแดง · พลาสมามียูเรีย อัลบูมิน และอิมมูโนโกลบูลิน · สารป้องกันการแข็งตัวทำให้ไม่เกิดไฟบริน (ยังเป็นไฟบริโนเจน)"]'::jsonb,'["ไม่ถูก ไม่มีไฟบริน", "ถูก", "ไม่ถูก เม็ดเลือดแดงอยู่ในส่วน C และไม่มีไฟบริน", "ไม่ถูก เม็ดเลือดแดงอยู่ในส่วน C", "ไม่ถูก ไม่มีไฟบริน"]'::jsonb,'{"img": "bio-69-19.png", "after": "พิจารณาองค์ประกอบของเลือดต่อไปนี้\nก. ยูเรีย (urea)\nข. ไฟบริน (fibrin)\nค. อัลบูมิน (albumin)\nง. เม็ดเลือดแดง (erythrocyte)\nจ. อิมมูโนโกลบูลิน (immunoglobulin)\nข้อใดที่พบได้ในส่วน A", "topic": "3.2", "n": 19, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/bio-69-19.png"}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2569,'bio:69-19');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-20','M6','M6-BI','M6-BI-S3','A-Level 66',null,2,'พิจารณาสถานการณ์ต่อไปนี้
นาย ก และนาย ข เป็นผู้ติดเชื้อ HIV (human immunodeficiency virus) โดย
นาย ก ได้รับยา tenofovir ซึ่งเป็นยาต้านไวรัส HIV ที่ออกฤทธิ์ยับยั้งกระบวนการถอดรหัสย้อนกลับ (reverse transcription) ส่งผลให้ นาย ก มีระดับเซลล์ทีชนิด CD4 (helper T cell) อยู่ในเกณฑ์ปกติ และไม่มีโรคแทรกซ้อนใด ๆ
นาย ข ไม่ได้รับยา tenofovir ส่งผลให้ นาย ข มีระดับเซลล์ทีชนิด CD4 ต่ำกว่าเกณฑ์เป็นโรคปอดอักเสบและมีเชื้อราในช่องปาก
ข้อใดถูกต้อง','["นาย ก ไม่เป็นโรคเอดส์ ส่วนนาย ข เป็นโรคเอดส์ เพราะนาย ข ติดเชื้อ HIV และมีระดับเซลล์ทีชนิด CD4 ต่ำ", "นาย ก สามารถหยุดกินยาต้านไวรัสได้ด้วยตนเอง เพราะไม่มีอาการใด ๆ", "นาย ข ติดเชื้อฉวยโอกาส เพราะเชื้อ HIV ผลิตสารพิษไปกดการทำงานของไขกระดูกโดยตรง", "นาย ก มีระดับเซลล์ทีชนิด CD4 ปกติ เพราะยา tenofovir ยับยั้งไม่ให้เชื้อ HIV เข้าสู่เซลล์ทีชนิด CD4 ได้ตั้งแต่แรก", "หากเจาะเลือดตรวจแอนติบอดี (antibody) ต่อเชื้อ HIV นาย ก จะมีแอนติบอดีสูงกว่านาย ข เพราะเซลล์ทีชนิด CD4 ทำหน้าที่ผลิตแอนติบอดี"]'::jsonb,0,array[0]::smallint[],'["โรคเอดส์คือระยะที่ติดเชื้อ HIV แล้วเซลล์ที CD4 ลดต่ำจนเกิดโรคติดเชื้อฉวยโอกาส นาย ข เข้าเกณฑ์นี้ ส่วนนาย ก ติดเชื้อแต่ควบคุมได้ด้วยยา"]'::jsonb,'["ถูก", "ไม่ถูก ต้องกินยาต่อเนื่องตามแพทย์สั่ง ยาไม่ได้กำจัดเชื้อให้หมด หยุดยาแล้วไวรัสจะเพิ่มจำนวนอีก", "ไม่ถูก HIV ทำลายเซลล์ที CD4 ทำให้ภูมิคุ้มกันบกพร่อง ไม่ได้ผลิตสารพิษกดไขกระดูก", "ไม่ถูก ยานี้ยับยั้งการถอดรหัสย้อนกลับหลังไวรัสเข้าเซลล์แล้ว ไม่ได้ยับยั้งการเข้าเซลล์", "ไม่ถูก แอนติบอดีสร้างจากเซลล์พลาสมา (เซลล์บี) ไม่ใช่เซลล์ที CD4"]'::jsonb,'{"topic": "3.3", "n": 20}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'bio:69-20');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-21','M6','M6-BI','M6-BI-S3','A-Level 66',null,2,'พิจารณาสถานการณ์ต่อไปนี้
ชายไทยวัย 30 ปี มีอาการชาที่ริมฝีปาก ปลายมือและเท้า เวียนศีรษะ หลังรับประทานหมึกผัดไข่เค็มไป 30 นาที ต่อมามีอาการหายใจลำบากและแขนขาอ่อนแรงจนขยับไม่ได้ เมื่อถึงโรงพยาบาลพบว่าหัวใจเต้นช้าลง จากการตรวจสอบอาหารพบหมึกบลูริง (Hapalochlaena sp.) ซึ่งมีสารพิษเทโทรโดท็อกซิน (tetrodotoxin) สารพิษนี้ออกฤทธิ์ยับยั้งการทำงานของช่องโซเดียมที่มีประตู (voltage-gated sodium channel) บนเยื่อหุ้มเซลล์ประสาท
ข้อใดถูกต้อง','["สารพิษนี้กระตุ้นการหลั่งสารสื่อประสาทอะเซทิลโคลีน (acetylcholine) จึงเกิดอาการเวียนศีรษะ", "สารพิษนี้กระตุ้นระบบประสาทซิมพาเทติก (sympathetic nervous system) อย่างรุนแรง จึงส่งผลให้หัวใจเต้นช้าลง", "สารพิษนี้ทำให้โซเดียมไอออน (Na⁺) ไม่สามารถเข้าสู่แอกซอน (axon) ของเซลล์ประสาทสั่งการ (motor neuron) เมื่อถูกกระตุ้นได้จึงสั่งการให้ขยับแขนขาไม่ได้", "สารพิษนี้ทำให้โพแทสเซียมไอออน (K⁺) ไม่สามารถออกจากเซลล์ประสาทได้ เป็นการรบกวนระยะรีโพลาไรเซชัน (repolarization) โดยตรง จึงทำให้หายใจลำบาก", "สารพิษนี้ขัดขวางการทำงานของเซลล์ประสาทรับความรู้สึก (sensory neuron) บริเวณเดนไดรต์ (dendrite) โดยตรง ทำให้เซลล์ไม่ตอบสนองต่อสิ่งเร้า จึงเกิดอาการชา"]'::jsonb,2,array[2]::smallint[],'["เทโทรโดท็อกซินปิดกั้นช่องโซเดียมที่มีประตู Na⁺ จึงเข้าแอกซอนไม่ได้ ไม่เกิดดีโพลาไรเซชันและกระแสประสาท เซลล์ประสาทสั่งการจึงสั่งกล้ามเนื้อไม่ได้"]'::jsonb,'["ไม่ถูก สารพิษไม่ได้กระตุ้นการหลั่งสารสื่อประสาท แต่ยับยั้งการเกิดกระแสประสาท", "ไม่ถูก การกระตุ้นซิมพาเทติกทำให้หัวใจเต้นเร็วขึ้น และสารพิษนี้ไม่ได้กระตุ้นระบบประสาท", "ถูก", "ไม่ถูก สารพิษออกฤทธิ์ที่ช่องโซเดียม ไม่ใช่ช่องโพแทสเซียม", "ไม่ถูก สารพิษยับยั้งช่องโซเดียมบนเยื่อหุ้มแอกซอนทั่วไป ไม่ได้ออกฤทธิ์เฉพาะที่เดนไดรต์"]'::jsonb,'{"topic": "3.6", "n": 21}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'bio:69-21');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-22','M6','M6-BI','M6-BI-S3','A-Level 66',null,2,'นาย ก ฝึกขอมือสุนัข โดยนาย ก จะยื่นฝ่ามือไปข้างหน้าพร้อมพูดว่า “ขอมือ” แล้วทุกครั้งที่สุนัขวางเท้าหน้าบนฝ่ามือ นาย ก จะให้อาหารเม็ดแก่สุนัข
การฝึกสุนัขของ นาย ก อาศัยพฤติกรรมแบบใดของสัตว์','["การฝังใจ (imprinting)", "แฮบิชูเอชัน (habituation)", "พฤติกรรมที่เป็นมาแต่กำเนิด (innate behavior)", "การเชื่อมโยงแบบมีเงื่อนไข (classical conditioning)", "การเชื่อมโยงแบบลองผิดลองถูก (operant conditioning)"]'::jsonb,4,array[4]::smallint[],'["สุนัขทำพฤติกรรม (วางเท้า) แล้วได้รางวัล จึงเรียนรู้ที่จะทำซ้ำ เป็นการเรียนรู้แบบลองผิดลองถูก"]'::jsonb,'["ไม่ถูก การฝังใจเกิดช่วงแรกเกิดโดยไม่ต้องมีรางวัล", "ไม่ถูก แฮบิชูเอชันคือการเลิกตอบสนองต่อสิ่งเร้าที่ซ้ำ ๆ", "ไม่ถูก พฤติกรรมนี้เกิดจากการฝึก ไม่ใช่มีมาแต่กำเนิด", "ไม่ถูก แบบมีเงื่อนไขเป็นการจับคู่สิ่งเร้ากับรีเฟล็กซ์ (เช่น น้ำลายไหล) โดยไม่ขึ้นกับการกระทำของสัตว์", "ถูก"]'::jsonb,'{"topic": "3.9", "n": 22}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'bio:69-22');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-23','M6','M6-BI','M6-BI-S3','A-Level 66',null,2,'พิจารณาสถานการณ์ต่อไปนี้
นาย ก ทำงานในห้องเย็นปิดทึบที่มีการใช้น้ำแข็งแห้ง วันหนึ่งนาย ก ลืมปิดภาชนะเก็บน้ำแข็งแห้ง ทำให้น้ำแข็งแห้งระเหิดเป็นแก๊สคาร์บอนไดออกไซด์ (CO₂) ฟุ้งเต็มห้อง หลังจากนั้นครึ่งชั่วโมง นาย ก มีอาการปวดศีรษะ หายใจถี่ขึ้น หัวใจเต้นเร็วขึ้น
ข้อใดกล่าวเกี่ยวกับการเปลี่ยนแปลงของระบบร่างกายนาย ก ได้ถูกต้อง','["pH ของเลือดเพิ่มสูงขึ้น", "ความเข้มข้นของ HCO₃⁻ ในเลือดเพิ่มสูงขึ้น", "ความดันย่อยของ CO₂ ในเลือด (PCO₂) ลดต่ำลง", "ศูนย์ควบคุมการหายใจบริเวณทาลามัส (thalamus) สั่งการให้หายใจถี่ขึ้น", "อัตราการเกิดปฏิกิริยา H₂CO₃ → CO₂ + H₂O ด้วยเอนไซม์คาร์บอกซิเลส (carboxylase) ในเซลล์เม็ดเลือดแดงเพิ่มขึ้น"]'::jsonb,1,array[1]::smallint[],'["หายใจเอา CO₂ เข้าไปมาก ทำให้ CO₂ + H₂O → H₂CO₃ → H⁺ + HCO₃⁻ เพิ่มขึ้น ความเข้มข้นของ HCO₃⁻ และ H⁺ ในเลือดจึงสูงขึ้น"]'::jsonb,'["ไม่ถูก H⁺ เพิ่มขึ้น pH จึงลดลง", "ถูก", "ไม่ถูก PCO₂ ในเลือดเพิ่มขึ้น", "ไม่ถูก ศูนย์ควบคุมการหายใจอยู่ที่เมดัลลาออบลองกาตาและพอนส์", "ไม่ถูก ปฏิกิริยาที่เพิ่มขึ้นคือ CO₂ + H₂O → H₂CO₃ และเอนไซม์คือคาร์บอนิกแอนไฮเดรส"]'::jsonb,'{"topic": "3.5", "n": 23}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'bio:69-23');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-24','M6','M6-BI','M6-BI-S4','A-Level 66',null,2,'จากภาพภาคตัดขวางของแผ่นใบพืชใบเลี้ยงคู่ ที่เจริญอยู่ในสภาพแวดล้อมที่มีความชื้นปานกลาง','["A คือชั้นคิวทิเคิล (cuticle) – หนาในพืชทนแล้ง เพื่อลดการสูญเสียน้ำ\nF คือปากใบ (stoma) – พบทางด้านล่างของใบในพืชน้ำ เพื่อลดการคายน้ำ", "B คือเนื้อเยื่อชั้นผิวใบด้านบน (upper epidermis) – มีปากใบจำนวนมากในพืชทนแล้ง เพื่อช่วยระบายความร้อน\nC คือสปองจีมีโซฟิลล์ (spongy mesophyll) – พบเฉพาะในพืชน้ำ เพื่อรับแสงจากทุกทิศทาง", "D คือมัดท่อลำเลียง (vascular bundle) – มีขนาดใหญ่ในพืชน้ำ เพื่อช่วยพยุงลำต้นให้ลอยน้ำ\nF คือปากใบ (stoma) – พบทางด้านบนของใบในพืชทนแล้ง เพื่อรับแสงได้มากขึ้น", "A คือชั้นคิวทิเคิล (cuticle) – บางมากหรือแทบไม่มีในพืชน้ำ เพื่อแลกเปลี่ยนแก๊สได้สะดวก\nE คือสปองจีมีโซฟิลล์ (spongy mesophyll) – มีช่องอากาศขนาดใหญ่ เพื่อช่วยในการลอยตัวของพืชน้ำและการแลกเปลี่ยนแก๊ส", "B คือเซลล์ผิว (epidermal cell) – มีคลอโรพลาสต์จำนวนมาก เพื่อสังเคราะห์ด้วยแสง\nE คือมัดท่อลำเลียง (vascular bundle) – อยู่ติดกับเนื้อเยื่อชั้นผิวของใบ เพื่อรับแสงและทำหน้าที่ลำเลียงน้ำและอาหาร"]'::jsonb,3,array[3]::smallint[],'["A = คิวทิเคิล · B = เอพิเดอร์มิสด้านบน · C = แพลิเสดมีโซฟิลล์ · D = มัดท่อลำเลียง · E = สปองจีมีโซฟิลล์ · F = ปากใบ (ด้านล่างของใบ) · พืชน้ำมีคิวทิเคิลบางมาก และมีช่องอากาศใหญ่ช่วยลอยตัว"]'::jsonb,'["ไม่ถูก ส่วน A ถูก แต่พืชที่ใบลอยน้ำมีปากใบด้านบนของใบ", "ไม่ถูก พืชทนแล้งมีปากใบน้อยและมักอยู่ด้านล่าง และ C คือแพลิเสดมีโซฟิลล์", "ไม่ถูก พืชน้ำมีเนื้อเยื่อลำเลียงน้อย และพืชทนแล้งไม่มีปากใบด้านบนมาก", "ถูก", "ไม่ถูก เซลล์เอพิเดอร์มิสส่วนใหญ่ไม่มีคลอโรพลาสต์ และ E คือสปองจีมีโซฟิลล์"]'::jsonb,'{"img": "bio-69-24.png", "after": "ข้อใดระบุชื่อส่วนประกอบและอธิบายการปรับตัวของโครงสร้างนั้นในสภาพแวดล้อมแบบอื่นได้ถูกต้องทั้งหมด", "topic": "4.1", "n": 24, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/bio-69-24.png"}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'bio:69-24');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-25','M6','M6-BI','M6-BI-S4','A-Level 66',null,2,'ข้อใดอธิบายความสัมพันธ์ระหว่างระยะสปอโรไฟต์และแกมีโทไฟต์ของพืช ได้ถูกต้อง','["สปอโรไฟต์เป็นระยะที่มีจำนวนโครโมโซมเป็น n สร้างเซลล์สืบพันธุ์โดยกระบวนการแบ่งเซลล์แบบไมโอซิส", "สปอโรไฟต์เป็นระยะที่มีจำนวนโครโมโซมเป็น 2n สร้างสปอร์โดยกระบวนการแบ่งเซลล์แบบไมโอซิส ซึ่งสปอร์จะเจริญเป็นแกมีโทไฟต์", "แกมีโทไฟต์เป็นระยะที่มีจำนวนโครโมโซมเป็น 2n สร้างสปอร์โดยกระบวนการแบ่งเซลล์แบบไมโทซิส ซึ่งจะเจริญเป็นสปอโรไฟต์", "แกมีโทไฟต์เป็นระยะที่มีจำนวนโครโมโซมเป็น n สร้างเซลล์สืบพันธุ์โดยกระบวนการแบ่งเซลล์แบบไมโอซิส ซึ่งรวมกันเป็นสปอโรไฟต์", "สปอโรไฟต์และแกมีโทไฟต์มีจำนวนโครโมโซมเท่ากัน และต่างก็สร้างสปอร์โดยกระบวนการแบ่งเซลล์แบบไมโอซิส"]'::jsonb,1,array[1]::smallint[],'["สปอโรไฟต์ (2n) สร้างสปอร์ (n) ด้วยไมโอซิส สปอร์เจริญเป็นแกมีโทไฟต์ (n) ซึ่งสร้างเซลล์สืบพันธุ์ด้วยไมโทซิส"]'::jsonb,'["ไม่ถูก สปอโรไฟต์เป็น 2n และสร้างสปอร์ ไม่ใช่เซลล์สืบพันธุ์", "ถูก", "ไม่ถูก แกมีโทไฟต์เป็น n และสร้างเซลล์สืบพันธุ์", "ไม่ถูก แกมีโทไฟต์สร้างเซลล์สืบพันธุ์ด้วยไมโทซิส", "ไม่ถูก ทั้งสองระยะมีจำนวนโครโมโซมต่างกัน (2n กับ n)"]'::jsonb,'{"topic": "4.4", "n": 25}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'bio:69-25');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-26','M6','M6-BI','M6-BI-S4','A-Level 66',null,2,'พิจารณาข้อความเกี่ยวกับลักษณะโครงสร้างลำต้นพืชในระยะปฐมภูมิและทุติยภูมิ ต่อไปนี้
ก. ลำต้นพืชใบเลี้ยงคู่ในระยะปฐมภูมิ จะมีมัดท่อลำเลียงเรียงเป็นวงอย่างเป็นระเบียบ และมีเนื้อเยื่อพื้นแทรกระหว่างมัดท่อลำเลียง
ข. ลำต้นพืชใบเลี้ยงเดี่ยวทุกชนิด จะมีมัดท่อลำเลียงกระจายทั่วลำต้น และเกิดการเจริญทุติยภูมิเพราะมีวาสคิวลาร์แคมเบียม
ค. ลำต้นพืชที่มีการเจริญทุติยภูมิ จะมีการสร้างไซเล็มทุติยภูมิเข้าด้านใน และสร้างโฟลเอ็มทุติยภูมิออกด้านนอก
ง. คอร์กแคมเบียม สร้างเซลล์คอร์กที่มีผนังเซลล์หนา ทำหน้าที่ป้องกันการสูญเสียน้ำของลำต้น
จ. ลำต้นที่มีการเจริญทุติยภูมิ จะมีวงปีของเนื้อไม้เนื่องจากอัตราการสร้างไซเล็มทุติยภูมิเท่ากันในทุกฤดูกาล
ข้อใดถูกต้อง','["ก. และ ข. เท่านั้น", "ข. และ ค. เท่านั้น", "ค. และ จ. เท่านั้น", "ก. ค. และ ง. เท่านั้น", "ค. ง. และ จ. เท่านั้น"]'::jsonb,3,array[3]::smallint[],'["ก ค ง ถูก · ข ผิด พืชใบเลี้ยงเดี่ยวส่วนใหญ่ไม่มีวาสคิวลาร์แคมเบียม จึงไม่มีการเจริญทุติยภูมิแบบนี้ · จ ผิด วงปีเกิดเพราะอัตราการสร้างไซเล็มต่างกันในแต่ละฤดู"]'::jsonb,'["ไม่ถูก ข ผิด", "ไม่ถูก ข ผิด", "ไม่ถูก จ ผิด", "ถูก", "ไม่ถูก จ ผิด"]'::jsonb,'{"topic": "4.1", "n": 26}'::jsonb,'imported_m6','imported',true,'labelseq','Exam Gym ม.6 · 5620e4c',2569,'bio:69-26');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-27','M6','M6-BI','M6-BI-S4','A-Level 66',null,2,'จากการทดลองเรื่องความสำคัญของธาตุอาหารหลัก (macronutrient) ในต้นแตงกวา พิจารณาข้อมูลด้านล่างนี้
ความสำคัญของธาตุอาหารพืช
ธาตุ ก. เป็นองค์ประกอบของกรดแอมิโนและนิวคลีโอไทด์
ธาตุ ข. เป็นธาตุหลักที่เกี่ยวข้องกับการควบคุมความเต่งของเซลล์และการปิดเปิดของรูปากใบ
ธาตุ ค. เป็นองค์ประกอบของ ATP และเยื่อหุ้มเซลล์
อาการที่พืชแสดงออกเมื่อขาดธาตุ
อาการ ง. ขอบใบและปลายใบไหม้ เนื้อเยื่อตายเป็นจุด ๆ และแสดงอาการที่ใบล่างก่อน
อาการ จ. ใบเหลืองโดยแสดงที่ใบล่างก่อน ลำต้นแคระ การเติบโตของรากลดลง
อาการ ฉ. ใบมีสีเหลืองทั้งใบทุกใบ และแสดงอาการที่ใบล่างก่อน
ข้อใดจับคู่ระหว่างความสำคัญของธาตุอาหารกับอาการที่พืชแสดงออกเมื่อขาดธาตุนั้น ๆ ได้ถูกต้อง','["ก. และ ง.; ข. และ ฉ.; ค. และ จ.", "ก. และ ง.; ข. และ จ.; ค. และ ฉ.", "ก. และ จ.; ข. และ ฉ.; ค. และ ง.", "ก. และ ฉ.; ข. และ ง.; ค. และ จ.", "ก. และ ฉ.; ข. และ จ.; ค. และ ง."]'::jsonb,3,array[3]::smallint[],'["ก = ไนโตรเจน ขาดแล้วใบเหลืองทั้งใบเริ่มที่ใบล่าง (ฉ) · ข = โพแทสเซียม ขาดแล้วขอบใบและปลายใบไหม้ (ง) · ค = ฟอสฟอรัส ขาดแล้วต้นแคระและรากเจริญน้อย (จ)"]'::jsonb,'["ไม่ถูก อาการขอบใบไหม้ (ง) เป็นของโพแทสเซียม ไม่ใช่ไนโตรเจน", "ไม่ถูก", "ไม่ถูก", "ถูก", "ไม่ถูก อาการขอบใบไหม้ (ง) เป็นของโพแทสเซียม (ข) ไม่ใช่ฟอสฟอรัส"]'::jsonb,'{"topic": "4.2", "n": 27}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'bio:69-27');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-28','M6','M6-BI','M6-BI-S4','A-Level 66',null,2,'พิจารณาข้อความเกี่ยวกับกลไกการลำเลียงซูโครสในโฟลเอ็มของพืชดอก ดังต่อไปนี้
ก. ซูโครสเคลื่อนที่ออกจากซีฟทิวบ์เมมเบอร์เข้าสู่เซลล์ในเนื้อเยื่อบริเวณแหล่งรับ ทำให้ความเข้มข้นของสารละลายในซีฟทิวบ์เมมเบอร์ลดลง ชลศักย์จึงสูงขึ้น
ข. น้ำจากซีฟทิวบ์เมมเบอร์จึงเคลื่อนที่ออกสู่เซลล์ข้างเคียงและเวสเซลเมมเบอร์โดยออสโมซิส ทำให้ความดันในซีฟทิวบ์เมมเบอร์บริเวณแหล่งรับต่ำลง ซึ่งยังคงมีความแตกต่างของความดันในซีฟทิวบ์เมมเบอร์ระหว่างบริเวณแหล่งสร้างกับแหล่งรับ การลำเลียงสารในโฟลเอ็มจึงเกิดอย่างต่อเนื่อง
ค. ซูโครสออกจากแหล่งสร้างสู่ซีฟทิวบ์เมมเบอร์ จึงทำให้ค่าชลศักย์ในซีฟทิวบ์เมมเบอร์ต่ำลง
ง. ความดันที่สูงขึ้นทำให้สารละลายในซีฟทิวบ์เมมเบอร์ซึ่งมีซูโครสอยู่ เคลื่อนที่จากซีฟทิวบ์เมมเบอร์บริเวณแหล่งสร้าง ไปยังซีฟทิวบ์เมมเบอร์บริเวณแหล่งรับที่มีความดันต่ำกว่า
จ. น้ำจากเซลล์ข้างเคียงและเวสเซลเมมเบอร์ซึ่งมีค่าชลศักย์สูงกว่า จะเข้าสู่ซีฟทิวบ์เมมเบอร์โดยออสโมซิส ทำให้ความดันในซีฟทิวบ์เมมเบอร์บริเวณแหล่งสร้างอาหารสูงขึ้น
ข้อใดเรียงลำดับการลำเลียงซูโครสในโฟลเอ็มของพืชดอก จากแหล่งสร้างไปยังแหล่งรับได้ถูกต้อง','["ค. ง. ก. ข. และ จ.", "ค. จ. ก. ง. และ ข.", "ค. จ. ง. ก. และ ข.", "จ. ง. ค. ก. และ ข.", "จ. ง. ค. ข. และ ก."]'::jsonb,2,array[2]::smallint[],'["สมมติฐานการไหลของมวล: ซูโครสเข้าซีฟทิวบ์ที่แหล่งสร้าง (ค) → น้ำเข้าตามโดยออสโมซิส ความดันสูงขึ้น (จ) → สารละลายไหลไปแหล่งรับ (ง) → ซูโครสออกที่แหล่งรับ (ก) → น้ำออก ความดันลดลง (ข)"]'::jsonb,'["ไม่ถูก ต้องมีน้ำเข้า (จ) ก่อนจึงเกิดความดันที่ทำให้ไหล (ง)", "ไม่ถูก สารละลายต้องไหลไปถึงแหล่งรับ (ง) ก่อนซูโครสจะออก (ก)", "ถูก", "ไม่ถูก ขั้นแรกต้องเป็นการขนซูโครสเข้าซีฟทิวบ์ (ค)", "ไม่ถูก ขั้นแรกต้องเป็น ค และ ก ต้องเกิดก่อน ข"]'::jsonb,'{"topic": "4.2", "n": 28}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2569,'bio:69-28');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-29','M6','M6-BI','M6-BI-S4','A-Level 66',null,2,'จากการทดลองเพาะเลี้ยงเนื้อเยื่อพืช เติมสาร 2 ชนิดลงในอาหารวุ้นเพื่อศึกษาการเจริญเติบโตของชิ้นส่วนพืช ได้ผลการทดลองดังตาราง','["TDZ และ IBA", "น้ำมะพร้าว และ BA", "BA และ น้ำมะพร้าว", "IAA และ TDZ", "IBA และ NAA"]'::jsonb,0,array[0]::smallint[],'["สาร A สูงกว่า B มากทำให้เกิดยอด จึงเป็นไซโทไคนิน · สาร B สูงกว่ามากทำให้เกิดราก จึงเป็นออกซิน · TDZ ออกฤทธิ์แบบไซโทไคนิน ส่วน IBA เป็นออกซิน"]'::jsonb,'["ถูก", "ไม่ถูก ทั้งสองมีฤทธิ์แบบไซโทไคนิน B ต้องเป็นออกซิน", "ไม่ถูก น้ำมะพร้าวมีไซโทไคนิน ไม่ใช่ออกซิน", "ไม่ถูก สลับกัน IAA เป็นออกซิน TDZ มีฤทธิ์แบบไซโทไคนิน", "ไม่ถูก ทั้งสองเป็นออกซิน"]'::jsonb,'{"table": [["สาร A (mg/l)", "สาร B (mg/l)", "การเจริญของชิ้นส่วนพืช"], ["0.2", "ไม่เติม", "ไม่มีการเจริญ"], ["0.2", "2", "เกิดแคลลัส"], ["0.02", "2", "เกิดราก"], ["1", "0.02", "เกิดยอด"]], "after": "จากตารางสาร A และ B คือข้อใด ตามลำดับ", "topic": "4.5", "n": 29}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'bio:69-29');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-30','M6','M6-BI','M6-BI-S5','A-Level 66',null,2,'พิจารณาสถานการณ์ต่อไปนี้
ทารกเพศชายอายุ 3 สัปดาห์ถูกส่งเข้าโรงพยาบาลด้วยภาวะหัวใจล้มเหลวเฉียบพลัน จากการวินิจฉัยโดยละเอียดพบว่ามีสาเหตุจากสภาวะกล้ามเนื้อหัวใจผิดปกติ นอกจากนี้ทารกยังมีภาวะเม็ดเลือดขาวชนิดนิวโทรฟิลต่ำด้วย การวิเคราะห์พันธุประวัติย้อนหลังไป 7 รุ่นพบว่า ในครอบครัวฝ่ายแม่มีประวัติญาติเพศชายจำนวน 6 คน ใน 3 รุ่นที่ไม่ต่อเนื่องกัน มีภาวะกล้ามเนื้อหัวใจผิดปกติ กล้ามเนื้อโครงร่างอ่อนแอ และมีภาวะนิวโทรฟิลต่ำ ในผู้ป่วยทั้ง 6 คนนี้ มีจำนวน 4 คน ที่ตรวจพบความผิดปกติตั้งแต่อายุ 6 สัปดาห์ และเสียชีวิตในเวลาไม่เกิน 10 ปี อีก 2 คน ตรวจพบความผิดปกติดังกล่าวเมื่ออายุประมาณ 10 ปี นอกเหนือจากความผิดปกติข้างต้นแล้ว ยังมีพัฒนาการการเคลื่อนไหวช้าและมีรูปร่างเตี้ยอีกด้วย
ข้อใดกล่าวเกี่ยวกับความผิดปกติที่พบในครอบครัวฝ่ายแม่ได้ถูกต้อง','["ความผิดปกตินี้ไม่ได้ถูกถ่ายทอดทางพันธุกรรม", "ความผิดปกตินี้มีการถ่ายทอดทางพันธุกรรมแบบลักษณะเด่นบนออโทโซม", "ความผิดปกตินี้มีการถ่ายทอดทางพันธุกรรมแบบลักษณะด้อยบนออโทโซม", "ความผิดปกตินี้มีการถ่ายทอดทางพันธุกรรมแบบลักษณะเด่นบนโครโมโซม X", "ความผิดปกตินี้มีการถ่ายทอดทางพันธุกรรมแบบลักษณะด้อยบนโครโมโซม X"]'::jsonb,4,array[4]::smallint[],'["ผู้ป่วยเป็นเพศชายทั้งหมด ถ่ายทอดผ่านฝ่ายแม่ และข้ามรุ่น (แม่ที่เป็นพาหะไม่แสดงอาการ) จึงเป็นลักษณะด้อยบนโครโมโซม X"]'::jsonb,'["ไม่ถูก พบในญาติหลายรุ่นอย่างมีรูปแบบ จึงถ่ายทอดทางพันธุกรรม", "ไม่ถูก ลักษณะเด่นจะไม่ข้ามรุ่น และควรพบได้ทั้งสองเพศ", "ไม่ถูก ลักษณะบนออโทโซมควรพบทั้งเพศชายและหญิงใกล้เคียงกัน", "ไม่ถูก ลักษณะเด่นบน X จะพบในหญิงด้วย และไม่ข้ามรุ่น", "ถูก"]'::jsonb,'{"topic": "5.1", "n": 30}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'bio:69-30');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-31','M6','M6-BI','M6-BI-S5','A-Level 66',null,2,'พิจารณาโมเลกุลในกระบวนการถอดรหัส (transcription) ดังภาพ','["โมเลกุล X ที่ลูกศรชี้ คือไนโตรจีนัสเบสไทมีน", "กระบวนการนี้เกิดขึ้นภายในไซโทพลาซึมของเซลล์สัตว์", "พอลินิวคลีโอไทด์แม่แบบมีทิศทางการวางตัวจากบนลงล่าง เป็น 5′ ไปยังปลาย 3′", "เอนไซม์ที่ทำหน้าที่เชื่อมต่อโมเลกุลนิวคลีโอไทด์ในกระบวนการนี้ คืออาร์เอ็นเอพอลิเมอเรส", "ผลผลิตที่ได้จากกระบวนการนี้ คือพอลินิวคลีโอไทด์สายใหม่ที่มีรหัสพันธุกรรมเหมือนกับแม่แบบทุกประการ"]'::jsonb,3,array[3]::smallint[],'["สายซ้ายมี OH ที่คาร์บอนตำแหน่ง 2′ จึงเป็นสาย RNA ที่สร้างใหม่ ส่วนสายขวาเป็น DNA แม่แบบ · อาร์เอ็นเอพอลิเมอเรสเชื่อมนิวคลีโอไทด์ในการถอดรหัส"]'::jsonb,'["ไม่ถูก X อยู่ในสาย RNA และจับคู่กับ A จึงเป็นยูราซิล", "ไม่ถูก การถอดรหัสในเซลล์สัตว์เกิดในนิวเคลียส", "ไม่ถูก สาย RNA วางจากบนลงล่างเป็น 5′ → 3′ สายแม่แบบจึงวางสวนทางเป็น 3′ → 5′", "ถูก", "ไม่ถูก สายใหม่มีลำดับเบสเป็นคู่สมกับแม่แบบ และใช้ U แทน T"]'::jsonb,'{"img": "bio-69-31.png", "after": "ข้อใดถูกต้อง", "topic": "5.2", "n": 31, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/bio-69-31.png"}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'bio:69-31');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-32','M6','M6-BI','M6-BI-S5','A-Level 66',null,2,'ในการศึกษายีนสังเคราะห์โปรตีน R ในสิ่งมีชีวิตชนิดหนึ่ง พบว่า DNA สายต้นแบบมีลำดับนิวคลีโอไทด์ดังภาพ กำหนดให้การแปลรหัสเริ่มที่กรดแอมิโนเมไทโอนีนตัวแรกในสาย mRNA','["โปรตีน R ประกอบด้วยกรดแอมิโนจำนวน 11 โมเลกุล", "mRNA ที่ได้จากกระบวนการถอดรหัสประกอบด้วยนิวคลีโอไทด์ 39 โมเลกุล", "การแทนที่นิวคลีโอไทด์ C ในตำแหน่งที่ 4 ด้วย A ทำให้ไม่เกิดการแปลรหัสขึ้น", "การขาดหายไปของนิวคลีโอไทด์ตำแหน่งที่ 20 จะส่งผลต่อความยาวสายพอลิเพปไทด์", "แอนติโคดอนของ tRNA ที่จะนำกรดแอมิโนตัวที่ 2 มาต่อยังสายพอลิเพปไทด์ คือ 3′ UAC 5′"]'::jsonb,2,array[2]::smallint[],'["mRNA (5′→3′) = UAUGAUGGCCUUAGACCAUUUAGGGCAAUAUAGAUAACA · เริ่มที่ AUG ตำแหน่ง 2–4 แล้วอ่านได้ AUG AUG GCC UUA GAC CAU UUA GGG CAA UAU AGA แล้วหยุดที่ UAA · ถ้าเปลี่ยน C ตำแหน่งที่ 4 เป็น A โคดอนแรกจะเป็น AUU แต่ยังมี AUG ที่ตำแหน่ง 5–7 จึงยังแปลรหัสได้"]'::jsonb,'["ถูกต้อง นับได้ 11 โคดอนก่อนถึง UAA", "ถูกต้อง สายต้นแบบยาว 39 นิวคลีโอไทด์", "ไม่ถูกต้อง จึงเป็นคำตอบ ยังมี AUG ที่ตำแหน่ง 5–7 ให้เริ่มแปลรหัส", "ถูกต้อง เกิดเฟรมชิฟต์ ได้โคดอนหยุด UAG เร็วขึ้น สายพอลิเพปไทด์จึงสั้นลงเหลือ 6 กรดแอมิโน", "ถูกต้อง โคดอนตัวที่ 2 คือ AUG แอนติโคดอนคือ 3′ UAC 5′"]'::jsonb,'{"img": "bio-69-32.png", "after": "ข้อใด**ไม่**ถูกต้อง", "topic": "5.2", "n": 32, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/bio-69-32.png"}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'bio:69-32');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-33','M6','M6-BI','M6-BI-S5','A-Level 66',null,2,'นักพันธุศาสตร์นำเซลล์ไข่และสเปิร์มจากหนูพันธุ์หนึ่งซึ่งมีจำนวนโครโมโซม 5 คู่ มาผสมในห้องทดลอง หลังจากหนึ่งสัปดาห์พบว่าเอ็มบริโอที่ได้มีพัฒนาการช้ากว่าปกติ จึงนำเซลล์มาศึกษาโครโมโซมโดยการย้อมสีโครโมโซมด้วยเทคนิค chromosome banding ทำให้เห็นเป็นแถบสีเข้มและจางสลับกันตามแนวยาวของโครโมโซมแต่ละคู่ ดังภาพ','["ความผิดปกติของเอ็มบริโอเกิดจากการมีจำนวนโครโมโซมขาดไปหนึ่งแท่ง", "ความผิดปกติของเอ็มบริโอเกิดจากการมีจำนวนโครโมโซมเกินมาหนึ่งแท่ง", "ความผิดปกติของเอ็มบริโอเกิดจากการกลายพันธุ์แบบเฟรมชิฟท์มิวเทชัน", "ความผิดปกติของเอ็มบริโอเกิดจากการเกินมาของบางส่วนจากคู่ฮอมอโลกัสโครโมโซม", "ความผิดปกติของเอ็มบริโอเกิดจากการเกินมาจากการเคลื่อนย้ายชิ้นส่วนจากโครโมโซมต่างคู่กัน"]'::jsonb,4,array[4]::smallint[],'["จำนวนโครโมโซมครบ 5 คู่ (10 แท่ง) แต่โครโมโซมคู่ที่ 3 แท่งหนึ่งยาวกว่าคู่ของมัน มีชิ้นส่วนเกินที่มีแถบสีไม่ตรงกับโครโมโซมคู่ที่ 3 จึงน่าจะเป็นชิ้นส่วนจากโครโมโซมต่างคู่ที่ย้ายมาต่อ"]'::jsonb,'["ไม่ถูก ภาพมีโครโมโซมครบ 10 แท่ง", "ไม่ถูก ภาพมีโครโมโซมครบ 10 แท่ง ไม่มีแท่งเกิน", "ไม่ถูก เฟรมชิฟต์เป็นมิวเทชันระดับยีน มองไม่เห็นจากการย้อมแถบโครโมโซม", "ไม่ถูก ถ้าเกินจากคู่ฮอมอโลกัสเอง ชิ้นส่วนควรมีแถบเหมือนส่วนของโครโมโซมคู่ที่ 3", "ถูก"]'::jsonb,'{"img": "bio-69-33.png", "after": "คำอธิบายในข้อใดมีความเป็นไปได้มากที่สุด", "topic": "5.3", "n": 33, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/bio-69-33.png"}'::jsonb,'imported_m6','imported',false,null,'คำอธิบายอ่านจากแถบสีในภาพประกอบ ครูควรตรวจทานว่าชิ้นส่วนเกินบนโครโมโซมคู่ที่ 3 ไม่ตรงกับแถบของคู่ที่ 3 เอง',2569,'bio:69-33');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-34','M6','M6-BI','M6-BI-S5','A-Level 66',null,2,'นักวิจัยต้องการผลิตเอนไซม์ Q ปริมาณมากสำหรับใช้ในห้องปฏิบัติการ จึงเพิ่มจำนวนชิ้นส่วนยีนด้วยวิธี PCR และโคลนยีนเข้าสู่เซลล์แบคทีเรีย E. coli โดยใช้พลาสมิด E ที่สามารถกระตุ้นให้เกิดการแสดงออกของยีนได้ ซึ่งประกอบด้วย ยีนต้านยาปฏิชีวนะ 2 ยีน คือ ยีนต้านยาปฏิชีวนะแอมพิซิลิน (Ampᴿ) และคานาไมซิน (Kanᴿ) เป็นเครื่องหมายในการคัดเลือก มี promotor (ตำแหน่งจำเป็นสำหรับการเข้าจับดีเอ็นเอสายต้นแบบของเอ็นอาร์เอ็นเอพอลิเมอเรส) และ terminator (ตำแหน่งสิ้นสุดการสังเคราะห์สาย mRNA) ซึ่งจำเป็นต่อการแสดงออกของยีน และ cloning site โดยตำแหน่งของเอนไซม์ตัดจำเพาะบนพลาสมิดและชิ้นส่วน DNA ที่ได้จากการทำ PCR ดังแสดงในภาพประกอบ','["เอนไซม์ตัดจำเพาะ RE1", "เอนไซม์ตัดจำเพาะ RE2", "เอนไซม์ตัดจำเพาะ RE3", "เอนไซม์ตัดจำเพาะ RE4", "เอนไซม์ตัดจำเพาะ RE5"]'::jsonb,2,array[2]::smallint[],'["ต้องเลือกเอนไซม์ที่ (1) ไม่ตัดยีน Ampᴿ และ Kanᴿ บนพลาสมิด (2) ตัดที่ cloning site ระหว่างโพรโมเตอร์กับเทอร์มิเนเตอร์ และ (3) ตัดชิ้น PCR ที่หัวและท้ายของยีน (ก่อน ATG และหลัง TGA) โดยไม่ตัดกลางยีน · RE3 ตรงทุกเงื่อนไข"]'::jsonb,'["ไม่ถูก RE1 ตัดในยีน Ampᴿ และตัดกลางยีน Q", "ไม่ถูก RE2 ตัดกลางยีน Q", "ถูก", "ไม่ถูก RE4 ตัดกลางยีน Q", "ไม่ถูก RE5 ตัดในยีน Kanᴿ และตัดกลางยีน Q"]'::jsonb,'{"img": "bio-69-34.png", "after": "หากนักวิจัยต้องการสร้างดีเอ็นเอรีคอมบิแนนท์ที่สามารถใช้ยีนต้านยาปฏิชีวนะทั้งสองเป็นเครื่องหมายในการคัดเลือก และสามารถผลิตเอนไซม์ Q ได้ ต้องเลือกใช้เอนไซม์ตัดจำเพาะใดในการตัดพลาสมิดและชิ้นส่วน DNA ที่ได้จากการทำ PCR", "topic": "5.4", "n": 34, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/bio-69-34.png"}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'bio:69-34');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-69-35','M6','M6-BI','M6-BI-S5','A-Level 66',null,2,'ข้อใด**ไม่**จัดเป็นการเปลี่ยนแปลงความถี่แอลลีลในประชากรจากผลของเจเนติกดริฟต์','["หนูทดลองสายพันธุ์ BALB/c เป็นสายพันธุ์เผือกจึงมีขนสีขาวและตาสีแดง", "ค้างคาวหูยาวบนหมู่เกาะกาลาปากอสมีความหลากหลายทางพันธุกรรมต่ำกว่าในทวีปอเมริกาใต้", "การลดจำนวนลงอย่างรวดเร็วของประชากรกล้วยไม้ A ที่พบเฉพาะบนยอดเขา Z จากการลักลอบตัดไม้", "ความถี่ของโรคจอประสาทตาเสื่อม สูงในประชากรชาวอังกฤษที่อาศัยในหมู่เกาะเล็ก ๆ ในมหาสมุทรแอตแลนติก", "ความถี่แอลลีลโรคตาบอดสี Pingelapese สูงในประชากรหมู่เกาะปิงเกลาป หลังพายุไต้ฝุ่นรุนแรงในปี ค.ศ. 1770"]'::jsonb,0,array[0]::smallint[],'["หนูทดลองสายพันธุ์เผือกเกิดจากมนุษย์คัดเลือกและผสมพันธุ์ในห้องปฏิบัติการ (การคัดเลือกโดยมนุษย์/ผสมเลือดชิด) ไม่ใช่การเปลี่ยนแปลงแบบสุ่มของประชากรธรรมชาติ"]'::jsonb,'["ไม่ใช่เจเนติกดริฟต์ จึงเป็นคำตอบ", "เป็นเจเนติกดริฟต์ (ผลของผู้ก่อตั้ง)", "เป็นเจเนติกดริฟต์ (ปรากฏการณ์คอขวด)", "เป็นเจเนติกดริฟต์ (ผลของผู้ก่อตั้ง)", "เป็นเจเนติกดริฟต์ (คอขวดจากพายุ)"]'::jsonb,'{"topic": "5.5", "n": 35}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'bio:69-35');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-1','M6','M6-BI','M6-BI-S1','A-Level 66',null,2,'สิ่งมีชีวิต 3 ชนิดมีแหล่งที่อยู่อาศัยในภาคกลางของประเทศไทย และมีลักษณะดังนี้
- ชนิด A เป็นพืชที่มีถิ่นกำเนิดในประเทศอินโดนีเซีย สามารถปรับตัวเข้ากับแหล่งน้ำที่หลากหลาย มีอัตราการเจริญพันธุ์เร็ว และแพร่กระจายได้ดีในแม่น้ำเจ้าพระยาผ่านกิจกรรมของมนุษย์และจากปัจจัยทางธรรมชาติ
- ชนิด B เป็นสัตว์เลื้อยคลานที่มีถิ่นกำเนิดในทวีปอเมริกาใต้เป็นพาหะนำเชื้อซัลโมเนลลา (Salmonella spp.) มีการปรับตัวต่อแหล่งที่อยู่ตามธรรมชาติและเขตเมืองของจังหวัดลพบุรี และทำลายพืชผลทางการเกษตร
- ชนิด C เป็นสัตว์น้ำที่มีถิ่นกำเนิดในทวีปแอฟริกา แพร่กระจายอย่างรวดเร็วในลำคลองย่อยของแม่น้ำแม่กลอง ส่งผลต่อการทำประมงท้องถิ่นในหลายพื้นที่ ทนต่อความเค็มได้สูง
จากข้อมูล ข้อใด**ไม่**ถูกต้อง','["ชนิด A ส่งผลกระทบต่อปริมาณแก๊สออกซิเจนในน้ำ ทำให้อาหารของสัตว์น้ำลดน้อยลง", "ชนิด B เป็นสัตว์ต่างถิ่นที่มีแนวโน้มรุกรานเมื่อมีปัจจัยสิ่งแวดล้อมที่เหมาะสมต่อการเจริญเติบโต", "ชนิด C มีอัตราการรอดชีวิตตามกราฟรูปแบบ III ถ้าไม่ได้รับการจัดการจะส่งผลเสียต่อระบบเศรษฐกิจ", "สิ่งมีชีวิตทั้ง 3 ชนิดส่งผลกระทบทั้งทางตรงและทางอ้อมต่อระบบนิเวศและห่วงโซ่อาหารของชนิดเฉพาะถิ่น", "การแพร่กระจายของสิ่งมีชีวิต 3 ชนิดก่อให้เกิดการเปลี่ยนแปลงต่อระบบนิเวศและความหลากหลายทางชีวภาพแบบถาวร"]'::jsonb,0,array[0,1,4]::smallint[],'["ทั้งสามชนิดเป็นสิ่งมีชีวิตต่างถิ่นที่รุกรานแล้ว (พืชน้ำลอยน้ำ, อิกัวนาเขียวที่ลพบุรี, ปลาหมอคางดำ) · ทปอ. เฉลย 3 คำตอบ คือข้อ 1, 2 และ 5 · ข้อ 3 และ 4 สอดคล้องกับข้อมูล"]'::jsonb,'["ทปอ. นับเป็นคำตอบ (ข้อความไม่ถูกต้อง) · ประเด็นที่ครูควรอธิบาย: พืชน้ำที่ปกคลุมผิวน้ำบังแสงและทำให้ออกซิเจนลดลงเมื่อเน่าเปื่อย แต่การสรุปว่า “อาหารของสัตว์น้ำลดลง” เป็นผลโดยตรงจากออกซิเจนไม่ใช่เหตุผลที่ถูกต้อง", "ทปอ. นับเป็นคำตอบ (ข้อความไม่ถูกต้อง) · B ทำลายพืชผลและแพร่กระจายในเขตเมืองแล้ว จึงเป็นชนิดพันธุ์รุกรานแล้ว ไม่ใช่เพียง “มีแนวโน้ม”", "ข้อความสอดคล้องกับข้อมูล ปลาออกลูกจำนวนมากและอัตรารอดช่วงแรกต่ำ (รูปแบบ III) และกระทบการประมง", "ข้อความสอดคล้องกับข้อมูล ชนิดต่างถิ่นแย่งอาหาร/ที่อยู่และกินชนิดพื้นถิ่น", "ทปอ. นับเป็นคำตอบ (ข้อความไม่ถูกต้อง) · ผลกระทบอาจลดลงหรือฟื้นฟูได้ถ้ามีการจัดการ จึงไม่จำเป็นต้อง “ถาวร”"]'::jsonb,'{"topic": "1.3", "n": 1}'::jsonb,'imported_m6','imported',true,'expl','ทปอ. เฉลย 3 คำตอบ (ข้อ 1, 2 หรือ 5) · เหตุผลรายข้อในคำอธิบายเป็นการตีความของผู้จัดทำ ครูควรตรวจทาน',2568,'bio:68-1');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-2','M6','M6-BI','M6-BI-S1','A-Level 66',null,2,'ข้อใด**ไม่**ใช่ลักษณะของการเติบโตของประชากรแบบลอจิสติก (logistic population growth)','["อาหารเป็นปัจจัยหนึ่งของตัวต้านทานในสิ่งแวดล้อมที่จำกัดการเติบโตของประชากร", "เป็นการเติบโตของประชากรที่มีปัจจัยของสภาพแวดล้อมมาเป็นตัวจำกัดอัตราการเพิ่มขนาดประชากร", "ระยะที่อัตราการเติบโตเริ่มลดลงเรื่อย ๆ จนถึงระดับคงที่ เรียกว่า ถึงระดับความจุที่รับได้สูงสุด (carrying capacity)", "ระยะแรกของการเติบโตมีอัตราเพิ่มขึ้น เมื่อถึงจุดหนึ่งอัตราการเติบโตลดลงจนถึงระยะที่ไม่มีการเพิ่มขนาดของประชากร", "กราฟมีลักษณะเป็นรูปอักษร J เช่น ยุงมีการเติบโตของประชากรอย่างช้า ๆ และเพิ่มการเติบโตอย่างรวดเร็วแบบไม่มีที่สิ้นสุด"]'::jsonb,4,array[4]::smallint[],'["การเติบโตแบบลอจิสติกมีกราฟรูปตัว S และถูกจำกัดด้วยความจุที่รับได้สูงสุด ส่วนกราฟรูปตัว J ที่เพิ่มขึ้นไม่สิ้นสุดคือการเติบโตแบบเอกซ์โพเนนเชียล"]'::jsonb,'["เป็นลักษณะแบบลอจิสติก อาหารเป็นตัวต้านทานในสิ่งแวดล้อม", "เป็นลักษณะแบบลอจิสติก", "เป็นลักษณะแบบลอจิสติก", "เป็นลักษณะแบบลอจิสติก (กราฟรูปตัว S)", "ไม่ใช่ จึงเป็นคำตอบ กราฟรูป J เป็นแบบเอกซ์โพเนนเชียล"]'::jsonb,'{"topic": "1.2", "n": 2}'::jsonb,'imported_m6','imported',true,'figure','Exam Gym ม.6 · 5620e4c',2568,'bio:68-2');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-3','M6','M6-BI','M6-BI-S1','A-Level 66',null,2,'ตารางแสดงปริมาณน้ำฝนเฉลี่ย อุณหภูมิเฉลี่ย ระดับความหลากหลายทางชีวภาพ และตัวอย่างพืชที่พบ ดังนี้','["ไบโอม D พบชั้นดินเยือกแข็งคงตัว (permafrost)", "ไบโอม B มีพื้นที่ส่วนใหญ่เป็นป่าแบบผลัดใบ (deciduous forest)", "ไบโอม C มีขอบเขตตั้งแต่ขั้วโลกเหนือ อเมริกาเหนือ ยุโรปและเอเชียตอนบน", "ไบโอม A มีการแพร่กระจายของพืชอวบน้ำเป็นแบบสม่ำเสมอ (uniform distribution)", "ไบโอม E พบพืชประเภทที่สามารถขึ้นในสภาพอากาศร้อนและแห้งแล้ง ต้นไม้เปิดเรือนยอด"]'::jsonb,1,array[1,2]::smallint[],'["A ทะเลทราย · B ป่าดิบชื้นเขตร้อน · C ป่าสน (ไทกา) · D ทุนดรา · E สะวันนา · ข้อ 2 ผิด เพราะป่าดิบชื้นเป็นป่าไม่ผลัดใบ · ข้อ 3 ผิด เพราะบริเวณขั้วโลกเหนือเป็นทุนดราและน้ำแข็ง ไม่ใช่ป่าสน · ทปอ. เฉลย 2 คำตอบ"]'::jsonb,'["ถูกต้อง ทุนดรามีชั้นดินเยือกแข็งคงตัว", "ไม่ถูกต้อง จึงเป็นคำตอบ ป่าดิบชื้นเป็นป่าไม่ผลัดใบ", "ไม่ถูกต้อง จึงเป็นคำตอบ ป่าสนอยู่ในอเมริกาเหนือ ยุโรปและเอเชียตอนบน แต่ไม่ถึงขั้วโลกเหนือ", "ถูกต้อง พืชทะเลทรายแย่งน้ำกัน จึงกระจายห่างกันสม่ำเสมอ", "ถูกต้อง สะวันนาเป็นทุ่งหญ้าเขตร้อนแห้งแล้ง มีต้นไม้กระจายห่าง ๆ"]'::jsonb,'{"table": [["ไบโอม", "ปริมาณน้ำฝนเฉลี่ย (เซนติเมตร)", "อุณหภูมิเฉลี่ย (องศาเซลเซียส)", "ระดับความหลากหลายทางชีวภาพ", "ตัวอย่างพืชที่พบ"], ["A", "น้อยกว่า 25", "-3 ถึง 60", "ต่ำ", "ไม้อวบน้ำ พืชปีเดียว"], ["B", "200 ถึง 400", "20 ถึง 29", "สูง", "ไม้ป่าดงดิบ"], ["C", "25 ถึง 75", "-25 ถึง 16", "ต่ำ", "พืชใบรูปเข็ม"], ["D", "น้อยกว่า 25", "-40 ถึง 18", "ต่ำ", "พืชพุ่มเตี้ย มอส"], ["E", "30 ถึง 50", "20 ถึง 30", "สูง", "หญ้า พืชพุ่มมีหนาม"]], "after": "จากข้อมูล ข้อใด**ไม่**ถูกต้อง", "topic": "1.1", "n": 3}'::jsonb,'imported_m6','imported',true,'expl','Exam Gym ม.6 · 5620e4c',2568,'bio:68-3');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-4','M6','M6-BI','M6-BI-S1','A-Level 66',null,2,'ลักษณะของสัตว์ชนิด A B C D และ E เป็นดังนี้
ชนิด A มีเนื้อเยื่อแรกเกิดสองชั้น ไม่มีโพรงภายในลำตัว มีสมมาตรแบบรัศมี และมีช่องแกสโทรวาสคิวลาร์
ชนิด B มีเนื้อเยื่อแรกเกิดสามชั้น มีโพรงภายในลำตัวแบบเทียม มีสมมาตรแบบครึ่งซีก และบลาสโทพอร์เจริญไปเป็นปาก
ชนิด C มีเนื้อเยื่อแรกเกิดสามชั้น บลาสโทพอร์เจริญไปเป็นปาก ลำตัวเป็นปล้อง และมีระบบหมุนเวียนเลือดแบบเปิด
ชนิด D มีเนื้อเยื่อแรกเกิดสามชั้น มีโพรงภายในลำตัวที่แท้จริง บลาสโทพอร์เจริญไปเป็นทวารหนัก มีระบบท่อน้ำ และผิวหนังเป็นหนาม
ชนิด E มีเนื้อเยื่อแรกเกิดสามชั้น มีโพรงภายในลำตัวที่แท้จริง บลาสโทพอร์เจริญไปเป็นทวารหนัก และมีโนโทคอร์ดเป็นโครงร่างค้ำจุน
จากข้อมูล ข้อใด**ไม่**ถูกต้อง','["ชนิด A คือไฮดรา มีระบบประสาทเป็นแบบร่างแห (nerve net) และใช้เข็มพิษ (nematocyst) ป้องกันตัวและล่าเหยื่อ", "ชนิด B คือไส้เดือนฝอย มีระบบทางเดินอาหารแบบสมบูรณ์ (complete digestive tract)", "ชนิด C คือแมงดาทะเล มีโครงร่างแข็งภายนอกร่างกาย (exoskeleton) จำพวกไคทินและโปรตีน", "ชนิด D คือหอยมือเสือ เป็นหนึ่งในกลุ่มที่มีความหลากหลายทางชนิดมากที่สุดในอาณาจักรสัตว์", "ชนิด E คือปลาแลมเพรย์เป็นสมาชิกในกลุ่มปลาไม่มีขากรรไกร (jawless fish)"]'::jsonb,3,array[3]::smallint[],'["D มีระบบท่อน้ำและผิวหนังเป็นหนาม คือสัตว์กลุ่มเอไคโนเดิร์ม (เช่น ดาวทะเล เม่นทะเล) ส่วนหอยมือเสือเป็นมอลลัสก์ จึงไม่ถูกต้อง"]'::jsonb,'["ถูกต้อง ไฮดราเป็นไนดาเรียน", "ถูกต้อง ไส้เดือนฝอยมีโพรงลำตัวเทียมและทางเดินอาหารสมบูรณ์", "ถูกต้อง แมงดาทะเลเป็นอาร์โทรพอด", "ไม่ถูกต้อง จึงเป็นคำตอบ หอยมือเสือไม่มีระบบท่อน้ำ และกลุ่มที่หลากหลายที่สุดคืออาร์โทรพอด", "ถูกต้อง แลมเพรย์เป็นคอร์เดตที่ไม่มีขากรรไกร"]'::jsonb,'{"topic": "1.4", "n": 4}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'bio:68-4');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-5','M6','M6-BI','M6-BI-S1','A-Level 66',null,2,'นักเรียนเดินสำรวจพืชภายในโรงเรียนแห่งหนึ่ง เพื่อศึกษาความหลากหลายของพืช นักเรียนระบุชนิดพืชที่พบ โดยพิจารณาลักษณะเด่นของโครงสร้างภายนอกพืช และเก็บตัวอย่างเพื่อนำไปศึกษาลักษณะโครงสร้างต่าง ๆ ในห้องปฏิบัติการเพิ่มเติม บันทึกข้อมูลพืชที่ได้ดังตาราง','["ลิเวอร์เวิร์ท สามร้อยยอด หวายทะนอย มะเมื่อย และบร็อกโคลี", "หวายทะนอย มะเมื่อย บร็อกโคลี ลิเวอร์เวิร์ท และสามร้อยยอด", "หวายทะนอย ลิเวอร์เวิร์ท มะเมื่อย สามร้อยยอด และบร็อกโคลี", "บร็อกโคลี หวายทะนอย มะเมื่อย สามร้อยยอด และลิเวอร์เวิร์ท", "มะเมื่อย ลิเวอร์เวิร์ท สามร้อยยอด หวายทะนอย และบร็อกโคลี"]'::jsonb,2,array[2]::smallint[],'["A แตกกิ่งสองแฉก อับสปอร์ 3 พู = หวายทะนอย · B แผ่นสีเขียว ไม่มีท่อลำเลียง = ลิเวอร์เวิร์ท · C สร้างโคน เมล็ดเปลือย = มะเมื่อย (จิมโนสเปิร์ม) · D ใบเล็กเส้นใบเดียว อับสปอร์ที่ปลายกิ่ง = สามร้อยยอด · E พืชดอก = บร็อกโคลี"]'::jsonb,'["ไม่ถูก ลิเวอร์เวิร์ทคือ B ไม่ใช่ A", "ไม่ถูก B ต้องเป็นลิเวอร์เวิร์ท", "ถูก", "ไม่ถูก บร็อกโคลีเป็นพืชดอก (E)", "ไม่ถูก มะเมื่อยเป็นพืชเมล็ดเปลือย (C)"]'::jsonb,'{"table": [["ชนิดพืช", "ลักษณะสำคัญที่พบ"], ["A", "ลำต้นเหนือดินแตกกิ่งแบบแยกสองแฉก และมีอับสปอร์ 3 พูเกิดบนกิ่ง"], ["B", "มีลักษณะเป็นแผ่นสีเขียว และยังไม่สร้างท่อลำเลียง"], ["C", "มีการสร้างโคน ออวุลไม่มีรังไข่ห่อหุ้ม เมื่อออวุลพัฒนาไปเป็นเมล็ด ทำให้เมล็ดไม่มีผลห่อหุ้ม"], ["D", "ใบมีขนาดเล็ก มีเส้นใบ 1 เส้น และมีการสร้างอับสปอร์ที่ปลายกิ่ง"], ["E", "มีดอก ออวุลมีรังไข่ห่อหุ้ม เมื่อออวุลพัฒนาไปเป็นเมล็ด ทำให้เมล็ดมีผลห่อหุ้ม"]], "after": "ข้อใดคือพืชชนิด A B C D และ E ตามลำดับ", "topic": "1.4", "n": 5}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'bio:68-5');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-6','M6','M6-BI','M6-BI-S2','A-Level 66',null,2,'พิจารณาข้อความเกี่ยวกับโมเลกุลของน้ำต่อไปนี้
ก. เมื่อน้ำอยู่ในสถานะของเหลว จะเกิดพันธะโคเวเลนต์ขึ้นระหว่างโมเลกุลของน้ำ
ข. โมเลกุลน้ำจะหันด้านที่มีขั้วลบเข้าหาไอออนบวกที่ได้จากการแตกตัวของ NaCl เมื่อละลายน้ำ
ค. โมเลกุลของน้ำเกิดจากอะตอมไฮโดรเจนและอะตอมออกซิเจนเชื่อมต่อกันด้วยพันธะไฮโดรเจน
ง. ค่า electronegativity ที่แตกต่างกันของอะตอมออกซิเจนและอะตอมไฮโดรเจน มีอิทธิพลต่อการเกิดสภาพขั้วของโมเลกุลน้ำ
ข้อใดถูกต้อง','["ก. และ ข. เท่านั้น", "ก. และ ค. เท่านั้น", "ข. และ ค. เท่านั้น", "ข. และ ง. เท่านั้น", "ค. และ ง. เท่านั้น"]'::jsonb,3,array[3]::smallint[],'["ก ผิด ระหว่างโมเลกุลน้ำเป็นพันธะไฮโดรเจน · ข ถูก ด้าน O (ขั้วลบ) หันเข้าหา Na⁺ · ค ผิด ภายในโมเลกุล O กับ H ยึดกันด้วยพันธะโคเวเลนต์ · ง ถูก"]'::jsonb,'["ไม่ถูก ก ผิด", "ไม่ถูก ก และ ค ผิด (สลับชนิดพันธะ)", "ไม่ถูก ค ผิด", "ถูก ข และ ง", "ไม่ถูก ค ผิด"]'::jsonb,'{"topic": "2.1", "n": 6}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2568,'bio:68-6');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-7','M6','M6-BI','M6-BI-S2','A-Level 66',null,2,'พิจารณาข้อความเกี่ยวกับสารประกอบประเภทคาร์โบไฮเดรต ต่อไปนี้
ก. พอลิแซ็กคาไรด์ประกอบด้วยหน่วยย่อยที่เชื่อมต่อกันด้วยพันธะไกลโคซิดิก
ข. ผนังเซลล์ของพืชมีองค์ประกอบสำคัญเป็นสารประกอบประเภทคาร์โบไฮเดรต
ค. เซลล์สิ่งมีชีวิตนำไดแซ็กคาไรด์เข้าสู่เซลล์เพื่อใช้เป็นสารตั้งต้นในการผลิตพลังงาน
ง. กลูโคสเป็นสารประกอบประเภทคาร์โบไฮเดรตที่เป็นองค์ประกอบสำคัญของสารพันธุกรรม
ข้อใดถูกต้อง','["ก. และ ข. เท่านั้น", "ก. และ ค. เท่านั้น", "ข. และ ค. เท่านั้น", "ข. และ ง. เท่านั้น", "ค. และ ง. เท่านั้น"]'::jsonb,0,array[0]::smallint[],'["ก ถูก · ข ถูก (เซลลูโลส) · ค ผิด ไดแซ็กคาไรด์ต้องถูกย่อยเป็นมอโนแซ็กคาไรด์ก่อนนำเข้าเซลล์ · ง ผิด น้ำตาลในสารพันธุกรรมคือไรโบสและดีออกซีไรโบส"]'::jsonb,'["ถูก ก และ ข", "ไม่ถูก ค ผิด", "ไม่ถูก ค ผิด", "ไม่ถูก ง ผิด", "ไม่ถูก ค และ ง ผิด"]'::jsonb,'{"topic": "2.1", "n": 7}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2568,'bio:68-7');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-8','M6','M6-BI','M6-BI-S2','A-Level 66',null,2,'พิจารณาภาพและข้อความเกี่ยวกับสารชีวโมเลกุล ต่อไปนี้','["ก. และ ค. เท่านั้น", "ก. และ ง. เท่านั้น", "ข. และ ค. เท่านั้น", "ข. และ ง. เท่านั้น", "ค. และ ง. เท่านั้น"]'::jsonb,1,array[1]::smallint[],'["ภาพคือนิวคลีโอไทด์ · ก ถูก A คือเบสไนโตรเจน · ข ผิด พอลิเมอร์คือพอลินิวคลีโอไทด์ · ค ผิด B คือ OH ที่คาร์บอน 2′ แสดงว่าเป็นน้ำตาลไรโบส (RNA) · ง ถูก หมู่ 3′-OH (C) เชื่อมกับหมู่ฟอสเฟตที่ 5′ (D) ของนิวคลีโอไทด์ถัดไปด้วยพันธะฟอสโฟไดเอสเทอร์"]'::jsonb,'["ไม่ถูก ค ผิด", "ถูก ก และ ง", "ไม่ถูก ข และ ค ผิด", "ไม่ถูก ข ผิด", "ไม่ถูก ค ผิด"]'::jsonb,'{"img": "bio-68-8.png", "after": "ก. ตำแหน่ง A มีอะตอมไนโตรเจนเป็นองค์ประกอบ\nข. พอลิเมอร์ของโมเลกุลในภาพ เรียกว่า พอลิเพปไทด์\nค. ตำแหน่ง B แสดงให้เห็นว่าโมเลกุลในภาพ เป็นองค์ประกอบของสายดีเอ็นเอ\nง. พอลิเมอร์ของโมเลกุลในภาพเกิดจากการเชื่อมต่อกันระหว่างตำแหน่ง C กับตำแหน่ง D ของโมเลกุลถัดไป\nข้อใดถูกต้อง", "topic": "2.1", "n": 8, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/bio-68-8.png"}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2568,'bio:68-8');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-9','M6','M6-BI','M6-BI-S2','A-Level 66',null,2,'พิจารณาเหตุการณ์ต่อไปนี้
ก. การกินอาหารของอะมีบาโดยกระบวนการ phagocytosis
ข. การเคลื่อนที่ของออร์แกเนลล์ไปบริเวณต่าง ๆ ของไซโทพลาซึม
ค. การลำเลียงกลูโคสเข้าสู่เซลล์ด้วยกระบวนการ active transport
ง. การเชื่อมต่อกันระหว่างเยื่อหุ้มเซลล์และเวสิเคิลในกระบวนการขนส่งโปรตีนออกนอกเซลล์
ข้อใดแสดงคุณสมบัติหลักของฟลูอิดโมเซอิกโมเดล (fluid mosaic model) ของเยื่อหุ้มเซลล์','["ก. และ ค. เท่านั้น", "ก. และ ง. เท่านั้น", "ข. และ ค. เท่านั้น", "ข. และ ง. เท่านั้น", "ค. และ ง. เท่านั้น"]'::jsonb,1,array[1]::smallint[],'["สมบัติหลักคือความเป็นของไหลของเยื่อหุ้มเซลล์ ทำให้เยื่อหุ้มโอบล้อมอาหาร (ฟาโกไซโทซิส) และหลอมรวมกับเวสิเคิล (เอกโซไซโทซิส) ได้ · ข เป็นงานของไซโทสเกเลตอน · ค เป็นงานของโปรตีนตัวพา"]'::jsonb,'["ไม่ถูก ค อาศัยโปรตีนตัวพาและ ATP", "ถูก ก และ ง", "ไม่ถูก ข และ ค ไม่ได้แสดงความเป็นของไหลของเยื่อหุ้ม", "ไม่ถูก ข เกี่ยวกับไซโทสเกเลตอน", "ไม่ถูก ค ผิด"]'::jsonb,'{"topic": "2.2", "n": 9}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2568,'bio:68-9');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-10','M6','M6-BI','M6-BI-S2','A-Level 66',null,2,'พิจารณาข้อความเกี่ยวกับไรโบโซม ต่อไปนี้
ก. ไรโบโซมเข้าจับกับ mRNA เพื่อเริ่มต้นการถอดรหัสพันธุกรรม
ข. ไรโบโซมในเซลล์มนุษย์ประกอบด้วย 2 หน่วยย่อยที่มีขนาดต่างกัน
ค. โครงสร้างของไรโบโซมประกอบด้วยกรดอะมิโนและนิวคลีโอไทด์จำนวนมาก
ง. ไรโบโซมที่เกาะอยู่ที่ผิวของเอนโดพลาสมิกเรติคูลัมไม่มีบทบาทในกระบวนการสังเคราะห์โปรตีน
ข้อใดถูกต้อง','["ก. และ ค. เท่านั้น", "ก. และ ง. เท่านั้น", "ข. และ ค. เท่านั้น", "ข. และ ง. เท่านั้น", "ค. และ ง. เท่านั้น"]'::jsonb,2,array[2]::smallint[],'["ก ผิด ไรโบโซมจับ mRNA เพื่อแปลรหัส (translation) ไม่ใช่ถอดรหัส · ข ถูก หน่วยย่อยใหญ่และเล็ก · ค ถูก ไรโบโซมประกอบด้วยโปรตีน (กรดอะมิโน) และ rRNA (นิวคลีโอไทด์) · ง ผิด ไรโบโซมบน ER สังเคราะห์โปรตีน"]'::jsonb,'["ไม่ถูก ก ผิด", "ไม่ถูก ก และ ง ผิด", "ถูก ข และ ค", "ไม่ถูก ง ผิด", "ไม่ถูก ง ผิด"]'::jsonb,'{"topic": "2.2", "n": 10}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2568,'bio:68-10');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-11','M6','M6-BI','M6-BI-S2','A-Level 66',null,2,'พิจารณาข้อความเกี่ยวกับการหายใจระดับเซลล์ต่อไปนี้
ก. พลังงานทั้งหมดจากการสลายสารประกอบคาร์บอนในวัฏจักรเครบส์อยู่ในรูปของโมเลกุล ATP
ข. การสลายกลูโคส 1 โมเลกุลในกระบวนการไกลโคไลซิสนำไปสู่การเกิดวัฏจักรเครบส์จำนวน 2 ครั้ง
ค. กระบวนการสลายลิพิดเพื่อสร้างพลังงานให้แก่เซลล์ไม่นำไปสู่การเกิดวัฏจักรเครบส์ ซึ่งแตกต่างจากการสลายคาร์โบไฮเดรต
ง. ความแตกต่างของความเข้มข้นของ H⁺ ระหว่างเมทริกซ์และช่องว่างระหว่างเยื่อหุ้มสองชั้นของไมโทคอนเดรีย เป็นปัจจัยหลักที่ก่อให้เกิดการสร้าง ATP ในกระบวนการถ่ายทอดอิเล็กตรอน
ข้อใดถูกต้อง','["ก. และ ค. เท่านั้น", "ก. และ ง. เท่านั้น", "ข. และ ค. เท่านั้น", "ข. และ ง. เท่านั้น", "ค. และ ง. เท่านั้น"]'::jsonb,3,array[3]::smallint[],'["ก ผิด พลังงานส่วนใหญ่จากวัฏจักรเครบส์อยู่ใน NADH และ FADH₂ · ข ถูก ได้ไพรูเวต 2 โมเลกุล → แอซิทิลโคเอ 2 โมเลกุล → วัฏจักรเครบส์ 2 รอบ · ค ผิด กรดไขมันถูกสลายเป็นแอซิทิลโคเอเข้าวัฏจักรเครบส์ · ง ถูก (เคมีออสโมซิส)"]'::jsonb,'["ไม่ถูก ก และ ค ผิด", "ไม่ถูก ก ผิด", "ไม่ถูก ค ผิด", "ถูก ข และ ง", "ไม่ถูก ค ผิด"]'::jsonb,'{"topic": "2.2", "n": 11}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2568,'bio:68-11');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-12','M6','M6-BI','M6-BI-S3','A-Level 66',null,2,'อวัยวะ ก ข ค ง และ จ เป็นอวัยวะที่เกี่ยวข้องกับระบบทางเดินอาหาร ดังนี้
อวัยวะ ก สร้างเพปซิโนเจน
อวัยวะ ข มีการย่อยไขมันและกรดนิวคลีอิกเกิดขึ้น
อวัยวะ ค มีการย่อยแป้งจนได้เดกซ์ทรินและมอลโทส
อวัยวะ ง สร้างสารที่ทำให้ไขมันแตกตัว
อวัยวะ จ สร้างโซเดียมไฮโดรเจนคาร์บอเนต
ข้อใดถูกต้อง','["อวัยวะ ค ไม่มีการย่อยเชิงกล", "อวัยวะ ง สร้างเอนไซม์ที่ใช้ในการย่อยอาหาร", "อวัยวะ ก มีการย่อยอาหารประเภทโปรตีนเท่านั้น", "มีการลำเลียงวิตามินเอเข้าสู่หลอดเลือดฝอยภายในอวัยวะ ข", "อวัยวะ จ มีการย่อยอาหารประเภทคาร์โบไฮเดรต โปรตีน ไขมัน และกรดนิวคลีอิก"]'::jsonb,2,array[2]::smallint[],'["ก กระเพาะอาหาร · ข ลำไส้เล็ก · ค ปาก · ง ตับ (สร้างน้ำดี) · จ ตับอ่อน · กระเพาะอาหารมีเอนไซม์เพปซินย่อยโปรตีนเท่านั้น"]'::jsonb,'["ไม่ถูก ปากมีการบดเคี้ยว (ย่อยเชิงกล)", "ไม่ถูก น้ำดีจากตับไม่ใช่เอนไซม์", "ถูก กระเพาะย่อยโปรตีนด้วยเพปซิน", "ไม่ถูก วิตามินเอละลายในไขมัน ลำเลียงเข้าหลอดน้ำเหลือง (แล็กทีล)", "ไม่ถูก ตับอ่อนสร้างเอนไซม์ แต่การย่อยเกิดในลำไส้เล็ก"]'::jsonb,'{"topic": "3.1", "n": 12}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'bio:68-12');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-13','M6','M6-BI','M6-BI-S3','A-Level 66',null,2,'ข้อใดถูกต้องเกี่ยวกับระบบขับถ่าย','["การขับเหงื่อและการหายใจออก ไม่เกี่ยวข้องกับระบบขับถ่าย", "การดื่มน้ำมาก ๆ จะส่งผลให้เกิดการดูดกลับน้ำที่ท่อขดส่วนปลายและท่อรวมเพิ่มขึ้น", "ฟองน้ำและไฮดรา ขับถ่ายของเสียออกสู่สิ่งแวดล้อมผ่านทางโครงสร้างที่มีลักษณะเฉพาะ", "กลูโคสและกรดอะมิโน เป็นสารที่ไม่สามารถผ่านโกลเมอรูลัสไปยังท่อขดส่วนต้นได้ ดังนั้นคนสุขภาพปกติจึงไม่พบกลูโคสและกรดอะมิโนในปัสสาวะ", "ห่วงเฮนเลขาลงมีบทบาทในการดูดกลับน้ำโดยการออสโมซิส ส่วนห่วงเฮนเลขาขึ้นมีบทบาทในการดูดกลับโซเดียมไอออนและคลอไรด์ไอออนโดยวิธีแอกทีฟทรานสปอร์ต"]'::jsonb,4,array[4]::smallint[],'["ห่วงเฮนเลขาลงยอมให้น้ำผ่านและดูดกลับน้ำโดยออสโมซิส ขาขึ้นไม่ยอมให้น้ำผ่านแต่ลำเลียง Na⁺ และ Cl⁻ ออก (ส่วนหนาใช้แอกทีฟทรานสปอร์ต)"]'::jsonb,'["ไม่ถูก ผิวหนังและปอดช่วยขับของเสีย", "ไม่ถูก ดื่มน้ำมาก ADH ลดลง การดูดกลับน้ำลดลง", "ไม่ถูก ฟองน้ำและไฮดราขับของเสียโดยการแพร่ผ่านผิวเซลล์ ไม่มีโครงสร้างเฉพาะ", "ไม่ถูก กลูโคสและกรดอะมิโนกรองผ่านโกลเมอรูลัสได้ แล้วถูกดูดกลับที่ท่อขดส่วนต้น", "ถูก"]'::jsonb,'{"topic": "3.4", "n": 13}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'bio:68-13');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-14','M6','M6-BI','M6-BI-S3','A-Level 66',null,2,'ฮอร์โมน A B และ C มีคุณสมบัติ ดังตาราง','["หากต่อมใต้สมองส่วนหลังถูกทำลาย จะส่งผลกระทบต่อการหลั่งฮอร์โมน A", "ฮอร์โมน B ทำหน้าที่กระตุ้นกล้ามเนื้อรอบต่อมน้ำนม เพื่อให้เกิดการขับน้ำนม", "หากไฮโพทาลามัสถูกทำลาย จะไม่ส่งผลกระทบต่อการสร้างฮอร์โมน A และ C", "ฮอร์โมน C ทำหน้าที่กระตุ้นการสร้างสเปิร์มในอัณฑะ และกระตุ้นการตกไข่ในรังไข่", "การสร้างและหลั่งฮอร์โมน B ถูกกระตุ้นโดยฮอร์โมน PIH ซึ่งสร้างจากไฮโพทาลามัส"]'::jsonb,0,array[0]::smallint[],'["A คือ ADH สร้างจากไฮโพทาลามัสและหลั่งจากต่อมใต้สมองส่วนหลัง · B คือโพรแล็กทิน · C คือโกนาโดโทรฟิน (FSH หรือ LH) · ถ้าต่อมใต้สมองส่วนหลังถูกทำลาย การหลั่ง ADH ได้รับผลกระทบ"]'::jsonb,'["ถูก", "ไม่ถูก การขับน้ำนมเป็นหน้าที่ของออกซิโทซิน โพรแล็กทินกระตุ้นการสร้างน้ำนม", "ไม่ถูก ADH สร้างที่ไฮโพทาลามัส และการหลั่ง C ถูกควบคุมโดย GnRH จากไฮโพทาลามัส", "ไม่ถูก FSH กระตุ้นการสร้างสเปิร์มและการเจริญของฟอลลิเคิล ส่วนการตกไข่กระตุ้นโดย LH ฮอร์โมนเดียวไม่ได้ทำทั้งสองหน้าที่", "ไม่ถูก PIH ยับยั้งการหลั่งโพรแล็กทิน"]'::jsonb,'{"table": [["ฮอร์โมน", "สร้างจาก", "หน้าที่", "อวัยวะเป้าหมาย"], ["A", "?", "ควบคุมการดูดกลับน้ำในระบบขับถ่ายปัสสาวะ", "?"], ["B", "ต่อมใต้สมองส่วนหน้า", "?", "ต่อมน้ำนม"], ["C", "ต่อมใต้สมองส่วนหน้า", "?", "รังไข่และอัณฑะ"]], "after": "จากข้อมูล ข้อใดถูกต้อง", "topic": "3.8", "n": 14}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'bio:68-14');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-15','M6','M6-BI','M6-BI-S3','A-Level 66',null,2,'พิจารณาเหตุการณ์หนึ่ง ดังนี้
เช้าวันหนึ่ง นาย A กำลังนั่งรับประทานอาหารอยู่ที่โรงอาหาร เขามองออกไปด้านนอก เห็นนาย B กำลังวิ่งออกกำลังกายรอบสนาม
หลังจากนั้น นาย C เดินเข้ามาหานาย A ด้วยสีหน้าเคร่งเครียด เขานั่งลงข้างนาย A พร้อมกับหยิบหนังสือวิชาชีววิทยาออกมาอ่าน เมื่อนาย A ชวนคุย จึงรู้ว่านาย C กำลังจะเข้าสอบวิชาชีววิทยาในอีก 1 ชั่วโมงข้างหน้า แต่นาย C ยังไม่เข้าใจเนื้อหาในบทเรียน จึงเกิดความเครียดสะสมมาตั้งแต่เมื่อคืน นาย A ให้กำลังใจนาย C แล้วขอตัวไปเข้าเรียนก่อน
เมื่อมาถึงห้องเรียน เพื่อน ๆ เล่าให้นาย A ฟังว่า เมื่อวานนี้บ้านของนาย D เกิดไฟไหม้ นาย D ตกใจมาก จึงยกข้าวของต่าง ๆ ทั้งตู้เย็น ตู้เสื้อผ้า โซฟา เครื่องซักผ้า โทรทัศน์ ออกมาวางไว้นอกบ้านด้วยตัวคนเดียว แต่เมื่อเหตุการณ์คลี่คลายลงแล้ว นาย D กลับไม่สามารถยกข้าวของต่าง ๆ กลับเข้าบ้านได้ด้วยตัวเอง จึงไปขอความช่วยเหลือจากเพื่อนบ้าน
จากข้อมูล ข้อใดถูกต้อง','["ร่างกายของนาย C มีการหลั่งฮอร์โมนในกลุ่มกลูโคคอร์ทิคอยด์ ทำให้ระดับน้ำตาลในเลือดลดต่ำลง", "ร่างกายของนาย D มีการหลั่งฮอร์โมนจากต่อมหมวกไตส่วนนอกอย่างรวดเร็ว ซึ่งถูกควบคุมโดยระบบประสาทอัตโนมัติ", "ร่างกายของนาย A เกิดการรักษาดุลยภาพของระดับน้ำตาลในเลือด โดยมีฮอร์โมนจากต่อมใต้สมองส่วนหน้ามากระตุ้นการหลั่งฮอร์โมนอินซูลิน", "การหลั่งฮอร์โมนของนาย A นาย B นาย C และนาย D จากเหตุการณ์ข้างต้น เกี่ยวข้องกับฮอร์โมนประสาทที่สร้างและหลั่งจากไฮโพทาลามัส", "ร่างกายของนาย B เกิดการรักษาดุลยภาพของระดับน้ำตาลในเลือด โดยมีการหลั่งฮอร์โมนที่สร้างจากเซลล์แอลฟาของไอส์เลตออฟลังเกอร์ฮันส์ในตับอ่อน ซึ่งมีบทบาทในการสลายไกลโคเจน"]'::jsonb,4,array[4]::smallint[],'["นาย B ออกกำลังกาย น้ำตาลในเลือดถูกใช้ไป เซลล์แอลฟาของไอส์เลตออฟลังเกอร์ฮันส์หลั่งกลูคากอน กระตุ้นการสลายไกลโคเจนที่ตับ"]'::jsonb,'["ไม่ถูก กลูโคคอร์ทิคอยด์ (คอร์ทิซอล) เพิ่มระดับน้ำตาลในเลือด", "ไม่ถูก ภาวะตกใจฉับพลันกระตุ้นต่อมหมวกไตส่วนใน (เอพิเนฟริน) ผ่านระบบประสาทซิมพาเทติก", "ไม่ถูก อินซูลินหลั่งตามระดับน้ำตาลในเลือดโดยตรง ไม่ได้ถูกกระตุ้นโดยต่อมใต้สมองส่วนหน้า", "ไม่ถูก อินซูลินและกลูคากอน (นาย A, B) ถูกควบคุมโดยระดับน้ำตาลในเลือด ไม่ได้ผ่านฮอร์โมนประสาทจากไฮโพทาลามัส", "ถูก"]'::jsonb,'{"topic": "3.8", "n": 15}'::jsonb,'imported_m6','imported',true,'ref','Exam Gym ม.6 · 5620e4c',2568,'bio:68-15');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-16','M6','M6-BI','M6-BI-S3','A-Level 66',null,2,'นางสาวเอ มีรอบประจำเดือนคงที่สม่ำเสมอที่ 28 วัน และมีประจำเดือนในวันที่ 3 ถึง 7 พฤศจิกายน ดังปฏิทิน นางสาวเอมีเพศสัมพันธ์โดยไม่มีการคุมกำเนิดเพียง 1 ครั้ง ในวันที่ 18 พฤศจิกายน และตรวจพบ human chorionic gonadotropin (hCG) ในเดือนธันวาคม','["นางสาวเอจะมีประจำเดือนอีกครั้งในวันที่ 30 พฤศจิกายน", "ในวันที่ 14 พฤศจิกายน luteinizing hormone (LH) และ estrogen ของนางสาวเออยู่ในระดับสูงสุด", "วันที่ 3 ถึง 15 พฤศจิกายน เป็นช่วงที่เซลล์สืบพันธุ์เพศหญิงเกิดการแบ่งเซลล์แบบไมโทซิสและไมโอซิส", "ในวันที่ 17 พฤศจิกายน secondary oocyte ที่ระยะเมทาเฟส II จะกำลังเคลื่อนที่อยู่ในท่อนำไข่ด้วยการพัดโบกของซิเลีย", "progesterone มีระดับสูงสุดในสัปดาห์ที่ 4 ของเดือนพฤศจิกายน แล้วค่อย ๆ ลดลงในสัปดาห์สุดท้ายของเดือนพฤศจิกายน"]'::jsonb,3,array[3]::smallint[],'["วันที่ 3 พ.ย. เป็นวันที่ 1 ของรอบ การตกไข่ประมาณวันที่ 14 ของรอบ คือราว 16 พ.ย. · วันที่ 17 พ.ย. เซลล์ไข่ (secondary oocyte ที่หยุดอยู่ระยะเมทาเฟส II) อยู่ในท่อนำไข่ และถูกพัดโบกด้วยซิเลีย · ตรวจพบ hCG แสดงว่าตั้งครรภ์"]'::jsonb,'["ไม่ถูก ตั้งครรภ์จึงไม่มีประจำเดือน (และถ้าไม่ตั้งครรภ์ รอบถัดไปจะเริ่ม 1 ธ.ค.)", "ไม่ถูก ระดับ LH สูงสุดเกิดก่อนการตกไข่ราว 1 วัน (ประมาณ 15 พ.ย.) ไม่ใช่วันที่ 14", "ไม่ถูก การแบ่งแบบไมโทซิสของโอโอโกเนียมเกิดตั้งแต่ก่อนเกิด", "ถูก", "ไม่ถูก เมื่อตั้งครรภ์ hCG รักษาคอร์ปัสลูเทียม โพรเจสเทอโรนจึงไม่ลดลง"]'::jsonb,'{"img": "bio-68-16.png", "after": "จากข้อมูล ข้อใดถูกต้อง", "topic": "3.7", "n": 16, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/bio-68-16.png"}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'bio:68-16');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-17','M6','M6-BI','M6-BI-S3','A-Level 66',null,2,'ข้อใดถูกต้องเกี่ยวกับการสืบพันธุ์ของสิ่งมีชีวิต','["ดาวทะเลและจิ้งจกสามารถสืบพันธุ์แบบงอกใหม่ได้", "เอ็มบริโอของกบ ไก่ และมนุษย์ได้รับสารอาหารจากไข่แดง", "สัตว์ที่อาศัยอยู่ในน้ำจำเป็นต้องอาศัยน้ำเพื่อช่วยในการปฏิสนธิภายนอกเสมอ", "ฟองน้ำ ไฮดรา พลานาเรีย และแมงกะพรุน สามารถสืบพันธุ์แบบอาศัยเพศได้", "การสืบพันธุ์แบบไม่อาศัยเพศทำให้สัตว์เพิ่มจำนวนได้อย่างรวดเร็วโดยไม่ต้องจับคู่ผสมพันธุ์ จึงทำให้สัตว์มีโอกาสอยู่รอดในกระบวนการคัดเลือกโดยธรรมชาติ มากกว่าการสืบพันธุ์แบบอาศัยเพศ"]'::jsonb,3,array[3]::smallint[],'["ฟองน้ำ ไฮดรา พลานาเรีย และแมงกะพรุน สืบพันธุ์ได้ทั้งแบบไม่อาศัยเพศและแบบอาศัยเพศ"]'::jsonb,'["ไม่ถูก จิ้งจกงอกหางใหม่ได้ แต่ไม่ใช่การสืบพันธุ์", "ไม่ถูก เอ็มบริโอมนุษย์ได้รับสารอาหารผ่านรก", "ไม่ถูก สัตว์น้ำหลายชนิด (เช่น ฉลาม วาฬ) ปฏิสนธิภายใน", "ถูก", "ไม่ถูก การสืบพันธุ์แบบอาศัยเพศเพิ่มความแปรผันทางพันธุกรรม ช่วยให้อยู่รอดในการคัดเลือกโดยธรรมชาติได้ดีกว่า"]'::jsonb,'{"topic": "3.7", "n": 17}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'bio:68-17');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-18','M6','M6-BI','M6-BI-S3','A-Level 66',null,2,'ชายรายหนึ่งถูกสุนัขจรจัดกัดที่ขาจนเป็นแผลเลือดออก ชายรายนี้ไม่เคยได้รับวัคซีนป้องกันโรคพิษสุนัขบ้ามาก่อน แพทย์จึงฉีดเซรุ่ม (serum) และวัคซีนป้องกันโรคพิษสุนัขบ้าให้
จากข้อมูล ข้อใดถูกต้อง','["เซรุ่มกระตุ้นเซลล์ความจำ (memory cell) ทำให้ร่างกายสร้างแอนติบอดีต่อไวรัสได้เร็วขึ้น", "วัคซีนมีองค์ประกอบเป็นแอนติบอดีสำเร็จรูปที่เข้าไปจับกับแอนติเจนของไวรัสโรคพิษสุนัขบ้า", "เซรุ่มประกอบด้วยโปรตีนประเภทอิมมูโนโกลบูลิน (immunoglobulin) ที่ช่วยต้านไวรัสได้ทันที", "วัคซีนช่วยกระตุ้นการสร้างเซลล์เม็ดเลือดขาวชนิดแมโครฟาจ (macrophage) เพื่อกำจัดเชื้อไวรัส", "การให้เซรุ่มเป็นการให้ภูมิคุ้มกันต้านไวรัสแบบไม่จำเพาะ เสริมการทำงานของวัคซีนซึ่งเป็นการต้านไวรัสแบบจำเพาะ"]'::jsonb,2,array[2]::smallint[],'["เซรุ่มคือแอนติบอดีสำเร็จรูป (อิมมูโนโกลบูลิน) ให้ภูมิคุ้มกันรับมาทันที ส่วนวัคซีนเป็นแอนติเจนที่กระตุ้นให้ร่างกายสร้างภูมิคุ้มกันเอง"]'::jsonb,'["ไม่ถูก เซรุ่มไม่ได้กระตุ้นการสร้างเซลล์ความจำ", "ไม่ถูก วัคซีนประกอบด้วยแอนติเจน (เชื้อที่ทำให้อ่อนฤทธิ์หรือตายแล้ว)", "ถูก", "ไม่ถูก วัคซีนกระตุ้นลิมโฟไซต์ (เซลล์บี เซลล์ที) ซึ่งเป็นภูมิคุ้มกันแบบจำเพาะ", "ไม่ถูก แอนติบอดีในเซรุ่มจำเพาะต่อไวรัส"]'::jsonb,'{"topic": "3.3", "n": 18}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'bio:68-18');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-19','M6','M6-BI','M6-BI-S3','A-Level 66',null,2,'แผนภาพระบบไหลเวียนเลือดของสัตว์มีกระดูกสันหลังชนิดหนึ่ง เป็นดังนี้','["หัวใจของสัตว์ชนิดนี้มีสามห้อง", "สัตว์ชนิดนี้เป็นสัตว์เลี้ยงลูกด้วยน้ำนม", "เลือดในหลอดเลือด A มีอัตราการไหลต่ำที่สุด", "เลือดในหลอดเลือด A มี PO₂ สูงกว่าเลือดในหลอดเลือด B", "เลือดในหลอดเลือด B มี PO₂ สูงกว่าเลือดในหลอดเลือด C"]'::jsonb,4,array[4]::smallint[],'["เลือดผ่านหัวใจครั้งเดียวต่อรอบ (ระบบไหลเวียนเดี่ยว) แบบปลา หัวใจ 2 ห้อง · หัวใจ → A → อวัยวะแลกเปลี่ยนแก๊ส (เหงือก) → B (เลือดมีออกซิเจนสูง) → เนื้อเยื่อ → C (ออกซิเจนต่ำ) → หัวใจ"]'::jsonb,'["ไม่ถูก ระบบไหลเวียนเดี่ยวแบบปลามีหัวใจ 2 ห้อง", "ไม่ถูก สัตว์เลี้ยงลูกด้วยน้ำนมมีระบบไหลเวียนคู่", "ไม่ถูก A ออกจากหัวใจโดยตรง ความดันและอัตราการไหลสูง", "ไม่ถูก A ยังไม่ผ่านการแลกเปลี่ยนแก๊ส มี PO₂ ต่ำกว่า B", "ถูก B ผ่านเหงือกแล้ว ส่วน C ผ่านเนื้อเยื่อมาแล้ว"]'::jsonb,'{"img": "bio-68-19.png", "after": "จากข้อมูล ข้อใดถูกต้อง", "topic": "3.2", "n": 19, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/bio-68-19.png"}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'bio:68-19');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-20','M6','M6-BI','M6-BI-S3','A-Level 66',null,2,'ตารางแสดงระดับความดันย่อยของออกซิเจน (PO₂) และความดันย่อยของคาร์บอนไดออกไซด์ (PCO₂) ในเลือด ของหลอดเลือดที่นำเลือดเข้าหรือออกจากหัวใจ ของชายรายหนึ่ง เป็นดังนี้','["ก. เท่านั้น", "ข. เท่านั้น", "ก. และ ข. เท่านั้น", "ก. และ ค. เท่านั้น", "ข. และ ค. เท่านั้น"]'::jsonb,1,array[1]::smallint[],'["B (PO₂ 40, PCO₂ 45) เป็นเลือดที่มีออกซิเจนต่ำ เช่น pulmonary artery หรือ vena cava · C (PO₂ 104) คือ pulmonary vein · ก ผิด · ข ถูก aorta นำเลือดที่ผ่านปอดแล้ว · ค ผิด ที่ที่สูงความดันย่อยของออกซิเจนในอากาศต่ำ PO₂ ในเลือดจึงลดลง การเพิ่มเม็ดเลือดแดงเพิ่มปริมาณออกซิเจนที่ขนได้ แต่ไม่ได้เพิ่ม PO₂"]'::jsonb,'["ไม่ถูก pulmonary vein มีเลือดออกซิเจนสูง", "ถูก", "ไม่ถูก ก ผิด", "ไม่ถูก ก และ ค ผิด", "ไม่ถูก ค ผิด"]'::jsonb,'{"table": [["หลอดเลือด", "ชื่อหลอดเลือด", "ระดับ PO₂ (mmHg)", "ระดับ PCO₂ (mmHg)"], ["A", "aorta", "?", "?"], ["B", "?", "40", "45"], ["C", "?", "104", "40"]], "after": "พิจารณาข้อความต่อไปนี้\nก. หลอดเลือด B คือหลอดเลือด pulmonary vein เพราะเลือดมีระดับ PO₂ ต่ำ\nข. เลือดในหลอดเลือด A มีระดับ PCO₂ น้อยกว่า 45 mmHg เพราะผ่านการแลกเปลี่ยนแก๊สที่ปอดแล้ว\nค. หากชายคนนี้ไปปีนเขาเอเวอเรสต์ถึงระดับความสูงเหนือน้ำทะเล 4,000 เมตร เลือดในหลอดเลือด A และ C จะมีระดับ PO₂ เพิ่มขึ้น เพราะร่างกายปรับตัวให้ผลิตเม็ดเลือดแดงจำนวนเพิ่มมากขึ้น\nจากข้อมูล ข้อใดถูกต้อง", "topic": "3.2", "n": 20}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2568,'bio:68-20');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-21','M6','M6-BI','M6-BI-S3','A-Level 66',null,2,'การทดลองหาความไวในการรับสัมผัสของผิวหนัง โดยวิธี “การจำแนกจุดสัมผัส 2 จุด (two-point discrimination test)” มีผลการทดลอง ดังนี้','["ปลายนิ้วชี้มีความไวในการรับสัมผัสมากกว่าแก้ม", "บริเวณไหล่มีปลายประสาทรับสัมผัสหนาแน่นที่สุด", "แอกซอนของเซลล์ประสาทรับความรู้สึกนี้ ไม่มีเยื่อไมอีลินหุ้ม", "หน่วยรับความรู้สึกที่เกี่ยวข้อง เป็นหน่วยรับรู้สารเคมี (chemoreceptor)", "หากระยะห่างที่แยกจุดสัมผัสได้เป็น 2 จุดมีค่าน้อย แสดงว่าบริเวณนั้นมีความไวในการรับสัมผัสน้อย"]'::jsonb,0,array[0]::smallint[],'["ระยะที่แยก 2 จุดได้ยิ่งน้อย แสดงว่าปลายประสาทรับสัมผัสหนาแน่นและไวมาก · ปลายนิ้วชี้ (2 mm) ไวกว่าแก้ม (8 mm)"]'::jsonb,'["ถูก", "ไม่ถูก ไหล่มีระยะมากที่สุด ปลายประสาทหนาแน่นน้อยที่สุด", "ไม่ถูก ใยประสาทรับสัมผัสส่วนใหญ่มีเยื่อไมอีลินหุ้ม", "ไม่ถูก การสัมผัสรับรู้ด้วยหน่วยรับแรงกล (mechanoreceptor)", "ไม่ถูก ระยะน้อยแสดงว่าไวมาก"]'::jsonb,'{"table": [["บริเวณร่างกาย", "ระยะที่น้อยที่สุดซึ่งสามารถแยกจุดสัมผัสออกเป็น 2 จุด (มิลลิเมตร)"], ["ปลายนิ้วชี้", "2"], ["แก้ม", "8"], ["ฝ่ามือ", "13"], ["ไหล่", "42"]], "after": "จากข้อมูล ข้อใดถูกต้อง", "topic": "3.6", "n": 21}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'bio:68-21');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-22','M6','M6-BI','M6-BI-S3','A-Level 66',null,2,'พิจารณาข้อความต่อไปนี้
ก. สะสมแร่ธาตุแคลเซียมคลอไรด์
ข. ทำงานร่วมกับกล้ามเนื้อเพื่อเคลื่อนไหว
ค. สร้างเซลล์เม็ดเลือดแดงและเม็ดเลือดขาว
ง. สร้างฮอร์โมนแคลซิโทนินควบคุมระดับแคลเซียมในเลือด
ข้อใดเป็นหน้าที่ของกระดูก','["ก. และ ข. เท่านั้น", "ข. และ ค. เท่านั้น", "ค. และ ง. เท่านั้น", "ก. ข. และ ค. เท่านั้น", "ข. ค. และ ง. เท่านั้น"]'::jsonb,1,array[1]::smallint[],'["ข ถูก · ค ถูก (ไขกระดูกแดง) · ก ผิด กระดูกสะสมแคลเซียมฟอสเฟต ไม่ใช่แคลเซียมคลอไรด์ · ง ผิด แคลซิโทนินสร้างจากต่อมไทรอยด์"]'::jsonb,'["ไม่ถูก ก ผิด", "ถูก ข และ ค", "ไม่ถูก ง ผิด", "ไม่ถูก ก ผิด", "ไม่ถูก ง ผิด"]'::jsonb,'{"topic": "3.6", "n": 22}'::jsonb,'imported_m6','imported',true,'labelseq','Exam Gym ม.6 · 5620e4c',2568,'bio:68-22');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-23','M6','M6-BI','M6-BI-S3','A-Level 66',null,2,'ข้อใดเป็นพฤติกรรมที่เป็นมาแต่กำเนิด (innate behavior)','["ชิมแปนซีใช้วัตถุเป็นเครื่องมือในการหาอาหาร", "นกพิราบในเมืองไม่บินหนี เมื่อมีคนเดินผ่านไปมา", "ลูกห่านเดินตามของเล่นที่เห็นขณะฟักออกจากไข่", "แม่ห่านที่กกไข่กลิ้งไข่กลับเข้ารัง เมื่อเห็นไข่อยู่นอกรัง", "แมววิ่งเข้าไปในครัว เมื่อได้ยินเสียงเปิดกระป๋องอาหาร"]'::jsonb,3,array[3]::smallint[],'["การกลิ้งไข่กลับเข้ารังของแม่ห่านเป็นพฤติกรรมแบบรูปแบบตายตัว (fixed action pattern) ซึ่งเป็นมาแต่กำเนิด"]'::jsonb,'["ไม่ถูก เป็นการเรียนรู้แบบใช้เหตุผล (insight)", "ไม่ถูก เป็นแฮบิชูเอชัน (การเรียนรู้)", "ไม่ถูก เป็นการฝังใจ (imprinting) ซึ่งจัดเป็นการเรียนรู้", "ถูก", "ไม่ถูก เป็นการเรียนรู้แบบมีเงื่อนไข"]'::jsonb,'{"topic": "3.9", "n": 23}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'bio:68-23');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-24','M6','M6-BI','M6-BI-S4','A-Level 66',null,2,'พิจารณาข้อความเกี่ยวกับใบพืช ต่อไปนี้
ก. ปากใบ (stomata) ในแผ่นใบพืช พบได้เฉพาะที่เนื้อเยื่อชั้นผิวใบด้านล่าง
ข. แพลิเซดมีโซฟิลล์ (palisade mesophyll) ประกอบด้วยเซลล์พาเรงคิมารูปร่างยาว เรียงตัวเป็นแถวตั้งฉากกับผิวใบ และมีคลอโรพลาสต์สะสมอยู่ภายในเซลล์
ค. สปองจีมีโซฟิลล์ (spongy mesophyll) ประกอบด้วยเซลล์ที่มีรูปร่างไม่แน่นอน ช่องว่างระหว่างเซลล์มาก และไม่มีคลอโรพลาสต์สะสมอยู่ภายในเซลล์
ง. วาสคิวลาร์บันเดิล (vascular bundle) ที่มีขนาดใหญ่จะอยู่บริเวณเส้นกลางใบ ที่เหลือมีขนาดเล็กลดหลั่นกันไปอยู่ที่บริเวณเส้นใบและเส้นใบย่อย
ข้อใด**ไม่**ถูกต้อง','["ก. และ ข. เท่านั้น", "ก. และ ค. เท่านั้น", "ข. และ ค. เท่านั้น", "ข. และ ง. เท่านั้น", "ทั้ง ก. ข. ค. และ ง."]'::jsonb,1,array[1]::smallint[],'["ก ผิด ปากใบพบได้ทั้งผิวใบด้านบนและด้านล่าง (พืชหลายชนิดมีด้านล่างมากกว่า) · ค ผิด สปองจีมีโซฟิลล์มีคลอโรพลาสต์ แต่น้อยกว่าแพลิเซด · ข และ ง ถูก"]'::jsonb,'["ไม่ถูก ข ถูกต้อง", "ถูก ก และ ค ไม่ถูกต้อง", "ไม่ถูก ข ถูกต้อง", "ไม่ถูก ข และ ง ถูกต้อง", "ไม่ถูก ข และ ง ถูกต้อง"]'::jsonb,'{"topic": "4.1", "n": 24}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2568,'bio:68-24');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-25','M6','M6-BI','M6-BI-S4','A-Level 66',null,2,'พิจารณากระบวนการสืบพันธุ์ของพืชดอก ดังภาพ','["การถ่ายเรณู การปฏิสนธิคู่ การงอกของหลอดเรณู การงอกของเมล็ด ไซโกต และเอ็มบริโอ", "การถ่ายเรณู การปฏิสนธิคู่ การงอกของเมล็ด การงอกของหลอดเรณู เอนโดสเปิร์ม และเอ็มบริโอ", "การถ่ายเรณู การปฏิสนธิคู่ การงอกของเมล็ด การงอกของหลอดเรณู เอ็มบริโอ และเอนโดสเปิร์ม", "การถ่ายเรณู การงอกของหลอดเรณู การปฏิสนธิคู่ การงอกของเมล็ด เอนโดสเปิร์ม และเอ็มบริโอ", "การถ่ายเรณู การงอกของหลอดเรณู การปฏิสนธิคู่ การงอกของเมล็ด เอ็มบริโอ และเอนโดสเปิร์ม"]'::jsonb,4,array[4]::smallint[],'["A เรณูตกบนยอดเกสรเพศเมีย (การถ่ายเรณู) · B หลอดเรณูงอกลงไปในก้านเกสร · C สเปิร์มเข้าผสมกับเซลล์ไข่และโพลาร์นิวคลีไอ (การปฏิสนธิคู่) · D ต้นอ่อนงอกจากเมล็ด · E คือไซโกต เจริญเป็นเอ็มบริโอ · F คือเซลล์ที่จะเจริญเป็นเอนโดสเปิร์ม"]'::jsonb,'["ไม่ถูก ลำดับ B และ C สลับกัน", "ไม่ถูก ลำดับกระบวนการผิด และ E/F สลับกัน", "ไม่ถูก ลำดับกระบวนการผิด", "ไม่ถูก E และ F สลับกัน", "ถูก"]'::jsonb,'{"img": "bio-68-25.png", "after": "ข้อใดระบุกระบวนการ A B C และ D ได้ถูกต้อง และโครงสร้าง E และ F พัฒนาไปเป็นโครงสร้างใด ตามลำดับ", "topic": "4.4", "n": 25, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/bio-68-25.png"}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'bio:68-25');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-26','M6','M6-BI','M6-BI-S4','A-Level 66',null,2,'พิจารณาข้อความเกี่ยวกับการลำเลียงของพืช ต่อไปนี้
ก. ในภาวะปกติการลำเลียงน้ำจากรากขึ้นสู่ลำต้นจะอาศัยแรงดึงจากการคายน้ำเป็นหลัก
ข. การลำเลียงซูโครสในโฟลเอ็มและการลำเลียงน้ำในไซเล็มมีทิศการลำเลียงทั้งขึ้นสู่ยอดและลงสู่ราก
ค. การลำเลียงน้ำเข้าสู่ไซเล็มแบบอโพพลาสต์เมื่อถึงเอนโดเดอร์มิสที่มีแถบแคสพาเรียน จะมีการเปลี่ยนทิศทางการลำเลียงของน้ำเป็นซิมพลาสต์และทรานส์เมมเบรน
ง. การลำเลียงธาตุอาหารเข้าสู่ไซเล็มสามารถเคลื่อนที่ผ่านชั้นคอร์เทกซ์โดยการลำเลียงแบบทรานส์เมมเบรนเท่านั้น เนื่องจากอยู่ในรูปไอออน แล้วสู่เอนโดเดอร์มิสก่อนเข้าสู่ไซเล็ม
ข้อใดถูกต้อง','["ก. และ ค. เท่านั้น", "ข. และ ง. เท่านั้น", "ก. ค. และ ง. เท่านั้น", "ข. ค. และ ง. เท่านั้น", "ทั้ง ก. ข. ค. และ ง."]'::jsonb,0,array[0]::smallint[],'["ก ถูก (แรงดึงจากการคายน้ำ) · ค ถูก แถบแคสพาเรียนกั้นทางอโพพลาสต์ · ข ผิด น้ำในไซเล็มลำเลียงขึ้นทางเดียว · ง ผิด ไอออนผ่านคอร์เทกซ์ได้ทั้งทางอโพพลาสต์และซิมพลาสต์"]'::jsonb,'["ถูก ก และ ค", "ไม่ถูก ข และ ง ผิด", "ไม่ถูก ง ผิด", "ไม่ถูก ข และ ง ผิด", "ไม่ถูก ข และ ง ผิด"]'::jsonb,'{"topic": "4.2", "n": 26}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2568,'bio:68-26');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-27','M6','M6-BI','M6-BI-S4','A-Level 66',null,2,'กราฟแสดงความกว้างของรูปากใบ การสะสมโพแทสเซียมไอออน และซูโครส ในเซลล์คุมในช่วงเวลาต่าง ๆ เป็นดังนี้','["ก. และ ข. เท่านั้น", "ก. และ ค. เท่านั้น", "ก. และ ง. เท่านั้น", "ข. และ ค. เท่านั้น", "ข. และ ง. เท่านั้น"]'::jsonb,2,array[2]::smallint[],'["ก ผิด รูปากใบแคบลงทำให้การคายน้ำลดลง · ง ผิด เมื่อ K⁺ ลดลง ชลศักย์ในเซลล์คุมสูงขึ้น น้ำจะออกจากเซลล์คุม ทำให้รูปากใบแคบลง · ข และ ค สอดคล้องกับกราฟ"]'::jsonb,'["ไม่ถูก ข สอดคล้องกับกราฟ", "ไม่ถูก ค ถูกต้อง", "ถูก ก และ ง ไม่ถูกต้อง", "ไม่ถูก ข และ ค ถูกต้อง", "ไม่ถูก ข ถูกต้อง"]'::jsonb,'{"img": "bio-68-27.png", "after": "พิจารณาเหตุการณ์ที่เกิดขึ้นหลังจากเวลา 13.00 น. เป็นต้นไป และข้อความต่อไปนี้\nก. เมื่อขนาดของรูปากใบมีแนวโน้มลดลง ทำให้การคายน้ำเพิ่มขึ้น ซึ่งส่งผลต่อการสะสมซูโครสในเซลล์คุมด้วย\nข. ในช่วงบ่ายที่มีการสะสมของซูโครสที่สูงในเซลล์คุม เป็นผลจากกระบวนการสังเคราะห์ด้วยแสง ทำให้เซลล์คุมยังคงรักษาความเต่งไว้ได้ถึงแม้โพแทสเซียมไอออนในเซลล์คุมจะลดลงก็ตาม\nค. ช่วงกลางคืนรูปากใบแคบลงเรื่อย ๆ เนื่องจากปริมาณซูโครสในเซลล์คุมมีแนวโน้มลดลง ส่งผลให้ค่าชลศักย์ภายในเซลล์คุมสูงกว่าเซลล์ข้างเคียง น้ำในเซลล์คุมจึงเคลื่อนที่ออกไปยังเซลล์ข้างเคียงทำให้รูปากใบแคบจนกระทั่งปากใบปิด\nง. เมื่อการสะสมโพแทสเซียมไอออนที่เซลล์คุมลดลงในช่วงเย็น ทำให้ค่าชลศักย์ภายในเซลล์คุมสูงกว่าเซลล์ข้างเคียง น้ำจากเซลล์ข้างเคียงจะเคลื่อนที่เข้าเซลล์คุม ส่งผลให้เซลล์คุมเต่งมากขึ้น และทำให้รูปากใบมีแนวโน้มเปิดกว้างขึ้น\nข้อใด**ไม่**ถูกต้อง", "topic": "4.2", "n": 27, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/bio-68-27.png"}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2568,'bio:68-27');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-28','M6','M6-BI','M6-BI-S4','A-Level 66',null,2,'ภาพแสดงอัตราการสังเคราะห์ด้วยแสงต่อหน่วยพื้นที่ของใบ ของพืชชนิด A และ B เป็นดังนี้','["ก. เท่านั้น", "ก. และ จ. เท่านั้น", "ข. และ ง. เท่านั้น", "ค. และ ง. เท่านั้น", "ค. และ จ. เท่านั้น"]'::jsonb,4,array[4]::smallint[],'["A อัตราไม่ลดลงเมื่อแสงและอุณหภูมิสูง = พืช C₄ (ข้าวโพด) ซึ่งเพิ่มความเข้มข้นของ CO₂ ในเซลล์บันเดิลชีท · B อัตราลดลงที่อุณหภูมิสูง = พืช C₃ (ถั่วเหลือง) อุณหภูมิสูงทำให้สัดส่วน CO₂ ต่อ O₂ ลดลง เกิดโฟโตเรสไพเรชันมากขึ้น"]'::jsonb,'["ไม่ถูก อ้อยเป็นพืช C₄ แต่กลไกคือเพิ่ม (ไม่ใช่ลด) ความเข้มข้นของ CO₂", "ไม่ถูก ก ผิด", "ไม่ถูก ข้าวสาลีเป็นพืช C₃ และ ง ผิดทิศทางของสัดส่วน", "ไม่ถูก ง ผิด สัดส่วน CO₂ ต่อ O₂ ลดลงเมื่ออุณหภูมิสูง", "ถูก ค และ จ"]'::jsonb,'{"img": "bio-68-28.png", "after": "พิจารณาข้อความเกี่ยวกับการสังเคราะห์ด้วยแสงของพืชชนิด A และ B ต่อไปนี้\nก. A คืออ้อย เนื่องจากมีกลไกในการลดความเข้มข้นของ CO₂ ทำให้เกิดโฟโตเรสไพเรชันน้อยลง จึงรักษาอัตราการสังเคราะห์ด้วยแสงไว้ได้ดีกว่าข้าวสาลี\nข. A คือข้าวสาลี เนื่องจากมีกลไกในการเพิ่มความเข้มข้นของ CO₂ ในเซลล์บันเดิลชีท ทำให้เกิดโฟโตเรสไพเรชันน้อยลง จึงรักษาอัตราการสังเคราะห์ด้วยแสงไว้ได้ดีกว่าข้าวโพด\nค. A คือข้าวโพด เนื่องจากมีกลไกในการเพิ่มความเข้มข้นของ CO₂ ในเซลล์บันเดิลชีท ทำให้เกิดโฟโตเรสไพเรชันน้อยลง จึงรักษาอัตราการสังเคราะห์ด้วยแสงไว้ได้ดีกว่าข้าวสาลี\nง. B คือข้าว เนื่องจากเมื่ออุณหภูมิสูงขึ้นจะทำให้ความเข้มข้นของ CO₂ ต่อ O₂ เพิ่มขึ้น ทำให้พืชมีการเกิดโฟโตเรสไพเรชันสูงขึ้น อัตราการสังเคราะห์ด้วยแสงจะลดลง\nจ. B คือถั่วเหลือง เนื่องจากเมื่ออุณหภูมิสูงขึ้นจะทำให้ความเข้มข้นของ CO₂ ต่อ O₂ ลดลง ทำให้พืชมีการเกิดโฟโตเรสไพเรชันสูงขึ้น อัตราการสังเคราะห์ด้วยแสงจะลดลง\nจากข้อมูล ข้อใดถูกต้อง", "topic": "4.3", "n": 28, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/bio-68-28.png"}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2568,'bio:68-28');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-29','M6','M6-BI','M6-BI-S4','A-Level 66',null,2,'หากพิจารณาการตอบสนองของพืชในลักษณะการเคลื่อนไหวกับทิศทางของสิ่งเร้าภายนอก ข้อใดมีรูปแบบการตอบสนองแตกต่างจากข้ออื่น','["การโค้งเข้าหาแสงของยอดพืช", "การเกี่ยวพันของมือเกาะตำลึง", "การเจริญเข้าหาน้ำหรือความชื้นของรากพืช", "การงอกของหลอดเรณูไปยังออวุลของพืชดอก", "การหุบและการบานของดอกบัวสายสีขาวจากการตอบสนองต่อแสง"]'::jsonb,4,array[4]::smallint[],'["ข้อ 1–4 เป็นทรอปิซึม (ทิศทางการเคลื่อนไหวสัมพันธ์กับทิศทางของสิ่งเร้า) ส่วนการหุบและบานของดอกเป็นนาสติกมูฟเมนต์ ซึ่งไม่ขึ้นกับทิศทางของสิ่งเร้า"]'::jsonb,'["เป็นโฟโททรอปิซึม", "เป็นทิกโมทรอปิซึม", "เป็นไฮโดรทรอปิซึม", "เป็นเคโมทรอปิซึม", "ต่างจากข้ออื่น จึงเป็นคำตอบ เป็นนาสติกมูฟเมนต์"]'::jsonb,'{"topic": "4.5", "n": 29}'::jsonb,'imported_m6','imported',true,'expl','Exam Gym ม.6 · 5620e4c',2568,'bio:68-29');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-30','M6','M6-BI','M6-BI-S5','A-Level 66',null,2,'กลุ่มอาการวาร์เดนเบิร์ก (Waardenburg syndrome) เป็นความผิดปกติทางพันธุกรรมที่ส่งผลให้เกิดภาวะสูญเสียการได้ยินและความผิดปกติในการสร้างเม็ดสี ลักษณะที่มักพบบ่อย คือการมีดวงตาสีฟ้าอ่อน ซึ่งมีสาเหตุจากมิวเทชันของยีนใดยีนหนึ่งที่เกี่ยวข้องกับการแบ่งและกระจายของนิวรัล เครสต์ (neural crest) ได้แก่ EDN3, EDNRB, MITF, PAX3, SNAI2 หรือ SOX10 โดยแอลลีลก่อโรคสามารถถ่ายทอดได้ทั้งแบบลักษณะเด่นและด้อยบนออโทโซม
ทารกแฝดชายหญิงคู่หนึ่ง ทารกเพศชายเกิดมามีดวงตาสีฟ้าอ่อนและได้รับการวินิจฉัยว่าป่วยด้วยกลุ่มอาการวาร์เดนเบิร์ก ในขณะที่ทารกเพศหญิงปกติ ในการสืบประวัติทางการแพทย์ของบิดาและมารดา พบว่า บิดามีดวงตาสีฟ้าอ่อน มีภาวะสูญเสียการได้ยินตั้งแต่กำเนิด แต่ได้ทำการผ่าตัดฝังประสาทหูเทียม ทำให้ความสามารถในการรับฟังเสียงเป็นปกติ เมื่อสืบค้นประวัติครอบครัวนี้กลับไป 4 รุ่น พบว่ามีสมาชิกในครอบครัวฝ่ายพ่อ 1 คน คือย่าของทารกคู่นี้ซึ่งเสียชีวิตแล้วด้วยอุบัติเหตุ มีดวงตาสีฟ้าเช่นกัน ส่วนครอบครัวของฝ่ายแม่ไม่พบความผิดปกติแต่อย่างใด
จากข้อมูล ข้อใดถูกต้อง','["แอลลีลก่อโรคในครอบครัวนี้มีการถ่ายทอดแบบลักษณะเด่นบนออโทโซม", "แอลลีลก่อโรคในครอบครัวนี้มีการถ่ายทอดแบบลักษณะด้อยบนออโทโซม", "แอลลีลก่อโรคในครอบครัวนี้มีการถ่ายทอดแบบลักษณะเด่นร่วมบนออโทโซม", "กลุ่มอาการวาร์เดนเบิร์กเป็นความผิดปกติทางพันธุกรรมที่ควบคุมด้วยยีนหลายคู่", "แอลลีลก่อโรคในครอบครัวนี้มีการถ่ายทอดแบบลักษณะเด่นไม่สมบูรณ์บนออโทโซม"]'::jsonb,0,array[0]::smallint[],'["ลักษณะปรากฏต่อเนื่องทุกรุ่นทางฝ่ายพ่อ (ย่า → พ่อ → ลูกชาย) โดยฝ่ายแม่ไม่มีประวัติ และพ่อมีแอลลีลก่อโรคเพียงชุดเดียวก็แสดงอาการ จึงเข้ากับการถ่ายทอดแบบลักษณะเด่นบนออโทโซม (ลูกสาวปกติได้ถ้าได้แอลลีลปกติจากพ่อ)"]'::jsonb,'["ถูก", "ไม่ถูก ถ้าเป็นลักษณะด้อย แม่ต้องเป็นพาหะ แต่ครอบครัวแม่ไม่พบความผิดปกติ และลักษณะไม่ข้ามรุ่น", "ไม่ถูก ข้อมูลไม่ได้แสดงลักษณะของทั้งสองแอลลีลปรากฏร่วมกัน", "ไม่ถูก โจทย์ระบุว่าเกิดจากมิวเทชันของยีนใดยีนหนึ่ง", "ไม่ถูก ข้อมูลไม่ได้แสดงฟีโนไทป์กึ่งกลาง"]'::jsonb,'{"topic": "5.1", "n": 30}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'bio:68-30');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-31','M6','M6-BI','M6-BI-S5','A-Level 66',null,2,'ยีนที่สังเคราะห์โปรตีน X ในสิ่งมีชีวิตชนิดหนึ่ง มีลำดับนิวคลีโอไทด์ ดังภาพ','["โปรตีน X ประกอบด้วยกรดอะมิโนจำนวน 12 โมเลกุล", "การขาดหายไปของนิวคลีโอไทด์ตำแหน่งที่ 35 ทำให้สายพอลิเพปไทด์สั้นลง", "mRNA ที่ได้จากกระบวนการถอดรหัสประกอบด้วยนิวคลีโอไทด์ 37 โมเลกุล", "การแทนที่นิวคลีโอไทด์ T ในตำแหน่งที่ 3 ด้วย C ไม่ส่งผลต่อความยาวสายพอลิเพปไทด์", "แอนติโคดอนของ tRNA ที่จะนำกรดอะมิโนตัวสุดท้ายมาต่อยังสายพอลิเพปไทด์ คือ 3'' AUU 5''"]'::jsonb,2,array[2]::smallint[],'["สายบน (5′→3′) เป็นสายรหัส สายล่างเป็นแม่แบบ · ยีนยาว 37 คู่เบส จึงได้ mRNA 37 นิวคลีโอไทด์ · AUG เริ่มที่ตำแหน่ง 3: AUG UGG CCC CAU CAU CGA GGC GUC AAA AAA แล้วพบ UAA (ตำแหน่ง 33–35) → โปรตีน 10 กรดอะมิโน"]'::jsonb,'["ไม่ถูก มี 10 โคดอนก่อนถึงโคดอนหยุด UAA", "ไม่ถูก ถ้าตำแหน่ง 35 (A ตัวสุดท้ายของ UAA) หายไป จะได้ UAG ซึ่งยังเป็นโคดอนหยุดตำแหน่งเดิม ความยาวไม่เปลี่ยน", "ถูก", "ไม่ถูก T ตำแหน่งที่ 3 ของสายแม่แบบเปลี่ยนเป็น C ทำให้สายรหัสเปลี่ยนจาก A เป็น G โคดอนเริ่ม AUG กลายเป็น GUG จึงกระทบการเริ่มแปลรหัส", "ไม่ถูก กรดอะมิโนตัวสุดท้ายคือ Lys (โคดอน AAA) แอนติโคดอนคือ 3′ UUU 5′"]'::jsonb,'{"img": "bio-68-31.png", "after": "ข้อใดถูกต้อง", "topic": "5.2", "n": 31, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/bio-68-31.png"}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'bio:68-31');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-32','M6','M6-BI','M6-BI-S5','A-Level 66',null,2,'คู่สมรสคู่หนึ่ง ภรรยาได้ตั้งครรภ์ในขณะอายุได้ 32 ปี และผลอัลตราซาวด์พบความผิดปกติของทารกในครรภ์ แพทย์จึงแนะนำให้ตรวจวินิจฉัยทารกในครรภ์ด้วยการเจาะน้ำคร่ำและทำแผนภาพโครโมโซม พบว่าทารกในครรภ์มีความผิดปกติ เป็นดังนี้
**46, X, +13**
พิจารณาเกี่ยวกับความผิดปกติของการแบ่งเซลล์ต่อไปนี้
ก. นอนดิสจังชันในการแบ่งเซลล์ระยะไมโทซิสของพ่อ
ข. นอนดิสจังชันในการแบ่งเซลล์ระยะไมโทซิสของแม่
ค. นอนดิสจังชันในการแบ่งเซลล์ระยะไมโอซิสของพ่อ
ง. นอนดิสจังชันในการแบ่งเซลล์ระยะไมโอซิสของแม่
ข้อใดเป็นสาเหตุของความผิดปกติของทารกในครรภ์','["ก. และ ข. เท่านั้น", "ก. และ ค. เท่านั้น", "ข. และ ง. เท่านั้น", "ค. และ ง. เท่านั้น", "ง. เท่านั้น"]'::jsonb,3,array[3]::smallint[],'["ทารกขาดโครโมโซมเพศ 1 แท่ง (มีเพียง X) และมีโครโมโซมคู่ที่ 13 เกิน 1 แท่ง ซึ่งเกิดจากเซลล์สืบพันธุ์ที่ผิดปกติจากนอนดิสจังชันระหว่างไมโอซิส ซึ่งอาจเกิดได้ทั้งในพ่อและแม่"]'::jsonb,'["ไม่ถูก นอนดิสจังชันในไมโทซิสของพ่อแม่ไม่ส่งต่อไปยังเซลล์สืบพันธุ์ตามปกติ", "ไม่ถูก ไมโทซิสของพ่อไม่ใช่สาเหตุ", "ไม่ถูก ไมโทซิสของแม่ไม่ใช่สาเหตุ", "ถูก ค และ ง", "ไม่ถูก ความผิดปกติอาจมาจากเซลล์สืบพันธุ์ของพ่อได้เช่นกัน"]'::jsonb,'{"topic": "5.3", "n": 32}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2568,'bio:68-32');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-33','M6','M6-BI','M6-BI-S5','A-Level 66',null,2,'นักวิจัยต้องการเพิ่มจำนวนชิ้นส่วน DNA บริเวณหนึ่งจากยีน Y เป็นจำนวนมาก เพื่อนำไปหาลำดับนิวคลีโอไทด์ของยีนนี้ จึงได้เลือกใช้วิธีโคลนชิ้นส่วนยีน Y เข้าสู่เซลล์แบคทีเรีย E. coli โดยในการสร้างดีเอ็นเอรีคอมบิแนนท์จะใช้พลาสมิด B ซึ่งประกอบด้วย ยีนต้านยาปฏิชีวนะ 2 ยีน คือ ยีนต้านยาปฏิชีวนะแอมพิซิลิน (Ampᴿ) และคานาไมซิน (Kanᴿ) เป็นเครื่องหมายในการคัดเลือก และยีน lac Z เป็นยีนรายงานผล ตำแหน่งของเอนไซม์ตัดจำเพาะบนพลาสมิดและยีน Y เป็นดังภาพ','["PstI", "EcoRI", "EcoRV", "BamHI", "Sau3AI"]'::jsonb,0,array[0,1,2,3,4]::smallint[],'["เอนไซม์ที่ใช้ต้องตัดพลาสมิดเฉพาะในยีน lac Z (ไม่ตัดยีน Ampᴿ และ Kanᴿ) และต้องตัดทั้งสองข้างของบริเวณยีน Y · เอนไซม์ที่ตัดใน lac Z และอยู่ทั้งสองข้างของยีน Y คือ EcoRI, TaqI และเอนไซม์ที่ภาพเขียนว่า “Sal3AI” แต่ EcoRI ตัดใน Ampᴿ ด้วย · ทปอ. ประกาศให้ข้อนี้ฟรี"]'::jsonb,'["ไม่ถูก PstI อยู่เพียงด้านซ้ายของยีน Y", "ไม่ถูก EcoRI ตัดในยีน Ampᴿ ด้วย", "ไม่ถูก EcoRV อยู่เพียงด้านขวาของยีน Y", "ไม่ถูก BamHI ตัดในยีน Kanᴿ และไม่ตัดใน lac Z", "ภาพในข้อสอบเขียนชื่อเอนไซม์ว่า “Sal3AI” ไม่ตรงกับตัวเลือก “Sau3AI” และลำดับจดจำของ Sau3AI (GATC) อยู่ในตำแหน่ง BamHI (GGATCC) ด้วย"]'::jsonb,'{"img": "bio-68-33.png", "after": "หากนักวิจัยต้องการสร้างดีเอ็นเอรีคอมบิแนนท์ที่สามารถใช้ยีนต้านยาปฏิชีวนะทั้งสองยีนเป็นเครื่องหมายในการคัดเลือก และใช้ความแตกต่างของการแสดงออกของยีน lac Z ในการรายงานผลแบคทีเรียที่ได้รับดีเอ็นเอรีคอมบิแนนท์เข้าสู่เซลล์\nข้อใดคือเอนไซม์ตัดจำเพาะสำหรับการตัดพลาสมิดและชิ้นส่วนยีน Y ที่นักวิจัยต้องเลือกใช้", "topic": "5.4", "n": 33, "key_free": true, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/bio-68-33.png"}'::jsonb,'imported_m6','imported',false,null,'ทปอ. ประกาศให้ข้อนี้ “ฟรีทุกข้อ” (ไม่ได้ระบุเหตุผล) · ข้อสังเกตของผู้จัดทำ: ภาพเขียน “Sal3AI” แต่ตัวเลือกเขียน “Sau3AI” และ Sau3AI ตัดในตำแหน่ง BamHI ของยีน Kanᴿ ได้ด้วย ครูควรอธิบายประเด็นนี้',2568,'bio:68-33');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-34','M6','M6-BI','M6-BI-S5','A-Level 66',null,2,'ม้าสีโรนเป็นผลจากการแสดงลักษณะเด่นร่วมของยีนกำหนดสีขน ระหว่างแอลลีลสำหรับขนสีแดงและแอลลีลสำหรับขนสีขาว การศึกษาประชากรม้าในจังหวัดหนึ่งซึ่งมีจำนวน 400 ตัว พบว่า มีม้าสีแดงจำนวน 180 ตัว สีขาวจำนวน 150 ตัว และสีโรนจำนวน 70 ตัว กำหนดให้ประชากรม้าอยู่ในสมดุลของฮาร์ดี-ไวน์เบิร์ก
ข้อใดคือความถี่ของแอลลีลสำหรับขนสีแดงในประชากรนี้','["0.18", "0.38", "0.46", "0.54", "0.55"]'::jsonb,3,array[3]::smallint[],'["ลักษณะเด่นร่วม นับแอลลีลได้โดยตรง: แอลลีลสีแดง = (2 × 180 + 70)/(2 × 400) = 430/800 = 0.5375 ≈ 0.54"]'::jsonb,'["ไม่ถูก คำนวณจากจำนวนแอลลีลไม่ได้ค่านี้", "ไม่ถูก คำนวณจากจำนวนแอลลีลไม่ได้ค่านี้", "ไม่ถูก 0.46 คือความถี่แอลลีลสีขาว (370/800)", "ถูก", "ไม่ถูก คำนวณจากจำนวนแอลลีลไม่ได้ค่านี้"]'::jsonb,'{"topic": "5.5", "n": 34}'::jsonb,'imported_m6','imported',true,'numeric','Exam Gym ม.6 · 5620e4c',2568,'bio:68-34');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-BI-68-35','M6','M6-BI','M6-BI-S5','A-Level 66',null,2,'พิจารณาเหตุการณ์หนึ่ง ดังนี้
สีเหนียงของกิ้งก่าเพศผู้เป็นลักษณะทางพันธุกรรมที่ควบคุมด้วยยีนเพียงหนึ่งยีนบนออโทโซม
การสำรวจประชากรกิ้งก่าในปี ค.ศ. 2023 ณ เกาะภูเขาไฟแห่งหนึ่ง ซึ่งมีหุบเหวลึกขนาดใหญ่แบ่งพื้นที่บนเกาะออกเป็นฝั่งตะวันออกและฝั่งตะวันตก พบว่าทั้งสองฝั่งมีกิ้งก่าอาศัยอยู่เป็นจำนวนหลายหมื่นตัว โดยทางฝั่งตะวันตกพบเฉพาะกิ้งก่าเพศผู้ที่มีเหนียงสีแดง ในขณะที่ทางฝั่งตะวันออกพบเฉพาะกิ้งก่าเพศผู้ที่มีเหนียงสีเหลือง
การสืบค้นข้อมูลย้อนหลังพบว่า เหตุการณ์ระเบิดครั้งใหญ่ของภูเขาไฟเมื่อประมาณ 30 ปีก่อนหน้านั้น ส่งผลให้เกิดหุบเหวลึกขนาดใหญ่ ความร้อนและธารลาวาทำให้สัตว์ประจำถิ่นจำนวนมากตายไป ความหลากหลายทางพันธุกรรมของสัตว์ที่ยังคงเหลืออยู่จึงต่ำ ต่อมาได้มีโครงการปรับปรุงพันธุ์โดยนำกิ้งก่าจากทั้งสองฝั่งมาเลี้ยงร่วมกันในสวนสัตว์พบว่าลูกผสมที่ได้ทุกตัวเป็นหมัน จึงสรุปว่ากิ้งก่าสองกลุ่มนี้ได้แยกกันเป็นสปีชีส์ใหม่อย่างสมบูรณ์
ข้อใดระบุปัจจัยทางวิวัฒนาการที่เป็นเหตุให้กิ้งก่าเพศผู้จากแต่ละฝั่งของเหวมีสีเหนียงต่างกัน และระบุกลไกผลักดันให้เกิดกิ้งก่าสปีชีส์ใหม่ขึ้นได้ถูกต้อง ตามลำดับ','["มิวเทชัน และการแบ่งแยกทางภูมิศาสตร์", "การถ่ายเทยีน และการแบ่งแยกทางภูมิศาสตร์", "เจเนติกดริฟท์แบบสุ่ม และการแบ่งแยกทางภูมิศาสตร์", "การผสมพันธุ์แบบไม่สุ่ม และการแบ่งแยกทางพฤติกรรม", "การคัดเลือกโดยธรรมชาติ และการแบ่งแยกทางพฤติกรรม"]'::jsonb,2,array[2]::smallint[],'["ภูเขาไฟระเบิดทำให้ประชากรเหลือน้อยแบบสุ่ม (ปรากฏการณ์คอขวด ซึ่งเป็นเจเนติกดริฟท์) แต่ละฝั่งจึงเหลือแอลลีลสีเหนียงต่างกัน · หุบเหวแยกประชากรทางภูมิศาสตร์ จนเกิดสปีชีส์ใหม่ (ลูกผสมเป็นหมัน)"]'::jsonb,'["ไม่ถูก ความต่างเกิดจากการลดจำนวนแบบสุ่ม ไม่ใช่มิวเทชันใหม่ในเวลา 30 ปี", "ไม่ถูก หุบเหวขวางการถ่ายเทยีนระหว่างสองฝั่ง", "ถูก", "ไม่ถูก ข้อมูลไม่ได้ชี้ว่าเกิดจากการเลือกคู่หรือการแบ่งแยกทางพฤติกรรม", "ไม่ถูก ข้อมูลไม่ได้ระบุว่าสีเหนียงช่วยให้อยู่รอดต่างกัน"]'::jsonb,'{"topic": "5.5", "n": 35}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'bio:68-35');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-69-1','M6','M6-SC','M6-SC-S1','A-Level 63',null,2,'ระบบนิเวศหนึ่งมีพืชเด่นเป็นหญ้า มีต้นไม้ใหญ่ขึ้นกระจายห่าง ๆ กัน อุณหภูมิเฉลี่ยอยู่ที่ 25 องศาเซลเซียส และปริมาณน้ำฝนเฉลี่ยอยู่ที่ 100 เซนติเมตรต่อปี หากการเปลี่ยนแปลงสภาวะอากาศทำให้อุณหภูมิเฉลี่ยสูงขึ้น 2 องศาเซลเซียส และปริมาณน้ำฝนเพิ่มขึ้นเป็น 200 เซนติเมตรต่อปี เมื่อผ่านไป 20 ปี พืชเด่นจะตรงกับข้อใด','["สัก", "มอส", "เฟิร์น", "กล้วยไม้", "สนสองใบ"]'::jsonb,0,array[0]::smallint[],'["ระบบนิเวศเดิมคือทุ่งหญ้าสะวันนา เมื่ออากาศร้อนขึ้นและฝนมากขึ้นจะพัฒนาเป็นป่าผลัดใบเขตร้อน (ป่าเบญจพรรณ) ซึ่งมีไม้สักเป็นพืชเด่น"]'::jsonb,'["ถูก", "ไม่ถูก มอสเป็นพืชบุกเบิกขนาดเล็ก ไม่ใช่พืชเด่นของป่า", "ไม่ถูก เฟิร์นมักเป็นพืชชั้นล่างในป่า", "ไม่ถูก กล้วยไม้เป็นพืชอิงอาศัย ไม่ใช่พืชเด่น", "ไม่ถูก สนสองใบเป็นพืชเด่นของป่าสนเขาบนที่สูงอากาศเย็น"]'::jsonb,'{"topic": "1.1", "n": 1}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'sci:69-1');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-69-2','M6','M6-SC','M6-SC-S1','A-Level 63',null,2,'ยาชนิดหนึ่งสามารถผ่านเยื่อหุ้มเซลล์และเยื่อหุ้มนิวเคลียสไปจับกับยีนเป้าหมายได้โดยตรง ยาชนิดนี้น่าจะมีคุณสมบัติคล้ายกับฮอร์โมนในข้อใด','["อินซูลิน", "อะดรีนาลิน", "เอสโตรเจน", "โกรทฮอร์โมน", "ไทรอยด์ฮอร์โมน"]'::jsonb,2,array[2]::smallint[],'["เอสโตรเจนเป็นฮอร์โมนสเตียรอยด์ ละลายในลิพิดได้ จึงผ่านเยื่อหุ้มเซลล์เข้าไปจับตัวรับภายในเซลล์ แล้วควบคุมการแสดงออกของยีนในนิวเคลียส"]'::jsonb,'["ไม่ถูก อินซูลินเป็นโปรตีน จับตัวรับที่เยื่อหุ้มเซลล์", "ไม่ถูก อะดรีนาลินละลายน้ำ จับตัวรับที่เยื่อหุ้มเซลล์", "ถูก", "ไม่ถูก โกรทฮอร์โมนเป็นโปรตีน จับตัวรับที่เยื่อหุ้มเซลล์", "ทปอ. ไม่ได้เฉลยข้อนี้ ไทรอยด์ฮอร์โมนก็มีตัวรับในนิวเคลียส แต่ไม่ใช่สเตียรอยด์ และต้องอาศัยโปรตีนขนส่งเข้าเซลล์"]'::jsonb,'{"topic": "1.3", "n": 2}'::jsonb,'imported_m6','imported',true,'expl','ไทรอยด์ฮอร์โมน (ตัวเลือก 5) ก็ออกฤทธิ์ผ่านตัวรับในนิวเคลียสเช่นกัน แต่ ทปอ. เฉลยข้อ 3 ข้อเดียว ครูควรตรวจทานคำอธิบายตัวเลือก 5',2569,'sci:69-2');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-69-3','M6','M6-SC','M6-SC-S1','A-Level 63',null,2,'การตรวจปัสสาวะของนักเรียนคนหนึ่งพบน้ำตาลกลูโคสและโปรตีนอัลบูมินในปัสสาวะ นักเรียนคนนี้ปกติหรือไม่เพราะเหตุใด','["ปกติ เพราะน้ำตาลกลูโคสและโปรตีนอัลบูมินสามารถผ่านการกรองของไตได้", "ปกติ เพราะน้ำตาลกลูโคสและโปรตีนอัลบูมินไม่สามารถถูกดูดกลับที่หน่วยไตได้หมด", "ผิดปกติ เพราะน้ำตาลกลูโคสและโปรตีนอัลบูมินไม่สามารถผ่านการกรองของไตเข้ามาที่ท่อไตส่วนต้นได้", "ผิดปกติ เพราะน้ำตาลกลูโคสควรจะถูกดูดกลับหมดที่ท่อไตส่วนต้นและโปรตีนอัลบูมินไม่สามารถผ่านการกรองเข้ามาที่ท่อไตส่วนต้นได้", "ผิดปกติ เพราะน้ำตาลกลูโคสไม่สามารถผ่านการกรองเข้ามาที่ท่อไตส่วนต้นได้และโปรตีนอัลบูมินควรจะถูกดูดกลับหมดที่ท่อไตส่วนต้น"]'::jsonb,3,array[3]::smallint[],'["กลูโคสผ่านการกรองได้ แต่ปกติจะถูกดูดกลับหมดที่ท่อไตส่วนต้น · อัลบูมินเป็นโปรตีนโมเลกุลใหญ่ ปกติไม่ผ่านการกรองที่โกลเมอรูลัส · พบทั้งสองอย่างในปัสสาวะจึงผิดปกติ"]'::jsonb,'["ไม่ถูก อัลบูมินปกติไม่ผ่านการกรอง", "ไม่ถูก กลูโคสปกติถูกดูดกลับหมด", "ไม่ถูก กลูโคสผ่านการกรองได้", "ถูก", "ไม่ถูก กลับกัน กลูโคสกรองผ่านได้ ส่วนอัลบูมินกรองไม่ผ่าน"]'::jsonb,'{"topic": "1.3", "n": 3}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'sci:69-3');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-69-4','M6','M6-SC','M6-SC-S1','A-Level 63',null,2,'ในการทดลองเพื่อศึกษาผลของอุณหภูมิต่ออัตราการเจริญเติบโตของพืช 4 ชนิด ได้แก่ ชนิด A, B, C และ D โดยนำพืชแต่ละชนิดปลูกไว้ที่อุณหภูมิ 20 องศาเซลเซียส และ 35 องศาเซลเซียส ระยะเวลาหนึ่งจากนั้นนำพืชทั้งหมดมาชั่งน้ำหนักแห้ง ได้ผลการทดลองดังนี้','["อุณหภูมิมีผลต่อการเจริญเติบโตของพืช B มากกว่าพืช A, C และ D", "หากนำพืชทั้ง 4 ชนิดไปปลูกในบริเวณที่มีอุณหภูมิเดียวกัน พืชทั้ง 4 ชนิดจะมีอัตราการเจริญเติบโตดีเหมือนกัน", "พืช A และ B เจริญเติบโตได้ดีที่อุณหภูมิต่ำ ส่วนพืช C และ D เจริญเติบโตได้ดีที่อุณหภูมิสูง", "พืช A และ C เจริญเติบโตได้ดีที่อุณหภูมิสูง ส่วนพืช D เจริญเติบโตได้ดีที่อุณหภูมิต่ำ ในขณะที่พืช B เจริญเติบโตได้ทั้งที่อุณหภูมิสูงและอุณหภูมิต่ำ", "อุณหภูมิมีผลต่อการเจริญเติบโตของพืช A, C และ D แต่ไม่มีผลต่อการเจริญเติบโตของพืช B"]'::jsonb,4,array[4]::smallint[],'["A และ C มีน้ำหนักแห้งที่ 20°C สูงกว่าที่ 35°C มาก · D กลับกัน · B มีน้ำหนักแห้งประมาณ 250 กรัมทั้งสองอุณหภูมิ จึงไม่ได้รับผลจากอุณหภูมิ"]'::jsonb,'["ไม่ถูก B ได้รับผลจากอุณหภูมิน้อยที่สุด", "ไม่ถูก ที่อุณหภูมิเดียวกันพืชแต่ละชนิดเติบโตต่างกันมาก", "ไม่ถูก C โตดีที่อุณหภูมิต่ำ", "ไม่ถูก กลับกัน A และ C โตดีที่อุณหภูมิต่ำ ส่วน D โตดีที่อุณหภูมิสูง", "ถูก"]'::jsonb,'{"img": "sci-69-4.png", "after": "ข้อใดอธิบายผลการทดลองได้ถูกต้อง", "topic": "1.5", "n": 4, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/sci-69-4.png"}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'sci:69-4');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-69-5','M6','M6-SC','M6-SC-S1','A-Level 63',null,2,'เกษตรกรปักชำต้นไม้โดยใช้สารสังเคราะห์ A เพื่อเร่งการเกิดราก เมื่อต้นไม้เจริญเติบโตดีแล้วจึงใช้สารสังเคราะห์ B ช่วยเร่งการแตกตาข้างของพืชเพื่อให้ต้นไม้เป็นทรงพุ่ม นอกจากนี้ยังใช้สารสังเคราะห์ C เพื่อกำจัดวัชพืช ข้อใดต่อไปนี้ถูกต้อง','["สารสังเคราะห์ A, B และ C มีสมบัติคล้ายออกซิน", "สารสังเคราะห์ A และ C มีสมบัติคล้ายไซโทไคนิน ส่วนสารสังเคราะห์ B มีสมบัติคล้ายออกซิน", "สารสังเคราะห์ A และ C มีสมบัติคล้ายออกซิน ส่วนสารสังเคราะห์ B มีสมบัติคล้ายไซโทไคนิน", "สารสังเคราะห์ A และ B มีสมบัติคล้ายไซโทไคนิน ส่วนสารสังเคราะห์ C มีสมบัติคล้ายออกซิน", "สารสังเคราะห์ A และ B มีสมบัติคล้ายออกซิน ส่วนสารสังเคราะห์ C มีสมบัติคล้ายไซโทไคนิน"]'::jsonb,2,array[2]::smallint[],'["ออกซินช่วยเร่งการเกิดรากของกิ่งปักชำ (A) และออกซินสังเคราะห์ความเข้มข้นสูง เช่น 2,4-D ใช้กำจัดวัชพืช (C) · ไซโทไคนินกระตุ้นการแตกตาข้าง (B)"]'::jsonb,'["ไม่ถูก ออกซินยับยั้งการแตกตาข้าง (ข่มตาข้าง)", "ไม่ถูก กลับกัน", "ถูก", "ไม่ถูก การเร่งรากใช้ออกซิน", "ไม่ถูก ไซโทไคนินไม่ใช้กำจัดวัชพืช"]'::jsonb,'{"topic": "1.5", "n": 5}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'sci:69-5');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-69-6','M6','M6-SC','M6-SC-S1','A-Level 63',null,2,'โรคฮีโมฟีเลีย ควบคุมด้วยแอลลีลด้อยบนโครโมโซม X และหมู่เลือดระบบ ABO มีการถ่ายทอดทางพันธุกรรมแบบมัลติเพิลแอลลีล ซึ่งมีแอลลีลที่เกี่ยวข้อง คือ แอลลีล Iᴬ แอลลีล Iᴮ และแอลลีล i
หากพ่อไม่เป็นฮีโมฟีเลียและมีหมู่เลือด AB ส่วนแม่ไม่เป็นฮีโมฟีเลียแต่มีจีโนไทป์เป็นเฮเทอโรไซกัสและมีหมู่เลือด O ข้อใดต่อไปนี้เป็นลูกของพ่อแม่คู่นี้','["ลูกสาว ไม่เป็นฮีโมฟีเลีย หมู่เลือด O", "ลูกสาว เป็นฮีโมฟีเลีย หมู่เลือด A", "ลูกชาย ไม่เป็นฮีโมฟีเลีย หมู่เลือด AB", "ลูกชาย ไม่เป็นฮีโมฟีเลีย หมู่เลือด O", "ลูกชาย เป็นฮีโมฟีเลีย หมู่เลือด B"]'::jsonb,4,array[4]::smallint[],'["พ่อ XᴴY IᴬIᴮ × แม่ XᴴXʰ ii · ลูกได้หมู่เลือด A (Iᴬi) หรือ B (Iᴮi) เท่านั้น · ลูกชายรับ X จากแม่ จึงเป็นฮีโมฟีเลียได้ (XʰY) · ลูกสาวได้ Xᴴ จากพ่อเสมอ จึงไม่เป็นโรค"]'::jsonb,'["ไม่ถูก ลูกเป็นหมู่ O ไม่ได้", "ไม่ถูก ลูกสาวได้ Xᴴ จากพ่อ จึงไม่เป็นฮีโมฟีเลีย", "ไม่ถูก ลูกเป็นหมู่ AB ไม่ได้ (แม่ให้ได้แต่ i)", "ไม่ถูก ลูกเป็นหมู่ O ไม่ได้", "ถูก"]'::jsonb,'{"topic": "1.6", "n": 6}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'sci:69-6');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-69-7','M6','M6-SC','M6-SC-S2','A-Level 63',null,2,'ธาตุแรร์เอิร์ธ ประกอบด้วยโลหะพิเศษ 17 ชนิด ซึ่งล้วนเป็นองค์ประกอบที่ขาดไม่ได้ในเทคโนโลยีสมัยใหม่ที่พบเห็นได้ในชีวิตประจำวัน ข้อมูลของธาตุแรร์เอิร์ธบางชนิดแสดงดังตาราง','["ก และ ข", "ก และ ค", "ก และ ง", "ข และ ค", "ค และ ง"]'::jsonb,2,array[2]::smallint[],'["ก ไม่สอดคล้อง เลขมวล = โปรตอน + นิวตรอน (Y: 39 + 50 = 89) ไม่ใช่ อิเล็กตรอน + โปรตอน (78) · ง ไม่สอดคล้อง Eu³⁺ มีโปรตอน 63 แต่ Nd มีอิเล็กตรอน 60 · ข สอดคล้อง 158 − 89 = 69 · ค สอดคล้อง Ce มีนิวตรอน 140 − 58 = 82 เท่ากับ Nd"]'::jsonb,'["ไม่ถูก ข สอดคล้องกับข้อมูล", "ไม่ถูก ค สอดคล้องกับข้อมูล", "ถูก", "ไม่ถูก ข และ ค สอดคล้องกับข้อมูล", "ไม่ถูก ค สอดคล้องกับข้อมูล"]'::jsonb,'{"table": [["สัญลักษณ์นิวเคลียร์", "จำนวนโปรตอน", "จำนวนอิเล็กตรอน", "จำนวนนิวตรอน", "สัญลักษณ์ธาตุ", "เลขอะตอม", "เลขมวล"], ["⁸⁹₃₉Y", "", "", "", "", "", ""], ["", "", "", "", "Ce", "58", "140"], ["", "", "60", "82", "Nd", "", ""], ["", "", "", "90", "Eu", "63", ""], ["¹⁵⁸₆₄Gd", "", "", "", "", "", ""]], "after": "พิจารณาข้อความต่อไปนี้\nก. เลขมวลของอิตเทรียม (Y) มีค่าเท่ากับผลรวมของจำนวนอิเล็กตรอนของอิตเทรียมและจำนวนโปรตอนของอิตเทรียม\nข. เลขมวลของแกโดลิเนียม (Gd) มีค่ามากกว่าเลขมวลของอิตเทรียม (Y) เท่ากับ 69\nค. จำนวนนิวตรอนของซีเรียม (Ce) มีค่าเท่ากับจำนวนนิวตรอนของนีโอดิเมียม (Nd)\nง. จำนวนโปรตอนของยูโรเปียมไอออน (Eu³⁺) มีค่าเท่ากับจำนวนอิเล็กตรอนของนีโอดิเมียม (Nd)\nข้อความใด**ไม่**สอดคล้องกับข้อมูลข้างต้น", "topic": "2.1", "n": 7}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2569,'sci:69-7');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-69-8','M6','M6-SC','M6-SC-S2','A-Level 63',null,2,'กำหนดโครงสร้างสารประกอบ ดังนี้','["ก และ ข", "ก และ ค", "ก และ ง", "ข และ ค", "ค และ ง"]'::jsonb,3,array[3]::smallint[],'["ข ถูก CS₂ มีโครงสร้าง S=C=S · ค ถูก NO เป็นโมเลกุลมีขั้ว แรงยึดเหนี่ยวมากกว่า O₂ ที่ไม่มีขั้ว จุดเดือดจึงสูงกว่า · ง ผิด Z (บิวทานอล) มีพันธะไฮโดรเจน จุดเดือดสูงกว่า Y (อีเทอร์) · ก ผิด สาร X มีพันธะเดี่ยวมากกว่า 13 พันธะ"]'::jsonb,'["ไม่ถูก ก ผิด", "ไม่ถูก ก ผิด", "ไม่ถูก ก และ ง ผิด", "ถูก", "ไม่ถูก ง ผิด แอลกอฮอล์มีพันธะไฮโดรเจน แต่อีเทอร์ไม่มี"]'::jsonb,'{"img": "sci-69-8.png", "after": "พิจารณาข้อความต่อไปนี้\nก. สาร X มีจำนวนพันธะเดี่ยวเท่ากับ 13 และจำนวนพันธะคู่เท่ากับ 5 พันธะ\nข. คาร์บอนไดซัลไฟด์เป็นสารประกอบโคเวเลนต์ที่ไม่มีประจุ ประกอบด้วยคาร์บอน 1 อะตอม และกำมะถัน 2 อะตอม โดยพันธะเคมีที่เกิดขึ้นระหว่างคาร์บอนและกำมะถันเป็นพันธะคู่\nค. แก๊สไนโตรเจนมอนอกไซด์มีจุดเดือดสูงกว่าแก๊สออกซิเจน\nง. สาร Y มีจุดเดือดสูงกว่าสาร Z\nข้อใดถูกต้อง", "topic": "2.2", "n": 8, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/sci-69-8.png"}'::jsonb,'imported_m6','imported',true,'combo','ข้อ ก: จำนวนพันธะเดี่ยวของสาร X ขึ้นกับวิธีนับ (ถ้านับรวม C−H, N−H และ O−H จะได้ประมาณ 31 พันธะ ถ้านับเฉพาะพันธะระหว่างอะตอมหนักจะได้ประมาณ 14 พันธะ) ทั้งสองแบบไม่ใช่ 13 ครูควรตรวจทานการนับ',2569,'sci:69-8');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-69-9','M6','M6-SC','M6-SC-S2','A-Level 63',null,2,'นำสารผสม 2 ชนิดไปละลายน้ำ พบว่ามีอะลูมิเนียมไอออน ซัลเฟตไอออน และแอมโมเนียมไอออน อยู่ในสารละลาย สูตรเอ็มพิริคัลที่ถูกต้องของสารประกอบไอออนิกที่เป็นองค์ประกอบในสารผสมดังกล่าว คือข้อใด','["(NH₄)₃Al และ (SO₄)₃Al₂", "Al(NH₄)₃ และ Al(SO₄)₃", "SO₄(NH₄)₂ และ (SO₄)₃Al₂", "Al(SO₄)₃ และ NH₄SO₄", "Al₂(SO₄)₃ และ (NH₄)₂SO₄"]'::jsonb,4,array[4]::smallint[],'["Al³⁺ กับ SO₄²⁻ รวมกันให้ประจุรวมเป็นศูนย์ ได้ Al₂(SO₄)₃ · NH₄⁺ กับ SO₄²⁻ ได้ (NH₄)₂SO₄ · เขียนไอออนบวกก่อนไอออนลบ"]'::jsonb,'["ไม่ถูก NH₄⁺ กับ Al³⁺ เป็นไอออนบวกทั้งคู่ รวมกันไม่ได้ และต้องเขียนไอออนบวกก่อน", "ไม่ถูก Al³⁺ กับ NH₄⁺ รวมกันไม่ได้ และ Al(SO₄)₃ ประจุไม่ดุล", "ไม่ถูก เขียนไอออนลบก่อนไอออนบวก", "ไม่ถูก ประจุไม่ดุลทั้งสองสูตร", "ถูก"]'::jsonb,'{"topic": "2.3", "n": 9}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'sci:69-9');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-69-10','M6','M6-SC','M6-SC-S2','A-Level 63',null,2,'พิจารณาโครงสร้างของสารอินทรีย์ 3 ชนิดที่พบได้ในธรรมชาติในตารางต่อไปนี้','["ลิโมนีน", "กรดคาโปรเลอิก", "เฮปเทน", "ลิโมนีน และ กรดคาโปรเลอิก", "ลิโมนีน และ เฮปเทน"]'::jsonb,0,array[0]::smallint[],'["ไฮโดรคาร์บอนต้องมีเฉพาะ C และ H · ลิโมนีนมีพันธะคู่ C=C จึงเป็นไฮโดรคาร์บอนไม่อิ่มตัว · กรดคาโปรเลอิกมีพันธะคู่ แต่มีออกซิเจน จึงไม่ใช่ไฮโดรคาร์บอน · เฮปเทนมีแต่พันธะเดี่ยว จึงอิ่มตัว"]'::jsonb,'["ถูก", "ไม่ถูก มีออกซิเจน (หมู่ −COOH) จึงไม่ใช่ไฮโดรคาร์บอน", "ไม่ถูก เฮปเทนอิ่มตัว", "ไม่ถูก กรดคาโปรเลอิกไม่ใช่ไฮโดรคาร์บอน", "ไม่ถูก เฮปเทนอิ่มตัว"]'::jsonb,'{"img": "sci-69-10.png", "after": "สารใดบ้างจัดเป็นสารประกอบไฮโดรคาร์บอนที่ไม่อิ่มตัว", "topic": "2.4", "n": 10, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/sci-69-10.png"}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'sci:69-10');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-69-11','M6','M6-SC','M6-SC-S2','A-Level 63',null,2,'เมื่อนำมอนอเมอร์ A ไปทำปฏิกิริยาพอลิเมอไรเซชันจะได้เป็นพอลิเมอร์ B ที่มีโครงสร้างแบบเส้น เมื่อนำพอลิเมอร์ B ไปทำปฏิกิริยาจะได้เป็นพอลิเมอร์ C ที่มีโครงสร้างแบบร่างแห
พิจารณาข้อความต่อไปนี้
ก. A กลายเป็นไอที่อุณหภูมิต่ำกว่า B
ข. B หลอมเหลวที่อุณหภูมิต่ำกว่า C
ค. C มีสมบัติเทอร์มอพลาสติก จึงสามารถนำไปรีไซเคิลได้ง่าย
จากข้อมูลข้างต้น ข้อความใด**ไม่**ถูกต้อง','["ก เท่านั้น", "ข เท่านั้น", "ค เท่านั้น", "ก และ ข", "ก และ ค"]'::jsonb,2,array[2]::smallint[],'["ค ไม่ถูก พอลิเมอร์แบบร่างแหเป็นเทอร์มอเซต หลอมขึ้นรูปใหม่ไม่ได้ รีไซเคิลยาก · ก ถูก มอนอเมอร์โมเลกุลเล็ก กลายเป็นไอง่ายกว่า · ข ถูก พอลิเมอร์แบบเส้นอ่อนตัวหรือหลอมได้ที่อุณหภูมิต่ำกว่าแบบร่างแห"]'::jsonb,'["ไม่ใช่ ก เป็นข้อความที่ถูก", "ไม่ใช่ ข เป็นข้อความที่ถูก", "ใช่ ค เป็นข้อความเดียวที่ไม่ถูก", "ไม่ใช่ ก และ ข ถูก", "ไม่ใช่ ก ถูก"]'::jsonb,'{"topic": "2.5", "n": 11}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2569,'sci:69-11');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-69-12','M6','M6-SC','M6-SC-S2','A-Level 63',null,2,'พิจารณาสมการเคมีของการเผาไหม้อีเทน (C₂H₆) และโพรเพน (C₃H₈) ต่อไปนี้
2C₂H₆(g) + 7O₂(g) → 4CO₂(g) + 6H₂O(g) + พลังงาน
C₃H₈(g) + 5O₂(g) → 3CO₂(g) + 4H₂O(g) + พลังงาน
