insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-69-13','M6','M6-SC','M6-SC-S2','A-Level 63',null,2,'สาร M และ สาร N เป็นสารกัมมันตรังสีชนิดหนึ่งซึ่งมีค่าครึ่งชีวิตเท่ากับ 5 วัน และ 10 วัน ตามลำดับ นำสาร M และ สาร N ปริมาณเท่ากันมาตั้งทิ้งไว้เป็นเวลา 20 วัน สาร M จะมีปริมาณมากกว่าหรือน้อยกว่า สาร N กี่เท่า','["สาร M มีปริมาณน้อยกว่า สาร N 4 เท่า", "สาร M มีปริมาณน้อยกว่า สาร N 2 เท่า", "สาร M มีปริมาณมากกว่า สาร N 2 เท่า", "สาร M มีปริมาณมากกว่า สาร N 4 เท่า", "สาร M มีปริมาณมากกว่า สาร N 8 เท่า"]'::jsonb,0,array[0]::smallint[],'["20 วัน M ผ่าน 4 ครึ่งชีวิต เหลือ 1/16 · N ผ่าน 2 ครึ่งชีวิต เหลือ 1/4 · (1/4) ÷ (1/16) = 4 M จึงน้อยกว่า N 4 เท่า"]'::jsonb,'["ถูก", "ไม่ถูก", "ไม่ถูก M ครึ่งชีวิตสั้นกว่า จึงสลายเร็วกว่าและเหลือน้อยกว่า", "ไม่ถูก กลับกัน", "ไม่ถูก"]'::jsonb,'{"topic": "2.7", "n": 13}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'sci:69-13');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-69-14','M6','M6-SC','M6-SC-S2','A-Level 63',null,2,'บนถนนตรงเส้นหนึ่ง รถยนต์ส่วนบุคคลคันหนึ่งขับฝ่าด่านตรวจด้วยความเร็วคงตัวซึ่งเกินค่าที่กฎหมายกำหนด หลังจากผ่านไป 10 วินาที ตำรวจจึงสตาร์ทรถและรีบขับตามมาด้วยความเร่งคงตัวและทันพอดีในเวลาอีก 2 นาที ต่อมา พิจารณาเฉพาะช่วงที่มีการเคลื่อนที่ของรถทั้งสองคันจากด่านตรวจมาถึงตำแหน่งที่รถขับทันกัน
