insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-69-16','M6','M6-SC','M6-SC-S2','A-Level 63',null,2,'ทดลองต่อขดลวดเข้ากับแกลแวนอมิเตอร์และวางแม่เหล็กไว้อยู่ที่ปลายด้านหนึ่งของขดลวด ณ ตอนเริ่มต้นทุกอย่างหยุดนิ่ง แสดงดังรูป','["เคลื่อนแม่เหล็กไปทางซ้าย ด้วยอัตราเร็ว 1 เซนติเมตรต่อวินาที", "เคลื่อนขดลวดไปทางขวา ด้วยอัตราเร็ว 5 เซนติเมตรต่อวินาที", "เคลื่อนขดลวดไปทางขวาด้วยอัตราเร็ว 5 เซนติเมตรต่อวินาที พร้อมกับเคลื่อนแม่เหล็กไปทางขวาด้วยอัตราเร็ว 5 เซนติเมตรต่อวินาที", "เคลื่อนขดลวดไปทางขวาด้วยอัตราเร็ว 5 เซนติเมตรต่อวินาที พร้อมกับเคลื่อนแม่เหล็กไปทางขวาด้วยอัตราเร็ว 1 เซนติเมตรต่อวินาที", "เคลื่อนขดลวดไปทางขวาด้วยอัตราเร็ว 5 เซนติเมตรต่อวินาที พร้อมกับเคลื่อนแม่เหล็กไปทางซ้ายด้วยอัตราเร็ว 1 เซนติเมตรต่อวินาที"]'::jsonb,4,array[4]::smallint[],'["แรงเคลื่อนไฟฟ้าเหนี่ยวนำขึ้นกับอัตราการเปลี่ยนฟลักซ์ คือขึ้นกับอัตราเร็วสัมพัทธ์ระหว่างขดลวดกับแม่เหล็ก · ข้อ 5 ทั้งสองเคลื่อนเข้าหากัน อัตราเร็วสัมพัทธ์ 5 + 1 = 6 cm/s มากที่สุด"]'::jsonb,'["ไม่ถูก อัตราเร็วสัมพัทธ์ 1 cm/s", "ไม่ถูก อัตราเร็วสัมพัทธ์ 5 cm/s", "ไม่ถูก เคลื่อนไปพร้อมกัน อัตราเร็วสัมพัทธ์เป็นศูนย์ เข็มไม่กระดิก", "ไม่ถูก อัตราเร็วสัมพัทธ์ 5 − 1 = 4 cm/s", "ถูก"]'::jsonb,'{"img": "sci-69-16.png", "after": "สถานการณ์ใดต่อไปนี้ที่เข็มของแกลแวนอมิเตอร์จะกระดิกและเบนไปจากเลข 0 มากที่สุด", "topic": "2.9", "n": 16, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/sci-69-16.png"}'::jsonb,'imported_m6','imported',true,'expl','Exam Gym ม.6 · 5620e4c',2569,'sci:69-16');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-69-17','M6','M6-SC','M6-SC-S2','A-Level 63',null,2,'คลื่นผิวน้ำที่มีหน้าคลื่นเป็นเส้นตรงเคลื่อนที่ผ่านช่องเปิดซึ่งมีความกว้างน้อยกว่าระยะห่างของสันคลื่น ดังรูป','["หน้าคลื่นจะเคลื่อนที่ผ่านช่องเปิด มีลักษณะเป็นเส้นตรงขนาดเท่ากับช่องเปิด", "หน้าคลื่นจะเคลื่อนที่ผ่านช่องเปิด มีลักษณะเป็นโค้งวงกลมเคลื่อนที่ออกจากช่องเปิด", "หน้าคลื่นเกิดการสะท้อนกลับที่ช่องเปิด ไปรวมกันแบบเสริมกับหน้าคลื่นที่เข้ามา (เส้นทึบ)", "หน้าคลื่นเกิดการสะท้อนกลับไปที่ช่องเปิด ไปรวมกันแบบหักล้างกับหน้าคลื่นที่เข้ามา (เส้นประ)", "หน้าคลื่นจะเคลื่อนที่ผ่านช่องเปิด มีลักษณะตรงกลางเป็นแนวตรงเหมือนเดิม ส่วนปลายทั้งสองด้านจะโค้งไปทางด้านหลังช่องเปิด"]'::jsonb,1,array[1]::smallint[],'["ช่องเปิดแคบกว่าความยาวคลื่น เกิดการเลี้ยวเบนชัดเจน ช่องเปิดทำตัวเหมือนแหล่งกำเนิดจุด หน้าคลื่นหลังช่องเปิดจึงเป็นโค้งวงกลม"]'::jsonb,'["ไม่ถูก คลื่นเลี้ยวเบนออก ไม่ได้เป็นแนวตรงแคบ ๆ", "ถูก", "ไม่ถูก คลื่นส่วนหนึ่งผ่านช่องเปิดและเลี้ยวเบน", "ไม่ถูก", "ไม่ถูก ลักษณะนี้เกิดเมื่อช่องเปิดกว้างกว่าความยาวคลื่นมาก"]'::jsonb,'{"img": "sci-69-17.png", "after": "หลังจากคลื่นผิวน้ำมาถึงช่องเปิด หน้าคลื่นจะเป็นไปตามข้อใด (ต้นฉบับมีภาพประกอบในแต่ละตัวเลือก)", "topic": "2.11", "n": 17, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/sci-69-17.png"}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'sci:69-17');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-69-18','M6','M6-SC','M6-SC-S2','A-Level 63',null,2,'วางลำโพง 2 ตัว ตัวที่หนึ่งไว้ที่ด้านซ้ายสุดและตัวที่สองไว้ที่ด้านขวาสุดของเวที และจัดให้ผู้ฟังนั่งอยู่ในแถวขนานกับหน้าเวที เมื่อเปิดเสียงออกจากลำโพงด้วยความถี่เดียวกัน ข้อใดกล่าวถูกต้องเกี่ยวกับเสียงที่ผู้ฟังจะได้ยิน','["ผู้ฟังทุกคนในแถวจะได้ยินเสียงดังเท่ากัน เพราะลำโพงทั้งสองเปิดด้วยความถี่เดียวกัน", "ผู้ฟังคนเดียวกันจะได้ยินเสียงดังค่อยสลับกันไป เนื่องจากลำโพงทั้งสองอยู่ห่างกัน", "ผู้ฟังบางตำแหน่งจะได้ยินเสียงแหลมขึ้น เนื่องจากความถี่ของเสียงรวมกันเพิ่มขึ้นเป็นสองเท่า", "ผู้ฟังบางตำแหน่งจะได้ยินเสียงค่อย บางตำแหน่งจะได้ยินเสียงดัง เมื่อเปิดเสียงความถี่เดียวกัน", "ผู้ฟังที่อยู่ใกล้ลำโพงตัวไหนก็จะได้ยินเฉพาะเสียงจากลำโพงตัวนั้น โดยไม่มีเสียงจากลำโพงอีกตัว"]'::jsonb,3,array[3]::smallint[],'["แหล่งกำเนิดอาพันธ์ 2 แหล่ง เกิดการแทรกสอด · ตำแหน่งที่ผลต่างระยะทางเป็นจำนวนเต็มเท่าของความยาวคลื่นจะเสริมกัน (ดัง) · ตำแหน่งอื่นหักล้างกัน (ค่อย) · ความดังจึงขึ้นกับตำแหน่ง"]'::jsonb,'["ไม่ถูก การแทรกสอดทำให้ความดังต่างกันตามตำแหน่ง", "ไม่ถูก ดังค่อยสลับกันตามเวลา (บีต) เกิดเมื่อความถี่ต่างกันเล็กน้อย", "ไม่ถูก การแทรกสอดไม่ได้เปลี่ยนความถี่", "ถูก", "ไม่ถูก ผู้ฟังได้ยินเสียงจากลำโพงทั้งสองตัว"]'::jsonb,'{"topic": "2.12", "n": 18}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'sci:69-18');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-69-19','M6','M6-SC','M6-SC-S2','A-Level 63',null,2,'นักเรียนคนหนึ่งทำการทดลองเกี่ยวกับแผ่นกรองแสง โดยนำวัตถุชิ้นหนึ่งมาทดลอง เมื่อมองวัตถุชิ้นนี้ผ่านแผ่นกรองแสงสีเหลืองพบว่าเห็นวัตถุเป็นสีแดง แต่เมื่อมองวัตถุชิ้นเดิมผ่านแผ่นกรองแสงสีน้ำเงินพบว่าเห็นวัตถุเป็นสีน้ำเงิน นักเรียนคนนี้จะสรุปว่าวัตถุนี้มีสีใด','["แดง", "น้ำเงิน", "เขียว", "เหลือง", "แดงม่วง"]'::jsonb,4,array[4]::smallint[],'["แผ่นกรองสีเหลืองให้แสงแดงและเขียวผ่าน เห็นวัตถุเป็นสีแดง แสดงว่าวัตถุสะท้อนแสงแดงแต่ไม่สะท้อนแสงเขียว · ผ่านแผ่นกรองน้ำเงินเห็นสีน้ำเงิน แสดงว่าวัตถุสะท้อนแสงน้ำเงิน · แดง + น้ำเงิน = แดงม่วง (magenta)"]'::jsonb,'["ไม่ถูก ถ้าเป็นสีแดง ผ่านแผ่นกรองน้ำเงินจะเห็นเป็นสีดำ", "ไม่ถูก ถ้าเป็นสีน้ำเงิน ผ่านแผ่นกรองเหลืองจะเห็นเป็นสีดำ", "ไม่ถูก", "ไม่ถูก ถ้าเป็นสีเหลือง ผ่านแผ่นกรองเหลืองจะเห็นเป็นสีเหลือง", "ถูก"]'::jsonb,'{"topic": "2.13", "n": 19}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'sci:69-19');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-69-20','M6','M6-SC','M6-SC-S3','A-Level 63',null,2,'ดาวฤกษ์ในข้อใดต่อไปนี้ที่มีอุณหภูมิผิวสูงที่สุด','["ดาวรวงข้าว มีสเปกตรัม B", "ดาวหางหงส์ มีสเปกตรัม A", "ดาวดวงแก้ว มีสเปกตรัม K", "ดาวปริชาต มีสเปกตรัม M", "ดาวโพรซิออน มีสเปกตรัม F"]'::jsonb,0,array[0]::smallint[],'["ลำดับสเปกตรัมจากร้อนไปเย็นคือ O B A F G K M · ในตัวเลือก B ร้อนที่สุด"]'::jsonb,'["ถูก", "ไม่ถูก A เย็นกว่า B", "ไม่ถูก K ค่อนข้างเย็น", "ไม่ถูก M เย็นที่สุด", "ไม่ถูก F เย็นกว่า B"]'::jsonb,'{"topic": "3.2", "n": 20}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'sci:69-20');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-69-21','M6','M6-SC','M6-SC-S3','A-Level 63',null,2,'ค่าคงตัวของฮับเบิลหาได้จากกราฟความเร็วในการเคลื่อนที่ออกจากผู้สังเกตในหน่วยกิโลเมตรต่อวินาที (km s⁻¹) และระยะทางของกาแล็กซีจากผู้สังเกต มีหน่วยเป็นเมกะพาร์เซก (Mpc) นักดาราศาสตร์คนหนึ่งวัดระยะห่างของกาแล็กซีหนึ่งได้ระยะทาง 7 พาร์เซก แล้วกาแล็กซีนี้มีความเร็วในการเคลื่อนที่ออกจากผู้สังเกตกี่กิโลเมตรต่อวินาที
กำหนดให้ ค่าคงตัวของฮับเบิลมีค่าเท่ากับ 70 กิโลเมตรต่อวินาทีต่อเมกะพาร์เซก','["0.1", "10", "490", "10,000", "490,000"]'::jsonb,0,array[0,1,2,3,4]::smallint[],'["กฎของฮับเบิล v = H₀ × d · ถ้าระยะทางคือ 7 เมกะพาร์เซก จะได้ v = 70 × 7 = 490 km/s · แต่โจทย์เขียนว่า 7 พาร์เซก (= 7 × 10⁻⁶ Mpc) ซึ่งจะได้ v ≈ 0.00049 km/s ไม่ตรงกับตัวเลือกใด"]'::jsonb,'["ไม่ตรงกับการคำนวณทั้งสองแบบ", "ไม่ตรงกับการคำนวณทั้งสองแบบ", "ตรงกับกรณีที่ระยะทางคือ 7 เมกะพาร์เซก", "ไม่ตรงกับการคำนวณทั้งสองแบบ", "ไม่ตรง (เท่ากับ 490 × 1,000)"]'::jsonb,'{"topic": "3.1", "n": 21, "key_free": true}'::jsonb,'imported_m6','imported',true,'numeric','ทปอ. ประกาศ “ฟรีทุกข้อ” โดยไม่ได้แจ้งเหตุผล ผู้จัดทำสันนิษฐานว่าเพราะโจทย์ใช้หน่วย “พาร์เซก” แทน “เมกะพาร์เซก” ครูควรตรวจทาน',2569,'sci:69-21');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-69-22','M6','M6-SC','M6-SC-S3','A-Level 63',null,2,'โลกของเรามีโครงสร้างภายในแบ่งออกเป็นหลายชั้น ข้อใดถูกต้องเกี่ยวกับโครงสร้างโลก','["เนื้อโลก (Mantle) ประกอบด้วยหินแกรนิตเป็นส่วนใหญ่", "แก่นโลกชั้นนอก (Outer Core) อยู่ในสถานะของเหลว", "แก่นโลกชั้นนอก (Outer Core) อยู่ในสถานะของแข็งและเป็นเหล็กล้วน", "เปลือกโลก (Crust) มีความหนามากที่สุดในบรรดาชั้นต่าง ๆ ของโลก", "เปลือกโลกมหาสมุทร (Oceanic Crust) มีความหนากว่าเปลือกโลกทวีป (Continental Crust)"]'::jsonb,1,array[1]::smallint[],'["แก่นโลกชั้นนอกเป็นของเหลว (เหล็กและนิกเกิลหลอมเหลว) ซึ่งเป็นหลักฐานจากการที่คลื่น S ผ่านไม่ได้"]'::jsonb,'["ไม่ถูก เนื้อโลกเป็นหินอัลตราเมฟิก เช่น เพริโดไทต์ ส่วนหินแกรนิตพบในเปลือกโลกทวีป", "ถูก", "ไม่ถูก แก่นโลกชั้นนอกเป็นของเหลว และเป็นเหล็กกับนิกเกิล", "ไม่ถูก เปลือกโลกบางที่สุด", "ไม่ถูก เปลือกโลกมหาสมุทรบางกว่า (ประมาณ 5–10 km)"]'::jsonb,'{"topic": "3.5", "n": 22}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'sci:69-22');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-69-23','M6','M6-SC','M6-SC-S3','A-Level 63',null,2,'หลักฐานในข้อใด**ไม่**ใช่ข้อมูลที่สนับสนุนแนวคิดเรื่องการเคลื่อนที่ของทวีปสำหรับทฤษฎีทวีปเลื่อนของเวเกเนอร์','["ลักษณะรูปร่างชายฝั่งทวีปที่ต่อกันได้พอดี เช่น ทวีปแอฟริกากับทวีปอเมริกาใต้", "การค้นพบซากดึกดำบรรพ์ชนิดเดียวกันบนทวีปที่อยู่ห่างไกลกันในปัจจุบัน", "การพบกลุ่มหินและแนวเทือกเขาที่มีอายุและลักษณะกลุ่มหินที่คล้ายคลึงกันบนทวีปที่ต่างกัน", "การพบร่องรอยธารน้ำแข็งบรรพกาลบนทวีปที่ปัจจุบันอยู่ในเขตร้อนชื้น", "การวัดการเคลื่อนที่ของแผ่นทวีปด้วยสัญญาณดาวเทียม GPS ในช่วง 10 ปี ที่ผ่านมา"]'::jsonb,4,array[4]::smallint[],'["เวเกเนอร์เสนอทฤษฎีทวีปเลื่อนในต้นศตวรรษที่ 20 ก่อนมีดาวเทียม GPS · ข้อมูล GPS เป็นหลักฐานยุคใหม่ ไม่ใช่หลักฐานของเวเกเนอร์"]'::jsonb,'["เป็นหลักฐานของเวเกเนอร์", "เป็นหลักฐานของเวเกเนอร์", "เป็นหลักฐานของเวเกเนอร์", "เป็นหลักฐานของเวเกเนอร์", "ไม่ใช่หลักฐานของเวเกเนอร์ จึงเป็นคำตอบ"]'::jsonb,'{"topic": "3.6", "n": 23}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'sci:69-23');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-69-24','M6','M6-SC','M6-SC-S3','A-Level 63',null,2,'เมื่อมวลอากาศเย็นเคลื่อนที่ปะทะมวลอากาศอุ่นเกิดเป็นแนวปะทะอากาศเย็น (Cold Front) สภาพลมฟ้าอากาศในข้อใดที่มักเกิดตามมาขณะหรือหลังแนวปะทะอากาศเย็นผ่านพื้นที่นั้น','["อากาศสงบ ฟ้าโปร่ง มีหมอกบาง ๆ อุณหภูมิสูงขึ้นเล็กน้อย", "อากาศแปรปรวน มีฝนตกหนักหรือพายุฝนฟ้าคะนอง ตามด้วยอุณหภูมิลดลงอย่างรวดเร็ว", "มีฝนตกพรำ ๆ ต่อเนื่องเป็นเวลานานหลายวัน อุณหภูมิและความกดอากาศเพิ่มสูงขึ้น", "เกิดพายุหมุนเขตร้อนรุนแรงทันที และลมพัดเข้าศูนย์กลางพายุตลอดวัน", "เกิดพายุทรายหรือพายุฝุ่น เนื่องจากอากาศแห้งเย็นพัดผ่านพื้นที่ทะเลทราย"]'::jsonb,1,array[1]::smallint[],'["มวลอากาศเย็นดันอากาศอุ่นให้ยกตัวขึ้นอย่างรวดเร็ว เกิดเมฆคิวมูโลนิมบัส ฝนตกหนักหรือพายุฝนฟ้าคะนอง และหลังแนวปะทะผ่านไปอุณหภูมิจะลดลง"]'::jsonb,'["ไม่ถูก ไม่ตรงกับแนวปะทะอากาศเย็น และอุณหภูมิลดลง ไม่ใช่สูงขึ้น", "ถูก", "ไม่ถูก ฝนพรำต่อเนื่องนาน ๆ เป็นลักษณะของแนวปะทะอากาศอุ่น", "ไม่ถูก พายุหมุนเขตร้อนเกิดเหนือมหาสมุทรอุ่น ไม่ได้เกิดจากแนวปะทะ", "ไม่ถูก ไม่ใช่ลักษณะทั่วไปของแนวปะทะอากาศเย็น"]'::jsonb,'{"topic": "3.8", "n": 24}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'sci:69-24');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-69-25','M6','M6-SC','M6-SC-S3','A-Level 63',null,2,'มาตราในข้อใดใช้วัดขนาดหรือพลังงานของการเกิดแผ่นดินไหว','["มาตราฟูจิตะ (Fujita scale)", "มาตราโมห์ส (Mohs scale)", "มาตราคลื่น (Wave scale)", "มาตราริกเตอร์ (Richter scale)", "มาตราเมอร์คัลลีปรับปรุงใหม่ (Modified Mercalli scale)"]'::jsonb,3,array[3]::smallint[],'["มาตราริกเตอร์วัดขนาด (พลังงาน) ของแผ่นดินไหวจากแอมพลิจูดของคลื่นไหวสะเทือน"]'::jsonb,'["ไม่ถูก มาตราฟูจิตะใช้วัดความรุนแรงของพายุทอร์นาโด", "ไม่ถูก มาตราโมห์สใช้วัดความแข็งของแร่", "ไม่ถูก", "ถูก", "ไม่ถูก มาตราเมอร์คัลลีวัดความรุนแรงจากผลกระทบที่สังเกตได้ ไม่ใช่ขนาดหรือพลังงาน"]'::jsonb,'{"topic": "3.7", "n": 25}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'sci:69-25');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-69-26','M6','M6-SC','M6-SC-S3','A-Level 63',null,2,'ข้อใด**ไม่**ใช่แก๊สเรือนกระจกที่มีบทบาทสำคัญในการเปลี่ยนแปลงภูมิอากาศโลก','["ไอน้ำ", "มีเทน", "ไนตรัสออกไซด์", "ไนโตรเจน", "โอโซน"]'::jsonb,3,array[3]::smallint[],'["แก๊สไนโตรเจน (N₂) มีมากที่สุดในบรรยากาศ แต่ไม่ดูดกลืนรังสีอินฟราเรด จึงไม่ใช่แก๊สเรือนกระจก"]'::jsonb,'["เป็นแก๊สเรือนกระจก", "เป็นแก๊สเรือนกระจก", "เป็นแก๊สเรือนกระจก (N₂O)", "ไม่ใช่แก๊สเรือนกระจก จึงเป็นคำตอบ", "เป็นแก๊สเรือนกระจก"]'::jsonb,'{"topic": "3.9", "n": 26}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2569,'sci:69-26');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-68-1','M6','M6-SC','M6-SC-S1','A-Level 63',null,2,'จากสถานการณ์ดังต่อไปนี้
หลังจากเกิดไฟป่าครั้งใหญ่ในพื้นที่ทุ่งหญ้า สิ่งมีชีวิตต่าง ๆ ในระบบนิเวศเริ่มมีการปรับตัวและเปลี่ยนแปลง พืชชนิดใหม่เริ่มเจริญเติบโตแทนที่พืชชนิดเดิมที่ถูกทำลาย และค่อย ๆ มีการพัฒนาขึ้นเป็นป่าละเมาะ เมื่อเวลาผ่านไปโครงสร้างของสิ่งมีชีวิตในระบบนิเวศเริ่มมีการเปลี่ยนแปลงอย่างชัดเจน และเกิดการเปลี่ยนแปลงในความหลากหลายทางชีวภาพ
จงพิจารณากระบวนการต่อไปนี้
ก. การขยายพันธุ์
ข. การคัดเลือกโดยธรรมชาติ
ค. การสืบพันธุ์ใหม่
ง. การเปลี่ยนแปลงแทนที่ของระบบนิเวศ
จากสถานการณ์ตรงกับกระบวนการใด','["ก และ ข เท่านั้น", "ก และ ค เท่านั้น", "ข และ ค เท่านั้น", "ข และ ง เท่านั้น", "ค และ ง เท่านั้น"]'::jsonb,3,array[3]::smallint[],'["พืชชนิดใหม่เข้ามาแทนที่จนกลายเป็นป่าละเมาะ คือการเปลี่ยนแปลงแทนที่ (ง) · สิ่งมีชีวิตที่ปรับตัวเข้ากับสภาพหลังไฟป่าได้จะอยู่รอด คือการคัดเลือกโดยธรรมชาติ (ข)"]'::jsonb,'["ไม่ถูก ขาด ง ซึ่งเป็นหัวใจของสถานการณ์", "ไม่ถูก ก และ ค ไม่ได้อธิบายการเปลี่ยนโครงสร้างของระบบนิเวศ", "ไม่ถูก ขาด ง", "ถูก", "ไม่ถูก “การสืบพันธุ์ใหม่” ไม่ได้อธิบายการแทนที่ของชนิดพืช"]'::jsonb,'{"topic": "1.1", "n": 1}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2568,'sci:68-1');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-68-2','M6','M6-SC','M6-SC-S1','A-Level 63',null,2,'จากสถานการณ์ดังต่อไปนี้
เมื่อแช่สตรอว์เบอร์รีสดในน้ำเกลือเข้มข้น ผลสตรอว์เบอร์รีกลับมีลักษณะเหี่ยวลง
จงพิจารณาข้อความต่อไปนี้
ก. น้ำเกลือเข้มข้นดึงน้ำออกจากเซลล์สตรอว์เบอร์รีผ่านกระบวนการออสโมซิส ทำให้เซลล์สูญเสียน้ำและเกิดการเหี่ยวลง
ข. เซลล์ของสตรอว์เบอร์รีดูดน้ำจากน้ำเกลือเข้มข้นเข้ามาเพื่อรักษาสมดุล ทำให้ผลสตรอว์เบอร์รีมีน้ำเกินจนเปราะและหดตัวลง
ค. น้ำเกลือเข้มข้นทำให้โปรตีนในเซลล์สตรอว์เบอร์รีจับตัวเป็นก้อน ส่งผลให้เซลล์หดตัวและผลเหี่ยวลง
ง. การแช่ในน้ำเกลือเข้มข้นทำให้เกิดการอิเล็กโตรลิซิสภายในเซลล์สตรอว์เบอร์รี ส่งผลให้เซลล์เสียสมดุลและเหี่ยวลง
ข้อใดต่อไปนี้คือสาเหตุของการเปลี่ยนแปลงของผลสตรอว์เบอร์รี','["ก เท่านั้น", "ก และ ค เท่านั้น", "ข และ ค เท่านั้น", "ข และ ง เท่านั้น", "ค เท่านั้น"]'::jsonb,0,array[0]::smallint[],'["น้ำเกลือเข้มข้นเป็นสารละลายไฮเพอร์โทนิก น้ำจึงออสโมซิสออกจากเซลล์ เซลล์เหี่ยว (ก)"]'::jsonb,'["ถูก", "ไม่ถูก การเหี่ยวเกิดจากการเสียน้ำ ไม่ใช่การจับตัวของโปรตีน", "ไม่ถูก น้ำเคลื่อนออกจากเซลล์ ไม่ใช่เข้าเซลล์", "ไม่ถูก ไม่มีกระแสไฟฟ้า จึงไม่เกิดอิเล็กโตรลิซิส", "ไม่ถูก"]'::jsonb,'{"topic": "1.2", "n": 2}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2568,'sci:68-2');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-68-3','M6','M6-SC','M6-SC-S1','A-Level 63',null,2,'จากสถานการณ์ดังต่อไปนี้
ในช่วงบ่ายวันหนึ่ง คุณรู้สึกกระหายน้ำมาก จึงดื่มน้ำไปหลายแก้วติดกัน หลังจากนั้นไม่นาน จึงสังเกตพบว่าเริ่มปัสสาวะบ่อยขึ้น และสีของปัสสาวะจางกว่าปกติ
จงพิจารณาข้อความต่อไปนี้
ก. ไตจะเพิ่มการดูดซึมน้ำกลับเข้าสู่กระแสเลือดเพื่อลดปริมาณปัสสาวะ ทำให้ร่างกายสามารถกักเก็บน้ำไว้ใช้ในภาวะขาดน้ำ
ข. ไตจะเพิ่มการดูดซึมโซเดียมกลับเข้าสู่กระแสเลือด เพื่อให้ร่างกายกักเก็บน้ำในปริมาณมากขึ้นและรักษาสมดุลความเข้มข้นของเลือด
ค. ไตจะขับน้ำส่วนเกินออกทางปัสสาวะมากขึ้น เพื่อรักษาความเข้มข้นของเลือดให้คงที่หลังจากการดื่มน้ำปริมาณมาก
ง. ไตจะลดการผลิตฮอร์โมน ADH (Antidiuretic hormone) ซึ่งช่วยลดการดูดซึมน้ำกลับเข้าสู่กระแสเลือด ทำให้มีการขับน้ำออกทางปัสสาวะมากขึ้น
ข้อใดกล่าวถึงกระบวนการที่ร่างกายกำลังรักษาสมดุลน้ำถูกต้อง','["ก และ ค เท่านั้น", "ข และ ง เท่านั้น", "ค เท่านั้น", "ค และ ง เท่านั้น", "ง เท่านั้น"]'::jsonb,2,array[2]::smallint[],'["ดื่มน้ำมาก ไตจึงขับน้ำส่วนเกินออก ปัสสาวะมากและจาง (ค) · ง ผิด เพราะ ADH สร้างจากไฮโพทาลามัสและหลั่งจากต่อมใต้สมองส่วนหลัง ไม่ได้สร้างที่ไต และ ADH เพิ่มการดูดน้ำกลับ ไม่ใช่ลด"]'::jsonb,'["ไม่ถูก ก เป็นการตอบสนองต่อภาวะขาดน้ำ ตรงข้ามกับสถานการณ์", "ไม่ถูก ข และ ง ผิด", "ถูก", "ไม่ถูก ง ผิด ไตไม่ได้สร้าง ADH", "ไม่ถูก ง ผิด"]'::jsonb,'{"topic": "1.3", "n": 3}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2568,'sci:68-3');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-68-4','M6','M6-SC','M6-SC-S1','A-Level 63',null,2,'ชายวัย 35 ปี มีอาการเหนื่อยล้าเรื้อรัง ปวดข้อ ผื่นแดงบนใบหน้า เจ็บหน้าอกเมื่อหายใจ ระดับแอนติบอดีในเลือดสูง มีโปรตีนสะสมในไตทำให้การทำงานของไตลดลง และการอักเสบในอวัยวะหลายส่วนโดยไม่มีการติดเชื้อ ผู้ป่วยมีโอกาสป่วยเป็นโรคใด เพราะเหตุใด','["โรคข้ออักเสบรูมาตอยด์ (Rheumatoid Arthritis): โรคภูมิคุ้มกันทำลายตนเองที่ทำให้เกิดการอักเสบของข้อต่อ แต่ไม่ค่อยมีผื่นแดงบนใบหน้าและปัญหาการทำงานของไต", "โรคผิวหนังอักเสบภูมิแพ้ (Atopic Dermatitis): โรคผิวหนังเรื้อรังที่ทำให้เกิดผื่นคัน แต่ไม่เกี่ยวข้องกับอาการปวดข้อหรือปัญหาการทำงานของไต", "โรคไตอักเสบ (Glomerulonephritis): การอักเสบของหน่วยกรองในไตที่ทำให้มีโปรตีนในปัสสาวะสูง แต่ไม่ค่อยมีอาการปวดข้อหรือผื่นแดงบนใบหน้า", "โรคปอดอักเสบ (Pneumonitis): การอักเสบของเนื้อเยื่อปอดที่ทำให้เจ็บหน้าอกเมื่อหายใจ แต่ไม่ค่อยมีอาการปวดข้อหรือผื่นแดงบนใบหน้า", "โรคลูปัส (Systemic Lupus Erythematous): โรคภูมิคุ้มกันทำลายตนเองที่ทำให้เกิดการอักเสบทั่วร่างกาย มีอาการปวดข้อ ผื่นแดงบนใบหน้า เจ็บหน้าอกเมื่อหายใจ และปัญหาการทำงานของไต"]'::jsonb,4,array[4]::smallint[],'["อาการหลายระบบพร้อมกัน (ข้อ ผิวหน้า ปอด ไต) และแอนติบอดีสูงโดยไม่มีการติดเชื้อ ตรงกับโรคลูปัส ซึ่งเป็นโรคภูมิคุ้มกันทำลายตนเอง"]'::jsonb,'["ไม่ถูก อธิบายผื่นที่หน้าและปัญหาไตไม่ได้", "ไม่ถูก อธิบายอาการปวดข้อและไตไม่ได้", "ไม่ถูก อธิบายอาการปวดข้อและผื่นไม่ได้", "ไม่ถูก อธิบายอาการที่ข้อ ผิว และไตไม่ได้", "ถูก"]'::jsonb,'{"topic": "1.4", "n": 4}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'sci:68-4');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-68-5','M6','M6-SC','M6-SC-S1','A-Level 63',null,2,'จากสถานการณ์ดังต่อไปนี้
ในการทดลองเพื่อศึกษาปัจจัยที่มีผลต่อการสังเคราะห์โปรตีนในพืช นักวิทยาศาสตร์ได้ปลูกพืชภายใต้สภาวะแวดล้อมที่แตกต่างกัน โดยควบคุมปัจจัยต่าง ๆ ได้แก่ ปริมาณแสง อุณหภูมิ ปริมาณไนโตรเจน คาร์บอนไดออกไซด์ และออกซิเจน ผลการทดลองพบว่าพืชที่ได้รับปัจจัยหนึ่งในปริมาณสูงสามารถสังเคราะห์โปรตีนได้มากกว่าปกติอย่างมีนัยสำคัญ ขณะที่ปัจจัยอื่นมีผลต่อการเจริญเติบโตและการผลิตน้ำตาล แต่ไม่ส่งผลโดยตรงต่อการสังเคราะห์โปรตีน
จงพิจารณาข้อความต่อไปนี้
ก. ปริมาณแสง เนื่องจากแสงเป็นปัจจัยที่จำเป็นในการสังเคราะห์แสง ซึ่งช่วยให้พืชผลิตพลังงานที่จำเป็นสำหรับการสังเคราะห์โปรตีน แม้ว่าแสงไม่ได้เป็นองค์ประกอบโดยตรงของโปรตีน แต่พืชต้องการพลังงานจากแสงเพื่อดำเนินกระบวนการสร้างกรดอะมิโนและโปรตีน
ข. อุณหภูมิ เนื่องจากอุณหภูมิที่เหมาะสมช่วยเร่งปฏิกิริยาของเอนไซม์ที่เกี่ยวข้องกับการสังเคราะห์โปรตีน การทำงานของเอนไซม์เหล่านี้ขึ้นอยู่กับสภาพอุณหภูมิที่เหมาะสม และการเปลี่ยนแปลงของอุณหภูมิอาจส่งผลต่อการผลิตโปรตีนของพืช
ค. ปริมาณไนโตรเจน เนื่องจากไนโตรเจนเป็นธาตุหลักที่จำเป็นในการสร้างกรดอะมิโน ซึ่งเป็นองค์ประกอบพื้นฐานของโปรตีน การมีไนโตรเจนเพียงพอทำให้พืชสามารถสังเคราะห์กรดอะมิโนและโปรตีนได้อย่างมีประสิทธิภาพ
ง. ความเข้มข้นของคาร์บอนไดออกไซด์ เนื่องจากคาร์บอนไดออกไซด์เป็นปัจจัยที่ช่วยในกระบวนการสังเคราะห์แสง การที่พืชมีการผลิตน้ำตาลที่มากขึ้นจะช่วยส่งเสริมการผลิตพลังงานที่จำเป็นต่อการสังเคราะห์โปรตีน
ข้อใดต่อไปนี้กล่าวถูกต้อง','["ก และ ข เท่านั้น", "ก และ ง เท่านั้น", "ข เท่านั้น", "ค เท่านั้น", "ค และ ง เท่านั้น"]'::jsonb,3,array[3]::smallint[],'["โจทย์บอกว่ามีปัจจัยเดียวที่เพิ่มการสังเคราะห์โปรตีนโดยตรง ปัจจัยนั้นคือไนโตรเจน ซึ่งเป็นองค์ประกอบของกรดอะมิโน · แสง อุณหภูมิ และ CO₂ มีผลต่อการเจริญเติบโตและการผลิตน้ำตาล (ผลทางอ้อม)"]'::jsonb,'["ไม่ถูก แสงและอุณหภูมิมีผลทางอ้อม", "ไม่ถูก แสงและ CO₂ มีผลผ่านการผลิตน้ำตาล ซึ่งโจทย์บอกว่าไม่ส่งผลโดยตรง", "ไม่ถูก", "ถูก", "ไม่ถูก CO₂ มีผลต่อการผลิตน้ำตาล ไม่ได้มีผลโดยตรงต่อโปรตีน"]'::jsonb,'{"topic": "1.5", "n": 5}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2568,'sci:68-5');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-68-6','M6','M6-SC','M6-SC-S1','A-Level 63',null,2,'จงพิจารณาจากสถานการณ์ดังต่อไปนี้
สถานการณ์ที่ 1 พืชประสบภาวะแห้งแล้งเป็นเวลานาน
สถานการณ์ที่ 2 เมล็ดพืชอยู่ในสภาวะพักตัวและต้องการกระตุ้นการงอก
พืชตอบสนองต่อสภาวะแวดล้อมที่แตกต่างกันผ่านการปรับระดับฮอร์โมนภายใน
ในสถานการณ์ต่อไปนี้ ฮอร์โมนใดมีบทบาทสำคัญ และมีหน้าที่อย่างไร','["สถานการณ์ที่ 1: กรดแอบไซซิก (ABA) ระดับเพิ่มขึ้น เพื่อปิดปากใบ ลดการคายน้ำ · สถานการณ์ที่ 2: จิบเบอเรลลิน ระดับเพิ่มขึ้น เพื่อกระตุ้นการงอกของเมล็ด", "สถานการณ์ที่ 1: เอทิลีน ระดับเพิ่มขึ้น เพื่อปิดปากใบ ลดการคายน้ำ · สถานการณ์ที่ 2: ไซโตไคนิน ระดับเพิ่มขึ้น เพื่อกระตุ้นการงอกของเมล็ด", "สถานการณ์ที่ 1: ออกซิน ระดับลดลง ทำให้ปากใบเปิด เพิ่มการคายน้ำ · สถานการณ์ที่ 2: ไซโตไคนิน ระดับลดลง ยับยั้งการงอกของเมล็ด", "สถานการณ์ที่ 1: จิบเบอเรลลิน ระดับเพิ่มขึ้น เพื่อปิดปากใบ ลดการคายน้ำ · สถานการณ์ที่ 2: กรดแอบไซซิก (ABA) ระดับลดลง ยับยั้งการงอกของเมล็ด", "สถานการณ์ที่ 1: เอทิลีน ระดับเพิ่มขึ้น เพื่อเปิดปากใบ รับความชื้นจากภายนอก · สถานการณ์ที่ 2: จิบเบอเรลลิน ระดับลดลง ยับยั้งการงอกของเมล็ด"]'::jsonb,0,array[0]::smallint[],'["ขาดน้ำ พืชเพิ่ม ABA เพื่อปิดปากใบลดการคายน้ำ · การงอกของเมล็ดถูกกระตุ้นด้วยจิบเบอเรลลิน"]'::jsonb,'["ถูก", "ไม่ถูก ฮอร์โมนหลักที่ปิดปากใบคือ ABA ไม่ใช่เอทิลีน", "ไม่ถูก การเปิดปากใบเพิ่มการคายน้ำเป็นผลเสียเมื่อแล้ง", "ไม่ถูก จิบเบอเรลลินไม่ได้ปิดปากใบ และ ABA ที่ลดลงช่วยให้เมล็ดงอก ไม่ใช่ยับยั้ง", "ไม่ถูก การเปิดปากใบทำให้เสียน้ำ และต้องเพิ่มจิบเบอเรลลินจึงจะงอก"]'::jsonb,'{"topic": "1.5", "n": 6}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'sci:68-6');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-68-7','M6','M6-SC','M6-SC-S1','A-Level 63',null,2,'ครอบครัวหนึ่งประกอบด้วย พ่อ แม่ และลูก 3 คน ได้รับการตรวจเลือด และลักษณะตาบอดสี ซึ่งลักษณะกรุ๊ปเลือดถูกควบคุมโดยยีนหลายแอลลีล (Multiple Alleles) ส่วนลักษณะตาบอดสีเป็นลักษณะที่ควบคุมโดยยีนบนโครโมโซม X
จงพิจารณาตารางแสดงผลการตรวจเลือดและการตรวจลักษณะตาบอดสีของสมาชิกในครอบครัว','["หมู่เลือด I^A i · ตาบอดสี X^C X^c", "หมู่เลือด I^A I^B · ตาบอดสี X^c X^c", "หมู่เลือด I^A i · ตาบอดสี X^c X^c", "หมู่เลือด I^A I^A · ตาบอดสี X^C X^c", "หมู่เลือด I^B i · ตาบอดสี X^c X^c"]'::jsonb,2,array[2]::smallint[],'["แม่ตาบอดสี (ลักษณะด้อยบน X) จึงต้องเป็น X^c X^c · แม่เลือดกรุ๊ป A และมีลูกกรุ๊ป O (ii) แม่จึงต้องมีแอลลีล i ด้วย คือ I^A i"]'::jsonb,'["ไม่ถูก ถ้าเป็น X^C X^c แม่จะไม่ตาบอดสี", "ไม่ถูก I^A I^B คือกรุ๊ป AB", "ถูก", "ไม่ถูก I^A I^A ให้ลูกกรุ๊ป O ไม่ได้ และ X^C X^c ไม่ตาบอดสี", "ไม่ถูก I^B i คือกรุ๊ป B"]'::jsonb,'{"table": [["บุคคลในครอบครัว", "เลือดกรุ๊ป", "ลักษณะตาบอดสี (เขียว-แดง)"], ["แม่", "A", "ตาบอดสี"], ["พ่อ", "B", "ปกติ"], ["ลูกคนที่ 1 (หญิง)", "A", "ปกติ"], ["ลูกคนที่ 2 (ชาย)", "O", "ตาบอดสี"], ["ลูกคนที่ 3 (หญิง)", "B", "ปกติ"]], "after": "กำหนดให้ I^A, I^B, i คือ แอลลีลควบคุมกรุ๊ปเลือดระบบ ABO และ X^C, X^c คือ แอลลีลควบคุมลักษณะตาบอดสี ตัวเลือกใดเป็นจีโนไทป์ของแม่", "topic": "1.6", "n": 7}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'sci:68-7');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-68-8','M6','M6-SC','M6-SC-S2','A-Level 63',null,2,'จากตารางข้อมูลเกี่ยวกับอะตอมของธาตุต่อไปนี้ จงเติมให้สมบูรณ์','["ก และ ข เท่านั้น", "ก และ ค เท่านั้น", "ก และ ง เท่านั้น", "ข และ ค เท่านั้น", "ข และ ง เท่านั้น"]'::jsonb,2,array[2]::smallint[],'["Na⁺ มี 11 − 1 = 10 อิเล็กตรอน · Ca²⁺ มี 20 − 2 = 18 · Mg²⁺ มี 12 − 2 = 10 · F⁻ มี 9 + 1 = 10 · ก ถูก (18 − 10 = 8) · ง ถูก · ข ผิด ต้องเป็น Ca²⁺ · ค ผิด ต้องเป็น F⁻"]'::jsonb,'["ไม่ถูก ข ผิด ให้อิเล็กตรอนแล้วเป็นไอออนบวก", "ไม่ถูก ค ผิด รับอิเล็กตรอนแล้วเป็นไอออนลบ", "ถูก", "ไม่ถูก ข และ ค ผิด", "ไม่ถูก ข ผิด"]'::jsonb,'{"table": [["สัญลักษณ์นิวเคลียร์", "ไอออน", "ให้/รับอิเล็กตรอน", "จำนวนอิเล็กตรอน"], ["²³₁₁Na", "Na⁺", "", ""], ["⁴⁰₂₀Ca", "", "ให้", "2 อิเล็กตรอน"], ["²⁴₁₂Mg", "Mg²⁺", "", ""], ["¹⁹₉F", "", "รับ", "1 อิเล็กตรอน"]], "after": "พิจารณาข้อความต่อไปนี้\nก. จำนวนอิเล็กตรอนของโซเดียมไอออนน้อยกว่าจำนวนอิเล็กตรอนของแคลเซียมไอออน เท่ากับ 8 อิเล็กตรอน\nข. เมื่อธาตุแคลเซียมให้อิเล็กตรอนไป 2 อิเล็กตรอน แคลเซียมไอออนจะเขียนสัญลักษณ์ได้ Ca²⁻\nค. เมื่อธาตุฟลูออรีนได้รับอิเล็กตรอน 1 อิเล็กตรอน ฟลูออรีนไอออนจะเขียนสัญลักษณ์ได้ F⁺\nง. โซเดียมไอออน แมกนีเซียมไอออน ฟลูออรีนไอออนมีจำนวนอิเล็กตรอนเท่ากัน แต่น้อยกว่าจำนวนอิเล็กตรอนของแคลเซียมไอออนเท่ากับ 8 อิเล็กตรอน\nข้อความใดกล่าวถูกต้อง", "topic": "2.1", "n": 8}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2568,'sci:68-8');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-68-9','M6','M6-SC','M6-SC-S2','A-Level 63',null,2,'จากตารางข้อมูลดังต่อไปนี้
น้ำ · กรดน้ำส้ม · คาร์บอนมอนอกไซด์ · เกลือแกง
พิจารณาข้อความต่อไปนี้
ก. กรดน้ำส้มเป็นสารโคเวเลนต์ มีพันธะที่ใช้เวเลนซ์อิเล็กตรอนร่วมกัน 1 คู่ จำนวน 6 พันธะ
ข. น้ำไม่ใช่สารโคเวเลนต์ น้ำประกอบด้วยออกซิเจน 1 อะตอม และไฮโดรเจน 2 อะตอม
ค. คาร์บอนมอนอกไซด์เป็นสารโคเวเลนต์มีพันธะที่ใช้เวเลนซ์อิเล็กตรอนร่วมกัน 2 คู่ จำนวน 1 พันธะ
ง. เกลือแกงเป็นสารโคเวเลนต์ที่ประกอบด้วยโซเดียม 1 อะตอมและคลอรีน 1 อะตอม
ข้อใดกล่าวเกี่ยวกับสารโคเวเลนต์ได้ถูกต้อง','["ก เท่านั้น", "ก และ ค เท่านั้น", "ข เท่านั้น", "ข และ ง เท่านั้น", "ข ค และ ง เท่านั้น"]'::jsonb,0,array[0]::smallint[],'["กรดน้ำส้ม CH₃COOH มีพันธะเดี่ยว 6 พันธะ (C−H 3 พันธะ, C−C, C−O และ O−H) และพันธะคู่ C=O 1 พันธะ · ข ผิด น้ำเป็นสารโคเวเลนต์ · ค ผิด CO มีพันธะสาม · ง ผิด เกลือแกงเป็นสารประกอบไอออนิก"]'::jsonb,'["ถูก", "ไม่ถูก ค ผิด C กับ O ใน CO ใช้อิเล็กตรอนร่วมกัน 3 คู่", "ไม่ถูก น้ำเป็นสารโคเวเลนต์", "ไม่ถูก ข และ ง ผิด", "ไม่ถูก ข ค และ ง ผิด"]'::jsonb,'{"topic": "2.2", "n": 9}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2568,'sci:68-9');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-68-10','M6','M6-SC','M6-SC-S2','A-Level 63',null,2,'จากตารางข้อมูลดังต่อไปนี้
เกลือแกง · กรดน้ำส้ม · คาร์บอนไดออกไซด์ · โพแทสเซียมคลอไรด์
พิจารณาข้อความต่อไปนี้
ก. CO₂ เป็นสารในรูปโมเลกุล ไม่ใช่สารประกอบไอออนิก
ข. KCl เป็นสารประกอบไอออนิก เมื่อนำมาละลายน้ำจะได้สารในรูปไอออน คือ K⁺ และ Cl⁻
ค. CH₃COOH เป็นสารประกอบไอออนิก เมื่อนำมาละลายน้ำจะได้สารในรูปโมเลกุล CH₃COOH
ง. NaCl เป็นสารประกอบไอออนิก เมื่อนำมาละลายน้ำจะได้สารที่อยู่ในรูปไอออน คือ Na⁺ และ Cl⁻
ข้อใดกล่าวถูกต้อง','["ก และ ข เท่านั้น", "ข และ ค เท่านั้น", "ค และ ง เท่านั้น", "ก ข และ ค เท่านั้น", "ก ข และ ง เท่านั้น"]'::jsonb,4,array[4]::smallint[],'["CO₂ เป็นสารโคเวเลนต์ในรูปโมเลกุล · KCl และ NaCl เป็นสารประกอบไอออนิก ละลายน้ำแล้วแตกตัวเป็นไอออน · ค ผิด กรดน้ำส้มเป็นสารโคเวเลนต์ (กรดอ่อน แตกตัวเป็นไอออนได้บางส่วน)"]'::jsonb,'["ไม่ถูก ขาด ง ซึ่งถูกด้วย", "ไม่ถูก ค ผิด", "ไม่ถูก ค ผิด", "ไม่ถูก ค ผิด", "ถูก"]'::jsonb,'{"topic": "2.3", "n": 10}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2568,'sci:68-10');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-68-11','M6','M6-SC','M6-SC-S2','A-Level 63',null,2,'จากโครงสร้างของสารประกอบต่อไปนี้','["ก และ ง เท่านั้น", "ข เท่านั้น", "ข และ ค เท่านั้น", "ข ค และ ง เท่านั้น", "ค เท่านั้น"]'::jsonb,2,array[2]::smallint[],'["การอิ่มตัวดูจากชนิดพันธะ ไม่ใช่รูปร่างโมเลกุล · (1) และ (4) มีแต่พันธะเดี่ยว จึงอิ่มตัว · (2) (3) และ (5) มีพันธะคู่ จึงไม่อิ่มตัว"]'::jsonb,'["ไม่ถูก (2) และ (3) มีพันธะคู่ และ (4) เป็นวงแต่อิ่มตัว", "ไม่ถูก ค ถูกด้วย", "ถูก", "ไม่ถูก ง ผิด (4) อิ่มตัว และโครงสร้างแบบวงไม่ได้ทำให้ไม่อิ่มตัว", "ไม่ถูก ข ถูกด้วย"]'::jsonb,'{"img": "sci-68-11.png", "after": "พิจารณาข้อความต่อไปนี้\nก. โครงสร้าง (1) (2) และ (3) เป็นสารประกอบไฮโดรคาร์บอนอิ่มตัว เพราะเป็นโครงสร้างแบบเส้นและแบบกิ่ง\nข. โครงสร้าง (1) และ (4) เป็นสารประกอบไฮโดรคาร์บอนอิ่มตัว เพราะโครงสร้างมีพันธะเดี่ยวทั้งหมด\nค. โครงสร้าง (2) (3) และ (5) เป็นสารประกอบไฮโดรคาร์บอนไม่อิ่มตัว เพราะโครงสร้างมีพันธะคู่\nง. โครงสร้าง (4) และ (5) เป็นสารประกอบไฮโดรคาร์บอนที่ไม่อิ่มตัว เพราะเป็นโครงสร้างแบบวง\nข้อความใดกล่าวได้ถูกต้อง", "topic": "2.4", "n": 11, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/sci-68-11.png"}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2568,'sci:68-11');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-68-12','M6','M6-SC','M6-SC-S2','A-Level 63',null,2,'โรงงานอุตสาหกรรมแห่งหนึ่งมีวัตถุดิบเป็นพอลิเมอร์ซึ่งมีสูตรโครงสร้างทางเคมีดังต่อไปนี้','["เทอร์มอพลาสติก: ก และ ข · เทอร์มอเซต: ค · รีไซเคิลได้: ค", "เทอร์มอพลาสติก: ข และ ค · เทอร์มอเซต: ก · รีไซเคิลได้: ข และ ค", "เทอร์มอพลาสติก: ก และ ค · เทอร์มอเซต: ข · รีไซเคิลได้: ก และ ข", "เทอร์มอพลาสติก: ก · เทอร์มอเซต: ข และ ค · รีไซเคิลได้: ข", "เทอร์มอพลาสติก: ค · เทอร์มอเซต: ข และ ค · รีไซเคิลได้: ก"]'::jsonb,1,array[1]::smallint[],'["ก เป็นพอลิเมอร์จากเมลามีนที่เชื่อมโยงเป็นร่างแห (เทอร์มอเซต หลอมใหม่ไม่ได้) · ข คือพอลิโพรพิลีน (PP) · ค คือพอลิเอทิลีนเทเรฟทาเลต (PET) · PP และ PET เป็นเทอร์มอพลาสติก หลอมขึ้นรูปใหม่และรีไซเคิลได้"]'::jsonb,'["ไม่ถูก ก เป็นเทอร์มอเซต และ ค เป็นเทอร์มอพลาสติก", "ถูก", "ไม่ถูก ข (PP) เป็นเทอร์มอพลาสติก", "ไม่ถูก ข และ ค เป็นเทอร์มอพลาสติก", "ไม่ถูก ค อยู่ทั้งสองกลุ่มไม่ได้ และ ก เป็นเทอร์มอเซตจึงรีไซเคิลด้วยการหลอมไม่ได้"]'::jsonb,'{"img": "sci-68-12.png", "after": "พอลิเมอร์ใดที่จัดเป็นพอลิเมอร์ชนิดเทอร์มอพลาสติก พอลิเมอร์ชนิดเทอร์มอเซต และพอลิเมอร์ที่สามารถนำมารีไซเคิลได้ตามลำดับ", "topic": "2.5", "n": 12, "img_url": "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/sci-68-12.png"}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'sci:68-12');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-68-13','M6','M6-SC','M6-SC-S2','A-Level 63',null,2,'พิจารณาสถานการณ์ต่อไปนี้
สถานการณ์ ก เด็กหญิงมะลิทำการผสมสาร A กับสาร B ลงไปในบีกเกอร์ ขณะทดลองมีการคนสารเพื่อให้เข้ากัน ระหว่างนั้นเด็กหญิงมะลิได้สัมผัสที่บริเวณบีกเกอร์ พบว่ารู้สึกเย็นกว่าเดิม เด็กหญิงมะลิจึงบอกเพื่อนว่า ปฏิกิริยาที่กำลังเกิดขึ้นอยู่นี้เป็นปฏิกิริยาการคายความร้อน
สถานการณ์ ข เด็กหญิงมาลัยเข้าไปในครัวพบว่าแกงเขียวหวานในชามที่ 1 ถูกลืมทิ้งไว้บนโต๊ะทั้งวันทั้งคืน ทำให้แกงเขียวหวานชามที่ 1 บูดกินไม่ได้ แต่ยังโชคดีที่มีแกงเขียวหวานชามที่ 2 เก็บไว้ในตู้เย็นที่ยังไม่บูด เด็กหญิงมาลัยจึงรู้ว่าอุณหภูมิมีผลต่อการบูดของแกงเขียวหวานทั้งสองชาม
สถานการณ์ ค เด็กชายซีเจนำกรดไฮโดรคลอริกขวดหนึ่งมาเทลงในบีกเกอร์ 2 ใบ ใบที่ 1 เทกรดไฮโดรคลอริกปริมาตร 10 ml ใบที่ 2 ซึ่งมีน้ำกลั่นอยู่แล้วปริมาตร 5 ml จึงเทกรดไฮโดรคลอริกลงไปผสมจนได้ปริมาตรรวมเท่าใบที่ 1 หลังจากนั้นชั่งเม็ดแคลเซียมคาร์บอเนตใส่บีกเกอร์ทั้งสองใบจำนวนเท่ากัน เด็กชายซีเจสังเกตการเกิดฟองแก๊ส สรุปได้ว่าบีกเกอร์ใบที่ 1 เกิดฟองแก๊สเร็วกว่าบีกเกอร์ใบที่ 2 เพราะใบที่ 1 มีความเข้มข้นของกรดไฮโดรคลอริกน้อยกว่าใบที่ 2
สถานการณ์ ง แม่นำหมูมาหั่นเป็นชิ้นเล็ก ๆ แล้วนำยางมะละกอใส่ลงไปผสม หลังจากนั้นตั้งทิ้งไว้ 2-3 ชั่วโมง แล้วนำไปปรุงอาหาร ซึ่งเด็กชายบุญมีพบว่าหมูที่แม่หมักนุ่มมาก เขาจึงพูดกับแม่ว่า “การหมักหมูของแม่ทำให้หมูนุ่มเร็วกว่าหมูที่ไม่ได้หั่น เพราะหมูที่ถูกหั่นจะทำให้เพิ่มพื้นที่ผิวสัมผัสของหมูกับเอนไซม์ปาเปนในยางมะละกอที่เป็นตัวเร่งปฏิกิริยา”
สถานการณ์ในข้อใดถูกต้อง','["สถานการณ์ ก และ ข เท่านั้น", "สถานการณ์ ก และ ค เท่านั้น", "สถานการณ์ ก ข และ ง เท่านั้น", "สถานการณ์ ข และ ง เท่านั้น", "สถานการณ์ ข ค และ ง เท่านั้น"]'::jsonb,3,array[3]::smallint[],'["ข ถูก อุณหภูมิต่ำทำให้ปฏิกิริยา (การบูด) ช้าลง · ง ถูก การหั่นเพิ่มพื้นที่ผิว และปาเปนเป็นตัวเร่ง · ก ผิด บีกเกอร์เย็นลงแสดงว่าปฏิกิริยาดูดความร้อน · ค ผิด ใบที่ 1 ไม่ได้เจือจาง จึงมีความเข้มข้นมากกว่า"]'::jsonb,'["ไม่ถูก ก ผิด", "ไม่ถูก ก และ ค ผิด", "ไม่ถูก ก ผิด", "ถูก", "ไม่ถูก ค ผิด ข้อสรุปเรื่องความเข้มข้นกลับกัน"]'::jsonb,'{"topic": "2.6", "n": 13}'::jsonb,'imported_m6','imported',false,null,'Exam Gym ม.6 · 5620e4c',2568,'sci:68-13');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-68-14','M6','M6-SC','M6-SC-S2','A-Level 63',null,2,'พิจารณาข้อความต่อไปนี้
ก. การสลายของสารกัมมันตรังสี ไม่จัดเป็นปฏิกิริยาเคมี
ข. สารกัมมันตรังสีเป็นสารที่มีนิวเคลียสเสถียร สามารถแผ่รังสีได้
ค. สารกัมมันตรังสีชนิดหนึ่งเกิดการสลายจาก 500 กรัม จนเหลือ 62.5 กรัม ใช้เวลา 36 วัน แสดงว่าสารกัมมันตรังสีชนิดนี้มีครึ่งชีวิตเท่ากับ 18 วัน
ง. สารกัมมันตรังสีชนิดหนึ่ง 150 กรัม สลายตัวไป 75 กรัม ภายในเวลา 30 วัน พบว่าหลังทิ้งสารกัมมันตรังสีนี้ไว้ 150 วัน จะเหลือสารกัมมันตรังสี 150 กรัม แสดงว่าตอนเริ่มต้นมีสารกัมมันตรังสีชนิดนี้เท่ากับ 4,800 กรัม
ข้อความใดกล่าวได้ถูกต้อง','["ก และ ข เท่านั้น", "ก และ ค เท่านั้น", "ก และ ง เท่านั้น", "ก ข และ ง เท่านั้น", "ข ค และ ง เท่านั้น"]'::jsonb,2,array[2]::smallint[],'["ก ถูก เป็นการเปลี่ยนแปลงในนิวเคลียส · ข ผิด นิวเคลียสไม่เสถียรจึงแผ่รังสี · ค ผิด 500 → 62.5 คือ 3 ครึ่งชีวิตใน 36 วัน ครึ่งชีวิตจึงเท่ากับ 12 วัน · ง ถูก ครึ่งชีวิต 30 วัน 150 วันเท่ากับ 5 ครึ่งชีวิต เริ่มต้น = 150 × 2⁵ = 4,800 กรัม"]'::jsonb,'["ไม่ถูก ข ผิด", "ไม่ถูก ค ผิด ครึ่งชีวิตคือ 12 วัน", "ถูก", "ไม่ถูก ข ผิด", "ไม่ถูก ข และ ค ผิด"]'::jsonb,'{"topic": "2.7", "n": 14}'::jsonb,'imported_m6','imported',true,'combo','Exam Gym ม.6 · 5620e4c',2568,'sci:68-14');
insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-68-15','M6','M6-SC','M6-SC-S2','A-Level 63',null,2,'รถยนต์ A กำลังเคลื่อนที่ไปทางทิศตะวันตกด้วยอัตราเร็วคงที่ 10 เมตรต่อวินาที ส่วนรถยนต์ B เคลื่อนที่ไปทางทิศตะวันออกด้วยอัตราเร็วคงที่ 15 เมตรต่อวินาที โดยรถทั้งสองคันต่างมุ่งหน้าสู่สี่แยก เมื่อรถทั้งสองคันมองเห็นกันก็เริ่มเหยียบเบรก จนรถทั้งสองหยุดนิ่งที่บริเวณสี่แยกพอดีโดยใช้เวลาเท่ากัน
