insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-SC-68-19','M6','M6-SC','M6-SC-S2','A-Level 63',null,2,'รถสองคันกำลังแล่นผ่านบ้านเรือนที่มีเสียงสัญญาณไฟไหม้ โดยคนในรถตู้ A เพิ่งแล่นผ่านออกไป และคนในรถจักรยานยนต์ B กำลังแล่นเข้าหาบริเวณที่เกิดเหตุ อยากทราบว่าคนที่โดยสารในรถทั้งสองจะได้ยินเสียงสัญญาณไฟไหม้มีเสียงเป็นอย่างไร เมื่อเทียบกับเสียงสัญญาณจากบ้านที่ส่งเสียงสัญญาณ
