insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ('M6-TG3-p70-39','M6','M6-TG3','M6-TG3-S3','TGAT3',null,2,'〔ข้อสอบฝึก แต่งใหม่ — ไม่ใช่ข้อสอบจริง ทปอ. · TGAT3 · ความเข้าใจผู้อื่น (Interpersonal understanding)〕
